import C_JSON_API:JSONParser;
import C_JSON_API:JSONObject;

class CommonUtil
   method CommonUtil();

   method ReplaceWithRegex(&p_orig As string, &p_regex As string, &p_replace As string) Returns string;
   method EncodeBase64(&p_str As string) Returns string;
   method DecodeBase64(&p_str As string) Returns string;
   method EscapeJSON(&p_str As string) Returns string;
   method UnEscapeJSON(&p_str As string) Returns string;
   method JsonHexDigit(&p_n As number) Returns string;
   method JsonHexValue(&p_c As string) Returns number;
end-class;

method CommonUtil

end-method;

method ReplaceWithRegex
   /+ &p_orig as String, +/
   /+ &p_regex as String, +/
   /+ &p_replace as String +/
   /+ Returns String +/
   Local string &ReplacedStr;
   Local JavaObject &Pattern = GetJavaClass("java.util.regex.Pattern").compile(&p_regex);
   Local JavaObject &PatternClass = &Pattern.getClass();
   Local JavaObject &stringType = CreateJavaObject("java.lang.Class[]", GetJavaClass("java.lang.CharSequence"));
   Local JavaObject &MatcherMethod = &PatternClass.getDeclaredMethod("matcher", &stringType);
   Local JavaObject &JavaString = CreateJavaObject("java.lang.String", &p_orig);
   Local JavaObject &args = CreateJavaObject("java.lang.Object[]", &JavaString);
   Local JavaObject &Mater = &MatcherMethod.invoke(&Pattern, &args);
   &Mater = &Mater.getClass().cast(&Mater);
   &ReplacedStr = &Mater.replaceAll(&p_replace);
   Return &ReplacedStr;
end-method;

method EncodeBase64
   /+ &p_str as String +/
   /+ Returns String +/
   Local string &EncodeStr;
   Local JavaObject &Encoder, &StrBytes;
   try
      &Encoder = GetJavaClass("java.util.Base64").getEncoder();
      &StrBytes = CreateJavaObject("java.lang.String", &p_str).getBytes("UTF-8");
      &EncodeStr = &Encoder.encodeToString(&StrBytes);
   end-try;
   Return &EncodeStr;
end-method;

method DecodeBase64
   /+ &p_str as String +/
   /+ Returns String +/
   Local string &DecodeStr;
   Local JavaObject &Decoder, &StrBytes, &JavaStr;
   try
      &Decoder = GetJavaClass("java.util.Base64").getDecoder();
      &StrBytes = &Decoder.decode(&p_str);
      &JavaStr = CreateJavaObject("java.lang.String", &StrBytes, "UTF-8");
      &DecodeStr = &JavaStr.toString();
   end-try;
   Return &DecodeStr;
end-method;

method EscapeJSON
   /+ &p_str as String +/
   /+ Returns String +/
   rem Local string &EscapeStr;

   rem &EscapeStr = GetJavaClass("org.apache.commons.text.StringEscapeUtils").escapeJson(&p_str);
   Local string &EscapeStr, &Replacement;
   Local number &i;

   &EscapeStr = &p_str;

   /* 必须先转义反斜杠 */
   &EscapeStr = Substitute(&EscapeStr, Char(92), Char(92) | Char(92));

   /* 双引号 */
   &EscapeStr = Substitute(&EscapeStr, Char(34), Char(92) | Char(34));

   /* U+0000 到 U+001F 控制字符 */
   For &i = 0 To 31
      Evaluate &i
      When 8
         &Replacement = Char(92) | "b";
      When 9
         &Replacement = Char(92) | "t";
      When 10
         &Replacement = Char(92) | "n";
      When 12
         &Replacement = Char(92) | "f";
      When 13
         &Replacement = Char(92) | "r";
      When-Other
         &Replacement = Char(92) | "u00" | %This.JsonHexDigit(Int(&i / 16)) | %This.JsonHexDigit(Mod(&i, 16));
      End-Evaluate;

      &EscapeStr = Substitute(&EscapeStr, Char(&i), &Replacement);
   End-For;

   Return &EscapeStr;
end-method;

method UnEscapeJSON
   /+ &p_str as String +/
   /+ Returns String +/
   rem Local string &UnEscapeStr;

   rem &UnEscapeStr = GetJavaClass("org.apache.commons.text.StringEscapeUtils").unescapeJson(&p_str);

   Local string &UnEscapeStr;
   Local string &BackslashToken;
   Local string &JsonText;
   Local C_JSON_API:JSONParser &Parser;
   Local C_JSON_API:JSONObject &Wrapper;
   Local boolean &ParseOK;

   /*
    * 包含 \uXXXX 时，使用 C_JSON_API 兼容解析器
    */
   If Find(Char(92) | "u", &p_str) > 0 Then
      &JsonText = "{" | Char(34) | "_v" | Char(34) | ":" | Char(34) | &p_str | Char(34) | "}";

      &Parser = CreateObject("C_JSON_API:Factory").NewParser();
      &ParseOK = &Parser.Parse(&JsonText);

      If &ParseOK Then
         &Wrapper = &Parser.GetRootObject();
         Return &Wrapper.GetString("_v");
      End-If;
   End-If;

   /*
    * 处理普通 JSON 转义字符
    */
   &BackslashToken = "__PS_JSON_BACKSLASH_TOKEN_7F3A__";
   While Find(&BackslashToken, &p_str) > 0
      &BackslashToken = &BackslashToken | "_";
   End-While;

   &UnEscapeStr = Substitute(&p_str, Char(92) | Char(92), &BackslashToken);
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | Char(34), Char(34));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "/", "/");
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "b", Char(8));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "f", Char(12));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "n", Char(10));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "r", Char(13));
   &UnEscapeStr = Substitute(&UnEscapeStr, Char(92) | "t", Char(9));
   &UnEscapeStr = Substitute(&UnEscapeStr, &BackslashToken, Char(92));

   Return &UnEscapeStr;
end-method;


method JsonHexDigit
   /+ &p_n as Number +/
   /+ Returns String +/

   Local string &HexDigits = "0123456789ABCDEF";

   Return Substring(&HexDigits, &p_n + 1, 1);
end-method;


method JsonHexValue
   /+ &p_c as String +/
   /+ Returns Number +/

   Local string &c;
   Local number &Code;

   &c = Upper(&p_c);
   &Code = Code(&c);

   If &Code >= 48 And
         &Code <= 57 Then
      Return &Code - 48;
   End-If;

   If &Code >= 65 And
         &Code <= 70 Then
      Return &Code - 55;
   End-If;

   Return - 1;
end-method;

class HttpUtil
   method HttpUtil();

   method GetHeaderValue(&p_msg As Message, &p_key As string) Returns string;
end-class;

method HttpUtil

end-method;

method GetHeaderValue
   /+ &p_msg as Message, +/
   /+ &p_key as String +/
   /+ Returns String +/
   Local string &Value;
   Local integer &i;
   Local IBConnectorInfo &IBConnectorInfo;

   &IBConnectorInfo = &p_msg.IBInfo.IBConnectorInfo;
   For &i = 1 To &IBConnectorInfo.GetNumberOfConnectorProperties()
      Local string &PropName = &IBConnectorInfo.GetConnectorPropertiesName(&i);
      If &PropName = &p_key Then
         &Value = &IBConnectorInfo.GetConnectorPropertiesValue(&i);
         Break;
      End-If;
   End-For;

   Return &Value;
end-method;

/* Shared Java reflection bridge. Arrays and objects are allocated by Java,
   without PeopleCode CreateJavaObject/CreateJavaArray. Explicit parameter
   types select a public constructor without guessing overloaded signatures. */
class JavaReflect
   method JavaReflect();
   method ClassForName(&p_name As string) Returns JavaObject;
   method NewArray(&p_component As string, &p_length As integer) Returns JavaObject;
   method Types(&p_types As array of string) Returns JavaObject;
   method Arguments(&p_values As array of any) Returns JavaObject;
   method TypedArguments(&p_types As array of string, &p_values As array of any) Returns JavaObject;
   method ClearArguments(&p_args As JavaObject);
   method Invoke(&p_method As JavaObject, &p_target As JavaObject, &p_args As JavaObject) Returns JavaObject;
   method Call(&p_target As JavaObject, &p_method As string, &p_types As array of string, &p_values As array of any) Returns JavaObject;
   method NewObject(&p_class As string, &p_types As array of string, &p_values As array of any) Returns JavaObject;
   method PrimitiveObject(&p_type As string, &p_value As any) Returns JavaObject;
   method IntegerObject(&p_value As integer) Returns JavaObject;
   method ClassName(&p_value As any) Returns string;
private
   instance JavaObject &ReflectArray;
   instance JavaObject &Probe;
   instance JavaObject &IntProbe;
end-class;

method JavaReflect
   &ReflectArray = GetJavaClass("java.lang.reflect.Array");
   &Probe = %This.NewArray("java.lang.Object", 1);
   &IntProbe = %This.NewArray("int", 1);
end-method;

method ClassForName
   /+ &p_name as String +/
   /+ Returns JavaObject +/
   If &p_name = "int" Then
      Return GetJavaClass("java.lang.Integer").TYPE;
   End-If;
   If &p_name = "long" Then
      Return GetJavaClass("java.lang.Long").TYPE;
   End-If;
   If &p_name = "double" Then
      Return GetJavaClass("java.lang.Double").TYPE;
   End-If;
   If &p_name = "float" Then
      Return GetJavaClass("java.lang.Float").TYPE;
   End-If;
   If &p_name = "short" Then
      Return GetJavaClass("java.lang.Short").TYPE;
   End-If;
   If &p_name = "byte" Then
      Return GetJavaClass("java.lang.Byte").TYPE;
   End-If;
   If &p_name = "boolean" Then
      Return GetJavaClass("java.lang.Boolean").TYPE;
   End-If;
   If &p_name = "char" Then
      Return GetJavaClass("java.lang.Character").TYPE;
   End-If;
   Return GetJavaClass("java.lang.Class").forName(&p_name, True, GetJavaClass("java.lang.ClassLoader").getSystemClassLoader());
end-method;

method NewArray
   /+ &p_component as String, +/
   /+ &p_length as Integer +/
   /+ Returns JavaObject +/
   Local JavaObject &result;
   If &p_length < 0 Then
      throw CreateException(0, 0, "JavaReflect.NewArray: length must be nonnegative");
   End-If;
   &result = &ReflectArray.newInstance(%This.ClassForName(&p_component), &p_length);
   Return &result.getClass().cast(&result);
end-method;

method Types
   /+ &p_types as Array of String +/
   /+ Returns JavaObject +/
   Local JavaObject &result = %This.NewArray("java.lang.Class", &p_types.Len);
   Local integer &i;
   For &i = 1 To &p_types.Len
      &ReflectArray.set(&result, &i - 1, %This.ClassForName(&p_types [&i]));
   End-For;
   Return &result;
end-method;

method Arguments
   /+ &p_values as Array of Any +/
   /+ Returns JavaObject +/
   Local JavaObject &result = %This.NewArray("java.lang.Object", &p_values.Len);
   Local integer &i;
   For &i = 1 To &p_values.Len
      &ReflectArray.set(&result, &i - 1, &p_values [&i]);
   End-For;
   Return &result;
end-method;

method TypedArguments
   /+ &p_types as Array of String, +/
   /+ &p_values as Array of Any +/
   /+ Returns JavaObject +/
   Local JavaObject &args;
   Local integer &i;
   Local string &kind;
   If &p_types.Len <> &p_values.Len Then
      throw CreateException(0, 0, "JavaReflect: parameter and value counts differ");
   End-If;
   &args = %This.Arguments(&p_values);
   For &i = 1 To &p_types.Len
      &kind = &p_types [&i];
      If &kind = "int" Or
            &kind = "long" Or
            &kind = "double" Or
            &kind = "float" Or
            &kind = "short" Or
            &kind = "byte" Or
            &kind = "boolean" Or
            &kind = "char" Then
         &ReflectArray.set(&args, &i - 1, %This.PrimitiveObject(&kind, &p_values [&i]));
      End-If;
   End-For;
   Return &args;
end-method;

method NewObject
   /+ &p_class as String, +/
   /+ &p_types as Array of String, +/
   /+ &p_values as Array of Any +/
   /+ Returns JavaObject +/
   Local JavaObject &targetClass, &constructor, &types, &args, &result;
   &args = %This.TypedArguments(&p_types, &p_values);
   &targetClass = %This.ClassForName(&p_class);
   &types = %This.Types(&p_types);
   &constructor = &targetClass.getConstructor(&types);
   try
      &result = &constructor.newInstance(&args);
   catch Exception &error
      %This.ClearArguments(&args);
      throw &error;
   end-try;
   %This.ClearArguments(&args);
   Return &result.getClass().cast(&result);
end-method;

method Call
   /+ &p_target as JavaObject, +/
   /+ &p_method as String, +/
   /+ &p_types as Array of String, +/
   /+ &p_values as Array of Any +/
   /+ Returns JavaObject +/
   Local JavaObject &method, &args;
   &args = %This.TypedArguments(&p_types, &p_values);
   &method = &p_target.getClass().getMethod(&p_method, %This.Types(&p_types));
   Return %This.Invoke(&method, &p_target, &args);
end-method;

method ClearArguments
   /+ &p_args as JavaObject +/
   Local integer &i;
   For &i = 0 To &ReflectArray.getLength(&p_args) - 1
      &ReflectArray.set(&p_args, &i, Null);
   End-For;
end-method;

method Invoke
   /+ &p_method as JavaObject, +/
   /+ &p_target as JavaObject, +/
   /+ &p_args as JavaObject +/
   /+ Returns JavaObject +/
   Local JavaObject &result;
   try
      &result = &p_method.invoke(&p_target, &p_args);
   catch Exception &error
      %This.ClearArguments(&p_args);
      throw &error;
   end-try;
   %This.ClearArguments(&p_args);
   If &result = Null Then
      Return Null;
   End-If;
   Return &result.getClass().cast(&result);
end-method;

method PrimitiveObject
   /+ &p_type as String, +/
   /+ &p_value as Any +/
   /+ Returns JavaObject +/
   Local JavaObject &box, &result;
   Local string &text;
   If &p_type = "int" Then
      Return %This.IntegerObject(&p_value);
   End-If;
   If &p_type <> "long" And
         &p_type <> "double" And
         &p_type <> "float" And
         &p_type <> "short" And
         &p_type <> "byte" And
         &p_type <> "boolean" And
         &p_type <> "char" Then
      throw CreateException(0, 0, "JavaReflect.PrimitiveObject: unsupported primitive " | &p_type);
   End-If;
   &box = %This.NewArray(&p_type, 1);
   If &p_type = "long" Then
      &ReflectArray.setLong(&box, 0, &p_value);
   End-If;
   If &p_type = "double" Then
      &ReflectArray.setDouble(&box, 0, &p_value);
   End-If;
   If &p_type = "float" Then
      &ReflectArray.setFloat(&box, 0, &p_value);
   End-If;
   If &p_type = "short" Then
      &ReflectArray.setShort(&box, 0, &p_value);
   End-If;
   If &p_type = "byte" Then
      &ReflectArray.setByte(&box, 0, &p_value);
   End-If;
   If &p_type = "boolean" Then
      &ReflectArray.setBoolean(&box, 0, &p_value);
   End-If;
   If &p_type = "char" Then
      &text = String(&p_value);
      If Len(&text) <> 1 Then
         throw CreateException(0, 0, "JavaReflect: char requires one character");
      End-If;
      /* PeopleCode has no Java char primitive; obtain char[] inside Java. */
      &box = %This.NewObject("java.lang.String", CreateArray("java.lang.String"), CreateArrayAny(&text)).toCharArray();
   End-If;
   &result = &ReflectArray.get(&box, 0);
   Return &result.getClass().cast(&result);
end-method;

method IntegerObject
   /+ &p_value as Integer +/
   /+ Returns JavaObject +/
   Local JavaObject &result;
   &ReflectArray.setInt(&IntProbe, 0, &p_value);
   &result = &ReflectArray.get(&IntProbe, 0);
   Return &result.getClass().cast(&result);
end-method;

method ClassName
   /+ &p_value as Any +/
   /+ Returns String +/
   Local string &name;
   try
      &ReflectArray.set(&Probe, 0, &p_value);
      &name = &ReflectArray.get(&Probe, 0).getClass().getName();
   catch Exception &error
      &ReflectArray.set(&Probe, 0, Null);
      throw &error;
   end-try;
   /* Do not retain the last caller value between requests to this instance. */
   &ReflectArray.set(&Probe, 0, Null);
   Return &name;
end-method;

import PS_PT:Integration:IRequestHandler;
import C_JSON_API:*;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:HttpClient:HttpUtil;

class Login implements PS_PT:Integration:IRequestHandler
   method Login();

   method OnRequest(&message As Message) Returns Message;
private
   Constant &OperationName = "PSTOKEN_GET";
   Constant &DatetimeFormat = "yyyy-MM-dd HH:mm:ss";

   instance C_JSON_API:JsonUtil &JsonUtil;
   instance C_COMMONS_PKG:HttpClient:HttpUtil &HttpUtil;
end-class;


method Login
   &JsonUtil = create C_JSON_API:JsonUtil();
   &HttpUtil = create C_COMMONS_PKG:HttpClient:HttpUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local C_JSON_API:JSONObject &RespObject;
   Local string &ErrorTxt, &LanguageCd, &LanguageInstall, &PropValue;
   Local integer &SessionTimeOut;

   try
      &LanguageCd = &HttpUtil.GetHeaderValue(&message, "LanguageCd");

      /* 如果有指定语言，切换语言 */
      If All(&LanguageCd) Then
         SQLExec("SELECT 'Y' FROM PSLANGUAGES WHERE LANGUAGE_CD = :1 AND INSTALLED = 1", &LanguageCd, &LanguageInstall);
         If &LanguageInstall = "Y" Then
            SetLanguage(&LanguageCd);
         Else
            &ErrorTxt = "不支持的语言：" | &LanguageCd;
         End-If;
      End-If;

      If All(&ErrorTxt) Then
         &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 1, &ErrorTxt);
         Return &RespMsg;
      End-If;

      &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
      &RespObject.AddProperty("userid", %UserId);
      &RespObject.AddProperty("description", %UserDescription);
      &RespObject.AddProperty("psToken", %AuthenticationToken);
      &RespObject.AddProperty("emplid", %EmployeeId);
      &RespObject.AddProperty("language", %Language);

      /* 获取Token失效时间(由PeopleTools-安全性-安全性对象-单点登录中的Token过期时间决定) */
      SQLExec("SELECT TIMEOUTMINUTES FROM PSOPTIONS", &SessionTimeOut);
      &RespObject.AddProperty("TokenExpireTime", DateTimeToLocalizedString((%Datetime + &SessionTimeOut * 60), &DatetimeFormat));

      &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "遇到未知异常：" | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

import C_JSON_API:JSONArray;
import C_JSON_API:JSONObject;
import C_JSON_API:JSONNode;
import C_JSON_API:CustomApi:JSONStorage;

/* C_JSON_API:CustomApi:JSONArray —— 实现 C_JSON_API:JSONArray 接口；
 * 方法集对齐 8.57 内置 JsonArray（22 个方法 + Size 只读属性）。
 *
 * 注意（实测踩过的坑，改动前务必看）：
 *   1) JSONArray/JSONObject/JSONNode 与内置类同名（PeopleCode 大小写不敏感），
 *      所以所有类型引用必须写全限定名 C_JSON_API:CustomApi:XXX，且仍要 import；
 *   2) create 必须跟全限定名；
 *   3) 参数名一律 p_ 前缀，避免与实例变量重名（大小写不敏感）；
 *   4) 没有 ElseIf，用嵌套 If/Else；
 *   5) 有返回值的方法不能当语句调用，必须赋值给局部变量。
 */
class JSONArray implements C_JSON_API:JSONArray
   method JSONArray();

   method Store() Returns any;
   method NodeIndex() Returns integer;
   method BindCode(&p_store As C_JSON_API:CustomApi:JSONStorage, &p_idx As integer);

   method AddElement(&p_value As any);
   /* 显式类型扩展（非 8.57 API）：类型由调用方声明，绕开弱类型判定 */
   method AddStringElement(&p_value As any);
   method AddNumberElement(&p_value As any);
   method AddBooleanElement(&p_value As any);
   method AddDateElement(&p_value As any);
   method AddTimeElement(&p_value As any);
   method AddDateTimeElement(&p_value As any);
   method AddJsonArrayElement(&p_name As string, &p_arr As C_JSON_API:JSONArray);
   method AddJsonObjectElement(&p_name As string, &p_obj As C_JSON_API:JSONObject);
   method AddNullElement();
   method GetAsString(&p_idx As integer) Returns string;
   method GetBoolean(&p_idx As integer) Returns boolean;
   method GetDate(&p_idx As integer) Returns date;
   method GetDateTime(&p_idx As integer) Returns datetime;
   method GetFloat(&p_idx As integer) Returns float;
   method GetInteger(&p_idx As integer) Returns integer;
   method GetJsonArray(&p_idx As integer) Returns C_JSON_API:JSONArray;
   method GetJsonNode(&p_idx As integer) Returns C_JSON_API:JSONNode;
   method GetJsonObject(&p_idx As integer) Returns C_JSON_API:JSONObject;
   method GetNumber(&p_idx As integer) Returns number;
   method GetString(&p_idx As integer) Returns string;
   method GetTime(&p_idx As integer) Returns time;
   method GetType(&p_idx As integer) Returns integer;
   method IsNull(&p_idx As integer) Returns boolean;
   method Length() Returns integer;
   method Pop();
   method Remove(&p_idx As integer);
   method ToString() Returns string;
   property integer Size get;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance integer &NodeIdx;

   method ChildIdx(&p_idx As integer) Returns integer;
   method AddSubtree(&p_name As string, &p_src As C_JSON_API:CustomApi:JSONStorage, &p_srcIdx As integer);
end-class;

method JSONArray
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
   &NodeIdx = &StoreRef.NewNode("array", "", "");
end-method;

method Store
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONArray.Store +/
   Return &StoreRef;
end-method;

method NodeIndex
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONArray.NodeIndex +/
   Return &NodeIdx;
end-method;

method BindCode
   /+ &p_store as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &p_idx as Integer +/
   &StoreRef = &p_store;
   &NodeIdx = &p_idx;
end-method;

method ChildIdx
   /+ &p_idx as Integer +/
   /+ Returns Integer +/
   Return &StoreRef.ChildAt(&NodeIdx, &p_idx);
end-method;

method AddSubtree
   /+ &p_name as String, +/
   /+ &p_src as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &p_srcIdx as Integer +/
   Local integer &ignored;
   &ignored = &StoreRef.ImportSubtree(&NodeIdx, &p_name, &p_src, &p_srcIdx);
end-method;

method AddElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddValueNode(&NodeIdx, "", &p_value);
end-method;

method AddStringElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddStringElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(&NodeIdx, "", "string", &p_value);
end-method;

method AddNumberElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddNumberElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(&NodeIdx, "", "number", &p_value);
end-method;

method AddBooleanElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddBooleanElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(&NodeIdx, "", "boolean", &p_value);
end-method;

method AddDateElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddDateElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(&NodeIdx, "", "date", &p_value);
end-method;

method AddTimeElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddTimeElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(&NodeIdx, "", "time", &p_value);
end-method;

method AddDateTimeElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONArray.AddDateTimeElement +/
   Local integer &ignored;
