method AddJsonArrayElement
   /+ &p_name as String, +/
   /+ &p_arr as C_JSON_API:JSONArray +/
   /+ Extends/implements C_JSON_API:JSONArray.AddJsonArrayElement +/
   /* 数组元素没有键名：与你们现有代码 AddJsonObjectElement("", &obj) 的用法一致 */
   Local C_JSON_API:CustomApi:JSONStorage &s;
   &s = &p_arr.Store();
   %This.AddSubtree("", &s, &p_arr.NodeIndex());
end-method;

