import C_JSON_API:JSONBuilder;
import C_JSON_API:JSONNode;
import C_JSON_API:CustomApi:JSONStorage;

/* C_JSON_API:CustomApi:JSONBuilder —— 实现 C_JSON_API:JSONBuilder 接口；
 * 方法集对齐 8.57 内置 JsonBuilder（13 个方法 + BuildMode 只读属性）。
 *
 * 与内置一致的行为：根节点恒为 object（即便第一次调用是 StartArray）；
 * StartXReturnsTrue 成功返回 True；GetBuildMode 1=OBJECT 2=ARRAY 0=NONE
 * （内置还定义了 3=JSON_BUILD_MODE_MEMBER，本实现不产生该状态）。
 * 名称传空串时：父容器是数组→按元素追加；父容器是对象→属性名为空串。
 */
class JSONBuilder implements C_JSON_API:JSONBuilder
   method JSONBuilder();

   method StartObject(&p_name As string);
   method StartObjectReturnsTrue(&p_name As string) Returns boolean;
   method EndObject(&p_name As string);
   method StartArray(&p_name As string);
   method StartArrayReturnsTrue(&p_name As string) Returns boolean;
   method EndArray(&p_name As string);
   method AddProperty(&p_name As string, &p_value As any);
   method AddNullProperty(&p_name As string);
   method AddElement(&p_value As any);
   method AddNullElement();
   /* 显式类型扩展（非 8.57 API）：属性版与元素版，类型由调用方声明 */
   method AddString(&p_name As string, &p_value As any);
   method AddNumber(&p_name As string, &p_value As any);
   method AddBoolean(&p_name As string, &p_value As any);
   method AddDate(&p_name As string, &p_value As any);
   method AddTime(&p_name As string, &p_value As any);
   method AddDateTime(&p_name As string, &p_value As any);
   method AddStringElement(&p_value As any);
   method AddNumberElement(&p_value As any);
   method AddBooleanElement(&p_value As any);
   method AddDateElement(&p_value As any);
   method AddTimeElement(&p_value As any);
   method AddDateTimeElement(&p_value As any);
   method GetBuildMode() Returns integer;
   method GetRootNode() Returns C_JSON_API:JSONNode;
   method ToString() Returns string;
   property integer BuildMode get;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance array of number &StkNode;
   instance integer &RootIdx;

   method EnsureRoot();
   method CurIdx() Returns integer;
   method OpenNode(&p_kind As string, &p_name As string) Returns integer;
   method PopLevel();
end-class;

method JSONBuilder
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
   &StkNode = CreateArrayRept(0, 0);
   &RootIdx = 0;
end-method;

method EnsureRoot
   /* 内置行为：根恒为 object */
   If &RootIdx = 0 Then
      &RootIdx = &StoreRef.NewNode("object", "", "");
      &StkNode.Push(&RootIdx);
   End-If;
end-method;

method CurIdx
   /+ Returns Integer +/
   %This.EnsureRoot();
   Return &StkNode [&StkNode.Len];
end-method;

method OpenNode
   /+ &p_kind as String, +/
   /+ &p_name as String +/
   /+ Returns Integer +/
   /* 在当前容器下新建子容器并压栈；父容器是数组时忽略名字。
      特例：首次空名 Start（栈只有根层且根还没有子节点）视作“激活根”，
      与内置 JsonBuilder 行为对齐（首个空名 StartObject 不产生无名子层）。 */
   Local integer &parent, &node;
   Local boolean &ok;
   %This.EnsureRoot();
   If &p_name = "" And
         &StkNode.Len = 1 And
         &StoreRef.ChildCount(&RootIdx) = 0 Then
      Return &RootIdx;
   End-If;
   &parent = &StkNode [&StkNode.Len];
   &node = &StoreRef.NewNode(&p_kind, "", "");
   If &StoreRef.Kind(&parent) = "array" Then
      &ok = &StoreRef.AppendChild(&parent, &node, "");
   Else
      &ok = &StoreRef.AppendChild(&parent, &node, &p_name);
   End-If;
   &StkNode.Push(&node);
   Return &node;
end-method;

method StartObject
   /+ &p_name as String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.StartObject +/
   Local integer &ignored;
   &ignored = %This.OpenNode("object", &p_name);
end-method;

method StartObjectReturnsTrue
   /+ &p_name as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONBuilder.StartObjectReturnsTrue +/
   Local integer &ignored;
   &ignored = %This.OpenNode("object", &p_name);
   Return True;
end-method;

method StartArray
   /+ &p_name as String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.StartArray +/
   Local integer &ignored;
   &ignored = %This.OpenNode("array", &p_name);
end-method;

method StartArrayReturnsTrue
   /+ &p_name as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONBuilder.StartArrayReturnsTrue +/
   Local integer &ignored;
   &ignored = %This.OpenNode("array", &p_name);
   Return True;
end-method;

method EndObject
   /+ &p_name as String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.EndObject +/
   %This.PopLevel();
end-method;

method EndArray
   /+ &p_name as String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.EndArray +/
   %This.PopLevel();
end-method;

method AddProperty
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddProperty +/
   Local integer &ignored;
   &ignored = &StoreRef.AddValueNode(%This.CurIdx(), &p_name, &p_value);
end-method;

method AddNullProperty
   /+ &p_name as String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddNullProperty +/
   Local integer &ignored;
   &ignored = &StoreRef.AddValueNode(%This.CurIdx(), &p_name, Null);
end-method;

method AddElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddValueNode(%This.CurIdx(), "", &p_value);
end-method;

method AddNullElement
   /+ Extends/implements C_JSON_API:JSONBuilder.AddNullElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddValueNode(%This.CurIdx(), "", Null);
end-method;

method AddString
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddString +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "string", &p_value);
end-method;

method AddNumber
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddNumber +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "number", &p_value);
end-method;

method AddBoolean
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddBoolean +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "boolean", &p_value);
end-method;

method AddDate
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddDate +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "date", &p_value);
end-method;

method AddTime
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddTime +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "time", &p_value);
end-method;

method AddDateTime
   /+ &p_name as String, +/
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddDateTime +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), &p_name, "datetime", &p_value);
end-method;

method AddStringElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddStringElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "string", &p_value);
end-method;

method AddNumberElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddNumberElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "number", &p_value);
end-method;

method AddBooleanElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddBooleanElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "boolean", &p_value);
end-method;

method AddDateElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddDateElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "date", &p_value);
end-method;

method AddTimeElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddTimeElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "time", &p_value);
end-method;

method AddDateTimeElement
   /+ &p_value as Any +/
   /+ Extends/implements C_JSON_API:JSONBuilder.AddDateTimeElement +/
   Local integer &ignored;
   &ignored = &StoreRef.AddTypedNode(%This.CurIdx(), "", "datetime", &p_value);
end-method;

method PopLevel
   /* 至少保留根层 */
   %This.EnsureRoot();
   If &StkNode.Len > 1 Then
      &StkNode.Len = &StkNode.Len - 1;
   End-If;
end-method;


method GetBuildMode
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONBuilder.GetBuildMode +/
   Local integer &n;
   %This.EnsureRoot();
   &n = &StkNode [&StkNode.Len];
   If &StoreRef.Kind(&n) = "object" Then
      Return 1;
   End-If;
   If &StoreRef.Kind(&n) = "array" Then
      Return 2;
   End-If;
   Return 0;
end-method;

method GetRootNode
   /+ Returns C_JSON_API:JSONNode +/
   /+ Extends/implements C_JSON_API:JSONBuilder.GetRootNode +/
   Local object &nd;
   %This.EnsureRoot();
   &nd = CreateObject("C_JSON_API:CustomApi:JSONNode");
   &nd.BindCode(&StoreRef, &RootIdx);
   Return &nd;
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONBuilder.ToString +/
   %This.EnsureRoot();
   Return &StoreRef.ToJson(&RootIdx);
end-method;

get BuildMode
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONBuilder.BuildMode +/
   /* 0=NONE 1=OBJECT 2=ARRAY（复用 GetBuildMode 的行为） */
   Return %This.GetBuildMode();
end-get;

import C_JSON_API:JSONNode;
import C_JSON_API:JSONArray;
import C_JSON_API:JSONObject;
import C_JSON_API:JSONValue;
import C_JSON_API:CustomApi:JSONStorage;

/* C_JSON_API:CustomApi:JSONNode
 * 实现 C_JSON_API:JSONNode 接口；方法集对齐 8.57 内置 JsonNode
 * （31 个方法 + NodeType / ValueType 只读属性）。
 *
 * 与内置一致的语义：
 *   - 节点持有 (JSONStorage, 下标)，所以通过 GetJsonObject/GetJsonArray/GetJsonNode
 *     拿到的子节点与原对象共享同一份存储，SetNull()/SetString() 会改到父对象；
 *   - SetJsonObject/SetJsonArray/SetJsonValue 是“深拷贝进来”（跨文档也支持）。
 * 类型码：GetNodeType 0=NULL 1=OBJECT 2=ARRAY 3=VALUE
 *         GetValueType 0=INVALID 1=INT 2=FLOAT 3=DOUBLE 4=NUMBER 5=BOOLEAN
 *                      6=STRING 7=NULL 8=DATE 9=TIME 10=DATETIME
 */
class JSONNode implements C_JSON_API:JSONNode
   method JSONNode();

   method Store() Returns any;
   method NodeIndex() Returns integer;
   method BindCode(&p_store As C_JSON_API:CustomApi:JSONStorage, &p_idx As integer);

   method GetBoolean() Returns boolean;
   method GetFloat() Returns float;
   method GetInteger() Returns integer;
   method GetJsonArray() Returns C_JSON_API:JSONArray;
   method GetJsonObject() Returns C_JSON_API:JSONObject;
   method GetJsonValue() Returns C_JSON_API:JSONValue;
   method GetNodeType() Returns integer;
   method GetNumber() Returns number;
   method GetParentNode() Returns C_JSON_API:JSONNode;
   method GetString() Returns string;
   method GetValueType() Returns integer;
   method IsJsonArray() Returns boolean;
   method IsJsonObject() Returns boolean;
   method IsJsonValue() Returns boolean;
   method IsNull() Returns boolean;
   method SetBoolean(&p_value As boolean);
   method SetDate(&p_value As date);
   method SetDateTime(&p_value As datetime);
   method SetFalse();
   method SetFloat(&p_value As float);
   method SetInteger(&p_value As integer);
   method SetJsonArray(&p_arr As C_JSON_API:JSONArray);
   method SetJsonObject(&p_obj As C_JSON_API:JSONObject);
   method SetJsonValue(&p_value As C_JSON_API:JSONValue);
   method SetNodeName(&p_name As string);
   method SetNull();
   method SetNumber(&p_value As number);
   method SetString(&p_value As string);
   method SetTime(&p_value As time);
   method SetTrue();
   method ToString() Returns string;
   property integer NodeType get;
   property integer ValueType get;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance integer &NodeIdx;
   instance string &KObj;
   instance string &KArr;
   instance string &KStr;
   instance string &KNum;
   instance string &KBool;
   instance string &KNull;
   instance string &KDate;
   instance string &KTime;
   instance string &KDttm;

   method InitKinds();
   method KindIs(&p_k As string) Returns boolean;
   method SetScalarCode(&p_kindStr As string, &p_sub As string, &p_txt As string);
end-class;

method JSONNode
   %This.InitKinds();
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
   &NodeIdx = &StoreRef.NewNode(&KNull, "", "null");
end-method;

method InitKinds
   &KObj = "object";
   &KArr = "array";
   &KStr = "string";
   &KNum = "number";
   &KBool = "boolean";
   &KNull = "null";
   &KDate = "date";
   &KTime = "time";
   &KDttm = "datetime";
end-method;

method KindIs
   /+ &p_k as String +/
   /+ Returns Boolean +/
   Local string &k;
   &k = &StoreRef.Kind(&NodeIdx);
   If &k = &p_k Then
      Return True;
   End-If;
   Return False;
end-method;

method SetScalarCode
   /+ &p_kindStr as String, +/
   /+ &p_sub as String, +/
   /+ &p_txt as String +/
   Local boolean &ok;
   &ok = &StoreRef.SetScalar(&NodeIdx, &p_kindStr, &p_sub, &p_txt);
end-method;

method Store
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONNode.Store +/
   Return &StoreRef;
end-method;

method NodeIndex
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONNode.NodeIndex +/
   Return &NodeIdx;
end-method;

method BindCode
   /+ &p_store as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &p_idx as Integer +/
   &StoreRef = &p_store;
   &NodeIdx = &p_idx;
end-method;

method GetNodeType
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONNode.GetNodeType +/
   Return &StoreRef.NodeType(&NodeIdx);
end-method;

method GetValueType
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONNode.GetValueType +/
   Return &StoreRef.ValueType(&NodeIdx);
end-method;

method GetString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONNode.GetString +/
   Return &StoreRef.AsString(&NodeIdx);
end-method;

method GetNumber
   /+ Returns Number +/
   /+ Extends/implements C_JSON_API:JSONNode.GetNumber +/
   Return &StoreRef.AsNumber(&NodeIdx);
end-method;

method GetInteger
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONNode.GetInteger +/
   Return &StoreRef.AsInteger(&NodeIdx);
end-method;

method GetFloat
   /+ Returns Float +/
   /+ Extends/implements C_JSON_API:JSONNode.GetFloat +/
   Return &StoreRef.AsNumber(&NodeIdx);
end-method;

method GetBoolean
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONNode.GetBoolean +/
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "true" Then
      Return True;
   End-If;
   Return False;
end-method;

method IsNull
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONNode.IsNull +/
   Return %This.KindIs(&KNull);
end-method;

method IsJsonObject
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONNode.IsJsonObject +/
   Return %This.KindIs(&KObj);
end-method;

method IsJsonArray
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONNode.IsJsonArray +/
   Return %This.KindIs(&KArr);
end-method;

method IsJsonValue
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONNode.IsJsonValue +/
   Local string &k;
   &k = &StoreRef.Kind(&NodeIdx);
   If &k = &KObj Or
         &k = &KArr Or
         &k = &KNull Or
         &k = "" Then
      Return False;
   End-If;
   Return True;
end-method;

method GetJsonObject
   /+ Returns C_JSON_API:JSONObject +/
   /+ Extends/implements C_JSON_API:JSONNode.GetJsonObject +/
   Local object &o;
   &o = CreateObject("C_JSON_API:CustomApi:JSONObject");
   &o.BindCode(&StoreRef, &NodeIdx);
   Return &o;
