/* C_JSON_API:CustomApi:JSONObject —— 实现 C_JSON_API:JSONObject 接口；
 * 方法集对齐 8.57 内置 JsonObject（23 个方法 + ChildCount 只读属性）。
 * 踩坑说明同 JSONArray.pcode 头部。
 */
class JSONObject implements C_JSON_API:JSONObject
   method JSONObject();

   method Store() Returns any;
   method NodeIndex() Returns integer;
   method BindCode(&p_store As C_JSON_API:CustomApi:JSONStorage, &p_idx As integer);

   method AddProperty(&p_name As string, &p_value As any);
   /* 显式类型扩展（非 8.57 API）：绕开弱类型判定，类型由调用方声明 */
   method AddString(&p_name As string, &p_value As any);
   method AddNumber(&p_name As string, &p_value As any);
   method AddBoolean(&p_name As string, &p_value As any);
   method AddDate(&p_name As string, &p_value As any);
   method AddTime(&p_name As string, &p_value As any);
   method AddDateTime(&p_name As string, &p_value As any);
   method AddJsonObject(&p_name As string, &p_obj As C_JSON_API:JSONObject);
   method AddJsonArray(&p_name As string, &p_arr As C_JSON_API:JSONArray);
   method GetString(&p_name As string) Returns string;
   method GetAsString(&p_name As string) Returns string;
   method GetInteger(&p_name As string) Returns integer;
   method GetNumber(&p_name As string) Returns number;
   method GetFloat(&p_name As string) Returns float;
   method GetBoolean(&p_name As string) Returns boolean;
   method GetBooleanProperty(&p_name As string) Returns boolean;
   method GetDate(&p_name As string) Returns date;
   method GetDateTime(&p_name As string) Returns datetime;
   method GetTime(&p_name As string) Returns time;
   method GetJsonObject(&p_name As string) Returns C_JSON_API:JSONObject;
   method GetJsonArray(&p_name As string) Returns C_JSON_API:JSONArray;
   method GetJsonNode(&p_name As string) Returns C_JSON_API:JSONNode;
   method GetChildCount() Returns integer;
   method GetPropertyNameAt(&p_idx As integer) Returns string;
   method IsExist(&p_name As string) Returns boolean;
   method IsNullProperty(&p_name As string) Returns boolean;
   method IsJsonObject(&p_name As string) Returns boolean;
   method IsJsonArray(&p_name As string) Returns boolean;
   method ToString() Returns string;
   property integer ChildCount get;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance integer &NodeIdx;

   method ChildIdx(&p_name As string) Returns integer;
   method KindIs(&p_name As string, &p_kind As string) Returns boolean;
end-class;

method JSONObject
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
   &NodeIdx = &StoreRef.NewNode("object", "", "");
end-method;

method Store
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONObject.Store +/
   Return &StoreRef;
end-method;

method NodeIndex
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONObject.NodeIndex +/
