method IsExist
   /+ &p_name as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONObject.IsExist +/
   Local integer &c;
   &c = %This.ChildIdx(&p_name);
   If &c > 0 Then
      Return True;
   End-If;
   Return False;
end-method;

method IsNullProperty
   /+ &p_name as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONObject.IsNullProperty +/
   /* 比 8.55 内置实现更规整：内置版对取值为 0 的属性会误判为 null（见 C_PORTAL_PKG:Util:JSONObject
      里的 workaround 注释），这里只按节点类型判断 */
   Return %This.KindIs(&p_name, "null");
end-method;

method IsJsonObject
   /+ &p_name as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONObject.IsJsonObject +/
