end-get;

import C_JSON_API:JSONParser;
import C_JSON_API:JSONObject;
import C_JSON_API:CustomApi:JSONStorage;

/* C_JSON_API:CustomApi:JSONParser —— 实现 C_JSON_API:JSONParser 接口；
 * 方法集对齐 8.57 内置 JsonParser：Parse / GetRootObject / ToString 三个方法；
 * 这里额外提供 GetError() 便于排障（超集，不影响兼容性）。
 */
class JSONParser implements C_JSON_API:JSONParser
   method JSONParser();
   method Parse(&p_src As string) Returns boolean;
   method GetRootObject() Returns C_JSON_API:JSONObject;
   method ToString() Returns string;
   method GetError() Returns string;
private
   instance boolean &Parsed;
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
end-class;

method JSONParser
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
end-method;

method Parse
   /+ &p_src as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONParser.Parse +/
   &Parsed = &StoreRef.Parse(&p_src);
   Return &Parsed;
end-method;

method GetRootObject
   /+ Returns C_JSON_API:JSONObject +/
   /+ Extends/implements C_JSON_API:JSONParser.GetRootObject +/
   Local object &o;
   If Not &Parsed Or
         &StoreRef.Kind(&StoreRef.Root()) <> "object" Then
      Return Null;
   End-If;
   &o = CreateObject("C_JSON_API:CustomApi:JSONObject");
   &o.BindCode(&StoreRef, &StoreRef.Root());
   Return &o;
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONParser.ToString +/
   If Not &Parsed Then
      Return "";
   End-If;
   Return &StoreRef.ToJson(&StoreRef.Root());
end-method;

method GetError
   /+ Returns String +/
   Return &StoreRef.GetError();
end-method;

import C_JSON_API:Scalar;

/* ---------------------------------------------------------------------------
 * 文件：JSONStorage.pcode
 * 包：C_JSON_API:PeopleCode    类：JSONStorage
 *
 * 定位：C_JSON_API JSON 兼容层的“文档引擎”。JSONObject / JSONArray / JSONNode /
 *       JSONParser / JSONBuilder 都是它的薄包装：每个包装对象持有一份
 *       (JSONStorage 实例, 节点下标)，因此 Get 出来的子对象与原对象共享同一份存储，
 *       这正是内置 JsonNode.SetNull() 能改到父对象的语义所要求的。
 *
 * 存储模型（竞技场，1 基下标，0 表示“无”）：
 *   &Kind      object / array / string / number / boolean / null / date / time / datetime
 *   &SubKind   数字细分 int / float / number；其它为空
 *   &Text      标量文本（数字保留原文，不 Value() 转换，往返不丢精度）
 *   &PropName  作为对象成员时的属性名
 *   &Parent &FirstChild &LastChild &NextSibling
 *
 * 解析：显式栈的迭代状态机，不递归；扫描用 Find 跳段。
 * 序列化：容器游标栈的迭代遍历，输出用 array of string + Join("")。
 *
 * 只依赖 PeopleCode 内建函数，不依赖 8.55+ 的 JSON 类，不依赖 jar。
 * ------------------------------------------------------------------------ */

class JSONStorage
   method JSONStorage();

   /* 解析 / 序列化 */
   method Parse(&srcStore As string) Returns boolean;
   method GetError() Returns string;
   method Root() Returns integer;
   method ToJson(&idx As integer) Returns string;

   /* 只读查询 */
   method NewNode(&kindStr As string, &subKindStr As string, &textStr As string) Returns integer;
   method Kind(&idx As integer) Returns string;
   method SubKind(&idx As integer) Returns string;
   method Text(&idx As integer) Returns string;
   method NodeType(&idx As integer) Returns integer;
   method ValueType(&idx As integer) Returns integer;
   method NameOf(&idx As integer) Returns string;
   method ParentOf(&idx As integer) Returns integer;
   method IsContainer(&idx As integer) Returns boolean;
   method ChildCount(&idx As integer) Returns integer;
   method ChildAt(&idx As integer, &i As integer) Returns integer;
   method ChildNameAt(&idx As integer, &i As integer) Returns string;
   method ChildIndexByName(&idx As integer, &nm As string) Returns integer;

   /* 结构修改 */
   method AppendChild(&parIdx As integer, &childIdx As integer, &nm As string) Returns boolean;
   method DetachNode(&idx As integer) Returns boolean;
   method RemoveChildAt(&parIdx As integer, &i As integer) Returns boolean;
   method RemoveLastChild(&parIdx As integer) Returns boolean;
   method ClearNode(&idx As integer);
   method SetScalar(&idx As integer, &kindStr As string, &subKindStr As string, &textStr As string) Returns boolean;
   method SetName(&idx As integer, &nm As string) Returns boolean;
   method SetNull(&idx As integer) Returns boolean;

   /* 跨文档深拷贝（迭代，不递归） */
   method ImportSubtree(&parIdx As integer, &nm As string, &srcStore As C_JSON_API:CustomApi:JSONStorage, &srcNode As integer) Returns integer;
   method ReplaceWith(&idx As integer, &srcStore As C_JSON_API:CustomApi:JSONStorage, &srcNode As integer) Returns boolean;

   /* 取值 */
   method AsString(&idx As integer) Returns string;
   method AsNumber(&idx As integer) Returns number;
   method AsInteger(&idx As integer) Returns integer;
   method AddValueNode(&parIdx As integer, &nm As string, &value As any) Returns integer;
   /* 显式类型写入（C_JSON_API 扩展，非 8.57 API）：kindStr 取 string/number/boolean/date/time/datetime */
   method AddTypedNode(&parIdx As integer, &nm As string, &kindStr As string, &value As any) Returns integer;

protected
   method Reset();
   method SetRoot(&p_idx As integer);
   method Fail(&msg As string) Returns boolean;
private
   instance C_JSON_API:Scalar &ScalarHelper;

   Constant &KObj = "object";
   Constant &KArr = "array";
   Constant &KStr = "string";
   Constant &KNum = "number";
   Constant &KBool = "boolean";
   Constant &KNull = "null";
   Constant &KDate = "date";
   Constant &KTime = "time";
   Constant &KDttm = "datetime";
   Constant &Digits = "0123456789";
   Constant &Hex = "0123456789abcdef";

   instance array of string &Kind;
   instance array of string &SubKind;
   instance array of string &Text;
   instance array of string &PropName;
   instance array of number &Parent;
   instance array of number &FirstChild;
   instance array of number &LastChild;
   instance array of number &NextSibling;

   instance array of number &StackNode;
   instance array of string &StackKind;
   instance string &Src;
   instance integer &SrcLen;
   instance integer &Pos;
   instance string &Expect;
   instance string &Err;
   instance string &PendingName;
   instance string &StrVal;
   instance integer &NumEnd;
   instance integer &RootIdx;
   instance integer &MaxDepth;
   instance string &DQ;
   instance string &BS;
   instance string &Ws;

   method NumToStr(&n As integer) Returns string;
   method Describe(&ch As string) Returns string;
   method CharAt(&i As integer) Returns string;
   method Locate(&needle As string, &start As integer) Returns number;
   method Snippet() Returns string;
   method SkipWs();
   method IsWsAt(&i As integer) Returns boolean;
   method IsDigitAt(&i As integer) Returns boolean;
   method AllDigits(&s As string) Returns boolean;
   method IsCloser(&ch As string) Returns boolean;
   method AddScalarNode(&parIdx As integer, &nm As string, &kindStr As string, &subKindStr As string, &textStr As string) Returns integer;
   method StackPush(&n As integer, &k As string);
   method StackPop();
   method StackTopKind() Returns string;
   method Attach(&node As integer);
   method OpenNode(&k As string) Returns boolean;
   method ScalarNode(&k As string, &sub As string, &txt As string);
   method ExpectKey() Returns boolean;
   method AfterValue();
   method CloseContainer();
   method ReadString() Returns boolean;
   method CleanStringPiece(&p_piece As string) Returns boolean;
   method DecodeEscape(&e As string) Returns string;
   method Hex4(&s As string) Returns number;
   method ToChar(&code As integer) Returns string;
   method ScanNumber() Returns boolean;
   method TerminatorOk() Returns boolean;
   method Literal(&word As string) Returns boolean;
   method EscapeStr(&s As string) Returns string;
   method ScalarText(&idx As integer) Returns string;
end-class;


method JSONStorage
   &ScalarHelper = create C_JSON_API:Scalar();
   &MaxDepth = 64;
   &DQ = Char(34);
   &BS = Char(92);
   &Ws = " " | Char(9) | Char(13) | Char(10);
   %This.Reset();
end-method;


method Reset
   &Kind = CreateArrayRept("", 0);
   &SubKind = CreateArrayRept("", 0);
   &Text = CreateArrayRept("", 0);
   &PropName = CreateArrayRept("", 0);
   &Parent = CreateArrayRept(0, 0);
   &FirstChild = CreateArrayRept(0, 0);
   &LastChild = CreateArrayRept(0, 0);
   &NextSibling = CreateArrayRept(0, 0);
   &StackNode = CreateArrayRept(0, 0);
   &StackKind = CreateArrayRept("", 0);
   &Src = "";
   &SrcLen = 0;
   &Pos = 1;
   &Expect = "value";
   &Err = "";
   &PendingName = "";
   &StrVal = "";
   &NumEnd = 0;
   &RootIdx = 0;
end-method;


method Fail
   /+ &msg as String +/
   /+ Returns Boolean +/
   If &Err <> "" Then
      Return False;
   End-If;
   &Err = &msg | "（位置 " | %This.NumToStr(&Pos) | " 附近：" | %This.Snippet() | "）";
   Return False;
end-method;


method NumToStr
   /+ &n as Integer +/
   /+ Returns String +/
   /* 自己实现整数转字符串，避开 String()/NumberToString() 的格式不确定性 */
   Local string &s, &d;
   Local integer &v;
   &v = &n;
   If &v < 0 Then
      &s = "-";
      &v = 0 - &v;
   Else
      &s = "";
   End-If;
   If &v = 0 Then
      Return &s | "0";
   End-If;
   &d = "";
   While &v > 0
      &d = Substring(&Digits, Mod(&v, 10) + 1, 1) | &d;
      &v = Int(&v / 10);
   End-While;
   Return &s | &d;
end-method;


method Describe
   /+ &ch as String +/
   /+ Returns String +/
   If &ch = "" Then
      Return "输入结束";
   End-If;
   If &ch = Char(10) Then
      Return "\n";
   End-If;
   If &ch = Char(13) Then
      Return "\r";
   End-If;
   If &ch = Char(9) Then
      Return "\t";
   End-If;
   Return &ch;
end-method;


method CharAt
   /+ &i as Integer +/
   /+ Returns String +/
   If &i < 1 Or
         &i > &SrcLen Then
      Return "";
   End-If;
   Return Substring(&Src, &i, 1);
end-method;


method Locate
   /+ &needle as String, +/
   /+ &start as Integer +/
   /+ Returns Number +/
   /* 未找到返回 0。若目标版本 Find 不支持第三个参数，改成先 Substring 再 Find：
        Local string &tail = Substring(&Src, &start, &SrcLen - &start + 1);
        Local number &p = Find(&needle, &tail);
        If &p = 0 Then Return 0; End-If;
        Return &p + &start - 1;   -- 代价是每次复制剩余串 */
   Return Find(&needle, &Src, &start);
end-method;


method Snippet
   /+ Returns String +/
   Local integer &a, &b;
   Local string &s;
   &a = &Pos - 12;
   If &a < 1 Then
      &a = 1;
   End-If;
   &b = &Pos + 12;
   If &b > &SrcLen Then
      &b = &SrcLen;
   End-If;
   If &b < &a Then
      Return "";
   End-If;
   &s = Substring(&Src, &a, &b - &a + 1);
   &s = Substitute(&s, Char(10), "\n");
   &s = Substitute(&s, Char(13), "\r");
   &s = Substitute(&s, Char(9), " ");
   Return &s;
end-method;


method SkipWs
   While %This.IsWsAt(&Pos)
      &Pos = &Pos + 1;
   End-While;
end-method;


method IsWsAt
   /+ &i as Integer +/
   /+ Returns Boolean +/
   Local string &c;
   &c = %This.CharAt(&i);
   If &c = "" Then
      Return False;
   End-If;
   /* 注意：不能写 Return Find(...) > 0; 比较运算的结果是 Integer，
      且会与 Return/赋值的 “=” 抢绑定，编译报 (2,33)/(2,47) */
   If Find(&c, &Ws) > 0 Then
      Return True;
   End-If;
   Return False;
end-method;


method IsDigitAt
   /+ &i as Integer +/
   /+ Returns Boolean +/
   Local string &c;
   &c = %This.CharAt(&i);
   If &c = "" Then
      Return False;
   End-If;
   If Find(&c, &Digits) > 0 Then
      Return True;
   End-If;
   Return False;
end-method;


method AllDigits
   /+ &s as String +/
   /+ Returns Boolean +/
   /* 不要命名成 IsDigits：与内建函数同名会被编译器警告 */
   Local integer &i;
   If &s = "" Then
      Return False;
   End-If;
   For &i = 1 To Len(&s)
      If Find(Substring(&s, &i, 1), &Digits) = 0 Then
         Return False;
      End-If;
   End-For;
   Return True;
end-method;


method IsCloser
   /+ &ch as String +/
   /+ Returns Boolean +/
   /* 当前字符是不是栈顶容器的合法结束符 */
   Local string &k;
   &k = %This.StackTopKind();
   If &k = &KObj And
         &ch = "}" Then
      Return True;
   End-If;
   If &k = &KArr And
         &ch = "]" Then
      Return True;
   End-If;
   Return False;
end-method;


method AddScalarNode
   /+ &parIdx as Integer, +/
   /+ &nm as String, +/
   /+ &kindStr as String, +/
   /+ &subKindStr as String, +/
   /+ &textStr as String +/
   /+ Returns Integer +/
   Local integer &node;
   Local boolean &ok;
   &node = %This.NewNode(&kindStr, &subKindStr, &textStr);
   &ok = %This.AppendChild(&parIdx, &node, &nm);
   If Not &ok Then
      Return 0;
   End-If;
   Return &node;
end-method;


method AddValueNode
   /+ &parIdx as Integer, +/
   /+ &nm as String, +/
   /+ &value as Any +/
   /+ Returns Integer +/
   Local string &valueKind = &ScalarHelper.Kind(&value);
   Local object &sourceValue;
   Local C_JSON_API:CustomApi:JSONStorage &sourceStore;
   Local integer &sourceIndex;
   If &valueKind = "null" Then
      Return %This.AddScalarNode(&parIdx, &nm, "null", "", "null");
   End-If;
   If &valueKind = "object" Or
         &valueKind = "array" Then
      &sourceValue = &value;
      &sourceStore = &sourceValue.Store();
      &sourceIndex = &sourceValue.NodeIndex();
      Return %This.ImportSubtree(&parIdx, &nm, &sourceStore, &sourceIndex);
   End-If;
   Return %This.AddTypedNode(&parIdx, &nm, &valueKind, &value);
end-method;


method AddTypedNode
   /+ &parIdx as Integer, +/
   /+ &nm as String, +/
   /+ &kindStr as String, +/
   /+ &value as Any +/
   /+ Returns Integer +/
   /* 显式类型写入（C_JSON_API 扩展，非 8.57 API）。
      kindStr: string / number / boolean / date / time / datetime。
      - number 校验合法性，非法抛异常（避免生成非法 JSON）；
      - boolean 必须能判为 True/False；
      - date/time/datetime 取 String(&value) 文本（序列化时输出为字符串）。 */
   Local string &txt, &sk;
   Local C_JSON_API:CustomApi:JSONStorage &numberValidator;
   Local integer &numberRoot, &numberChild;
   Local boolean &numberValid;
   If &kindStr = "number" Then
      &txt = String(&value);
      &numberValidator = create C_JSON_API:CustomApi:JSONStorage();
      &numberValid = &numberValidator.Parse("[" | &txt | "]");
      &numberRoot = &numberValidator.Root();
      &numberChild = &numberValidator.ChildAt(&numberRoot, 1);
      If Not &numberValid Or
            &numberValidator.ChildCount(&numberRoot) <> 1 Or
            &numberValidator.Kind(&numberChild) <> "number" Then
         throw CreateException(0, 0, "AddNumber: 值不是合法数字 [" | &txt | "]");
      End-If;
      &sk = "int";
      If Find(".", &txt) > 0 Or
            Find("e", Lower(&txt)) > 0 Then
         &sk = "float";
      End-If;
      Return %This.AddScalarNode(&parIdx, &nm, &KNum, &sk, &txt);
   End-If;
   If &kindStr = "boolean" Then
      &txt = "?";
      If &value = True Then
         &txt = "true";
      Else
         If &value = False Then
            &txt = "false";
         Else
            throw CreateException(0, 0, "AddBoolean: 值不是布尔 [" | String(&value) | "]");
         End-If;
      End-If;
      Return %This.AddScalarNode(&parIdx, &nm, &KBool, "", &txt);
   End-If;
   If &kindStr = "string" Then
      &txt = String(&value);
      Return %This.AddScalarNode(&parIdx, &nm, &KStr, "", &txt);
   End-If;
   If &kindStr = "date" Then
      &txt = String(&value);
      Return %This.AddScalarNode(&parIdx, &nm, &KDate, "", &txt);
   End-If;
   If &kindStr = "time" Then
      &txt = String(&value);
      Return %This.AddScalarNode(&parIdx, &nm, &KTime, "", &txt);
   End-If;
   If &kindStr = "datetime" Then
      &txt = String(&value);
      Return %This.AddScalarNode(&parIdx, &nm, &KDttm, "", &txt);
   End-If;
   throw CreateException(0, 0, "AddTypedNode: 未知类型 [" | &kindStr | "]");
end-method;


/* ═════════════════════════════════════════════════════════════════════════
 * 竞技场：创建与只读查询
 * ═════════════════════════════════════════════════════════════════════════ */

method NewNode
   /+ &kindStr as String, +/
   /+ &subKindStr as String, +/
   /+ &textStr as String +/
   /+ Returns Integer +/
   &Kind.Push(&kindStr);
   &SubKind.Push(&subKindStr);
   &Text.Push(&textStr);
   &PropName.Push("");
   &Parent.Push(0);
   &FirstChild.Push(0);
   &LastChild.Push(0);
   &NextSibling.Push(0);
   Return &Kind.Len;
end-method;


method Kind
   /+ &idx as Integer +/
   /+ Returns String +/
   If &idx < 1 Or
         &idx > &Kind.Len Then
      Return "";
   End-If;
   Return &Kind [&idx];
end-method;


method SubKind
   /+ &idx as Integer +/
   /+ Returns String +/
   If &idx < 1 Or
         &idx > &SubKind.Len Then
      Return "";
   End-If;
   Return &SubKind [&idx];
end-method;


method Text
   /+ &idx as Integer +/
   /+ Returns String +/
   If &idx < 1 Or
         &idx > &Text.Len Then
      Return "";
   End-If;
   Return &Text [&idx];
end-method;


method NodeType
   /+ &idx as Integer +/
   /+ Returns Integer +/
   /* 对齐内置 JsonNode.GetNodeType：0=NULL 1=OBJECT 2=ARRAY 3=VALUE */
   Local string &k;
   &k = %This.Kind(&idx);
   If &k = "" Then
      Return 0;
   End-If;
   If &k = &KNull Then
      Return 0;
   End-If;
   If &k = &KObj Then
      Return 1;
   End-If;
   If &k = &KArr Then
      Return 2;
   End-If;
   Return 3;
end-method;


method ValueType
   /+ &idx as Integer +/
   /+ Returns Integer +/
   /* 对齐内置 JsonNode.GetValueType：
      0=INVALID 1=INT 2=FLOAT 3=DOUBLE 4=NUMBER 5=BOOLEAN 6=STRING
      7=NULL 8=DATE 9=TIME 10=DATETIME */
   Local string &k, &sk;
   &k = %This.Kind(&idx);
   If &k = "" Then
      Return 0;
   End-If;
   If &k = &KNum Then
      &sk = %This.SubKind(&idx);
      If &sk = "int" Then
         Return 1;
      End-If;
      If &sk = "float" Then
         Return 2;
      End-If;
      If &sk = "double" Then
         Return 3;
      End-If;
      Return 4;
   End-If;
   If &k = &KStr Then
      Return 6;
   End-If;
   If &k = &KBool Then
      Return 5;
   End-If;
   If &k = &KNull Then
      Return 7;
   End-If;
   If &k = &KDate Then
      Return 8;
   End-If;
   If &k = &KTime Then
      Return 9;
   End-If;
   If &k = &KDttm Then
      Return 10;
   End-If;
   Return 0;
end-method;


method NameOf
   /+ &idx as Integer +/
   /+ Returns String +/
   If &idx < 1 Or
         &idx > &PropName.Len Then
      Return "";
   End-If;
   Return &PropName [&idx];
end-method;


method ParentOf
   /+ &idx as Integer +/
   /+ Returns Integer +/
   If &idx < 1 Or
         &idx > &Parent.Len Then
      Return 0;
   End-If;
   Return &Parent [&idx];
end-method;


method IsContainer
   /+ &idx as Integer +/
   /+ Returns Boolean +/
   Local string &k;
   &k = %This.Kind(&idx);
   If &k = &KObj Or
         &k = &KArr Then
      Return True;
   End-If;
   Return False;
end-method;


method ChildCount
   /+ &idx as Integer +/
   /+ Returns Integer +/
   Local integer &c, &i;
   &c = 0;
   If &idx < 1 Or
         &idx > &FirstChild.Len Then
      Return 0;
   End-If;
   &i = &FirstChild [&idx];
   While &i <> 0
      &c = &c + 1;
      &i = &NextSibling [&i];
   End-While;
   Return &c;
end-method;


method ChildAt
   /+ &idx as Integer, +/
   /+ &i as Integer +/
   /+ Returns Integer +/
   Local integer &c, &k;
   If &i < 1 Or
         &idx < 1 Or
         &idx > &FirstChild.Len Then
      Return 0;
   End-If;
   &c = &FirstChild [&idx];
   &k = 1;
   While &c <> 0 And
         &k < &i
      &c = &NextSibling [&c];
      &k = &k + 1;
   End-While;
   Return &c;
end-method;


method ChildNameAt
   /+ &idx as Integer, +/
   /+ &i as Integer +/
   /+ Returns String +/
   Local integer &c;
   &c = %This.ChildAt(&idx, &i);
   If &c = 0 Then
      Return "";
   End-If;
   Return &PropName [&c];
end-method;


method ChildIndexByName
   /+ &idx as Integer, +/
   /+ &nm as String +/
   /+ Returns Integer +/
   /* 同名取最后一个，与 dict / JS / json.org 语义一致 */
   Local integer &found, &i;
   &found = 0;
   If &idx < 1 Or
         &idx > &FirstChild.Len Then
      Return 0;
   End-If;
   &i = &FirstChild [&idx];
   While &i <> 0
      If &PropName [&i] = &nm Then
         &found = &i;
      End-If;
      &i = &NextSibling [&i];
   End-While;
   Return &found;
end-method;


/* ═════════════════════════════════════════════════════════════════════════
 * 结构修改
 * ═════════════════════════════════════════════════════════════════════════ */

method AppendChild
   /+ &parIdx as Integer, +/
   /+ &childIdx as Integer, +/
   /+ &nm as String +/
   /+ Returns Boolean +/
   Local boolean &ok;
   Local integer &previousChild;
   If &parIdx < 1 Or
         &parIdx > &FirstChild.Len Then
      Return False;
   End-If;
   If &childIdx < 1 Or
         &childIdx > &Kind.Len Then
      Return False;
   End-If;
   If &Parent [&childIdx] <> 0 Then
      &ok = %This.DetachNode(&childIdx);
   End-If;
   If &Kind [&parIdx] = "object" Then
      &previousChild = %This.ChildIndexByName(&parIdx, &nm);
      If &previousChild > 0 And
            &previousChild <> &childIdx Then
         &ok = %This.DetachNode(&previousChild);
      End-If;
   End-If;
   &PropName [&childIdx] = &nm;
   &Parent [&childIdx] = &parIdx;
   If &FirstChild [&parIdx] = 0 Then
      &FirstChild [&parIdx] = &childIdx;
   Else
      &NextSibling [&LastChild [&parIdx]] = &childIdx;
   End-If;
   &NextSibling [&childIdx] = 0;
   &LastChild [&parIdx] = &childIdx;
   Return True;
end-method;


method DetachNode
   /+ &idx as Integer +/
   /+ Returns Boolean +/
   Local integer &p, &c, &prev;
   If &idx < 1 Or
         &idx > &Parent.Len Then
      Return False;
   End-If;
   &p = &Parent [&idx];
   If &p = 0 Then
      Return False;
   End-If;
   &c = &FirstChild [&p];
   &prev = 0;
   While &c <> 0 And
         &c <> &idx
      &prev = &c;
      &c = &NextSibling [&c];
   End-While;
   If &c = 0 Then
      Return False;
   End-If;
   If &prev = 0 Then
      &FirstChild [&p] = &NextSibling [&idx];
   Else
      &NextSibling [&prev] = &NextSibling [&idx];
   End-If;
   If &LastChild [&p] = &idx Then
      &LastChild [&p] = &prev;
   End-If;
   &Parent [&idx] = 0;
   &NextSibling [&idx] = 0;
   &PropName [&idx] = "";
   Return True;
end-method;


method RemoveChildAt
   /+ &parIdx as Integer, +/
   /+ &i as Integer +/
   /+ Returns Boolean +/
   Local integer &c;
   &c = %This.ChildAt(&parIdx, &i);
   If &c = 0 Then
      Return False;
   End-If;
   Return %This.DetachNode(&c);
end-method;


method RemoveLastChild
   /+ &parIdx as Integer +/
   /+ Returns Boolean +/
   Local integer &c;
   If &parIdx < 1 Or
         &parIdx > &LastChild.Len Then
      Return False;
   End-If;
   &c = &LastChild [&parIdx];
   If &c = 0 Then
      Return False;
   End-If;
   Return %This.DetachNode(&c);
end-method;


method ClearNode
   /+ &idx as Integer +/
   /* 只摘掉全部子节点；节点自身的 Kind/Text 由调用方决定 */
   Local boolean &ok;
   Local integer &childToDetach;
   If &idx < 1 Or
         &idx > &FirstChild.Len Then
      Return;
   End-If;
   While &FirstChild [&idx] <> 0
      &childToDetach = &FirstChild [&idx];
      &ok = %This.DetachNode(&childToDetach);
   End-While;
   &FirstChild [&idx] = 0;
   &LastChild [&idx] = 0;
end-method;


method SetScalar
   /+ &idx as Integer, +/
   /+ &kindStr as String, +/
   /+ &subKindStr as String, +/
   /+ &textStr as String +/
   /+ Returns Boolean +/
   If &idx < 1 Or
         &idx > &Kind.Len Then
      Return False;
   End-If;
   If &Kind [&idx] = &KObj Or
         &Kind [&idx] = &KArr Then
      %This.ClearNode(&idx);
   End-If;
   &Kind [&idx] = &kindStr;
   &SubKind [&idx] = &subKindStr;
   &Text [&idx] = &textStr;
   Return True;
end-method;


method SetName
   /+ &idx as Integer, +/
   /+ &nm as String +/
   /+ Returns Boolean +/
   If &idx < 1 Or
         &idx > &PropName.Len Then
      Return False;
   End-If;
   &PropName [&idx] = &nm;
   Return True;
end-method;


method SetNull
   /+ &idx as Integer +/
   /+ Returns Boolean +/
   Return %This.SetScalar(&idx, &KNull, "", "null");
end-method;


method ImportSubtree
   /+ &parIdx as Integer, +/
   /+ &nm as String, +/
   /+ &srcStore as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &srcNode as Integer +/
   /+ Returns Integer +/
   /* 跨文档深拷贝，迭代实现：栈里放 (目标节点, 源节点) 对 */
   Local integer &newIdx, &d, &s, &i, &cnt, &childSrc, &childNew;
   Local boolean &ok;
   Local array of number &StkDst, &StkSrc;
   If &srcStore = Null Then
      Return 0;
   End-If;
   If &srcStore.Kind(&srcNode) = "" Then
      Return 0;
   End-If;
   &newIdx = %This.NewNode(&srcStore.Kind(&srcNode), &srcStore.SubKind(&srcNode), &srcStore.Text(&srcNode));
   If Not %This.AppendChild(&parIdx, &newIdx, &nm) Then
      Return 0;
   End-If;
   &StkDst = CreateArrayRept(0, 0);
   &StkSrc = CreateArrayRept(0, 0);
   &StkDst.Push(&newIdx);
   &StkSrc.Push(&srcNode);
   While &StkDst.Len > 0
      &d = &StkDst [&StkDst.Len];
      &s = &StkSrc [&StkSrc.Len];
      &StkDst.Len = &StkDst.Len - 1;
      &StkSrc.Len = &StkSrc.Len - 1;
      &cnt = &srcStore.ChildCount(&s);
      For &i = 1 To &cnt
         &childSrc = &srcStore.ChildAt(&s, &i);
         &childNew = %This.NewNode(&srcStore.Kind(&childSrc), &srcStore.SubKind(&childSrc), &srcStore.Text(&childSrc));
         &ok = %This.AppendChild(&d, &childNew, &srcStore.ChildNameAt(&s, &i));
         If &srcStore.IsContainer(&childSrc) Then
            &StkDst.Push(&childNew);
            &StkSrc.Push(&childSrc);
         End-If;
      End-For;
   End-While;
   Return &newIdx;
end-method;


method ReplaceWith
   /+ &idx as Integer, +/
   /+ &srcStore as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &srcNode as Integer +/
   /+ Returns Boolean +/
   /* 让 &idx 变成 src 中 &srcNode 的深拷贝（JsonNode.SetJsonObject/SetJsonArray 用） */
   Local integer &i, &cnt, &ignored;
   Local boolean &okB;
   Local string &k;
   If &srcStore = Null Then
      Return False;
   End-If;
   &k = &srcStore.Kind(&srcNode);
   If %This.Kind(&idx) = "" Then
      Return False;
   End-If;
   If &k = &KObj Or
         &k = &KArr Then
      %This.ClearNode(&idx);
      &Kind [&idx] = &k;
      &SubKind [&idx] = "";
      &Text [&idx] = "";
      &cnt = &srcStore.ChildCount(&srcNode);
      For &i = 1 To &cnt
         &ignored = %This.ImportSubtree(&idx, &srcStore.ChildNameAt(&srcNode, &i), &srcStore, &srcStore.ChildAt(&srcNode, &i));
      End-For;
   Else
      &okB = %This.SetScalar(&idx, &k, &srcStore.SubKind(&srcNode), &srcStore.Text(&srcNode));
   End-If;
   Return True;
end-method;


method AsString
   /+ &idx as Integer +/
   /+ Returns String +/
   /* 与内置一致：null 属性取回字面量 "null"（C_PORTAL_PKG:Util:JSONObject 依赖此行为） */
   Local string &k;
   &k = %This.Kind(&idx);
   If &k = "" Then
      Return "";
   End-If;
   If &k = &KNull Then
      Return "null";
   End-If;
   Return %This.Text(&idx);
end-method;


method AsNumber
   /+ &idx as Integer +/
   /+ Returns Number +/
   Local string &k, &t;
   &k = %This.Kind(&idx);
   If &k = "" Or
         &k = &KNull Then
      Return 0;
   End-If;
   &t = %This.Text(&idx);
   If &t = "true" Then
      Return 1;
   End-If;
   If &t = "false" Then
      Return 0;
   End-If;
   Return Value(&t);
end-method;


method AsInteger
   /+ &idx as Integer +/
   /+ Returns Integer +/
   Return Int(%This.AsNumber(&idx));
end-method;


/* ═════════════════════════════════════════════════════════════════════════
 * 解析：显式栈状态机
 * ═════════════════════════════════════════════════════════════════════════ */

method Parse
   /+ &srcStore as String +/
   /+ Returns Boolean +/
   Local string &ch, &numText, &sub, &state;
   Local integer &steps, &maxSteps;
   %This.Reset();
   &Src = &srcStore;
   &SrcLen = Len(&Src);
   If &SrcLen = 0 Then
      Return %This.Fail("输入为空");
   End-If;
   &steps = 0;
   &maxSteps = &SrcLen * 4 + 1024;
   While True
      &steps = &steps + 1;
      If &steps > &maxSteps Then
         Return %This.Fail("解析器状态机异常（内部错误）");
      End-If;
      %This.SkipWs();
      &ch = %This.CharAt(&Pos);

      /* 归约：把 “期望状态 + 当前字符” 折成一个分支键，再用单层 Evaluate 分派。
         PeopleCode 没有 ElseIf，且不建议在 When 里嵌套 Evaluate，所以用这种写法。 */
      &state = &Expect;
      If &Expect = "key_or_end" Then
         If &ch = "}" Then
            &state = "close";
         Else
            &state = "key";
         End-If;
      End-If;
      If &Expect = "value_or_end" Then
         If &ch = "]" Then
            &state = "close";
         Else
            /* 不能把 &state 设为 "value"：Evaluate 没有 When "value" 分支，
               会落进 When-Other 报“状态机异常”。改为转成 value 走正常覆盖。 */
            &Expect = "value";
         End-If;
      End-If;
      If &Expect = "comma_end" Then
         If &ch = "," Then
            &state = "comma";
         Else
            If %This.IsCloser(&ch) Then
               &state = "close";
            Else
               &state = "badtail";
            End-If;
         End-If;
      End-If;
      If &Expect = "value" Then
         &state = "val_bad";
         If &ch = "{" Then
            &state = "val_obj";
         End-If;
         If &ch = "[" Then
            &state = "val_arr";
         End-If;
         If &ch = &DQ Then
            &state = "val_str";
         End-If;
         If &ch = "n" Then
            &state = "val_null";
         End-If;
         If &ch = "t" Then
            &state = "val_true";
         End-If;
         If &ch = "f" Then
            &state = "val_false";
         End-If;
         If &ch = "-" Or
               %This.IsDigitAt(&Pos) Then
            &state = "val_num";
         End-If;
      End-If;

      Evaluate &state
      When "end"
         If &Pos > &SrcLen Then
            Return True;
         End-If;
         Return %This.Fail("根值之后存在多余内容");
      When "close"
         &Pos = &Pos + 1;
         %This.CloseContainer();
      When "key"
         If Not %This.ExpectKey() Then
            Return False;
         End-If;
      When "colon"
         If &ch <> ":" Then
            Return %This.Fail("属性名之后期望 [:] 实际是 [" | %This.Describe(&ch) | "]");
         End-If;
         &Pos = &Pos + 1;
         &Expect = "value";
      When "comma"
         &Pos = &Pos + 1;
         If %This.StackTopKind() = &KObj Then
            &Expect = "key";
         Else
            &Expect = "value";
         End-If;
      When "badtail"
         Return %This.Fail("期望 [,] 或容器结束，实际是 [" | %This.Describe(&ch) | "]");
      When "val_obj"
         &Pos = &Pos + 1;
         If Not %This.OpenNode(&KObj) Then
            Return False;
         End-If;
         &Expect = "key_or_end";
      When "val_arr"
         &Pos = &Pos + 1;
         If Not %This.OpenNode(&KArr) Then
            Return False;
         End-If;
         &Expect = "value_or_end";
      When "val_str"
         If Not %This.ReadString() Then
            Return False;
         End-If;
         %This.ScalarNode(&KStr, "", &StrVal);
         %This.AfterValue();
      When "val_null"
         If Not %This.Literal("null") Then
            Return False;
         End-If;
         %This.ScalarNode(&KNull, "", "null");
         %This.AfterValue();
      When "val_true"
         If Not %This.Literal("true") Then
            Return False;
         End-If;
         %This.ScalarNode(&KBool, "", "true");
         %This.AfterValue();
      When "val_false"
         If Not %This.Literal("false") Then
            Return False;
         End-If;
         %This.ScalarNode(&KBool, "", "false");
         %This.AfterValue();
      When "val_num"
         If Not %This.ScanNumber() Then
            Return False;
         End-If;
         &numText = Substring(&Src, &Pos, &NumEnd - &Pos);
         &Pos = &NumEnd;
         If Not %This.TerminatorOk() Then
            Return False;
         End-If;
         If Find(".", &numText) = 0 And
               Find("e", Lower(&numText)) = 0 Then
            &sub = "int";
         Else
            &sub = "float";
         End-If;
         %This.ScalarNode(&KNum, &sub, &numText);
         %This.AfterValue();
      When "val_bad"
         If &ch = "" Then
            Return %This.Fail("输入意外结束，期望一个 JSON 值");
         End-If;
         Return %This.Fail("期望一个 JSON 值，实际是 [" | %This.Describe(&ch) | "]");
      When-Other
         Return %This.Fail("解析器状态机异常（内部错误）");
      End-Evaluate;
   End-While;
   Return False;
end-method;


method StackPush
   /+ &n as Integer, +/
   /+ &k as String +/
   &StackNode.Push(&n);
   &StackKind.Push(&k);
end-method;


method StackPop
   /* Array 的 Len 可写，赋值即截断 */
   &StackNode.Len = &StackNode.Len - 1;
   &StackKind.Len = &StackKind.Len - 1;
end-method;


method StackTopKind
   /+ Returns String +/
   If &StackNode.Len = 0 Then
      Return "";
   End-If;
   Return &StackKind [&StackNode.Len];
end-method;


method Attach
   /+ &node as Integer +/
   /* 挂到栈顶容器；栈空则作为根 */
   Local integer &p;
   If &StackNode.Len = 0 Then
      &RootIdx = &node;
      Return;
   End-If;
   &p = &StackNode [&StackNode.Len];
   &PropName [&node] = &PendingName;
   &Parent [&node] = &p;
   If &FirstChild [&p] = 0 Then
      &FirstChild [&p] = &node;
   Else
      &NextSibling [&LastChild [&p]] = &node;
   End-If;
   &LastChild [&p] = &node;
end-method;


method OpenNode
   /+ &k as String +/
   /+ Returns Boolean +/
   Local integer &node;
   If &StackNode.Len >= &MaxDepth Then
      Return %This.Fail("JSON 嵌套层数超过上限（默认 64）");
   End-If;
   &node = %This.NewNode(&k, "", "");
   %This.Attach(&node);
   %This.StackPush(&node, &k);
   Return True;
end-method;


method ScalarNode
   /+ &k as String, +/
   /+ &sub as String, +/
   /+ &txt as String +/
   Local integer &node;
   &node = %This.NewNode(&k, &sub, &txt);
   %This.Attach(&node);
end-method;


method ExpectKey
   /+ Returns Boolean +/
   Local string &ch;
   &ch = %This.CharAt(&Pos);
   If &ch <> &DQ Then
      If &ch = "" Then
         Return %This.Fail("对象未闭合");
      End-If;
      Return %This.Fail("期望属性名（双引号字符串），实际是 [" | %This.Describe(&ch) | "]");
   End-If;
   If Not %This.ReadString() Then
      Return False;
   End-If;
   &PendingName = &StrVal;
   &Expect = "colon";
   Return True;
end-method;


method AfterValue
   If &StackNode.Len = 0 Then
      &Expect = "end";
   Else
      &Expect = "comma_end";
   End-If;
end-method;


method CloseContainer
   %This.StackPop();
   %This.AfterValue();
end-method;


method ReadString
   /+ Returns Boolean +/
   /* 成功：&StrVal 为解码后的值（允许空串）；无转义时只有 1 次 Locate + 1 次 Substring */
   Local number &p, &b, &q, &code, &lowCode;
   Local string &e, &c, &hex4;
   Local array of string &Chunks;
   &Chunks = CreateArrayRept("", 0);
   &p = &Pos + 1;
   While True
      &b = %This.Locate(&BS, &p);
      &q = %This.Locate(&DQ, &p);
      If &q = 0 Then
         Return %This.Fail("字符串未闭合");
      End-If;
      If &b = 0 Or
            &b > &q Then
         If Not %This.CleanStringPiece(Substring(&Src, &p, &q - &p)) Then
            Return False;
         End-If;
         &Chunks.Push(Substring(&Src, &p, &q - &p));
         &Pos = &q + 1;
         /* Join 第 2/3 参是包裹字符，默认 (,)，必须显式传空串 */
         &StrVal = &Chunks.Join("", "", "");
         Return True;
      End-If;
      If Not %This.CleanStringPiece(Substring(&Src, &p, &b - &p)) Then
         Return False;
      End-If;
      &Chunks.Push(Substring(&Src, &p, &b - &p));
      If &b + 1 > &SrcLen Then
         &Pos = &b;
         Return %This.Fail("转义符后没有字符");
      End-If;
      &e = Substring(&Src, &b + 1, 1);
      If &e = "u" Then
         If &b + 5 > &SrcLen Then
            &Pos = &b;
            Return %This.Fail("\u 转义不完整");
         End-If;
         &hex4 = Substring(&Src, &b + 2, 4);
         &code = %This.Hex4(&hex4);
         If &code < 0 Then
            &Pos = &b;
            Return %This.Fail("非法的 \u 转义：" | &hex4);
         End-If;
         If &code = 0 Then
            &Pos = &b;
            Return %This.Fail("不支持 \u0000（NUL）");
         End-If;
         If &code >= 55296 And
               &code <= 56319 Then
            If &b + 11 > &SrcLen Or
                  Substring(&Src, &b + 6, 2) <> &BS | "u" Then
               &Pos = &b;
               Return %This.Fail("High surrogate requires a low surrogate");
            End-If;
            &lowCode = %This.Hex4(Substring(&Src, &b + 8, 4));
            If &lowCode < 56320 Or
                  &lowCode > 57343 Then
               &Pos = &b;
               Return %This.Fail("Invalid low surrogate");
            End-If;
            &Chunks.Push(Char(&code) | Char(&lowCode));
            &p = &b + 12;
         Else
            If &code >= 56320 And
                  &code <= 57343 Then
               &Pos = &b;
               Return %This.Fail("Unpaired low surrogate");
            End-If;
            &c = %This.ToChar(&code);
            If &c = "" Then
               &Pos = &b;
               Return %This.Fail("Cannot decode Unicode escape");
            End-If;
            &Chunks.Push(&c);
            &p = &b + 6;
         End-If;
      Else
         &c = %This.DecodeEscape(&e);
         If &c = "" Then
            &Pos = &b;
            Return %This.Fail("非法的转义 [" | &BS | &e | "]");
         End-If;
         &Chunks.Push(&c);
         &p = &b + 2;
      End-If;
   End-While;
   Return False;
end-method;


method DecodeEscape
   /+ &e as String +/
   /+ Returns String +/
   If &e = &DQ Then
      Return &DQ;
   End-If;
   If &e = &BS Then
      Return &BS;
   End-If;
   If &e = "/" Then
      Return "/";
   End-If;
   If &e = "b" Then
      Return Char(8);
   End-If;
   If &e = "f" Then
      Return Char(12);
   End-If;
   If &e = "n" Then
      Return Char(10);
   End-If;
   If &e = "r" Then
      Return Char(13);
   End-If;
   If &e = "t" Then
      Return Char(9);
   End-If;
   Return "";
end-method;


method Hex4
   /+ &s as String +/
   /+ Returns Number +/
   /* 4 位十六进制 → 数值，非法返回 -1 */
   Local integer &i, &v, &d;
   Local string &c;
   If Len(&s) <> 4 Then
      Return - 1;
   End-If;
   &v = 0;
   For &i = 1 To 4
      &c = Lower(Substring(&s, &i, 1));
      &d = Find(&c, &Hex);
      If &d = 0 Then
         Return - 1;
      End-If;
      &v = &v * 16 + (&d - 1);
   End-For;
   Return &v;
end-method;


method ToChar
   /+ &code as Integer +/
   /+ Returns String +/
   /* Char() 可支持范围随版本不同，try 兜住；返回空串表示生成不了 */
   Local string &c;
   try
      &c = Char(&code);
   catch Exception &ex
      &c = "";
   end-try;
   If Len(&c) <> 1 Then
      Return "";
   End-If;
   Return &c;
end-method;


method ScanNumber
   /+ Returns Boolean +/
   /* 严格校验 -?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?；成功时 &NumEnd 指向数字之后 */
   Local integer &p;
   Local string &c, &s;
   &p = &Pos;
   If %This.CharAt(&p) = "-" Then
      &p = &p + 1;
   End-If;
   &c = %This.CharAt(&p);
   If &c = "0" Then
      &p = &p + 1;
   Else
      If %This.IsDigitAt(&p) Then
         While %This.IsDigitAt(&p)
            &p = &p + 1;
         End-While;
      Else
         &Pos = &p;
         Return %This.Fail("数字缺少整数部分");
      End-If;
   End-If;
   If %This.CharAt(&p) = "." Then
      &p = &p + 1;
      If Not %This.IsDigitAt(&p) Then
         &Pos = &p;
         Return %This.Fail("小数点后缺少数字");
      End-If;
      While %This.IsDigitAt(&p)
         &p = &p + 1;
      End-While;
   End-If;
   &s = %This.CharAt(&p);
   If &s = "e" Or
         &s = "E" Then
      &p = &p + 1;
      &s = %This.CharAt(&p);
      If &s = "+" Or
            &s = "-" Then
         &p = &p + 1;
      End-If;
      If Not %This.IsDigitAt(&p) Then
         &Pos = &p;
         Return %This.Fail("指数缺少数字");
      End-If;
      While %This.IsDigitAt(&p)
         &p = &p + 1;
      End-While;
   End-If;
   &NumEnd = &p;
   Return True;
end-method;


method TerminatorOk
   /+ Returns Boolean +/
   Local string &c;
   &c = %This.CharAt(&Pos);
   If &c = "" Then
      Return True;
   End-If;
   If Find(&c, &Ws) > 0 Then
      Return True;
   End-If;
   If Find(&c, ",}]") > 0 Then
      Return True;
   End-If;
   Return %This.Fail("此处出现非法字符 [" | %This.Describe(&c) | "]");
end-method;


method Literal
   /+ &word as String +/
   /+ Returns Boolean +/
   If Substring(&Src, &Pos, Len(&word)) <> &word Then
      Return %This.Fail("期望字面量 " | &word);
   End-If;
   &Pos = &Pos + Len(&word);
   Return %This.TerminatorOk();
end-method;


/* ═════════════════════════════════════════════════════════════════════════
 * 序列化：迭代遍历，不递归
 * ═════════════════════════════════════════════════════════════════════════ */

method EscapeStr
   /+ &s as String +/
   /+ Returns String +/
   Local string &r;
   Local integer &i;
   &r = Substitute(&s, &BS, &BS | &BS); /* 反斜杠必须先处理 */
   &r = Substitute(&r, &DQ, &BS | &DQ);
   &r = Substitute(&r, Char(8), &BS | "b");
   &r = Substitute(&r, Char(12), &BS | "f");
   &r = Substitute(&r, Char(10), &BS | "n");
   &r = Substitute(&r, Char(13), &BS | "r");
   &r = Substitute(&r, Char(9), &BS | "t");
   /* 其余 U+0001..U+001F 用 \u00XX；从 1 开始，跳过已处理的 8/9/10/12/13 */
   For &i = 1 To 31
      If &i <> 8 And
            &i <> 9 And
            &i <> 10 And
            &i <> 12 And
            &i <> 13 Then
         &r = Substitute(&r, Char(&i), &BS | "u00" | Substring(&Hex, Int(&i / 16) + 1, 1) | Substring(&Hex, Mod(&i, 16) + 1, 1));
      End-If;
   End-For;
   Return &r;
end-method;


method ScalarText
   /+ &idx as Integer +/
   /+ Returns String +/
   Local string &k;
   &k = %This.Kind(&idx);
   If &k = &KStr Then
      Return &DQ | %This.EscapeStr(&Text [&idx]) | &DQ;
   End-If;
   If &k = &KNull Then
      Return "null";
   End-If;
   If &k = &KDate Or
         &k = &KTime Or
         &k = &KDttm Then
      /* JSON 无日期类型：显式 SetDate/SetTime/SetDateTime 产生的节点序列化为字符串，
         不能裸文本输出（否则生成的 JSON 非法） */
      Return &DQ | %This.EscapeStr(&Text [&idx]) | &DQ;
   End-If;
   If &k = &KObj Or
         &k = &KArr Then
      Return "";
   End-If;
   Return &Text [&idx]; /* number / boolean 原样输出 */
end-method;


method ToJson
   /+ &idx as Integer +/
   /+ Returns String +/
   /* 容器游标栈（两个 number 数组），文本即时写出 */
   Local array of string &Out;
   Local array of number &StkNode, &StkIdx;
   Local string &k0, &ck;
   Local integer &top, &node, &i, &cnt, &childIdx;
   If &idx < 1 Or
         &idx > &Kind.Len Then
      Return "";
   End-If;
   &k0 = &Kind [&idx];
   If &k0 <> &KObj And
         &k0 <> &KArr Then
      Return %This.ScalarText(&idx);
   End-If;
   &Out = CreateArrayRept("", 0);
   &StkNode = CreateArrayRept(0, 0);
   &StkIdx = CreateArrayRept(0, 0);
   If &k0 = &KObj Then
      &Out.Push("{");
   Else
      &Out.Push("[");
   End-If;
   &StkNode.Push(&idx);
   &StkIdx.Push(1);
   While &StkNode.Len > 0
      &top = &StkNode.Len;
      &node = &StkNode [&top];
      &i = &StkIdx [&top];
      &cnt = %This.ChildCount(&node);
      If &i > &cnt Then
         If &Kind [&node] = &KObj Then
            &Out.Push("}");
         Else
            &Out.Push("]");
         End-If;
         &StkNode.Len = &top - 1;
         &StkIdx.Len = &top - 1;
      Else
         &StkIdx [&top] = &i + 1;
         If &i > 1 Then
            &Out.Push(",");
         End-If;
         &childIdx = %This.ChildAt(&node, &i);
         If &Kind [&node] = &KObj Then
            &Out.Push(&DQ | %This.EscapeStr(&PropName [&childIdx]) | &DQ | ":");
         End-If;
         &ck = &Kind [&childIdx];
         If &ck = &KObj Then
            &Out.Push("{");
            &StkNode.Push(&childIdx);
            &StkIdx.Push(1);
         Else
            If &ck = &KArr Then
               &Out.Push("[");
               &StkNode.Push(&childIdx);
               &StkIdx.Push(1);
            Else
               &Out.Push(%This.ScalarText(&childIdx));
            End-If;
         End-If;
      End-If;
   End-While;
   /* Join 第 2/3 参是包裹字符，默认 (,)，必须显式传空串 */
   Return &Out.Join("", "", "");
end-method;


method GetError
   /+ Returns String +/
   Return &Err;
end-method;


method Root
   /+ Returns Integer +/
   Return &RootIdx;
end-method;


method SetRoot
   /+ &p_idx as Integer +/
   &RootIdx = &p_idx;
end-method;

method CleanStringPiece
   /+ &p_piece as String +/
   /+ Returns Boolean +/
   Local integer &controlCode;
   For &controlCode = 1 To 31
      If Find(Char(&controlCode), &p_piece) > 0 Then
         Return %This.Fail("Unescaped control character in JSON string");
      End-If;
   End-For;
   Return True;
end-method;

import C_JSON_API:JSONValue;
import C_JSON_API:CustomApi:JSONStorage;

/* C_JSON_API:CustomApi:JSONValue — 对齐 8.57 内置 JsonValue 的方法集（19 个方法）。
 *
 * 与内置一致的语义：
 *   - 值节点持有 (JSONStorage, 下标)，通过 GetJsonValue() 拿到的子节点与原对象
 *     共享同一份存储，SetXxx() 会改到父对象。
 * 存储无关：纯 PeopleCode，不依赖 8.55+ 的 JSON 内建类。
 */
class JSONValue implements C_JSON_API:JSONValue
   method JSONValue();

   method Store() Returns any;
   method NodeIndex() Returns integer;
   method BindCode(&p_store As C_JSON_API:CustomApi:JSONStorage, &p_idx As integer);

   method GetBoolean() Returns boolean;
   method GetDate() Returns date;
   method GetDateTime() Returns datetime;
   method GetInteger() Returns integer;
   method GetNumber() Returns number;
   method GetString() Returns string;
   method GetTime() Returns time;
   method GetValue() Returns any;
   method IsNull() Returns boolean;
   method SetBoolean(&p_value As boolean);
   method SetDate(&p_value As date);
   method SetDateTime(&p_value As datetime);
   method SetFalse();
   method SetInteger(&p_value As integer);
   method SetNull();
   method SetNumber(&p_value As number);
   method SetString(&p_value As string);
   method SetTrue();
   method ToString() Returns string;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance integer &NodeIdx;
   instance string &KStr;
   instance string &KNum;
   instance string &KBool;
   instance string &KNull;
   instance string &KDate;
   instance string &KTime;
   instance string &KDttm;

   method InitKinds();
   method KindIs(&p_k As string) Returns boolean;
   method SetScalarCode(&p_kindStr As string, &p_sub As string, &p_txt As string);
end-class;

method JSONValue
   %This.InitKinds();
   &StoreRef = create C_JSON_API:CustomApi:JSONStorage();
   &NodeIdx = &StoreRef.NewNode(&KNull, "", "null");
end-method;

method InitKinds
   &KStr = "string";
   &KNum = "number";
   &KBool = "boolean";
   &KNull = "null";
   &KDate = "date";
   &KTime = "time";
   &KDttm = "datetime";
end-method;

method KindIs
   /+ &p_k as String +/
   /+ Returns Boolean +/
   Local string &k;
   &k = &StoreRef.Kind(&NodeIdx);
   If &k = &p_k Then
      Return True;
   End-If;
   Return False;
end-method;

method SetScalarCode
   /+ &p_kindStr as String, +/
   /+ &p_sub as String, +/
   /+ &p_txt as String +/
   Local boolean &ok;
   &ok = &StoreRef.SetScalar(&NodeIdx, &p_kindStr, &p_sub, &p_txt);
end-method;

method Store
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONValue.Store +/
   Return &StoreRef;
end-method;

method NodeIndex
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONValue.NodeIndex +/
   Return &NodeIdx;
end-method;

method BindCode
   /+ &p_store as C_JSON_API:CustomApi:JSONStorage, +/
   /+ &p_idx as Integer +/
   &StoreRef = &p_store;
   &NodeIdx = &p_idx;
end-method;

method GetString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONValue.GetString +/
   Return &StoreRef.AsString(&NodeIdx);
end-method;

method GetInteger
   /+ Returns Integer +/
   /+ Extends/implements C_JSON_API:JSONValue.GetInteger +/
   Return &StoreRef.AsInteger(&NodeIdx);
end-method;

method GetNumber
   /+ Returns Number +/
   /+ Extends/implements C_JSON_API:JSONValue.GetNumber +/
   Return &StoreRef.AsNumber(&NodeIdx);
end-method;

method GetBoolean
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.GetBoolean +/
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "true" Then
      Return True;
   End-If;
   Return False;
end-method;

method GetDate
   /+ Returns Date +/
   /+ Extends/implements C_JSON_API:JSONValue.GetDate +/
   Local date &d;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &d;
   End-If;
   Return Date(&t);
end-method;

method GetTime
   /+ Returns Time +/
   /+ Extends/implements C_JSON_API:JSONValue.GetTime +/
   Local time &tm;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &tm;
   End-If;
   Return TimeValue(&t);
end-method;

method GetDateTime
   /+ Returns DateTime +/
   /+ Extends/implements C_JSON_API:JSONValue.GetDateTime +/
   Local datetime &dt;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &dt;
   End-If;
   Return DateTimeValue(&t);
end-method;

method GetValue
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONValue.GetValue +/
   Local string &k, &t;
   Local any &v;
   &t = &StoreRef.Text(&NodeIdx);
   &k = &StoreRef.Kind(&NodeIdx);
   &v = Null;
   If &k = "string" Then
      &v = &StoreRef.AsString(&NodeIdx);
   Else
      If &k = "number" Then
         &v = &StoreRef.AsNumber(&NodeIdx);
      Else
         If &k = "boolean" Then
            If &t = "true" Then
               &v = True;
            Else
               &v = False;
            End-If;
         Else
            If &k = "date" And
                  &t <> "" Then
               &v = Date(&t);
            Else
               If &k = "time" And
                     &t <> "" Then
                  &v = TimeValue(&t);
               Else
                  If &k = "datetime" And
                        &t <> "" Then
                     &v = DateTimeValue(&t);
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
   End-If;
   Return &v;
end-method;

method IsNull
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.IsNull +/
   Return %This.KindIs(&KNull);
end-method;

method SetNull
   /+ Extends/implements C_JSON_API:JSONValue.SetNull +/
   Local boolean &ok;
   &ok = &StoreRef.SetNull(&NodeIdx);
end-method;

method SetString
   /+ &p_value as String +/
   /+ Extends/implements C_JSON_API:JSONValue.SetString +/
   %This.SetScalarCode(&KStr, "", &p_value);
end-method;

method SetInteger
   /+ &p_value as Integer +/
   /+ Extends/implements C_JSON_API:JSONValue.SetInteger +/
   %This.SetScalarCode(&KNum, "int", String(&p_value));
end-method;

method SetNumber
   /+ &p_value as Number +/
   /+ Extends/implements C_JSON_API:JSONValue.SetNumber +/
   %This.SetScalarCode(&KNum, "float", String(&p_value));
end-method;

method SetBoolean
   /+ &p_value as Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.SetBoolean +/
   If &p_value Then
      %This.SetScalarCode(&KBool, "", "true");
   Else
      %This.SetScalarCode(&KBool, "", "false");
   End-If;
end-method;

method SetTrue
   /+ Extends/implements C_JSON_API:JSONValue.SetTrue +/
   %This.SetScalarCode(&KBool, "", "true");
end-method;

method SetFalse
   /+ Extends/implements C_JSON_API:JSONValue.SetFalse +/
   %This.SetScalarCode(&KBool, "", "false");
end-method;

method SetDate
   /+ &p_value as Date +/
   /+ Extends/implements C_JSON_API:JSONValue.SetDate +/
   %This.SetScalarCode(&KDate, "", String(&p_value));
end-method;

method SetDateTime
   /+ &p_value as DateTime +/
   /+ Extends/implements C_JSON_API:JSONValue.SetDateTime +/
   %This.SetScalarCode(&KDttm, "", String(&p_value));
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONValue.ToString +/
   Return &StoreRef.ToJson(&NodeIdx);
end-method;

import C_JSON_API:JSONObject;
