import C_JSON_API:JSONParser;
import C_JSON_API:JSONBuilder;

/* Change DefaultBackend to CustomApi or JavaApi for an installation override.
   AUTO selects at target compile time. No backend is statically imported. */
class Factory
   method Factory();
   method SetBackend(&p_backend As string);
   method GetBackend() Returns string;
   method DefaultForRelease(&p_release As string) Returns string;
   method NewObject() Returns C_JSON_API:JSONObject;
   method NewArray() Returns C_JSON_API:JSONArray;
   method NewNode() Returns C_JSON_API:JSONNode;
   method NewValue() Returns C_JSON_API:JSONValue;
   method NewParser() Returns C_JSON_API:JSONParser;
   method NewBuilder() Returns C_JSON_API:JSONBuilder;
private
   Constant &DefaultBackend = "AUTO";
   instance string &Backend;
   method Resolve(&p_backend As string) Returns string;
end-class;

method Factory
   &Backend = %This.Resolve(&DefaultBackend);
end-method;

method Resolve
   /+ &p_backend as String +/
   /+ Returns String +/
   Local string &choice = Upper(&p_backend);
   If &choice = "AUTO" Then
      #If #ToolsRel >= "8.55.11" #Then
         Return "NativeApi";
      #Else
         Return "CustomApi";
      #End-If
   End-If;
   If &choice = "CUSTOMAPI" Then
      Return "CustomApi";
   End-If;
   If &choice = "NATIVEAPI" Then
      #If #ToolsRel >= "8.55.11" #Then
         Return "NativeApi";
      #Else
         throw CreateException(0, 0, "NativeApi requires PeopleTools 8.55.11 or newer");
      #End-If
   End-If;
   If &choice = "JAVAAPI" Then
      Return "JavaApi";
   End-If;
   throw CreateException(0, 0, "JSON backend must be AUTO, CustomApi, NativeApi, or JavaApi");
end-method;

method SetBackend
   /+ &p_backend as String +/
   Local string &choice = %This.Resolve(&p_backend);
   Local object &probe;
   try
      &probe = CreateObject("C_JSON_API:" | &choice | ":JSONParser");
   catch Exception &missingBackend
      throw CreateException(0, 0, "JSON backend " | &choice | " is unavailable: " | &missingBackend.ToString());
   end-try;
   &Backend = &choice;
end-method;

method GetBackend
   /+ Returns String +/
   Return &Backend;
end-method;

method DefaultForRelease
   /+ &p_release as String +/
   /+ Returns String +/
   Local array of string &parts = Split(&p_release, ".");
   Local integer &major, &minor, &patch;
   If &parts.Len < 2 Or
         &parts.Len > 3 Then
      throw CreateException(0, 0, "Invalid PeopleTools release");
   End-If;
   &major = Value(&parts [1]);
   &minor = Value(&parts [2]);
   &patch = 0;
   If &parts.Len = 3 Then
      &patch = Value(&parts [3]);
   End-If;
   If &major > 8 Or
         (&major = 8 And
            &minor > 55) Or
         (&major = 8 And
            &minor = 55 And
            &patch >= 11) Then
      Return "NativeApi";
   End-If;
   Return "CustomApi";
end-method;

method NewObject
   /+ Returns C_JSON_API:JSONObject +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONObject");
end-method;

method NewArray
   /+ Returns C_JSON_API:JSONArray +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONArray");
end-method;

method NewNode
   /+ Returns C_JSON_API:JSONNode +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONNode");
end-method;

method NewValue
   /+ Returns C_JSON_API:JSONValue +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONValue");
end-method;

method NewParser
   /+ Returns C_JSON_API:JSONParser +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONParser");
end-method;

method NewBuilder
   /+ Returns C_JSON_API:JSONBuilder +/
   Return CreateObject("C_JSON_API:" | &Backend | ":JSONBuilder");
end-method;

