/* C_JSON_API:JavaApi:JSONParser —— 实现 C_JSON_API:JSONParser 接口；
 * 方法集对齐 8.57 内置 JsonParser：Parse / GetRootObject / ToString 三个方法；
 * 这里额外提供 GetError() 便于排障（超集，不影响兼容性）。
 */
class JSONParser implements C_JSON_API:JSONParser
   method JSONParser();
   method Parse(&p_src As string) Returns boolean;
   method GetRootObject() Returns C_JSON_API:JSONObject;
   method ToString() Returns string;
   method GetError() Returns string;
private
   instance boolean &Parsed;
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
end-class;

method JSONParser
   &StoreRef = create C_JSON_API:JavaApi:JSONStorage();
end-method;

method Parse
   /+ &p_src as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONParser.Parse +/
   &Parsed = &StoreRef.Parse(&p_src);
   Return &Parsed;
end-method;

method GetRootObject
   /+ Returns C_JSON_API:JSONObject +/
   /+ Extends/implements C_JSON_API:JSONParser.GetRootObject +/
   Local object &o;
   If Not &Parsed Or
         &StoreRef.Kind(&StoreRef.Root()) <> "object" Then
      Return Null;
   End-If;
   &o = CreateObject("C_JSON_API:JavaApi:JSONObject");
   &o.BindCode(&StoreRef, &StoreRef.Root());
   Return &o;
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONParser.ToString +/
   If Not &Parsed Then
      Return "";
   End-If;
   Return &StoreRef.ToJson(&StoreRef.Root());
end-method;

method GetError
   /+ Returns String +/
   Return &StoreRef.GetError();
end-method;

import C_COMMONS_PKG:JavaReflect;
import C_JSON_API:CustomApi:JSONStorage;

/* org.json owns parsing and JSON output. The inherited node arena supplies
   shared child nodes, parent traversal, and deep-copy behavior for all wrappers.
   The portable parser is used only as a strict JSON syntax guard because older
   org.json releases also accept JavaScript object literals and trailing commas. */
class JSONStorage extends C_JSON_API:CustomApi:JSONStorage
   method JSONStorage();
   method Parse(&srcStore As string) Returns boolean;
   method ToJson(&idx As integer) Returns string;
private
   instance C_COMMONS_PKG:JavaReflect &Java;
   instance JavaObject &JavaNull;
   method ImportContainer(&p_container As JavaObject, &p_node As integer, &p_objectMode As boolean);
   method ImportMember(&p_container As JavaObject, &p_parent As integer, &p_name As string, &p_offset As integer, &p_objectMode As boolean);
   method ScalarObject(&p_idx As integer) Returns JavaObject;
end-class;

method JSONStorage
   /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.JSONStorage +/
   &Java = create C_COMMONS_PKG:JavaReflect();
   %Super = create C_JSON_API:CustomApi:JSONStorage();
   Local JavaObject &probe = &Java.NewObject("org.json.JSONObject", CreateArrayRept("", 0), CreateArrayAny());
   &JavaNull = &probe.getClass().getField("NULL").get( Null);
end-method;

method Parse
   /+ &srcStore as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.Parse +/
   Local C_JSON_API:CustomApi:JSONStorage &strict = create C_JSON_API:CustomApi:JSONStorage();
   Local JavaObject &tokener, &rootObject;
   Local string &className;
   Local integer &rootIndex;
   %This.Reset();
   If Not &strict.Parse(&srcStore) Then
      Return %This.Fail(&strict.GetError());
   End-If;
   try
      &tokener = &Java.NewObject("org.json.JSONTokener", CreateArray("java.lang.String"), CreateArrayAny(&srcStore));
      &rootObject = &tokener.nextValue();
      &className = &rootObject.getClass().getName();
      If &className = "org.json.JSONObject" Then
         &rootIndex = %This.NewNode("object", "", "");
         %This.ImportContainer(&rootObject, &rootIndex, True);
      Else
         If &className = "org.json.JSONArray" Then
            &rootIndex = %This.NewNode("array", "", "");
            %This.ImportContainer(&rootObject, &rootIndex, False);
         Else
            Return %This.Fail("JSONParser requires an object or array root");
         End-If;
      End-If;
      %This.SetRoot(&rootIndex);
      Return True;
   catch Exception &parseFailure
      %This.Reset();
      Return %This.Fail(&parseFailure.ToString());
   end-try;
end-method;

method ImportContainer
   /+ &p_container as JavaObject, +/
   /+ &p_node as Integer, +/
   /+ &p_objectMode as Boolean +/
   Local JavaObject &container, &names;
   Local integer &i, &count;
   Local string &name;
   &container = &p_container.getClass().cast(&p_container);
   &count = &container.length();
   If &p_objectMode Then
      &names = &container.names();
   End-If;
   For &i = 0 To &count - 1
      &name = "";
      If &p_objectMode Then
         &name = &names.optString(&i);
      End-If;
      %This.ImportMember(&container, &p_node, &name, &i, &p_objectMode);
   End-For;
end-method;

method ImportMember
   /+ &p_container as JavaObject, +/
   /+ &p_parent as Integer, +/
   /+ &p_name as String, +/
   /+ &p_offset as Integer, +/
   /+ &p_objectMode as Boolean +/
   Local JavaObject &container, &childObject, &childArray;
   Local string &kindText, &subText, &scalarText;
   Local integer &childIndex;
   Local boolean &isNull, &attached;
   &container = &p_container.getClass().cast(&p_container);
   If &p_objectMode Then
      &childObject = &container.optJSONObject(&p_name);
      &childArray = &container.optJSONArray(&p_name);
      &isNull = &container.isNull(&p_name);
   Else
      &childObject = &container.optJSONObject(&p_offset);
      &childArray = &container.optJSONArray(&p_offset);
      &isNull = &container.isNull(&p_offset);
   End-If;
   &scalarText = "";
   &subText = "";
   If &childObject <> Null Then
      &kindText = "object";
   Else
      If &childArray <> Null Then
         &kindText = "array";
      Else
         If &isNull Then
            &kindText = "null";
            &scalarText = "null";
         Else
            If &p_objectMode Then
               &scalarText = GetJavaClass("org.json.JSONObject").valueToString(&container.get(&p_name));
            Else
               &scalarText = GetJavaClass("org.json.JSONObject").valueToString(&container.get(&p_offset));
            End-If;
            If Left(&scalarText, 1) = Char(34) Then
               &kindText = "string";
               If &p_objectMode Then
                  &scalarText = &container.getString(&p_name);
               Else
                  &scalarText = &container.getString(&p_offset);
               End-If;
            Else
               If &scalarText = "true" Or
                     &scalarText = "false" Then
                  &kindText = "boolean";
               Else
                  &kindText = "number";
                  &subText = "int";
                  If Find(".", &scalarText) > 0 Or
                        Find("e", Lower(&scalarText)) > 0 Then
                     &subText = "float";
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
   End-If;
   &childIndex = %This.NewNode(&kindText, &subText, &scalarText);
   &attached = %This.AppendChild(&p_parent, &childIndex, &p_name);
   If Not &attached Then
      throw CreateException(0, 0, "Cannot attach org.json node");
   End-If;
   If &kindText = "object" Then
      %This.ImportContainer(&childObject, &childIndex, True);
   End-If;
   If &kindText = "array" Then
      %This.ImportContainer(&childArray, &childIndex, False);
   End-If;
end-method;

method ScalarObject
   /+ &p_idx as Integer +/
   /+ Returns JavaObject +/
   Local string &kindText = %This.Kind(&p_idx);
   If &kindText = "null" Or
         &kindText = "" Then
      Return &JavaNull;
   End-If;
   If &kindText = "number" Then
      Return &Java.NewObject("java.math.BigDecimal", CreateArray("java.lang.String"), CreateArrayAny(%This.Text(&p_idx)));
   End-If;
   If &kindText = "boolean" Then
      Return &Java.NewObject("java.lang.Boolean", CreateArray("java.lang.String"), CreateArrayAny(%This.Text(&p_idx)));
   End-If;
   Return &Java.NewObject("java.lang.String", CreateArray("java.lang.String"), CreateArrayAny(%This.Text(&p_idx)));
end-method;

method ToJson
   /+ &idx as Integer +/
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.ToJson +/
   Local JavaObject &writer, &valueMethod, &types, &args, &ignored;
   Local array of number &nodeStack, &positionStack;
   Local string &kindText;
   Local integer &topIndex, &nodeIndex, &position, &childIndex;
   &kindText = %This.Kind(&idx);
   If &kindText = "" Then
      Return "";
   End-If;
   If &kindText <> "object" And
         &kindText <> "array" Then
      Return GetJavaClass("org.json.JSONObject").valueToString(%This.ScalarObject(&idx));
   End-If;
   &writer = &Java.NewObject("org.json.JSONStringer", CreateArrayRept("", 0), CreateArrayAny());
   &types = &Java.Types(CreateArray("java.lang.Object"));
   &valueMethod = &writer.getClass().getMethod("value", &types);
   &args = &Java.NewArray("java.lang.Object", 1);
   If &kindText = "object" Then
      &ignored = &writer.object();
   Else
      &ignored = &writer.array();
   End-If;
   &nodeStack = CreateArrayRept(0, 0);
   &positionStack = CreateArrayRept(0, 0);
   &nodeStack.Push(&idx);
   &positionStack.Push(1);
   While &nodeStack.Len > 0
      &topIndex = &nodeStack.Len;
      &nodeIndex = &nodeStack [&topIndex];
      &position = &positionStack [&topIndex];
      If &position > %This.ChildCount(&nodeIndex) Then
         If %This.Kind(&nodeIndex) = "object" Then
            &ignored = &writer.endObject();
         Else
            &ignored = &writer.endArray();
         End-If;
         &nodeStack.Len = &topIndex - 1;
         &positionStack.Len = &topIndex - 1;
      Else
         &positionStack [&topIndex] = &position + 1;
         &childIndex = %This.ChildAt(&nodeIndex, &position);
         If %This.Kind(&nodeIndex) = "object" Then
            &ignored = &writer.key(%This.NameOf(&childIndex));
         End-If;
         &kindText = %This.Kind(&childIndex);
         If &kindText = "object" Or
               &kindText = "array" Then
            If &kindText = "object" Then
               &ignored = &writer.object();
            Else
               &ignored = &writer.array();
            End-If;
            &nodeStack.Push(&childIndex);
            &positionStack.Push(1);
         Else
            GetJavaClass("java.lang.reflect.Array").set(&args, 0, %This.ScalarObject(&childIndex));
            &ignored = &Java.Invoke(&valueMethod, &writer, &args);
         End-If;
      End-If;
   End-While;
   Return &writer.toString();
end-method;

