method GetValue
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONValue.GetValue +/
   Local string &k, &t;
   Local any &v;
   &t = &StoreRef.Text(&NodeIdx);
   &k = &StoreRef.Kind(&NodeIdx);
   &v = Null;
   If &k = "string" Then
      &v = &StoreRef.AsString(&NodeIdx);
   Else
      If &k = "number" Then
         &v = &StoreRef.AsNumber(&NodeIdx);
      Else
         If &k = "boolean" Then
            If &t = "true" Then
               &v = True;
            Else
               &v = False;
            End-If;
         Else
            If &k = "date" And
                  &t <> "" Then
               &v = Date(&t);
            Else
               If &k = "time" And
                     &t <> "" Then
                  &v = TimeValue(&t);
               Else
                  If &k = "datetime" And
                        &t <> "" Then
                     &v = DateTimeValue(&t);
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
   End-If;
   Return &v;
end-method;

