import C_JSON_API:*;

/* The metadata transport accepts and returns plain strings. Legacy request
   payload fields still receive their explicit UnEscapeJSON in the handlers. */
class JsonUtil
   method JsonUtil();
   method GetRootObject(&MessageContent As string) Returns C_JSON_API:JSONObject;
   method CreateSuccessMessage(&OperationName As string, &Data As C_JSON_API:JSONObject) Returns Message;
   method CreateFailedMessage(&OperationName As string, &Code As integer, &ErrStr As string) Returns Message;
private
   method Response(&p_operation As string, &p_body As C_JSON_API:JSONObject) Returns Message;
end-class;

method JsonUtil
end-method;

method GetRootObject
   /+ &MessageContent as String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:Factory &factory = create C_JSON_API:Factory();
   Local C_JSON_API:JSONParser &parser = &factory.NewParser();
   Local C_JSON_API:JSONObject &root;
   Local string &content = &MessageContent;
   If Left(LTrim(&content), 1) = "[" Then
      /* Preserve the legacy unnamed member used by Field batch requests. */
      &content = "{"""":" | &content | "}";
   End-If;
   If Not &parser.Parse(&content) Then
      throw CreateException(0, 0, "INVALID_JSON: request body is not valid JSON");
   End-If;
   &root = &parser.GetRootObject();
   If &root = Null Then
      throw CreateException(0, 0, "INVALID_JSON: request body must be an object");
   End-If;
   Return &root;
end-method;

method Response
   /+ &p_operation as String, +/
   /+ &p_body as C_JSON_API:JSONObject +/
   /+ Returns Message +/
   Local string &name = &p_operation;
   Local Message &reply;
   Local boolean &ok;
   If Upper(Left(&name, 10)) = "OPERATION." Then
      &name = Substring(&name, 11, Len(&name));
   End-If;
   &reply = CreateMessage(@("Operation." | &name), %IntBroker_Response);
   &ok = &reply.SetContentString(&p_body.ToString());
   If Not &ok Then
      throw CreateException(0, 0, "Cannot serialize metadata response");
   End-If;
   Return &reply;
end-method;

method CreateSuccessMessage
   /+ &OperationName as String, +/
   /+ &Data as C_JSON_API:JSONObject +/
   /+ Returns Message +/
   Local C_JSON_API:Factory &factory = create C_JSON_API:Factory();
   Local C_JSON_API:JSONObject &body = &factory.NewObject();
   Local C_JSON_API:JSONNode &node;
   &body.AddNumber("code", 0);
   &body.AddString("message", "success");
   If &Data <> Null Then
      &body.AddJsonObject("data", &Data);
   Else
      &body.AddNumber("data", 0);
      &node = &body.GetJsonNode("data");
      &node.SetNull();
   End-If;
   Return %This.Response(&OperationName, &body);
end-method;

method CreateFailedMessage
   /+ &OperationName as String, +/
   /+ &Code as Integer, +/
   /+ &ErrStr as String +/
   /+ Returns Message +/
   Local C_JSON_API:Factory &factory = create C_JSON_API:Factory();
   Local C_JSON_API:JSONBuilder &body = &factory.NewBuilder();
   Local C_JSON_API:JSONParser &parser = &factory.NewParser();
   &body.AddNumber("code", &Code);
   &body.AddString("message", &ErrStr);
   &body.AddNullProperty("data");
   If Not &parser.Parse(&body.ToString()) Then
      throw CreateException(0, 0, "Cannot serialize metadata error response");
   End-If;
   Return %This.Response(&OperationName, &parser.GetRootObject());
end-method;

