/* C_JSON_API:NativeApi:JSONParser —— 实现 C_JSON_API:JSONParser 接口；
 * 方法集对齐 8.57 内置 JsonParser：Parse / GetRootObject / ToString 三个方法；
 * 这里额外提供 GetError() 便于排障（超集，不影响兼容性）。
 */
class JSONParser implements C_JSON_API:JSONParser
   method JSONParser();
   method Parse(&p_src As string) Returns boolean;
   method GetRootObject() Returns C_JSON_API:JSONObject;
   method ToString() Returns string;
   method GetError() Returns string;
private
   instance boolean &Parsed;
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
end-class;

method JSONParser
   &StoreRef = create C_JSON_API:NativeApi:JSONStorage();
end-method;

method Parse
   /+ &p_src as String +/
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONParser.Parse +/
   &Parsed = &StoreRef.Parse(&p_src);
   Return &Parsed;
end-method;

method GetRootObject
   /+ Returns C_JSON_API:JSONObject +/
   /+ Extends/implements C_JSON_API:JSONParser.GetRootObject +/
   Local object &o;
   If Not &Parsed Or
         &StoreRef.Kind(&StoreRef.Root()) <> "object" Then
      Return Null;
   End-If;
   &o = CreateObject("C_JSON_API:NativeApi:JSONObject");
   &o.BindCode(&StoreRef, &StoreRef.Root());
   Return &o;
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONParser.ToString +/
   If Not &Parsed Then
      Return "";
   End-If;
   Return &StoreRef.ToJson(&StoreRef.Root());
end-method;

method GetError
   /+ Returns String +/
   Return &StoreRef.GetError();
end-method;

#If #ToolsRel >= "8.55.11" #Then
   import C_JSON_API:CustomApi:JSONStorage;
   import C_JSON_API:Scalar;

   /* Native validation and output, with the common node arena for consistent
   parent links, scalar array nodes, replacement, and copy semantics. */
   class JSONStorage extends C_JSON_API:CustomApi:JSONStorage
      method JSONStorage();
      method Parse(&srcStore As string) Returns boolean;
      method ToJson(&idx As integer) Returns string;
   end-class;

   method JSONStorage
      /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.JSONStorage +/
      %Super = create C_JSON_API:CustomApi:JSONStorage();
   end-method;

   method Parse
      /+ &srcStore as String +/
      /+ Returns Boolean +/
      /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.Parse +/
      Local JsonParser &parser = CreateJsonParser();
      Local boolean &parsed;
      %This.Reset();
      try
         &parsed = &parser.Parse(&srcStore);
         If Not &parsed Then
            Return %This.Fail("Native JSON parser rejected the input");
         End-If;
      catch Exception &parseFailure
         Return %This.Fail(&parseFailure.ToString());
      end-try;
      /* Retain exact number lexemes and enforce strict syntax across providers. */
      Return %Super.Parse(&srcStore);
   end-method;

   method ToJson
      /+ &idx as Integer +/
      /+ Returns String +/
      /+ Extends/implements C_JSON_API:CustomApi:JSONStorage.ToJson +/
      Local JsonBuilder &writer;
      Local C_JSON_API:Scalar &scalar = create C_JSON_API:Scalar();
      Local array of number &nodeStack, &positionStack;
      Local array of string &nameStack;
      Local string &kindText, &nodeName, &valueText, &output;
      Local integer &topIndex, &nodeIndex, &position, &childIndex;
      Local boolean &arrayRoot;
      &kindText = %This.Kind(&idx);
      If &kindText = "" Then
         Return "";
      End-If;
      If &kindText <> "object" And
            &kindText <> "array" Then
         If &kindText = "number" Or
               &kindText = "boolean" Or
               &kindText = "null" Then
            Return %This.Text(&idx);
         End-If;
         Return Char(34) | &scalar.Escape(%This.Text(&idx)) | Char(34);
      End-If;
      &writer = CreateJsonBuilder();
      &writer.StartObject("");
      &arrayRoot = (&kindText = "array");
      &nodeName = "";
      If &arrayRoot Then
         &nodeName = "__array";
         &writer.StartArray(&nodeName);
      End-If;
      &nodeStack = CreateArrayRept(0, 0);
      &positionStack = CreateArrayRept(0, 0);
      &nameStack = CreateArrayRept("", 0);
      &nodeStack.Push(&idx);
      &positionStack.Push(1);
      &nameStack.Push(&nodeName);
      While &nodeStack.Len > 0
         &topIndex = &nodeStack.Len;
         &nodeIndex = &nodeStack [&topIndex];
         &position = &positionStack [&topIndex];
         If &position > %This.ChildCount(&nodeIndex) Then
            &nodeName = &nameStack [&topIndex];
            If %This.Kind(&nodeIndex) = "object" Then
               &writer.EndObject(&nodeName);
            Else
               &writer.EndArray(&nodeName);
            End-If;
            &nodeStack.Len = &topIndex - 1;
            &positionStack.Len = &topIndex - 1;
            &nameStack.Len = &topIndex - 1;
         Else
            &positionStack [&topIndex] = &position + 1;
            &childIndex = %This.ChildAt(&nodeIndex, &position);
            &nodeName = "";
            If %This.Kind(&nodeIndex) = "object" Then
               &nodeName = &scalar.Escape(%This.NameOf(&childIndex));
            End-If;
            &kindText = %This.Kind(&childIndex);
            If &kindText = "object" Or
                  &kindText = "array" Then
               If &kindText = "object" Then
                  &writer.StartObject(&nodeName);
               Else
                  &writer.StartArray(&nodeName);
               End-If;
               &nodeStack.Push(&childIndex);
               &positionStack.Push(1);
               &nameStack.Push(&nodeName);
            Else
               &valueText = %This.Text(&childIndex);
               If %This.Kind(&nodeIndex) = "array" Then
                  Evaluate &kindText
                  When "null"
                     &writer.AddNullElement();
                  When "number"
                     &writer.AddElement(Value(&valueText));
                  When "boolean"
                     &writer.AddElement((&valueText = "true"));
                  When-Other
                     &writer.AddElement(&scalar.Escape(&valueText));
                  End-Evaluate;
               Else
                  Evaluate &kindText
                  When "null"
                     &writer.AddNullProperty(&nodeName);
                  When "number"
                     &writer.AddProperty(&nodeName, Value(&valueText));
                  When "boolean"
                     &writer.AddProperty(&nodeName, (&valueText = "true"));
                  When-Other
                     &writer.AddProperty(&nodeName, &scalar.Escape(&valueText));
                  End-Evaluate;
               End-If;
            End-If;
         End-If;
      End-While;
      If &arrayRoot Then
         &writer.EndObject("");
      End-If;
      &output = &writer.ToString();
      If &arrayRoot Then
         /* JsonBuilder always has an object root; unwrap our fixed member. */
         &position = Find(":", &output);
         Return Substring(&output, &position + 1, Len(&output) - &position - 1);
      End-If;
      Return &output;
   end-method;

#Else
import C_JSON_API:CustomApi:JSONStorage;
class JSONStorage extends C_JSON_API:CustomApi:JSONStorage
   method JSONStorage();
end-class;
method JSONStorage
   %Super = create C_JSON_API:CustomApi:JSONStorage();
   throw CreateException(0, 0, "NativeApi requires PeopleTools 8.55.11 or newer");
end-method;
#End-If

import C_JSON_API:JSONValue;
import C_JSON_API:CustomApi:JSONStorage;
import C_JSON_API:NativeApi:JSONStorage;

/* C_JSON_API:NativeApi:JSONValue — 对齐 8.57 内置 JsonValue 的方法集（19 个方法）。
 *
 * 与内置一致的语义：
 *   - 值节点持有 (JSONStorage, 下标)，通过 GetJsonValue() 拿到的子节点与原对象
 *     共享同一份存储，SetXxx() 会改到父对象。
 * 存储无关：纯 PeopleCode，不依赖 8.55+ 的 JSON 内建类。
 */
class JSONValue implements C_JSON_API:JSONValue
   method JSONValue();

   method Store() Returns any;
   method NodeIndex() Returns integer;
   method BindCode(&p_store As C_JSON_API:CustomApi:JSONStorage, &p_idx As integer);

   method GetBoolean() Returns boolean;
   method GetDate() Returns date;
   method GetDateTime() Returns datetime;
   method GetInteger() Returns integer;
   method GetNumber() Returns number;
   method GetString() Returns string;
   method GetTime() Returns time;
   method GetValue() Returns any;
   method IsNull() Returns boolean;
   method SetBoolean(&p_value As boolean);
   method SetDate(&p_value As date);
   method SetDateTime(&p_value As datetime);
   method SetFalse();
   method SetInteger(&p_value As integer);
   method SetNull();
   method SetNumber(&p_value As number);
   method SetString(&p_value As string);
   method SetTrue();
   method ToString() Returns string;
private
   instance C_JSON_API:CustomApi:JSONStorage &StoreRef;
   instance integer &NodeIdx;
   instance string &KStr;
   instance string &KNum;
   instance string &KBool;
   instance string &KNull;
   instance string &KDate;
   instance string &KTime;
   instance string &KDttm;

   method InitKinds();
   method KindIs(&p_k As string) Returns boolean;
   method SetScalarCode(&p_kindStr As string, &p_sub As string, &p_txt As string);
end-class;

method JSONValue
   %This.InitKinds();
   &StoreRef = create C_JSON_API:NativeApi:JSONStorage();
   &NodeIdx = &StoreRef.NewNode(&KNull, "", "null");
end-method;

method InitKinds
   &KStr = "string";
   &KNum = "number";
   &KBool = "boolean";
   &KNull = "null";
   &KDate = "date";
   &KTime = "time";
   &KDttm = "datetime";
end-method;

method KindIs
   /+ &p_k as String +/
   /+ Returns Boolean +/
   Local string &k;
   &k = &StoreRef.Kind(&NodeIdx);
   If &k = &p_k Then
      Return True;
   End-If;
   Return False;
end-method;

method SetScalarCode
   /+ &p_kindStr as String, +/
   /+ &p_sub as String, +/
