end-method;

method GetBoolean
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.GetBoolean +/
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "true" Then
      Return True;
   End-If;
   Return False;
end-method;

method GetDate
   /+ Returns Date +/
   /+ Extends/implements C_JSON_API:JSONValue.GetDate +/
   Local date &d;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &d;
   End-If;
   Return Date(&t);
end-method;

method GetTime
   /+ Returns Time +/
   /+ Extends/implements C_JSON_API:JSONValue.GetTime +/
   Local time &tm;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &tm;
   End-If;
   Return TimeValue(&t);
end-method;

method GetDateTime
   /+ Returns DateTime +/
   /+ Extends/implements C_JSON_API:JSONValue.GetDateTime +/
   Local datetime &dt;
   Local string &t;
   &t = &StoreRef.Text(&NodeIdx);
   If &t = "" Then
      Return &dt;
   End-If;
   Return DateTimeValue(&t);
end-method;

method GetValue
   /+ Returns Any +/
   /+ Extends/implements C_JSON_API:JSONValue.GetValue +/
   Local string &k, &t;
   Local any &v;
   &t = &StoreRef.Text(&NodeIdx);
   &k = &StoreRef.Kind(&NodeIdx);
   &v = Null;
   If &k = "string" Then
      &v = &StoreRef.AsString(&NodeIdx);
   Else
      If &k = "number" Then
         &v = &StoreRef.AsNumber(&NodeIdx);
      Else
         If &k = "boolean" Then
            If &t = "true" Then
               &v = True;
            Else
               &v = False;
            End-If;
         Else
            If &k = "date" And
                  &t <> "" Then
               &v = Date(&t);
            Else
               If &k = "time" And
                     &t <> "" Then
                  &v = TimeValue(&t);
               Else
                  If &k = "datetime" And
                        &t <> "" Then
                     &v = DateTimeValue(&t);
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
   End-If;
   Return &v;
end-method;

method IsNull
   /+ Returns Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.IsNull +/
   Return %This.KindIs(&KNull);
end-method;

method SetNull
   /+ Extends/implements C_JSON_API:JSONValue.SetNull +/
   Local boolean &ok;
   &ok = &StoreRef.SetNull(&NodeIdx);
end-method;

method SetString
   /+ &p_value as String +/
   /+ Extends/implements C_JSON_API:JSONValue.SetString +/
   %This.SetScalarCode(&KStr, "", &p_value);
end-method;

method SetInteger
   /+ &p_value as Integer +/
   /+ Extends/implements C_JSON_API:JSONValue.SetInteger +/
   %This.SetScalarCode(&KNum, "int", String(&p_value));
end-method;

method SetNumber
   /+ &p_value as Number +/
   /+ Extends/implements C_JSON_API:JSONValue.SetNumber +/
   %This.SetScalarCode(&KNum, "float", String(&p_value));
end-method;

method SetBoolean
   /+ &p_value as Boolean +/
   /+ Extends/implements C_JSON_API:JSONValue.SetBoolean +/
   If &p_value Then
      %This.SetScalarCode(&KBool, "", "true");
   Else
      %This.SetScalarCode(&KBool, "", "false");
   End-If;
end-method;

method SetTrue
   /+ Extends/implements C_JSON_API:JSONValue.SetTrue +/
   %This.SetScalarCode(&KBool, "", "true");
end-method;

method SetFalse
   /+ Extends/implements C_JSON_API:JSONValue.SetFalse +/
   %This.SetScalarCode(&KBool, "", "false");
end-method;

method SetDate
   /+ &p_value as Date +/
   /+ Extends/implements C_JSON_API:JSONValue.SetDate +/
   %This.SetScalarCode(&KDate, "", String(&p_value));
end-method;

method SetDateTime
   /+ &p_value as DateTime +/
   /+ Extends/implements C_JSON_API:JSONValue.SetDateTime +/
   %This.SetScalarCode(&KDttm, "", String(&p_value));
end-method;

method ToString
   /+ Returns String +/
   /+ Extends/implements C_JSON_API:JSONValue.ToString +/
   Return &StoreRef.ToJson(&NodeIdx);
end-method;

import C_COMMONS_PKG:JavaReflect;

/* PeopleCode preserves scalar types at the standard Java bridge boundary.
   No org.json or third-party jar is used by this helper. */
class Scalar
   method Scalar();
   method Kind(&p_value As any) Returns string;
   method Escape(&p_text As string) Returns string;
private
   instance C_COMMONS_PKG:JavaReflect &Java;
end-class;

method Scalar
   &Java = create C_COMMONS_PKG:JavaReflect();
end-method;

method Kind
   /+ &p_value as Any +/
   /+ Returns String +/
   Local string &className;
   Local object &candidate, &storage;
   Local integer &nodeIndex;
   try
      If &p_value = Null Then
         Return "null";
      End-If;
   catch Exception &notObject
   end-try;
   try
      &candidate = &p_value;
      &storage = &candidate.Store();
      &nodeIndex = &candidate.NodeIndex();
      Return &storage.Kind(&nodeIndex);
   catch Exception &notJsonContainer
   end-try;
   &className = &Java.ClassName(&p_value);
   If &className = "java.lang.Boolean" Then
      Return "boolean";
   End-If;
   If &className = "java.lang.String" Or
         &className = "java.lang.Character" Then
      Return "string";
   End-If;
   If &className = "java.sql.Date" Then
      Return "date";
   End-If;
   If &className = "java.sql.Time" Then
      Return "time";
   End-If;
   If &className = "java.sql.Timestamp" Then
      Return "datetime";
   End-If;
   If &className = "java.util.Date" Then
      /* The bridge uses Date for all PeopleCode temporal primitives. Their
         String representation remains intact; explicit AddDate/AddTime retain
         the more specific JSONValue kind when that distinction is needed. */
      Return "datetime";
   End-If;
   If &className = "java.lang.Integer" Or
         &className = "java.lang.Long" Or
         &className = "java.lang.Double" Or
         &className = "java.lang.Float" Or
         &className = "java.lang.Short" Or
         &className = "java.lang.Byte" Or
         &className = "java.math.BigDecimal" Or
         &className = "java.math.BigInteger" Then
      Return "number";
   End-If;
   throw CreateException(0, 0, "Unsupported JSON scalar type: " | &className);
end-method;

method Escape
   /+ &p_text as String +/
   /+ Returns String +/
   Local string &text;
   Local string &hex = "0123456789abcdef";
   Local string &bs = Char(92);
   Local integer &i;
   &text = Substitute(&p_text, &bs, &bs | &bs);
   &text = Substitute(&text, Char(34), &bs | Char(34));
   For &i = 1 To 31
      &text = Substitute(&text, Char(&i), &bs | "u00" | Substring(&hex, Int(&i / 16) + 1, 1) | Substring(&hex, Mod(&i, 16) + 1, 1));
   End-For;
   Return &text;
end-method;

