class OperDefinitionList implements PS_PT:Integration:IRequestHandler
   method OperDefinitionList();
   method OnRequest(&message As Message) Returns Message;
end-class;

method OperDefinitionList
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_JSON_API:JSONObject &req, &out, &row;
   Local C_JSON_API:JSONArray &rows = CreateObject("C_JSON_API:Factory").NewArray();
   Local SQL &cursor;
   Local string &kind, &prefix, &afterName, &base, &pattern, &sql, &name, &descr, &nextAfter, &field;
   Local string &portal = "EMPLOYEE";
   Local string &refType = "F";
   Local number &limit = 50;
   Local integer &i;
   Local integer &count = 0;
   Local boolean &more = False;
   Local array of string &allowed = CreateArray("kind", "prefix", "after", "limit", "PortalName", "RefType", "IsLink");
   try
      &req = &json.GetRootObject(&message.GetContentString());
      For &i = 1 To &req.ChildCount
         &field = &req.GetPropertyNameAt(&i);
         If &allowed.Find(&field) = 0 Then
            throw CreateException(0, 0, "Unknown list property: " | &field);
         End-If;
      End-For;
      &kind = &req.GetString("kind");
      If &req.IsExist("prefix") Then
         &prefix = Upper(&req.GetString("prefix"));
      End-If;
      If &req.IsExist("after") Then
         &afterName = Upper(&req.GetString("after"));
      End-If;
      If Len(&prefix) > 30 Or
            Len(&afterName) > 30 Then
         throw CreateException(0, 0, "prefix and after must be at most 30 characters");
      End-If;
      If &req.IsExist("limit") Then
         &limit = &req.GetNumber("limit");
      End-If;
      If &limit <> Int(&limit) Or
            &limit < 1 Or
            &limit > 200 Then
         throw CreateException(0, 0, "limit must be an integer from 1 to 200");
      End-If;
      Evaluate &kind
      When "service"
         &base = "SELECT IB_SERVICENAME AS NAME, DESCR FROM PSSERVICE";
         Break;
      When "operation"
         &base = "SELECT IB_OPERATIONNAME AS NAME, DESCR FROM PSOPERATION";
         Break;
      When "menu"
         &base = "SELECT MENUNAME AS NAME, DESCR FROM PSMENUDEFN";
         Break;
      When "catalog"
         &base = "SELECT TO_CHAR(MESSAGE_SET_NBR) AS NAME, DESCR FROM PSMSGSETDEFN";
         Break;
      When "html"
         &base = "SELECT CONTNAME AS NAME, DESCR FROM PSCONTDEFN WHERE CONTTYPE=4";
         Break;
      When "stylesheet"
         &base = "SELECT STYLESHEETNAME AS NAME, DESCR FROM PSSTYLSHEETDEFN";
         Break;
      When "ci"
         &base = "SELECT BCNAME AS NAME, DESCR FROM PSBCDEFN";
         Break;
      When "portal"
         If &req.IsExist("PortalName") Then
            &portal = &req.GetString("PortalName");
         End-If;
         If &req.IsExist("RefType") Then
            &refType = &req.GetString("RefType");
         End-If;
         If Len(&portal) < 1 Or
               Len(&portal) > 30 Or
               (&refType <> "F" And
                  &refType <> "C") Then
            throw CreateException(0, 0, "PortalName and RefType=F/C are required for portal listing");
         End-If;
         &base = "SELECT PORTAL_OBJNAME AS NAME, PORTAL_LABEL AS DESCR FROM PSPRSMDEFN WHERE PORTAL_NAME=:4 AND PORTAL_REFTYPE=:5";
         If &refType = "C" And
               &req.IsExist("IsLink") Then
            If &req.GetBoolean("IsLink") Then
               &base = &base | " AND PORTAL_CREF_USGT='LINK'";
            Else
               &base = &base | " AND PORTAL_CREF_USGT<>'LINK'";
            End-If;
         End-If;
         Break;
      When-Other
         throw CreateException(0, 0, "Unsupported list kind");
      End-Evaluate;
      &pattern = Substitute(Substitute(Substitute(&prefix, "\", "\\"), "%", "\%"), "_", "\_") | "%";
      If &afterName = "" Then
         &afterName = " ";
      End-If;
      &sql = "SELECT NAME, DESCR FROM (SELECT NAME, DESCR FROM (" | &base | ") WHERE NAME LIKE :1 ESCAPE '\' AND NAME > :2 ORDER BY NAME) WHERE ROWNUM <= :3";
      If &kind = "portal" Then
         &cursor = CreateSQL(&sql, &pattern, &afterName, &limit + 1, &portal, &refType);
      Else
         &cursor = CreateSQL(&sql, &pattern, &afterName, &limit + 1);
      End-If;
      While &cursor.Fetch(&name, &descr)
         If &count >= &limit Then
            &more = True;
            Break;
         End-If;
         &row = CreateObject("C_JSON_API:Factory").NewObject();
         &row.AddProperty("name", &name);
         &row.AddProperty("descr", &descr);
         &rows.AddJsonObjectElement("", &row);
         &row = &rows.GetJsonObject(&rows.Size);
         &nextAfter = &name;
         &count = &count + 1;
      End-While;
      &cursor.Close();
      &out = CreateObject("C_JSON_API:Factory").NewObject();
      &out.AddProperty("kind", &kind);
      &out.AddProperty("prefix", &prefix);
      &out.AddProperty("hasMore", &more);
      &out.AddProperty("nextAfter", &nextAfter);
      &out.AddJsonArray("list", &rows);
      &rows = &out.GetJsonArray("list");
      Return &json.CreateSuccessMessage("AI_LIST_DEFN_POST", &out);
   catch Exception &ex
      Return &json.CreateFailedMessage("AI_LIST_DEFN_POST", 400, &ex.ToString());
   end-try;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import C_META_DATA_PKG:Utility:SqlTextGuard;

class OperExecSql implements PS_PT:Integration:IRequestHandler
   method OperExecSql();
   method OnRequest(&message As Message) Returns Message;
private
   method Query(&guard As C_META_DATA_PKG:Utility:SqlTextGuard) Returns C_JSON_API:JSONObject;
end-class;

method OperExecSql
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_META_DATA_PKG:Utility:SqlTextGuard &guard = create C_META_DATA_PKG:Utility:SqlTextGuard();
   Local C_JSON_API:JSONObject &req, &data;
   Local string &body = &message.GetContentString();
   try
      If Len(&body) > 262144 Then
         throw CreateException(0, 0, "Request exceeds 262144 characters");
      End-If;
      If Not &guard.Authorized("AI_EXEC_SQL_POST") Then
         Return &json.CreateFailedMessage("AI_EXEC_SQL_POST", 403, "Operation permission denied");
      End-If;
      &req = &guard.ParseRequest(&body);
      &guard.Validate(&req, False);
   catch Exception &invalid
      Return &json.CreateFailedMessage("AI_EXEC_SQL_POST", 400, Left(&invalid.ToString(), 2000));
   end-try;
   try
      &data = %This.Query(&guard);
      Return &json.CreateSuccessMessage("AI_EXEC_SQL_POST", &data);
   catch Exception &ex
      If Find("columns count differs", &ex.ToString()) > 0 Then
         Return &json.CreateFailedMessage("AI_EXEC_SQL_POST", 400, Left(&ex.ToString(), 2000));
      End-If;
      Return &json.CreateFailedMessage("AI_EXEC_SQL_POST", 999, Left(&ex.ToString(), 2000));
   end-try;
end-method;

method Query
   /+ &guard as C_META_DATA_PKG:Utility:SqlTextGuard +/
   /+ Returns C_JSON_API:JSONObject +/
   Local SQL &cursor;
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local array of any &values = CreateArrayAny();
   Local C_JSON_API:JSONObject &out, &row, &column;
   Local C_JSON_API:JSONArray &rows, &columns, &cells;
   Local integer &i, &width, &size;
   Local boolean &truncated = False;
   Local string &text, &name, &sql;
   &out = CreateObject("C_JSON_API:Factory").NewObject();
   &rows = CreateObject("C_JSON_API:Factory").NewArray();
   &columns = CreateObject("C_JSON_API:Factory").NewArray();
   &width = 0;
   &size = 0;
   try
      &sql = &guard.ExecutionText;
      If &guard.StatementType = "WITH" Then
         &sql = "SELECT * FROM (" | &sql | ")";
      End-If;
      &cursor = CreateSQL(&sql, &guard.Binds);
      While &cursor.Fetch(&values)
         If &rows.Size >= &guard.MaxRows Then
            &truncated = True;
            Break;
         End-If;
         If &width = 0 Then
            &width = &values.Len;
            If &width > 128 Then
               throw CreateException(0, 0, "Result exceeds 128 columns");
            End-If;
            If &guard.Columns.Len > 0 And
                  &guard.Columns.Len <> &width Then
               throw CreateException(0, 0, "columns count differs from result column count");
            End-If;
         End-If;
         &cells = CreateObject("C_JSON_API:Factory").NewArray();
         For &i = 1 To &width
            /* All(number 0) is False; use String to retain zero. Typed numeric
               NULL becomes 0 in PeopleCode; callers must TO_CHAR nullable numbers. */
            &text = String(&values [&i]);
            If Len(&text) > 65536 Then
               throw CreateException(0, 0, "Result cell exceeds 65536 characters");
            End-If;
            &cells.AddElement(&text);
         End-For;
         &row = CreateObject("C_JSON_API:Factory").NewObject();
         &row.AddJsonArray("v", &cells);
         &cells = &row.GetJsonArray("v");
         &size = &size + Len(&row.ToString());
         If &size > 1000000 Then
            throw CreateException(0, 0, "Result exceeds response character budget");
         End-If;
         &rows.AddJsonObjectElement("", &row);
         &row = &rows.GetJsonObject(&rows.Size);
      End-While;
      &cursor.Close();
   catch Exception &ex
      If All(&cursor) Then
         &cursor.Close();
      End-If;
      throw &ex;
   end-try;
   /* Empty results expose no column count. Preserve declared labels, otherwise []. */
   If &width = 0 Then
      &width = &guard.Columns.Len;
   End-If;
   For &i = 1 To &width
      &name = "c" | String(&i);
      If &guard.Columns.Len > 0 Then
         &name = &guard.Columns [&i];
      End-If;
      &column = CreateObject("C_JSON_API:Factory").NewObject();
      &column.AddProperty("name", &name);
      &columns.AddJsonObjectElement("", &column);
      &column = &columns.GetJsonObject(&columns.Size);
   End-For;
   &out.AddProperty("mode", "select");
   &out.AddProperty("source", &guard.Source);
   If &guard.Source = "sqlId" Then
      &out.AddProperty("sqlId", &guard.SqlId);
   End-If;
   &out.AddJsonArray("columns", &columns);
   &columns = &out.GetJsonArray("columns");
   &out.AddJsonArray("rows", &rows);
   &rows = &out.GetJsonArray("rows");
   &out.AddProperty("rowCount", &rows.Size);
   &out.AddProperty("truncated", &truncated);
   If Len(&out.ToString()) > 1048576 Then
      throw CreateException(0, 0, "Result exceeds 1048576 serialized characters");
   End-If;
   Return &out;
end-method;

