class SearchDefinition implements PS_PT:Integration:IRequestHandler
   method SearchDefinition();

   method OnRequest(&message As Message) Returns Message;
private
   method GetRecordDefinition(&p_name As string, &p_type As integer, &p_descr As string) Returns C_JSON_API:JSONArray;
   method GetFieldDefinition(&p_name As string, &p_type As integer) Returns C_JSON_API:JSONArray;
   method GetAppPackageDefinition(&p_name As string, &p_descr As string) Returns C_JSON_API:JSONArray;
   method GetSqlDefinition(&p_name As string, &p_type As integer, &p_descr As string) Returns C_JSON_API:JSONArray;
   method GetProjectDefinition(&p_name As string, &p_descr As string) Returns C_JSON_API:JSONArray;

   Constant &OperationName = "AI_SEARCH_DEFN_POST";
   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   instance C_JSON_API:JsonUtil &JsonUtil;
end-class;


method SearchDefinition
   &JsonUtil = create C_JSON_API:JsonUtil();
end-method;


method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local Message &RespMsg;
   Local C_JSON_API:JSONObject &ReqObject, &RespObject;
   Local C_JSON_API:JSONArray &DefnArr;
   Local integer &i, &j, &DefnType;
   Local string &DefnName, &RecordDescr, &AppPackageDescr, &SqlDescr, &ProjectDescr;

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      &RespObject = CreateObject("C_JSON_API:Factory").NewObject();

      /* 获取参数 */
      If Not &ReqObject.IsExist("definitionType") Then
         throw CreateException(0, 0, "definitionType is required");
      End-If;
      &DefnType = &ReqObject.GetNumber("definitionType");
      If &ReqObject.IsExist("definitionName") Then
         &DefnName = &ReqObject.GetString("definitionName");
      End-If;

      Evaluate &DefnType
      When 1
         /** 查Record **/
         Local integer &RecType = - 1;
         If &ReqObject.IsExist("recordType") Then
            &RecType = &ReqObject.GetNumber("recordType");
         End-If;
         If &ReqObject.IsExist("recordDescr") Then
            &RecordDescr = &ReqObject.GetString("recordDescr");
         End-If;
         &DefnArr = %This.GetRecordDefinition(&DefnName, &RecType, &RecordDescr);
         Break;
      When 2
         /** 查Field **/
         Local integer &FldType = - 1;
         If &ReqObject.IsExist("fieldType") Then
            &FldType = &ReqObject.GetNumber("fieldType");
         End-If;
         &DefnArr = %This.GetFieldDefinition(&DefnName, &FldType);
         Break;
      When 104
         /** 查Application Package **/
         If &ReqObject.IsExist("appPackageDescr") Then
            &AppPackageDescr = &ReqObject.GetString("appPackageDescr");
         End-If;
         &DefnArr = %This.GetAppPackageDefinition(&DefnName, &AppPackageDescr);
         Break;
      When 65
         /** 查SQL定义 **/
         Local integer &SqlType = - 1;
         If &ReqObject.IsExist("sqlType") Then
            &SqlType = &ReqObject.GetNumber("sqlType");
         End-If;
         If &ReqObject.IsExist("sqlDescr") Then
            &SqlDescr = &ReqObject.GetString("sqlDescr");
         End-If;
         &DefnArr = %This.GetSqlDefinition(&DefnName, &SqlType, &SqlDescr);
         Break;
      When 105
         /*** 查Project ***/
         If &ReqObject.IsExist("projectDescr") Then
            &ProjectDescr = &ReqObject.GetString("projectDescr");
         End-If;
         &DefnArr = %This.GetProjectDefinition(&DefnName, &ProjectDescr);
         Break;
      When-Other
         throw CreateException(0, 0, "definitionType is not exists");
      End-Evaluate;

      &RespObject.AddJsonArray("list", &DefnArr);
      &DefnArr = &RespObject.GetJsonArray("list");
      &RespMsg = &JsonUtil.CreateSuccessMessage(&OperationName, &RespObject);
   catch Exception &ex
      &RespMsg = &JsonUtil.CreateFailedMessage(&OperationName, 999, "遇到异常：" | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method GetRecordDefinition
   /+ &p_name as String, +/
   /+ &p_type as Integer, +/
   /+ &p_descr as String +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &Records;
   Local string &SelectStr, &WhereStr;
   Local string &RecName, &RecDescr;
   Local SQL &Sql;
   Local integer &i;

   &Records = CreateObject("C_JSON_API:Factory").NewArray();
   &SelectStr = "SELECT RECNAME,RECDESCR FROM PSRECDEFN";
   &WhereStr = " WHERE 1 = 1";

   /* 拼接查询参数 */
   If All(&p_name) Then
      If Right(&p_name, 1) <> "%" Then
         &p_name = &p_name | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECNAME LIKE :1", &p_name);
   End-If;
   If &p_type <> - 1 Then
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECTYPE = :1", &p_type);
   End-If;
   If All(&p_descr) Then
      If Right(&p_descr, 1) <> "%" Then
         &p_descr = &p_descr | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND RECDESCR LIKE :1", &p_descr);
   End-If;

   &Sql = CreateSQL(&SelectStr | &WhereStr);
   While &Sql.Fetch(&RecName, &RecDescr)
      Local C_JSON_API:JSONObject &RecObj = CreateObject("C_JSON_API:Factory").NewObject();
      &RecObj.AddProperty("recordName", &RecName);
      &RecObj.AddProperty("recordDescr", &RecDescr);
      &Records.AddJsonObjectElement("", &RecObj);
      &RecObj = &Records.GetJsonObject(&Records.Size);
   End-While;

   Return &Records;
end-method;

method GetFieldDefinition
