method GetSqlDefinition
   /+ &p_name as String, +/
   /+ &p_type as Integer, +/
   /+ &p_descr as String +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &SqlDefns;
   Local string &SelectStr, &WhereStr;
   Local string &SqlId, &SqlTypeChar, &SqlTypeStr;
   Local SQL &Sql;

   &SqlDefns = CreateObject("C_JSON_API:Factory").NewArray();
   &SelectStr = "SELECT SQLID,SQLTYPE FROM PSSQLDEFN";
   &WhereStr = " WHERE 1 = 1";

   /* SQLID 模糊查询 */
   If All(&p_name) Then
      If Right(&p_name, 1) <> "%" Then
         &p_name = &p_name | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND SQLID LIKE :1", &p_name);
   End-If;

   /* SQLTYPE 过滤 — 转为字符串比较 */
   If &p_type <> - 1 Then
      &SqlTypeStr = String(&p_type);
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND SQLTYPE = :1", &SqlTypeStr);
   End-If;

   /* sqlDescr 模糊查询 — PSSQLDEFN 无 DESCR 列，改为查 PSSQLTEXTDEFN 的 SQLTEXT */
   If All(&p_descr) Then
      If Right(&p_descr, 1) <> "%" Then
         &p_descr = &p_descr | "%";
      End-If;
      &WhereStr = &WhereStr | ExpandSqlBinds(" AND EXISTS (SELECT 1 FROM PSSQLTEXTDEFN T WHERE T.SQLID = PSSQLDEFN.SQLID AND T.SQLTYPE = PSSQLDEFN.SQLTYPE AND T.SQLTEXT LIKE :1)", &p_descr);
   End-If;

   &Sql = CreateSQL(&SelectStr | &WhereStr);
   While &Sql.Fetch(&SqlId, &SqlTypeChar)
      Local C_JSON_API:JSONObject &SqlObj = CreateObject("C_JSON_API:Factory").NewObject();
      &SqlObj.AddProperty("sqlId", &SqlId);
      &SqlObj.AddProperty("sqlType", Value(&SqlTypeChar));
      &SqlDefns.AddJsonObjectElement("", &SqlObj);
      &SqlObj = &SqlDefns.GetJsonObject(&SqlDefns.Size);
   End-While;

   Return &SqlDefns;
end-method;

method GetProjectDefinition
