import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_META_DATA_PKG:Utility:SqlTextGuard;

class OperExecSqlWrite implements PS_PT:Integration:IRequestHandler
   method OperExecSqlWrite();
   method OnRequest(&message As Message) Returns Message;
private
   method Audit(&guard As C_META_DATA_PKG:Utility:SqlTextGuard, &id As string, &rows As number, &status As string, &error As string);
end-class;

method OperExecSqlWrite
end-method;

method Audit
   /+ &guard as C_META_DATA_PKG:Utility:SqlTextGuard, +/
   /+ &id as String, +/
   /+ &rows as Number, +/
   /+ &status as String, +/
   /+ &error as String +/
   Local Record &rec = CreateRecord(Record.C_AI_SQLAUD);
   Local integer &i;
   Local number &total = 0;
   Local string &summary;
   For &i = 1 To &guard.Binds.Len
      &total = &total + Len(String(&guard.Binds [&i]));
   End-For;
   &summary = "bindCount=" | String(&guard.Binds.Len) | ",totalChars=" | String(&total) | ",allowAllRows=" | String(&guard.AllowAllRows);
   &rec.GetField(Field.GUID).Value = &id;
   &rec.GetField(Field.OPRID).Value = %OperatorId;
   &rec.GetField(Field.DTTM_STAMP).Value = %Datetime;
   &rec.GetField(Field.DESCRLONG).Value = &guard.Text;
   &rec.GetField(Field.DESCR254).Value = &summary;
   &rec.GetField(Field.ROW_COUNT).Value = &rows;
   &rec.GetField(Field.AUDIT_ACTN).Value = &status;
   &rec.GetField(Field.SQLTEXT).Value = &error;
   If Not &rec.Insert() Then
      throw CreateException(0, 0, "SQL execution audit insert failed");
   End-If;
end-method;

method OnRequest
   /+ &message as Message +/
   /+ Returns Message +/
   /+ Extends/implements PS_PT:Integration:IRequestHandler.OnRequest +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_META_DATA_PKG:Utility:SqlTextGuard &guard = create C_META_DATA_PKG:Utility:SqlTextGuard();
   Local C_JSON_API:JSONObject &req, &out;
   Local SQL &cursor;
   Local Message &reply;
   Local number &rows;
   Local string &id, &error;
   Local string &body = &message.GetContentString();
   try
      If Len(&body) > 262144 Then
         throw CreateException(0, 0, "Request exceeds 262144 characters");
      End-If;
      If Not &guard.Authorized("AI_EXEC_SQL_WRITE_POST") Then
         Return &json.CreateFailedMessage("AI_EXEC_SQL_WRITE_POST", 403, "Operation permission denied");
      End-If;
      &req = &guard.ParseRequest(&body);
      &guard.Validate(&req, True);
   catch Exception &invalid
      Return &json.CreateFailedMessage("AI_EXEC_SQL_WRITE_POST", 400, Left(&invalid.ToString(), 2000));
   end-try;
   &id = UuidGen();
   try
      /* CreateSQL with the binds array executes exactly once, even for zero binds.
         Execute() returns boolean; RowsAffected is the affected-row contract. */
      &cursor = CreateSQL(&guard.ExecutionText, &guard.Binds);
      If &cursor.Status = 2 Then
         throw CreateException(0, 0, "Duplicate record found");
      End-If;
      &rows = &cursor.RowsAffected;
      &cursor.Close();
      %This.Audit(&guard, &id, &rows, "S", "");
      &out = CreateObject("C_JSON_API:Factory").NewObject();
      &out.AddProperty("mode", "dml");
      &out.AddProperty("statementType", &guard.StatementType);
      &out.AddProperty("affectedRows", &rows);
      &out.AddProperty("auditId", &id);
      &reply = &json.CreateSuccessMessage("AI_EXEC_SQL_WRITE_POST", &out);
      SQLExec("commit");
      Return &reply;
   catch Exception &ex
      &error = Left(&ex.ToString(), 2000);
      SQLExec("rollback");
      If All(&cursor) Then
         &cursor.Close();
      End-If;
      try
         %This.Audit(&guard, &id, 0, "F", &error);
         SQLExec("commit");
      catch Exception &auditError
         SQLExec("rollback");
         Return &json.CreateFailedMessage("AI_EXEC_SQL_WRITE_POST", 999, Left("DML rolled back; failure audit unavailable: " | &auditError.ToString(), 2000));
      end-try;
      Return &json.CreateFailedMessage("AI_EXEC_SQL_WRITE_POST", 999, Left(&error, 1900) | " auditId=" | &id);
   end-try;
end-method;

