   Local C_META_DATA_PKG:Utility:MetadataAccess &access = create C_META_DATA_PKG:Utility:MetadataAccess();
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_META_DATA_PKG:Utility:CoreOperServiceOperation &engine;
   Local array of string &allowed = CreateArray("create", "modify", "delete", "deleteChild", "workflow");
   Local string &denied;
   try
      &denied = &access.Check(&message, "AI_OPER_SERVICE_OP_POST", "", &allowed);
      If &denied <> "" Then
         Return &json.CreateFailedMessage("AI_OPER_SERVICE_OP_POST", 403, &denied);
      End-If;
      &engine = create C_META_DATA_PKG:Utility:CoreOperServiceOperation();
      Return &engine.Execute(&message, "AI_OPER_SERVICE_OP_POST");
   catch Exception &ex
      Return &json.CreateFailedMessage("AI_OPER_SERVICE_OP_POST", 400, &ex.ToString());
   end-try;
end-method;

