   method CoreOperFieldDefn();
   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   method ReadXlat(&name As string) Returns C_JSON_API:JSONArray;
   method WriteXlat(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method LabelRows(&rs As Rowset, &where As string, &name As string, &labelId As string) Returns C_JSON_API:JSONArray;
   method DeleteLabelCli(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method DeleteFieldCli(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method QueryFieldsCli(&p_fields As C_JSON_API:JSONArray) Returns C_JSON_API:JSONObject;
   method CreateFieldCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method ModifyFieldCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method BuildFieldInfo(&p_field As Record) Returns C_JSON_API:JSONObject;
   method UpsertFieldLabels(&p_fieldName As string, &p_labels As C_JSON_API:JSONArray) Returns boolean;
   method PopulateFieldRecord(&p_obj As C_JSON_API:JSONObject, &p_field As Record, &p_isCreate As boolean);
   method ValidateFieldObject(&p_obj As C_JSON_API:JSONObject, &p_isCreate As boolean);
   method ResolveFieldType(&p_obj As C_JSON_API:JSONObject, &p_code As integer out, &p_imageFmt As integer out) Returns boolean;
   method BeginMetadataUpdate(&p_rdmVersion As integer out) Returns boolean;
   method EndMetadataUpdate(&p_rdmVersion As integer) Returns boolean;

   Constant &DateTimeFormat = "yyyy/MM/dd HH:mm:ss";
   instance string &_ErrText;
   instance C_JSON_API:JsonUtil &JsonUtil;
   instance C_COMMONS_PKG:CommonUtil &CommUtil;
   instance C_META_DATA_PKG:Utility:MappingUtil &MappingUtil;
end-class;

Declare Function TranslatePSLOCK PeopleCode PSXLATDEFN.FIELDNAME FieldFormula;
Declare Function TranslateUpdateVersions PeopleCode PSXLATDEFN.FIELDNAME FieldFormula;

method CoreOperFieldDefn
   &_ErrText = "";
   &JsonUtil = create C_JSON_API:JsonUtil();
   &CommUtil = create C_COMMONS_PKG:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;


method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local C_JSON_API:JSONObject &req, &out, &item, &checkReq;
   Local C_JSON_API:JSONArray &fields, &items;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &op, &name, &before, &afterVersion;
   Local integer &i, &status, &count;
   Local boolean &write, &dry, &xlat;
   Local number &xlatLock;
   Local array of string &seen = CreateArrayRept("", 0);
   &_ErrText = "";
   &status = 400;
   &write = False;
   try
      &req = &JsonUtil.GetRootObject(&message.GetContentString());
      &op = "query";
      If &req.IsExist("operationType") Then
         &op = &req.GetString("operationType");
      End-If;
      If &op = "" Then
         &op = "query";
      End-If;
      &xlat = (&op = "addXlat" Or
         &op = "modifyXlat" Or
         &op = "deleteXlat");
      &write = (&xlat Or
         &op = "createField" Or
         &op = "create" Or
         &op = "modifyField" Or
         &op = "modify" Or
         &op = "deleteField" Or
         &op = "deleteLabel");
      &dry = False;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      If &dry And
            Not &xlat And
            &op <> "deleteField" And
            &op <> "deleteLabel" Then
         throw CreateException(0, 0, "dryRun is supported for deleteField/deleteLabel only");
      End-If;
      If &xlat Or
            &op = "deleteField" Or
            &op = "deleteLabel" Then
         &name = &req.GetString("fieldName");
         &guard.ValidateName(&name, 18);
         &guard.Lock();
         If &xlat Then
            SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='XTM' FOR UPDATE OF VERSION", &xlatLock);
         End-If;
         &before = &guard.FieldVersion(&name);
         &status = &guard.Check(&req, &before);
         If &status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: retrieve the Field snapshot before writing");
         End-If;
         &status = 400;
         If &xlat Then
            &status = 403;
            If GetDefinitionAccess("TRANSLATE", &name) <> 0 Then
               throw CreateException(0, 0, "Translate definition write access is required");
            End-If;
            &status = 400;
            &out = %This.WriteXlat(&req);
         Else
            If &op = "deleteLabel" Then
               &out = %This.DeleteLabelCli(&req);
            Else
               &out = %This.DeleteFieldCli(&req);
            End-If;
         End-If;
      Else
         If &write Then
            &fields = &req.GetJsonArray("fields");
            If &fields.Size = 0 Then
               throw CreateException(0, 0, "fields must not be empty");
            End-If;
            &guard.Lock();
            For &i = 1 To &fields.Size
               &item = &fields.GetJsonObject(&i);
               &name = &item.GetString("fieldName");
               &guard.ValidateName(&name, 18);
               If &seen.Find(&name) > 0 Then
                  throw CreateException(0, 0, "Duplicate field in request: " | &name);
               End-If;
               &seen.Push(&name);
               &checkReq = &item;
               If &fields.Size = 1 And
                     Not &item.IsExist("expectedVersion") Then
                  &checkReq = &req;
               End-If;
               &status = &guard.Check(&checkReq, &guard.FieldVersion(&name));
               If &status <> 0 Then
                  throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: " | &name);
               End-If;
            End-For;
            &status = 400;
            If &op = "createField" Or
                  &op = "create" Then
               &out = %This.CreateFieldCli(&req);
            Else
               &out = %This.ModifyFieldCli(&req);
            End-If;
            If &_ErrText <> "" Then
               throw CreateException(0, 0, &_ErrText);
            End-If;
            &items = CreateObject("C_JSON_API:Factory").NewArray();
            For &i = 1 To &seen.Len
               &items.AddJsonObjectElement("", &guard.ProjectItem(2, CreateArray(&seen [&i], "", "", ""), False));
               &item = &out.GetJsonArray("fields").GetJsonObject(&i);
               &item.AddProperty("version", &guard.FieldVersion(&seen [&i]));
            End-For;
            &out.AddJsonArray("projectItems", &items);
            &items = &out.GetJsonArray("projectItems");
         Else
            If &op <> "query" And
                  &op <> "struct" Then
               throw CreateException(0, 0, "Unsupported operationType: " | &op);
            End-If;
            If &req.IsExist("fieldName") Then
               &name = &req.GetString("fieldName");
               &guard.ValidateName(&name, 18);
               &before = &guard.FieldVersion(&name);
               &fields = CreateObject("C_JSON_API:Factory").NewArray();
               &fields.AddElement(&name);
            Else
               If &req.IsExist("fields") Then
                  &fields = &req.GetJsonArray("fields");
               Else
                  &fields = &req.GetJsonArray("");
               End-If;
            End-If;
            &out = %This.QueryFieldsCli(&fields);
            If &name <> "" Then
               &afterVersion = &guard.FieldVersion(&name);
               If &before <> &afterVersion Then
                  &status = 409;
                  throw CreateException(0, 0, "VERSION_CONFLICT: Field changed during read");
               End-If;
               &out.AddProperty("fieldName", &name);
               &out.AddProperty("exists", (&out.GetJsonArray("fields").Size > 0));
               &out.AddProperty("version", &afterVersion);
            End-If;
         End-If;
      End-If;
      If &_ErrText <> "" Then
         throw CreateException(0, 0, &_ErrText);
      End-If;
      &out.AddProperty("xlatMaintenanceVersion", 1);
      If &write Then
         If &dry Then
            SQLExec("rollback");
         Else
            SQLExec("commit");
         End-If;
      End-If;
      Return &JsonUtil.CreateSuccessMessage(&responseOperation, &out);
   catch Exception &ex
      If &write Then
         SQLExec("rollback");
      End-If;
      If &status = 400 And
            Find("VERSION_CONFLICT:", &ex.ToString()) > 0 Then
         &status = 409;
      End-If;
      Return &JsonUtil.CreateFailedMessage(&responseOperation, &status, &ex.ToString());
   end-try;
end-method;


method ReadXlat
   /+ &name as String +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &values = CreateObject("C_JSON_API:Factory").NewArray();
   Local C_JSON_API:JSONArray &languages;
   Local C_JSON_API:JSONObject &value, &language;
   Local Rowset &rows = CreateRowset(Record.PSXLATITEM);
   Local Rowset &langs = CreateRowset(Record.PSXLATITEMLANG);
   Local Record &row, &lang;
   Local integer &n, &m, &i, &j;
   &n = &rows.Fill("WHERE FIELDNAME=:1 ORDER BY FIELDVALUE,EFFDT", &name);
   For &i = 1 To &n
      &row = &rows(&i).GetRecord(1);
      &value = CreateObject("C_JSON_API:Factory").NewObject();
      &value.AddProperty("fieldValue", &row.FIELDVALUE.Value);
      &value.AddProperty("effdt", DateTimeToLocalizedString(&row.EFFDT.Value, "yyyy-MM-dd"));
      &value.AddProperty("effStatus", &row.EFF_STATUS.Value);
      &value.AddProperty("longName", &row.XLATLONGNAME.Value);
      &value.AddProperty("shortName", &row.XLATSHORTNAME.Value);
      &value.AddProperty("lastUpdate", "Last updated by: " | &row.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&row.LASTUPDDTTM.Value, &DateTimeFormat));
      &languages = CreateObject("C_JSON_API:Factory").NewArray();
      &m = &langs.Fill("WHERE FIELDNAME=:1 AND FIELDVALUE=:2 AND EFFDT=:3 ORDER BY LANGUAGE_CD", &name, &row.FIELDVALUE.Value, &row.EFFDT.Value);
      For &j = 1 To &m
         &lang = &langs(&j).GetRecord(1);
         &language = CreateObject("C_JSON_API:Factory").NewObject();
         &language.AddProperty("language", &lang.LANGUAGE_CD.Value);
         &language.AddProperty("longName", &lang.XLATLONGNAME.Value);
         &language.AddProperty("shortName", &lang.XLATSHORTNAME.Value);
         &languages.AddJsonObjectElement("", &language);
      End-For;
      &value.AddJsonArray("translations", &languages);
      &values.AddJsonObjectElement("", &value);
   End-For;
   Return &values;
end-method;

method WriteXlat
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &name = &req.GetString("fieldName");
   Local string &op = &req.GetString("operationType");
   Local string &code = &req.GetString("fieldValue");
   Local string &dateText = &req.GetString("effdt");
   Local string &prop;
   Local date &effdt;
   Local Record &field = CreateRecord(Record.PSDBFIELD);
   Local Record &header = CreateRecord(Record.PSXLATDEFN);
   Local Record &row = CreateRecord(Record.PSXLATITEM);
   Local Record &lang;
   Local Rowset &langs = CreateRowset(Record.PSXLATITEMLANG);
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_JSON_API:JSONArray &items = CreateObject("C_JSON_API:Factory").NewArray();
   Local array of string &allowed = CreateArray("operationType", "fieldName", "fieldValue", "effdt", "longName", "shortName", "effStatus", "expectedVersion", "dryRun");
   Local boolean &exists;
   Local boolean &dry = False;
   Local integer &i, &n, &remaining, &uses;
   Local number &version;
   For &i = 1 To &req.ChildCount
      &prop = &req.GetPropertyNameAt(&i);
      If &allowed.Find(&prop) = 0 Then
         throw CreateException(0, 0, "Unknown XLAT property: " | &prop);
      End-If;
   End-For;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   &field.FIELDNAME.Value = &name;
   If Not &field.SelectByKey() Then
      throw CreateException(0, 0, "Field does not exist");
   End-If;
   If &field.FIELDTYPE.Value <> 0 Or
         &field.LENGTH.Value < 1 Or
         &field.LENGTH.Value > 4 Then
      throw CreateException(0, 0, "Translate values require a Character Field of length 1 through 4");
   End-If;
   If Len(LTrim(RTrim(&code))) = 0 Or
         Len(&code) > &field.LENGTH.Value Or
         &code <> RTrim(&code) Then
      throw CreateException(0, 0, "fieldValue must fit the Field length and cannot be blank or end with spaces");
   End-If;
   If Len(&dateText) <> 10 Or
         Substring(&dateText, 5, 1) <> "-" Or
         Substring(&dateText, 8, 1) <> "-" Then
      throw CreateException(0, 0, "effdt must be a valid YYYY-MM-DD date");
   End-If;
   &effdt = Date(&dateText);
   If DateTimeToLocalizedString(&effdt, "yyyy-MM-dd") <> &dateText Then
      throw CreateException(0, 0, "effdt must be a valid YYYY-MM-DD date");
   End-If;
   &row.FIELDNAME.Value = &name;
   &row.FIELDVALUE.Value = &code;
   &row.EFFDT.Value = &effdt;
   &exists = &row.SelectByKey();
   &row.FIELDNAME.Value = &name;
   &row.FIELDVALUE.Value = &code;
   &row.EFFDT.Value = &effdt;
   If (&op = "addXlat" And
         &exists) Or
         (&op <> "addXlat" And
            Not &exists) Then
      throw CreateException(0, 0, "XLAT row already exists for add, or does not exist for modify/delete");
   End-If;
   If &op = "addXlat" Then
      If Not &req.IsExist("longName") Then
         throw CreateException(0, 0, "addXlat requires longName");
      End-If;
      &row.EFF_STATUS.Value = "A";
      &row.XLATSHORTNAME.Value = Substring(&req.GetString("longName"), 1, 10);
   End-If;
   If &op = "modifyXlat" And
         Not &req.IsExist("longName") And
         Not &req.IsExist("shortName") And
         Not &req.IsExist("effStatus") Then
      throw CreateException(0, 0, "modifyXlat requires longName, shortName or effStatus");
   End-If;
   If &op = "deleteXlat" And
         (&req.IsExist("longName") Or
            &req.IsExist("shortName") Or
            &req.IsExist("effStatus")) Then
      throw CreateException(0, 0, "deleteXlat only accepts the exact row key");
   End-If;
   If &req.IsExist("longName") Then
      If Len(&req.GetString("longName")) > 30 Or
            &req.GetString("longName") <> RTrim(&req.GetString("longName")) Then
         throw CreateException(0, 0, "longName exceeds 30 characters or ends with spaces");
      End-If;
      &row.XLATLONGNAME.Value = &req.GetString("longName");
   End-If;
   If &req.IsExist("shortName") Then
      If Len(&req.GetString("shortName")) > 10 Or
            &req.GetString("shortName") <> RTrim(&req.GetString("shortName")) Then
         throw CreateException(0, 0, "shortName exceeds 10 characters or ends with spaces");
      End-If;
      &row.XLATSHORTNAME.Value = &req.GetString("shortName");
   End-If;
   If &req.IsExist("effStatus") Then
      If &req.GetString("effStatus") <> "A" And
            &req.GetString("effStatus") <> "I" Then
         throw CreateException(0, 0, "effStatus must be exactly A or I");
      End-If;
      &row.EFF_STATUS.Value = &req.GetString("effStatus");
   End-If;
   If Len(LTrim(RTrim(&row.XLATLONGNAME.Value))) = 0 Or
         Len(&row.XLATLONGNAME.Value) > 30 Or
         Len(LTrim(RTrim(&row.XLATSHORTNAME.Value))) = 0 Or
         Len(&row.XLATSHORTNAME.Value) > 10 Then
      throw CreateException(0, 0, "XLAT longName/shortName must be nonblank and at most 30/10 characters");
   End-If;
   If &row.EFF_STATUS.Value <> "A" And
         &row.EFF_STATUS.Value <> "I" Then
      throw CreateException(0, 0, "effStatus must be A or I");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSXLATITEM WHERE FIELDNAME=:1", &name, &remaining);
   If &op = "deleteXlat" And
         &remaining = 1 Then
      SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE FIELDNAME=:1 AND BITAND(USEEDIT,512)<>0", &name, &uses);
      If &uses > 0 Then
         throw CreateException(0, 0, "Cannot remove the last XLAT row while Records use TranslateTableEdit");
      End-If;
   End-If;
   &items.AddJsonObjectElement("", &guard.ProjectItem(4, CreateArray(&name, &code, &dateText, ""), (&op = "deleteXlat")));
   If Not &dry Then
      TranslatePSLOCK();
      If &op = "deleteXlat" Then
         &n = &langs.Fill("WHERE FIELDNAME=:1 AND FIELDVALUE=:2 AND EFFDT=:3", &name, &code, &effdt);
         For &i = 1 To &n
            &lang = &langs(&i).GetRecord(1);
            If Not &lang.Delete() Then
               throw CreateException(0, 0, "Deleting XLAT related language row failed");
            End-If;
         End-For;
         If Not &row.Delete() Then
            throw CreateException(0, 0, "Deleting XLAT row failed");
         End-If;
      Else
         &row.LASTUPDOPRID.Value = %UserId;
         &row.LASTUPDDTTM.Value = %Datetime;
         If &op = "addXlat" Then
            If Not &row.Insert() Then
               throw CreateException(0, 0, "Inserting XLAT row failed");
            End-If;
         Else
            If Not &row.Update() Then
               throw CreateException(0, 0, "Updating XLAT row failed");
            End-If;
         End-If;
      End-If;
      SQLExec("SELECT COUNT(*) FROM PSXLATITEM WHERE FIELDNAME=:1 AND FIELDVALUE=:2 AND EFFDT=:3", &name, &code, &effdt, &remaining);
      If (&op = "deleteXlat" And
            &remaining <> 0) Or
            (&op <> "deleteXlat" And
               &remaining <> 1) Then
         throw CreateException(0, 0, "XLAT row key readback failed before commit");
      End-If;
      &version = TranslateUpdateVersions();
      &header.FIELDNAME.Value = &name;
      &exists = &header.SelectByKey();
      &header.FIELDNAME.Value = &name;
      SQLExec("SELECT COUNT(*) FROM PSXLATITEM WHERE FIELDNAME=:1", &name, &remaining);
      If &remaining = 0 Then
         If &exists Then
            If Not &header.Delete() Then
               throw CreateException(0, 0, "Deleting empty XLAT header failed");
            End-If;
         End-If;
      Else
         &header.VERSION.Value = &version;
         If &exists Then
            If Not &header.Update() Then
               throw CreateException(0, 0, "Updating XLAT header failed");
            End-If;
         Else
            If Not &header.Insert() Then
               throw CreateException(0, 0, "Inserting XLAT header failed");
            End-If;
         End-If;
      End-If;
   End-If;
   &out.AddProperty("fieldName", &name);
   &out.AddProperty("fieldValue", &code);
   &out.AddProperty("effdt", &dateText);
   &out.AddProperty("operationType", &op);
   &out.AddProperty("dryRun", &dry);
   &out.AddProperty("deleted", (&op = "deleteXlat" And
      Not &dry));
   &out.AddProperty("version", &guard.FieldVersion(&name));
   &out.AddJsonArray("projectItems", &items);
   Return &out;
end-method;

method QueryFieldsCli
   /+ &p_fields as C_JSON_API:JSONArray +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObject, &FieldInfo;
   Local C_JSON_API:JSONArray &FieldInfoList;
   Local Rowset &DBFieldRs;
   Local Record &DBFieldRec;
   Local string &FieldName;
   Local integer &i, &j;

   &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
   &FieldInfoList = CreateObject("C_JSON_API:Factory").NewArray();
   If &p_fields = Null Then
      &RespObject.AddJsonArray("fields", &FieldInfoList);
      &FieldInfoList = &RespObject.GetJsonArray("fields");
      Return &RespObject;
   End-If;

   Local C_META_DATA_PKG:Utility:DefinitionVersion &readGuard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &readVersion;
   &DBFieldRs = CreateRowset(Record.PSDBFIELD);
   For &i = 1 To &p_fields.Size
      &FieldName = Upper(&p_fields.GetString(&i));
      If All(&FieldName) Then
         &readVersion = &readGuard.FieldVersion(&FieldName);
         &DBFieldRs.Flush();
         &DBFieldRs.Fill(" WHERE FIELDNAME = :1", &FieldName);
         For &j = 1 To &DBFieldRs.ActiveRowCount
            &DBFieldRec = &DBFieldRs(&j).GetRecord(1);
            If All(&DBFieldRec.FIELDNAME.Value) Then
               &FieldInfo = %This.BuildFieldInfo(&DBFieldRec);
               If &readVersion <> &FieldInfo.GetString("version") Then
                  throw CreateException(0, 0, "VERSION_CONFLICT: Field changed during query");
               End-If;
               &FieldInfoList.AddJsonObjectElement("", &FieldInfo);
               &FieldInfo = &FieldInfoList.GetJsonObject(&FieldInfoList.Size);
            End-If;
         End-For;
      End-If;
   End-For;

   &RespObject.AddJsonArray("fields", &FieldInfoList);
   &FieldInfoList = &RespObject.GetJsonArray("fields");
   Return &RespObject;
end-method;


method BuildFieldInfo
   /+ &p_field as Record +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &FieldInfo, &LabelObj;
   Local C_JSON_API:JSONArray &LabelArr;
   Local Rowset &LabelRs;
   Local Record &LabelRec;
   Local integer &i;

   &FieldInfo = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &snapshotVersion = &guard.FieldVersion(&p_field.FIELDNAME.Value);
   &FieldInfo.AddProperty("version", &snapshotVersion);
   &FieldInfo.AddProperty("fieldVersion", &p_field.VERSION.Value);
   &FieldInfo.AddProperty("fieldName", &p_field.FIELDNAME.Value);
   &FieldInfo.AddProperty("fieldType", &MappingUtil.GetFieldTypeName(&p_field.FIELDTYPE.Value, &p_field.IMAGE_FMT.Value));
   &FieldInfo.AddProperty("fieldTypeCode", &p_field.FIELDTYPE.Value);
   &FieldInfo.AddProperty("length", &p_field.LENGTH.Value);
   &FieldInfo.AddProperty("decimalPos", &p_field.DECIMALPOS.Value);
   &FieldInfo.AddProperty("format", &p_field.FORMAT.Value);
   &FieldInfo.AddProperty("formatLength", &p_field.FORMATLENGTH.Value);
   &FieldInfo.AddProperty("imageFmt", &p_field.IMAGE_FMT.Value);
   &FieldInfo.AddProperty("formatFamily", &p_field.FORMATFAMILY.Value);
   &FieldInfo.AddProperty("dispFmtName", &p_field.DISPFMTNAME.Value);
   &FieldInfo.AddProperty("defCntryYr", &p_field.DEFCNTRYYR.Value);
   &FieldInfo.AddProperty("imeMode", &p_field.IMEMODE.Value);
   &FieldInfo.AddProperty("kbLayout", &p_field.KBLAYOUT.Value);
   &FieldInfo.AddProperty("objectOwnerId", &p_field.OBJECTOWNERID.Value);
   &FieldInfo.AddProperty("fldNotUsed", &p_field.FLDNOTUSED.Value);
   &FieldInfo.AddProperty("auxFlagMask", &p_field.AUXFLAGMASK.Value);
   &FieldInfo.AddProperty("lastUpdate", "Last updated by: " | &p_field.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&p_field.LASTUPDDTTM.Value, &DateTimeFormat));
   &FieldInfo.AddProperty("comment", &p_field.DESCRLONG.Value);
   &FieldInfo.AddProperty("xlatMaintenanceVersion", 1);
   &FieldInfo.AddJsonArray("xlatValues", %This.ReadXlat(&p_field.FIELDNAME.Value));

   &LabelArr = CreateObject("C_JSON_API:Factory").NewArray();
   &LabelRs = CreateRowset(Record.PSDBFLDLABL);
   &LabelRs.Flush();
   &LabelRs.Fill(" WHERE FIELDNAME = :1", &p_field.FIELDNAME.Value);
   For &i = 1 To &LabelRs.ActiveRowCount
      &LabelRec = &LabelRs(&i).GetRecord(1);
      If All(&LabelRec.FIELDNAME.Value) Then
         &LabelObj = CreateObject("C_JSON_API:Factory").NewObject();
         &LabelObj.AddProperty("labelId", &LabelRec.LABEL_ID.Value);
         &LabelObj.AddProperty("longName", &LabelRec.LONGNAME.Value);
         &LabelObj.AddProperty("shortName", &LabelRec.SHORTNAME.Value);
         &LabelObj.AddProperty("defaultLabel", &LabelRec.DEFAULT_LABEL.Value);
         &LabelArr.AddJsonObjectElement("", &LabelObj);
         &LabelObj = &LabelArr.GetJsonObject(&LabelArr.Size);
      End-If;
   End-For;
   &FieldInfo.AddJsonArray("labels", &LabelArr);
   &LabelArr = &FieldInfo.GetJsonArray("labels");

   If &snapshotVersion <> &guard.FieldVersion(&p_field.FIELDNAME.Value) Then
      throw CreateException(0, 0, "VERSION_CONFLICT: Field changed during read");
   End-If;
   Return &FieldInfo;
end-method;


method CreateFieldCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObject, &JField, &ResultObj;
   Local C_JSON_API:JSONArray &Fields, &Results, &Labels;
   Local Record &DBFieldRec;
   Local string &FieldName;
   Local integer &i, &RDMVersion;
   Local boolean &Exists, &BeginOk, &InsertOk, &LabelOk;

   &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
   &Results = CreateObject("C_JSON_API:Factory").NewArray();
   &RespObject.AddProperty("operationType", "createField");
   If Not &p_obj.IsExist("fields") Then
      &_ErrText = &_ErrText | "fields is required, ";
      Return &RespObject;
   End-If;
   &Fields = &p_obj.GetJsonArray("fields");
   If &Fields.Size <= 0 Then
      &_ErrText = &_ErrText | "fields must not be empty, ";
      Return &RespObject;
   End-If;

   For &i = 1 To &Fields.Size
      &JField = &Fields.GetJsonObject(&i);
      %This.ValidateFieldObject(&JField, True);
      If &JField.IsExist("fieldName") Then
         &FieldName = Upper(&JField.GetString("fieldName"));
         &DBFieldRec = CreateRecord(Record.PSDBFIELD);
         &DBFieldRec.FIELDNAME.Value = &FieldName;
         &Exists = &DBFieldRec.SelectByKey();
         If &Exists Then
            &_ErrText = &_ErrText | "field already exists: " | &FieldName | ", ";
         End-If;
      End-If;
   End-For;
   If &_ErrText <> "" Then
      Return &RespObject;
   End-If;

   &BeginOk = %This.BeginMetadataUpdate(&RDMVersion);
   If Not &BeginOk Then
      Return &RespObject;
   End-If;

   For &i = 1 To &Fields.Size
      &JField = &Fields.GetJsonObject(&i);
      &FieldName = Upper(&JField.GetString("fieldName"));
      &DBFieldRec = CreateRecord(Record.PSDBFIELD);
      %This.PopulateFieldRecord(&JField, &DBFieldRec, True);
      &DBFieldRec.VERSION.Value = &RDMVersion;
      &InsertOk = &DBFieldRec.Insert();
      If Not &InsertOk Then
         &_ErrText = &_ErrText | "insert PSDBFIELD failed: " | &FieldName | ", ";
      End-If;
      If &JField.IsExist("labels") Then
         &Labels = &JField.GetJsonArray("labels");
         &LabelOk = %This.UpsertFieldLabels(&FieldName, &Labels);
         If Not &LabelOk Then
            &_ErrText = &_ErrText | "upsert labels failed: " | &FieldName | ", ";
         End-If;
      End-If;
      &ResultObj = CreateObject("C_JSON_API:Factory").NewObject();
      &ResultObj.AddProperty("fieldName", &FieldName);
      &ResultObj.AddProperty("action", "created");
      &Results.AddJsonObjectElement("", &ResultObj);
      &ResultObj = &Results.GetJsonObject(&Results.Size);
   End-For;

   If &_ErrText = "" Then
      If Not %This.EndMetadataUpdate(&RDMVersion) Then
         Return &RespObject;
      End-If;
   End-If;
   &RespObject.AddProperty("affectedCount", &Fields.Size);
   &RespObject.AddJsonArray("fields", &Results);
   &Results = &RespObject.GetJsonArray("fields");
   Return &RespObject;
end-method;


method ModifyFieldCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObject, &JField, &ResultObj;
   Local C_JSON_API:JSONArray &Fields, &Results, &Labels;
   Local Record &DBFieldRec;
   Local string &FieldName;
   Local integer &i, &RDMVersion;
   Local boolean &Exists, &BeginOk, &UpdateOk, &LabelOk;
   Local integer &xlatLength;

   &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
   &Results = CreateObject("C_JSON_API:Factory").NewArray();
   &RespObject.AddProperty("operationType", "modifyField");
   If Not &p_obj.IsExist("fields") Then
      &_ErrText = &_ErrText | "fields is required, ";
      Return &RespObject;
   End-If;
   &Fields = &p_obj.GetJsonArray("fields");
   If &Fields.Size <= 0 Then
      &_ErrText = &_ErrText | "fields must not be empty, ";
      Return &RespObject;
   End-If;

   For &i = 1 To &Fields.Size
      &JField = &Fields.GetJsonObject(&i);
      %This.ValidateFieldObject(&JField, False);
      If &JField.IsExist("fieldName") Then
         &FieldName = Upper(&JField.GetString("fieldName"));
         &DBFieldRec = CreateRecord(Record.PSDBFIELD);
         &DBFieldRec.FIELDNAME.Value = &FieldName;
         &Exists = &DBFieldRec.SelectByKey();
         If Not &Exists Then
            &_ErrText = &_ErrText | "field does not exist: " | &FieldName | ", ";
         End-If;
      End-If;
   End-For;
   If &_ErrText <> "" Then
      Return &RespObject;
   End-If;

   &BeginOk = %This.BeginMetadataUpdate(&RDMVersion);
   If Not &BeginOk Then
      Return &RespObject;
   End-If;

   For &i = 1 To &Fields.Size
      &JField = &Fields.GetJsonObject(&i);
      &FieldName = Upper(&JField.GetString("fieldName"));
      &DBFieldRec = CreateRecord(Record.PSDBFIELD);
      &DBFieldRec.FIELDNAME.Value = &FieldName;
      If Not &DBFieldRec.SelectByKey() Then
         &_ErrText = &_ErrText | "field disappeared before update: " | &FieldName | ", ";
      Else
         %This.PopulateFieldRecord(&JField, &DBFieldRec, False);
         SQLExec("SELECT NVL(MAX(LENGTH(RTRIM(FIELDVALUE))),0) FROM PSXLATITEM WHERE FIELDNAME=:1", &FieldName, &xlatLength);
         If &xlatLength > 0 And
               (&DBFieldRec.FIELDTYPE.Value <> 0 Or
                  &DBFieldRec.LENGTH.Value > 4 Or
                  &DBFieldRec.LENGTH.Value < &xlatLength) Then
            throw CreateException(0, 0, "Field type/length change would invalidate existing Translate values");
         End-If;
         &DBFieldRec.LASTUPDOPRID.Value = %UserId;
         &DBFieldRec.LASTUPDDTTM.Value = %Datetime;
         &DBFieldRec.VERSION.Value = &RDMVersion;
         &UpdateOk = &DBFieldRec.Update();
         If Not &UpdateOk Then
            &_ErrText = &_ErrText | "update PSDBFIELD failed: " | &FieldName | ", ";
         End-If;
         If &JField.IsExist("labels") Then
            &Labels = &JField.GetJsonArray("labels");
            &LabelOk = %This.UpsertFieldLabels(&FieldName, &Labels);
            If Not &LabelOk Then
               &_ErrText = &_ErrText | "upsert labels failed: " | &FieldName | ", ";
            End-If;
         End-If;
      End-If;
      &ResultObj = CreateObject("C_JSON_API:Factory").NewObject();
      &ResultObj.AddProperty("fieldName", &FieldName);
      &ResultObj.AddProperty("action", "modified");
      &Results.AddJsonObjectElement("", &ResultObj);
      &ResultObj = &Results.GetJsonObject(&Results.Size);
   End-For;

   If &_ErrText = "" Then
      If Not %This.EndMetadataUpdate(&RDMVersion) Then
         Return &RespObject;
      End-If;
   End-If;
   &RespObject.AddProperty("affectedCount", &Fields.Size);
   &RespObject.AddJsonArray("fields", &Results);
   &Results = &RespObject.GetJsonArray("fields");
   Return &RespObject;
end-method;


method ValidateFieldObject
   /+ &p_obj as C_JSON_API:JSONObject, +/
   /+ &p_isCreate as Boolean +/
   Local string &FieldName, &LabelId, &LongName, &ShortName, &SqlStmt;
   Local C_JSON_API:JSONArray &Labels;
   Local C_JSON_API:JSONObject &LabelObj;
   Local integer &Length, &DefaultLabel, &Code, &ImageFmt, &i, &ExistingLabelCount;
   Local boolean &HasType, &HasChange, &HasLabel, &IsAttachment;

   If Not &p_obj.IsExist("fieldName") Then
      &_ErrText = &_ErrText | "fieldName is required, ";
      Return;
   End-If;
   &FieldName = Upper(&p_obj.GetString("fieldName"));
   If Not All(&FieldName) Then
      &_ErrText = &_ErrText | "fieldName cannot be empty, ";
   Else
      If Len(&FieldName) > 18 Then
         &_ErrText = &_ErrText | "fieldName length must be <= 18: " | &FieldName | ", ";
      End-If;
   End-If;

   &HasType = False;
   &IsAttachment = False;
   If &p_obj.IsExist("fieldType") Then
      &HasType = True;
   End-If;
   If &p_obj.IsExist("fieldTypeCode") Then
      &HasType = True;
   End-If;
   If &HasType Then
      If Not %This.ResolveFieldType(&p_obj, &Code, &ImageFmt) Then
         &_ErrText = &_ErrText | "fieldType/fieldTypeCode is invalid: " | &FieldName | ", ";
      Else
         If &Code = 8 And
               &ImageFmt = 16 Then
            &IsAttachment = True;
         End-If;
      End-If;
   Else
      If &p_isCreate Then
         &_ErrText = &_ErrText | "fieldType or fieldTypeCode is required: " | &FieldName | ", ";
      End-If;
   End-If;

   If &p_obj.IsExist("length") Then
      &Length = &p_obj.GetNumber("length");
      If &Length < 0 Then
         &_ErrText = &_ErrText | "length cannot be negative: " | &FieldName | ", ";
      End-If;
   Else
      If &p_isCreate And
            Not &IsAttachment Then
         &_ErrText = &_ErrText | "length is required: " | &FieldName | ", ";
      End-If;
   End-If;

   &HasLabel = False;
   If &p_obj.IsExist("labels") Then
      &Labels = &p_obj.GetJsonArray("labels");
      If &Labels.Size <= 0 Then
         &_ErrText = &_ErrText | "labels must contain at least one labelId: " | &FieldName | ", ";
      Else
         For &i = 1 To &Labels.Size
            &LabelObj = &Labels.GetJsonObject(&i);
            If Not &LabelObj.IsExist("labelId") Then
               &_ErrText = &_ErrText | "labelId is required: " | &FieldName | ", ";
            Else
               &LabelId = Upper(&LabelObj.GetString("labelId"));
               If Not All(&LabelId) Or
                     Len(&LabelId) > 18 Then
                  &_ErrText = &_ErrText | "labelId must be 1-18 chars: " | &FieldName | ", ";
               Else
                  &HasLabel = True;
               End-If;
            End-If;
            If &LabelObj.IsExist("longName") Then
               &LongName = &LabelObj.GetString("longName");
               If Len(&LongName) > 30 Then
                  &_ErrText = &_ErrText | "longName length must be <= 30: " | &FieldName | ", ";
               End-If;
            End-If;
            If &LabelObj.IsExist("shortName") Then
               &ShortName = &LabelObj.GetString("shortName");
               If Len(&ShortName) > 15 Then
                  &_ErrText = &_ErrText | "shortName length must be <= 15: " | &FieldName | ", ";
               End-If;
            End-If;
            If &LabelObj.IsExist("defaultLabel") Then
               &DefaultLabel = &LabelObj.GetNumber("defaultLabel");
               If &DefaultLabel <> 0 And
                     &DefaultLabel <> 1 Then
                  &_ErrText = &_ErrText | "defaultLabel must be 0 or 1: " | &FieldName | ", ";
               End-If;
            End-If;
         End-For;
         If Not &HasLabel Then
            &_ErrText = &_ErrText | "labels must contain at least one non-empty labelId: " | &FieldName | ", ";
         End-If;
      End-If;
   Else
      If &p_isCreate Then
         &_ErrText = &_ErrText | "labels is required and must contain at least one labelId: " | &FieldName | ", ";
      Else
         &ExistingLabelCount = 0;
         &SqlStmt = "SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME = :1";
         If Not SQLExec(&SqlStmt, &FieldName, &ExistingLabelCount) Then
            &_ErrText = &_ErrText | "cannot verify existing labels: " | &FieldName | ", ";
         Else
            If &ExistingLabelCount <= 0 Then
               &_ErrText = &_ErrText | "labels is required because field has no Label ID: " | &FieldName | ", ";
            End-If;
         End-If;
      End-If;
   End-If;

   If Not &p_isCreate Then
      &HasChange = &HasType;
      If &p_obj.IsExist("length") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("decimalPos") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("format") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("formatLength") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("imageFmt") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("formatFamily") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("dispFmtName") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("defCntryYr") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("imeMode") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("kbLayout") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("objectOwnerId") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("fldNotUsed") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("auxFlagMask") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("comment") Then
         &HasChange = True;
      End-If;
      If &p_obj.IsExist("labels") Then
         &HasChange = True;
      End-If;
      If Not &HasChange Then
         &_ErrText = &_ErrText | "no field property to modify: " | &FieldName | ", ";
      End-If;
   End-If;
end-method;


method ResolveFieldType
   /+ &p_obj as C_JSON_API:JSONObject, +/
   /+ &p_code as Integer out, +/
   /+ &p_imageFmt as Integer out +/
   /+ Returns Boolean +/
   Local string &TypeName;
   Local integer &InputCode;
   Local boolean &HasName, &HasCode;

   &p_code = - 1;
   &p_imageFmt = 0;
   &HasName = &p_obj.IsExist("fieldType");
   &HasCode = &p_obj.IsExist("fieldTypeCode");
   If &HasCode Then
      &InputCode = &p_obj.GetNumber("fieldTypeCode");
   Else
      &InputCode = - 1;
   End-If;

   If &HasName Then
      &TypeName = Lower(&p_obj.GetString("fieldType"));
      Evaluate &TypeName
      When "character"
         &p_code = 0;
      When "char"
         &p_code = 0;
      When "long character"
         &p_code = 1;
      When "long"
         &p_code = 1;
      When "number"
         &p_code = 2;
      When "signed number"
         &p_code = 3;
      When "signed"
         &p_code = 3;
      When "date"
         &p_code = 4;
      When "time"
         &p_code = 5;
      When "datetime"
         &p_code = 6;
      When "image"
         &p_code = 8;
         /* DIB is the valid/default Image format in PSDBFIELD. */
         &p_imageFmt = 3;
      When "attachment"
         &p_code = 8;
         &p_imageFmt = 16;
      When "imagereference"
         &p_code = 9;
      When-Other
         Return False;
      End-Evaluate;
      If &HasCode And
            &InputCode <> &p_code Then
         Return False;
      End-If;
   Else
      &p_code = &InputCode;
   End-If;

   If &p_code <> 0 And
         &p_code <> 1 And
         &p_code <> 2 And
         &p_code <> 3 And
         &p_code <> 4 And
         &p_code <> 5 And
         &p_code <> 6 And
         &p_code <> 8 And
         &p_code <> 9 Then
      Return False;
   End-If;

   If &p_obj.IsExist("imageFmt") Then
      &p_imageFmt = &p_obj.GetNumber("imageFmt");
      /* A client-side zero is not a valid Image format. Keep the
          attachment semantic for an explicitly named attachment;
          otherwise normalize it to DIB. */
      If &p_code = 8 And
            &p_imageFmt = 0 Then
         If &HasName And
               Lower(&TypeName) = "attachment" Then
            &p_imageFmt = 16;
         Else
            &p_imageFmt = 3;
         End-If;
      End-If;
   End-If;
   Return True;
end-method;


method PopulateFieldRecord
   /+ &p_obj as C_JSON_API:JSONObject, +/
   /+ &p_field as Record, +/
   /+ &p_isCreate as Boolean +/
   Local integer &Code, &ImageFmt, &Length;
   Local string &Comment;
   Local boolean &HasType, &ResolveOk, &IsAttachment;

   If &p_isCreate Then
      &p_field.SetDefault();
      &p_field.VERSION.Value = 1;
      &p_field.FORMATFAMILY.Value = " ";
      &p_field.DISPFMTNAME.Value = " ";
      &p_field.DEFCNTRYYR.Value = 50;
      &p_field.IMEMODE.Value = 0;
      &p_field.KBLAYOUT.Value = 0;
      &p_field.OBJECTOWNERID.Value = " ";
      &p_field.FLDNOTUSED.Value = 0;
      &p_field.AUXFLAGMASK.Value = 8388608;
      &p_field.LASTUPDOPRID.Value = %UserId;
      &p_field.LASTUPDDTTM.Value = %Datetime;
      &p_field.FIELDNAME.Value = Upper(&p_obj.GetString("fieldName"));
   End-If;

   &HasType = False;
   If &p_obj.IsExist("fieldType") Then
      &HasType = True;
   End-If;
   If &p_obj.IsExist("fieldTypeCode") Then
      &HasType = True;
   End-If;
   If &HasType Then
      &ResolveOk = %This.ResolveFieldType(&p_obj, &Code, &ImageFmt);
      &p_field.FIELDTYPE.Value = &Code;
      &p_field.IMAGE_FMT.Value = &ImageFmt;
   End-If;
   &IsAttachment = False;
   If &p_field.FIELDTYPE.Value = 8 And
         &p_field.IMAGE_FMT.Value = 16 Then
      &IsAttachment = True;
   End-If;
   If &p_obj.IsExist("length") Then
      &Length = &p_obj.GetNumber("length");
      If &IsAttachment And
            &Length <= 0 Then
         &p_field.LENGTH.Value = 30;
      Else
         &p_field.LENGTH.Value = &Length;
      End-If;
   Else
      If &p_isCreate And
            &IsAttachment Then
         &p_field.LENGTH.Value = 30;
      End-If;
   End-If;
   If &p_obj.IsExist("decimalPos") Then
      &p_field.DECIMALPOS.Value = &p_obj.GetNumber("decimalPos");
   End-If;
   If &p_obj.IsExist("format") Then
      &p_field.FORMAT.Value = &p_obj.GetNumber("format");
   End-If;
   If &p_obj.IsExist("formatLength") Then
      &p_field.FORMATLENGTH.Value = &p_obj.GetNumber("formatLength");
   End-If;
   If &p_obj.IsExist("imageFmt") And
         Not &HasType Then
      &p_field.IMAGE_FMT.Value = &p_obj.GetNumber("imageFmt");
      If &p_field.FIELDTYPE.Value = 8 And
            &p_field.IMAGE_FMT.Value = 0 Then
         &p_field.IMAGE_FMT.Value = 3;
      End-If;
   End-If;
   If &p_obj.IsExist("formatFamily") Then
      &p_field.FORMATFAMILY.Value = &p_obj.GetString("formatFamily");
   End-If;
   If &p_obj.IsExist("dispFmtName") Then
      &p_field.DISPFMTNAME.Value = &p_obj.GetString("dispFmtName");
   End-If;
   If &p_obj.IsExist("defCntryYr") Then
      &p_field.DEFCNTRYYR.Value = &p_obj.GetNumber("defCntryYr");
   End-If;
   If &p_obj.IsExist("imeMode") Then
      &p_field.IMEMODE.Value = &p_obj.GetNumber("imeMode");
   End-If;
   If &p_obj.IsExist("kbLayout") Then
      &p_field.KBLAYOUT.Value = &p_obj.GetNumber("kbLayout");
   End-If;
   If &p_obj.IsExist("objectOwnerId") Then
      &p_field.OBJECTOWNERID.Value = &p_obj.GetString("objectOwnerId");
   End-If;
   If &p_obj.IsExist("fldNotUsed") Then
      &p_field.FLDNOTUSED.Value = &p_obj.GetNumber("fldNotUsed");
   End-If;
   If &p_obj.IsExist("auxFlagMask") Then
      &p_field.AUXFLAGMASK.Value = &p_obj.GetNumber("auxFlagMask");
   End-If;
   If &p_obj.IsExist("comment") Then
      &Comment = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
      &p_field.DESCRLONG.Value = &Comment;
   End-If;
   If &p_isCreate Then
      &p_field.LASTUPDOPRID.Value = %UserId;
      &p_field.LASTUPDDTTM.Value = %Datetime;
   End-If;
end-method;


method UpsertFieldLabels
   /+ &p_fieldName as String, +/
   /+ &p_labels as C_JSON_API:JSONArray +/
   /+ Returns Boolean +/
   Local C_JSON_API:JSONObject &LabelObj;
   Local string &LabelId, &LongName, &ShortName, &SqlStmt;
   Local integer &DefaultLabel, &Exists, &i;
   Local boolean &Ok;

   &Ok = True;
   For &i = 1 To &p_labels.Size
      &LabelObj = &p_labels.GetJsonObject(&i);
      &LabelId = Upper(&LabelObj.GetString("labelId"));
      &LongName = " ";
      &ShortName = " ";
      &DefaultLabel = 0;
      &SqlStmt = "SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME = :1 AND LABEL_ID = :2";
      If Not SQLExec(&SqlStmt, &p_fieldName, &LabelId, &Exists) Then
         &Ok = False;
      Else
         If &Exists = 0 Then
            If &LabelObj.IsExist("longName") Then
               &LongName = &LabelObj.GetString("longName");
            End-If;
            If &LabelObj.IsExist("shortName") Then
               &ShortName = &LabelObj.GetString("shortName");
            End-If;
            If &LabelObj.IsExist("defaultLabel") Then
               &DefaultLabel = &LabelObj.GetNumber("defaultLabel");
            End-If;
            &SqlStmt = "INSERT INTO PSDBFLDLABL (FIELDNAME, LABEL_ID, LONGNAME, SHORTNAME, DEFAULT_LABEL) VALUES (:1, :2, :3, :4, :5)";
            If Not SQLExec(&SqlStmt, &p_fieldName, &LabelId, &LongName, &ShortName, &DefaultLabel) Then
               &Ok = False;
            End-If;
         Else
            &SqlStmt = "SELECT LONGNAME, SHORTNAME, DEFAULT_LABEL FROM PSDBFLDLABL WHERE FIELDNAME = :1 AND LABEL_ID = :2";
            If Not SQLExec(&SqlStmt, &p_fieldName, &LabelId, &LongName, &ShortName, &DefaultLabel) Then
               &Ok = False;
            Else
               If &LabelObj.IsExist("longName") Then
                  &LongName = &LabelObj.GetString("longName");
               End-If;
               If &LabelObj.IsExist("shortName") Then
                  &ShortName = &LabelObj.GetString("shortName");
               End-If;
               If &LabelObj.IsExist("defaultLabel") Then
                  &DefaultLabel = &LabelObj.GetNumber("defaultLabel");
               End-If;
               &SqlStmt = "UPDATE PSDBFLDLABL SET LONGNAME = :1, SHORTNAME = :2, DEFAULT_LABEL = :3 WHERE FIELDNAME = :4 AND LABEL_ID = :5";
               If Not SQLExec(&SqlStmt, &LongName, &ShortName, &DefaultLabel, &p_fieldName, &LabelId) Then
                  &Ok = False;
               End-If;
            End-If;
         End-If;
      End-If;
   End-For;
   Return &Ok;
end-method;


method BeginMetadataUpdate
   /+ &p_rdmVersion as Integer out +/
   /+ Returns Boolean +/
   Local string &RDM;
   Local integer &RDMVersion;

   &RDM = "RDM";
   &RDMVersion = 0;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME = :1 FOR UPDATE OF VERSION", &RDM, &RDMVersion) Then
      &_ErrText = &_ErrText | "cannot lock PSLOCK(RDM), ";
      Return False;
   End-If;
   If Not SQLExec("UPDATE PSLOCK SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &RDM) Then
      &_ErrText = &_ErrText | "cannot update PSLOCK(RDM), ";
      Return False;
   End-If;
   &p_rdmVersion = &RDMVersion + 1;
   Return True;
end-method;


method EndMetadataUpdate
   /+ &p_rdmVersion as Integer +/
   /+ Returns Boolean +/
   Local string &SYS, &RDM;

   &SYS = "SYS";
   &RDM = "RDM";
   If Not SQLExec("UPDATE PSVERSION SET VERSION = VERSION + 1 WHERE OBJECTTYPENAME = :1", &SYS) Then
      &_ErrText = &_ErrText | "cannot update PSVERSION(SYS), ";
      Return False;
   End-If;
   If Not SQLExec("UPDATE PSVERSION SET VERSION = :2 WHERE OBJECTTYPENAME = :1", &RDM, &p_rdmVersion) Then
      &_ErrText = &_ErrText | "cannot update PSVERSION(RDM), ";
      Return False;
   End-If;
   /* The request owns commit, after all version checks and writes. */
   Return True;
end-method;



method LabelRows
   /+ &rs as Rowset, +/
   /+ &where as String, +/
   /+ &name as String, +/
   /+ &labelId as String +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &rows = CreateObject("C_JSON_API:Factory").NewArray();
   Local C_JSON_API:JSONObject &row;
   Local Record &rec;
   Local integer &count, &i, &j;
   &count = &rs.Fill(&where, &name, &labelId);
   For &i = 1 To &count
      &row = CreateObject("C_JSON_API:Factory").NewObject();
      &rec = &rs(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &row.AddProperty(&rec.GetField(&j).Name, String(&rec.GetField(&j).Value));
      End-For;
      &rows.AddJsonObjectElement("", &row);
      &row = &rows.GetJsonObject(&rows.Size);
   End-For;
   Return &rows;
end-method;


method DeleteLabelCli
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &name = &req.GetString("fieldName");
   Local string &labelId = Upper(&req.GetString("labelId"));
   Local string &replacement = "";
   Local integer &count, &uses, &langs, &contexts, &rdm;
   Local number &pageVersion;
   Local boolean &dry = False;
   Local Record &field = CreateRecord(Record.PSDBFIELD);
   Local Record &label = CreateRecord(Record.PSDBFLDLABL);
   Local Record &nextLabel = CreateRecord(Record.PSDBFLDLABL);
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_JSON_API:JSONArray &items = CreateObject("C_JSON_API:Factory").NewArray();
   Local C_JSON_API:JSONObject &backup = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_JSON_API:JSONArray &translations, &contextRows;
   If Not All(&labelId) Or
         Len(&labelId) > 18 Then
      throw CreateException(0, 0, "labelId must be a nonempty string of at most 18 characters");
   End-If;
   If &req.IsExist("replacementLabelId") Then
      &replacement = Upper(&req.GetString("replacementLabelId"));
      If Not All(&replacement) Or
            Len(&replacement) > 18 Or
            &replacement = &labelId Then
         throw CreateException(0, 0, "replacementLabelId must name a different existing label");
      End-If;
   End-If;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   &field.GetField(Field.FIELDNAME).Value = &name;
   If Not &field.SelectByKey() Then
      throw CreateException(0, 0, "Field does not exist");
   End-If;
   &label.GetField(Field.FIELDNAME).Value = &name;
   &label.GetField(Field.LABEL_ID).Value = &labelId;
   If Not &label.SelectByKey() Then
      throw CreateException(0, 0, "Label does not exist");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1", &name, &count);
   If &count <= 1 Then
      throw CreateException(0, 0, "Cannot delete the last Field Label");
   End-If;
   If &label.GetField(Field.DEFAULT_LABEL).Value = 1 Then
      If &replacement = "" Then
         throw CreateException(0, 0, "Deleting the default Label requires replacementLabelId");
      End-If;
      &nextLabel.GetField(Field.FIELDNAME).Value = &name;
      &nextLabel.GetField(Field.LABEL_ID).Value = &replacement;
      If Not &nextLabel.SelectByKey() Then
         throw CreateException(0, 0, "Replacement Label does not exist on this Field");
      End-If;
   Else
      If &req.IsExist("replacementLabelId") Then
         throw CreateException(0, 0, "replacementLabelId is only allowed when deleting the default Label");
      End-If;
   End-If;
   /* Serialize native Page saves while checking explicit references. */
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PPC' FOR UPDATE OF VERSION", &pageVersion) Then
      throw CreateException(0, 0, "Cannot lock Page definitions");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId, &uses);
   If &uses > 0 Then
      throw CreateException(0, 0, "Label is explicitly used in Record fields; update those references first");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSRECFIELDDB WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId, &uses);
   If &uses > 0 Then
      throw CreateException(0, 0, "Label is explicitly used in expanded Record fields; update those references first");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSPNLFIELD WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId, &uses);
   If &uses > 0 Then
      throw CreateException(0, 0, "Label is explicitly used in Pages; update those references first");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSDBFLDLABLLANG WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId, &langs);
   SQLExec("SELECT COUNT(*) FROM PSPTCONTEXT WHERE RECNAME='PSDBFLDLABL' AND OBJECTVALUE1=:1 AND OBJECTVALUE2=:2", &name, &labelId, &contexts);
   &backup.AddProperty("labelId", &labelId);
   &backup.AddProperty("longName", &label.GetField(Field.LONGNAME).Value);
   &backup.AddProperty("shortName", &label.GetField(Field.SHORTNAME).Value);
   &backup.AddProperty("defaultLabel", &label.GetField(Field.DEFAULT_LABEL).Value);
   &translations = %This.LabelRows(CreateRowset(Record.PSDBFLDLABLLANG), "WHERE FIELDNAME=:1 AND LABEL_ID=:2 ORDER BY LANGUAGE_CD", &name, &labelId);
   &contextRows = %This.LabelRows(CreateRowset(Record.PSPTCONTEXT), "WHERE RECNAME='PSDBFLDLABL' AND OBJECTVALUE1=:1 AND OBJECTVALUE2=:2 ORDER BY OBJECTVALUE3,OBJECTVALUE4", &name, &labelId);
   &items.AddJsonObjectElement("", &guard.ProjectItem(2, CreateArray(&name, "", "", ""), False));
   If Not &dry Then
      If Not %This.BeginMetadataUpdate(&rdm) Then
         throw CreateException(0, 0, &_ErrText);
      End-If;
      If Not SQLExec("DELETE FROM PSDBFLDLABLLANG WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId) Then
         throw CreateException(0, 0, "Deleting Label translations failed");
      End-If;
      If Not SQLExec("DELETE FROM PSPTCONTEXT WHERE RECNAME='PSDBFLDLABL' AND OBJECTVALUE1=:1 AND OBJECTVALUE2=:2", &name, &labelId) Then
         throw CreateException(0, 0, "Deleting Label context failed");
      End-If;
      If Not &label.Delete() Then
         throw CreateException(0, 0, "Deleting Label failed");
      End-If;
      If &replacement <> "" Then
         If Not SQLExec("UPDATE PSDBFLDLABL SET DEFAULT_LABEL=0 WHERE FIELDNAME=:1", &name) Or
               Not SQLExec("UPDATE PSDBFLDLABL SET DEFAULT_LABEL=1 WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &replacement) Then
            throw CreateException(0, 0, "Updating replacement default Label failed");
         End-If;
      End-If;
      &field.GetField(Field.VERSION).Value = &rdm;
      &field.GetField(Field.LASTUPDOPRID).Value = %UserId;
      &field.GetField(Field.LASTUPDDTTM).Value = %Datetime;
      If Not &field.Update() Or
            Not %This.EndMetadataUpdate(&rdm) Then
         throw CreateException(0, 0, "Updating Field cache version failed: " | &_ErrText);
      End-If;
      SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND LABEL_ID=:2", &name, &labelId, &count);
      If &count <> 0 Then
         throw CreateException(0, 0, "Label still exists after deletion");
      End-If;
   End-If;
   &out.AddProperty("fieldName", &name);
   &out.AddProperty("labelId", &labelId);
   &out.AddProperty("replacementLabelId", &replacement);
   &out.AddProperty("languageRowCount", &langs);
   &out.AddProperty("contextRowCount", &contexts);
   &out.AddProperty("deleted", ( Not &dry));
   &out.AddProperty("dryRun", &dry);
   &out.AddProperty("version", &guard.FieldVersion(&name));
   &out.AddJsonObject("labelBackup", &backup);
   &backup = &out.GetJsonObject("labelBackup");
   &out.AddJsonArray("translations", &translations);
   &translations = &out.GetJsonArray("translations");
   &out.AddJsonArray("contexts", &contextRows);
   &contextRows = &out.GetJsonArray("contexts");
   &out.AddJsonArray("projectItems", &items);
   &items = &out.GetJsonArray("projectItems");
   Return &out;
end-method;


method DeleteFieldCli
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &name = &req.GetString("fieldName");
   Local object &mgr = CreateObject("%metadata:RecordFieldDefn:RecordFieldDefn_Manager");
   Local object &key = CreateObject("%metadata:Key", 6, &name);
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_JSON_API:JSONArray &items = CreateObject("C_JSON_API:Factory").NewArray();
   Local integer &uses;
   Local boolean &dry = False;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
      throw CreateException(0, 0, "Field does not exist");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSXLATITEM WHERE FIELDNAME=:1", &name, &uses);
   If &uses > 0 Then
      throw CreateException(0, 0, "Field has Translate values; delete their exact rows before deleting the Field");
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE FIELDNAME=:1 AND SUBRECORD='N'", &name, &uses);
   If &uses > 0 Then
      throw CreateException(0, 0, "Field is still used in Records; remove its Record fields first");
   End-If;
   &items.AddJsonObjectElement("", &guard.ProjectItem(2, CreateArray(&name, "", "", ""), True));
   If Not &dry Then
      If Not ObjectDoMethodArray(&mgr, "DeleteDefn", CreateArrayAny(&key)) Then
         throw CreateException(0, 0, "Native Field DeleteDefn failed");
      End-If;
      If ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
         throw CreateException(0, 0, "Field still exists after deletion");
      End-If;
   End-If;
   &out.AddProperty("fieldName", &name);
   &out.AddProperty("deleted", ( Not &dry));
   &out.AddProperty("dryRun", &dry);
   &out.AddProperty("version", &guard.FieldVersion(&name));
   &out.AddJsonArray("projectItems", &items);
   &items = &out.GetJsonArray("projectItems");
   Return &out;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import C_META_DATA_PKG:Utility:NativeAdapter;
import C_META_DATA_PKG:Utility:DefinitionVersion;

class CoreOperHtmlDefn
   method CoreOperHtmlDefn();
   method VersionRows(&rows As Rowset, &where As string, &name As string) Returns string;
   method BlobVersion(&name As string, &translated As boolean) Returns string;
   method ContentVersion(&name As string) Returns string;
   method LockContent(&name As string);
   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   instance integer &_ContentType;
end-class;

method CoreOperHtmlDefn
   &_ContentType = 4;
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   Local C_JSON_API:JSONObject &req, &result;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &name, &action, &beforeVersion, &afterVersion, &sourceName, &sourceVersion;
   Local integer &status = 400;
   Local integer &present;
   Local boolean &writing, &dry;
   try
      &req = &json.GetRootObject(&message.GetContentString());
      If Not &req.IsExist("operationType") Or
            Not &req.IsExist("kind") Then
         throw CreateException(0, 0, "operationType and kind are required");
      End-If;
      &_ContentType = 4;
      If &req.GetString("kind") = "image" Then
         &_ContentType = 1;
      Else
         If &req.GetString("kind") <> "html" Then
            throw CreateException(0, 0, "Kind is not supported by this endpoint");
         End-If;
      End-If;
      If Len(&message.GetContentString()) > 262144 Then
         throw CreateException(0, 0, "Request exceeds 262144 characters");
      End-If;
      Local integer &ri;
      Local string &requestField;
      Local array of string &allowed = CreateArray("kind", "name", "operationType", "properties", "collections", "dryRun", "expectedState", "expectedVersion", "sourceName", "expectedSourceVersion");
      For &ri = 1 To &req.ChildCount
         &requestField = &req.GetPropertyNameAt(&ri);
         If &allowed.Find(&requestField) = 0 Then
            throw CreateException(0, 0, "Unknown request property: " | &requestField);
         End-If;
      End-For;
      If Not &req.IsExist("name") Then
         throw CreateException(0, 0, "name is required");
      End-If;
      &name = &req.GetString("name");
      If &_ContentType = 4 And
            (&req.IsExist("sourceName") Or
               &req.IsExist("expectedSourceVersion")) Then
         throw CreateException(0, 0, "Source Image keys are not HTML properties");
      End-If;
      &action = &req.GetString("operationType");
      If Len(&name) = 0 Or
            Len(&name) > 30 Then
         throw CreateException(0, 0, "Definition name must have 1-30 characters");
      End-If;
      &allowed = CreateArray("view", "struct", "exists", "create", "modify");
      If &allowed.Find(&action) = 0 Then
         throw CreateException(0, 0, "Unsupported content operation");
      End-If;
      &writing = (&action = "create" Or
         &action = "modify");
      &dry = False;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      If &writing Then
         &guard.ValidateName(&name, 30);
         %This.LockContent(&name);
      End-If;
      &beforeVersion = %This.ContentVersion(&name);
      If &writing Then
         &status = &guard.Check(&req, &beforeVersion);
         If &status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original content snapshot");
         End-If;
         &status = 400;
      End-If;
      SQLExec("SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=:2", &name, &_ContentType, &present);
      If &_ContentType = 1 Then
         Local integer &unsupported;
         Local C_JSON_API:JSONObject &props;
         SQLExec("SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=1 AND (LOWER(CONTFMT)<>'svg' OR ALTCONTNUM<>1)", &name, &unsupported);
         If &unsupported > 0 Then
            throw CreateException(0, 0, "Only single SVG Image definitions are supported");
         End-If;
         If &writing Then
            If &action <> "create" Or
                  Not &req.IsExist("sourceName") Or
                  &req.IsExist("properties") Or
                  &req.IsExist("collections") Then
               throw CreateException(0, 0, "Image writes only clone an existing source definition into an absent target");
            End-If;
            If &present > 0 Then
               throw CreateException(0, 0, "Target Image already exists");
            End-If;
            &sourceName = &req.GetString("sourceName");
            &guard.ValidateName(&sourceName, 30);
            If &sourceName = &name Then
               throw CreateException(0, 0, "Source and target Image names must differ");
            End-If;
            %This.LockContent(&sourceName);
            &sourceVersion = %This.ContentVersion(&sourceName);
            If Not &req.IsExist("expectedSourceVersion") Or
                  &req.GetString("expectedSourceVersion") = "" Then
               &status = 428;
               throw CreateException(0, 0, "Original source Image version is required");
            End-If;
            If &req.GetString("expectedSourceVersion") <> &sourceVersion Then
               &status = 409;
               throw CreateException(0, 0, "VERSION_CONFLICT: source Image changed");
            End-If;
            SQLExec("SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=1 AND LOWER(CONTFMT)='svg' AND ALTCONTNUM=1 AND (SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=1)=1", &sourceName, &unsupported);
            If &unsupported <> 1 Then
               &status = 400;
               throw CreateException(0, 0, "Source must be an existing single SVG Image");
            End-If;
         End-If;
         If &writing And
               &req.IsExist("properties") Then
            &props = &req.GetJsonObject("properties");
            If &props.IsExist("ContFmt") Then
               If Lower(&props.GetString("ContFmt")) <> "svg" Then
                  throw CreateException(0, 0, "Image ContFmt must be svg");
               End-If;
            End-If;
         End-If;
      End-If;
      If &action = "exists" Or
            ((&action = "view" Or
               &action = "struct") And
               &present = 0) Then
         &result = CreateObject("C_JSON_API:Factory").NewObject();
         &result.AddProperty("exists", (&present > 0));
      Else
         &result = &engine.Run(&req);
         If &action = "view" Or
               &action = "struct" Then
            &result.AddProperty("exists", True);
         End-If;
      End-If;
      &afterVersion = %This.ContentVersion(&name);
      If &_ContentType = 1 Then
         &result.AddProperty("blobFingerprint", %This.BlobVersion(&name, False));
         &result.AddProperty("translationBlobFingerprint", %This.BlobVersion(&name, True));
         If &writing And
               Not &dry Then
            If %This.ContentVersion(&sourceName) <> &sourceVersion Or
                  %This.BlobVersion(&name, False) <> %This.BlobVersion(&sourceName, False) Or
                  %This.BlobVersion(&name, True) <> %This.BlobVersion(&sourceName, True) Then
               throw CreateException(0, 0, "Image clone did not preserve source and native BLOB data");
            End-If;
         End-If;
      End-If;
      If Not &writing And
            &beforeVersion <> &afterVersion Then
         &status = 409;
         throw CreateException(0, 0, "VERSION_CONFLICT: content changed during read; read again");
      End-If;
      &result.AddProperty("beforeVersion", &beforeVersion);
      &result.AddProperty("version", &afterVersion);
      &result.AddProperty(&req.GetString("kind") | "VersionControl", 1);
      If &writing Then
         If &dry Then
            SQLExec("rollback");
         Else
            SQLExec("commit");
         End-If;
      End-If;
      Return &json.CreateSuccessMessage(&responseOperation, &result);
   catch Exception &ex
      SQLExec("rollback");
      Return &json.CreateFailedMessage(&responseOperation, &status, &ex.ToString());
   end-try;
end-method;


method VersionRows
   /+ &rows as Rowset, +/
   /+ &where as String, +/
   /+ &name as String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &count = &rows.Fill(&where, &name);
   &state = String(&count);
   For &i = 1 To &count
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;

method BlobVersion
   /+ &name as String, +/
   /+ &translated as Boolean +/
   /+ Returns String +/
   Local SQL &cursor;
   Local number &alt, &seq, &length, &offset;
   Local string &language, &chunk, &state;
   &state = "";
   If &translated Then
      &cursor = CreateSQL("SELECT ALTCONTNUM,SEQNUM,LANGUAGE_CD,DBMS_LOB.GETLENGTH(CONTDATA) FROM PSCONTENTLANG WHERE CONTNAME=:1 AND CONTTYPE=:2 ORDER BY ALTCONTNUM,LANGUAGE_CD,SEQNUM", &name, &_ContentType);
   Else
      &cursor = CreateSQL("SELECT ALTCONTNUM,SEQNUM,' ',DBMS_LOB.GETLENGTH(CONTDATA) FROM PSCONTENT WHERE CONTNAME=:1 AND CONTTYPE=:2 ORDER BY ALTCONTNUM,SEQNUM", &name, &_ContentType);
   End-If;
   While &cursor.Fetch(&alt, &seq, &language, &length)
      &state = &state | "|" | String(&alt) | ":" | String(&seq) | ":" | &language | ":" | String(&length);
      &offset = 1;
      While &offset <= &length
         If &translated Then
            SQLExec("SELECT RAWTOHEX(DBMS_LOB.SUBSTR(CONTDATA,2000,:1)) FROM PSCONTENTLANG WHERE CONTNAME=:2 AND CONTTYPE=:6 AND ALTCONTNUM=:3 AND SEQNUM=:4 AND LANGUAGE_CD=:5", &offset, &name, &alt, &seq, &language, &_ContentType, &chunk);
         Else
            SQLExec("SELECT RAWTOHEX(DBMS_LOB.SUBSTR(CONTDATA,2000,:1)) FROM PSCONTENT WHERE CONTNAME=:2 AND CONTTYPE=:5 AND ALTCONTNUM=:3 AND SEQNUM=:4", &offset, &name, &alt, &seq, &_ContentType, &chunk);
         End-If;
         &state = &state | ":" | HashSHA256(&chunk);
         &offset = &offset + 2000;
      End-While;
   End-While;
   Return HashSHA256(&state);
end-method;

method ContentVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "HTML1|" | &name | "|" | %Language;
   Local integer &present;
   Local number &generation;
   If &_ContentType = 1 Then
      &state = "IMAGE1|" | &name | "|" | %Language;
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=:2", &name, &_ContentType, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='CRM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEFN), "WHERE CONTNAME=:1 AND CONTTYPE=" | String(&_ContentType) | " ORDER BY ALTCONTNUM", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEFNLANG), "WHERE CONTNAME=:1 AND CONTTYPE=" | String(&_ContentType) | " ORDER BY ALTCONTNUM,LANGUAGE_CD", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEL), "WHERE CONTNAME=:1 AND CONTTYPE=" | String(&_ContentType) | " ORDER BY ALTCONTNUM,VERSION", &name);
   &state = &state | %This.BlobVersion(&name, False) | %This.BlobVersion(&name, True);

   If &_ContentType = 1 Then
      Return "image1:" | HashSHA256(&state);
   End-If;
   Return "html1:" | HashSHA256(&state);
end-method;

method LockContent
   /+ &name as String +/
   Local number &generation;
   Local SQL &cursor;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='CRM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock CRM");
   End-If;

   &cursor = CreateSQL("SELECT VERSION FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=:2 ORDER BY ALTCONTNUM FOR UPDATE OF VERSION", &name, &_ContentType);
   While &cursor.Fetch(&generation)
   End-While;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import C_META_DATA_PKG:Utility:NativeAdapter;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import %metadata:Key;
import C_META_DATA_PKG:Utility:DefinitionVersion;
import C_META_DATA_PKG:Utility:MenuCodeAdapter;

class CoreOperMenuDefn
   method CoreOperMenuDefn();
   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   method MenuVersion(&name As string) Returns string;
   method VersionRows(&name As string, &rows As Rowset, &order As string) Returns string;
   method LockMenu(&name As string);
end-class;

method CoreOperMenuDefn
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   Local C_JSON_API:JSONObject &req, &result;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local integer &status = 400;
   Local integer &present;
   Local boolean &writing, &dry;
   Local string &name, &beforeVersion, &afterVersion;
   try
      &req = &json.GetRootObject(&message.GetContentString());
      If Not &req.IsExist("operationType") Or
            Not &req.IsExist("kind") Then
         throw CreateException(0, 0, "operationType and kind are required");
      End-If;
      If &req.GetString("kind") <> "menu" Then
         throw CreateException(0, 0, "Kind is not supported by this endpoint");
      End-If;
      If Len(&message.GetContentString()) > 262144 Then
         throw CreateException(0, 0, "Request exceeds 262144 characters");
      End-If;
      Local integer &ri;
      Local string &requestField;
      Local string &action = &req.GetString("operationType");
      Local boolean &codeAction = (&action = "viewCode" Or
         &action = "modifyCode" Or
         &action = "deleteCode");
      Local array of string &allowed;
      If &codeAction Then
         &allowed = CreateArray("kind", "name", "operationType", "peoplecode", "dryRun", "expectedCode", "expectedVersion", "BarName", "ItemName");
      Else
         &allowed = CreateArray("kind", "name", "operationType", "properties", "collections", "dryRun", "expectedState", "expectedVersion");
      End-If;
      For &ri = 1 To &req.ChildCount
         &requestField = &req.GetPropertyNameAt(&ri);
         If &allowed.Find(&requestField) = 0 Then
            throw CreateException(0, 0, "Unknown request property: " | &requestField);
         End-If;
      End-For;
      If Not &req.IsExist("name") Then
         throw CreateException(0, 0, "name is required");
      End-If;
      &name = &req.GetString("name");
      If Len(&name) = 0 Or
            Len(&name) > 30 Then
         throw CreateException(0, 0, "Menu name must have 1-30 characters");
      End-If;
      &allowed = CreateArray("view", "struct", "exists", "viewCode", "create", "modify", "deleteChild", "modifyCode", "deleteCode");
      If &allowed.Find(&action) = 0 Then
         throw CreateException(0, 0, "Unsupported Menu operation");
      End-If;
      &writing = (&action = "create" Or
         &action = "modify" Or
         &action = "deleteChild" Or
         &action = "modifyCode" Or
         &action = "deleteCode");
      &dry = False;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      If &writing Then
         &guard.ValidateName(&name, 30);
         %This.LockMenu(&name);
      End-If;
      &beforeVersion = %This.MenuVersion(&name);
      If &writing Then
         &status = &guard.Check(&req, &beforeVersion);
         If &status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original Menu snapshot");
         End-If;
         &status = 400;
      End-If;
      SQLExec("SELECT COUNT(*) FROM PSMENUDEFN WHERE MENUNAME=:1", &name, &present);
      If &codeAction Then
         Local C_META_DATA_PKG:Utility:MenuCodeAdapter &codeEngine = create C_META_DATA_PKG:Utility:MenuCodeAdapter();
         &result = &codeEngine.Run(&req);
      Else
         If &action = "exists" Or
               ((&action = "view" Or
                  &action = "struct") And
                  &present = 0) Then
            &result = CreateObject("C_JSON_API:Factory").NewObject();
            &result.AddProperty("exists", (&present > 0));
         Else
            &result = &engine.Run(&req);
            If &action = "view" Or
                  &action = "struct" Then
               &result.AddProperty("exists", True);
            End-If;
         End-If;
      End-If;
      &afterVersion = %This.MenuVersion(&name);
      If Not &writing And
            &beforeVersion <> &afterVersion Then
         &status = 409;
         throw CreateException(0, 0, "VERSION_CONFLICT: Menu changed during read; read again");
      End-If;
      &result.AddProperty("beforeVersion", &beforeVersion);
      &result.AddProperty("version", &afterVersion);
      &result.AddProperty("menuVersionControl", 1);
      If &writing Then
         If &dry Then
            SQLExec("rollback");
         Else
            SQLExec("commit");
         End-If;
      End-If;
      Return &json.CreateSuccessMessage(&responseOperation, &result);
   catch Exception &ex
      SQLExec("rollback");
      Return &json.CreateFailedMessage(&responseOperation, &status, &ex.ToString());
   end-try;
end-method;

method VersionRows
   /+ &name as String, +/
   /+ &rows as Rowset, +/
   /+ &order as String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &count = &rows.Fill("WHERE MENUNAME=:1 " | &order, &name);
   &state = String(&count);
   For &i = 1 To &count
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;

method MenuVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "MENU1|" | &name | "|" | %Language;
   Local integer &present;
   Local number &generation, &pcVersion;
   Local SQL &cursor;
   SQLExec("SELECT COUNT(*) FROM PSMENUDEFN WHERE MENUNAME=:1", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='MDM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUDEFN), "ORDER BY MENUNAME");
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUDEFNLANG), "ORDER BY LANGUAGE_CD");
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUDEL), "ORDER BY VERSION");
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUITEM), "ORDER BY BARNAME,ITEMNAME");
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUITEMLANG), "ORDER BY BARNAME,ITEMNAME,LANGUAGE_CD");
   &state = &state | %This.VersionRows(&name, CreateRowset(Record.PSMENUORIGIN), "ORDER BY MENUNAME");
   Local string &bar, &item, &event;
   &cursor = CreateSQL("SELECT OBJECTVALUE2,OBJECTVALUE3,OBJECTVALUE4,VERSION FROM PSPCMPROG WHERE OBJECTID1=3 AND OBJECTVALUE1=:1 AND OBJECTID2=4 AND OBJECTID3=5 AND OBJECTID4=12 ORDER BY OBJECTVALUE2,OBJECTVALUE3,OBJECTVALUE4,VERSION", &name);
   While &cursor.Fetch(&bar, &item, &event, &pcVersion)
      &state = &state | "|PC:" | String(Len(&bar)) | ":" | &bar | ":" | String(Len(&item)) | ":" | &item | ":" | &event | ":" | String(&pcVersion);
   End-While;
   Return "menu1:" | HashSHA256(&state);
end-method;

method LockMenu
   /+ &name as String +/
   Local number &generation;
   REM Match the PCM then definition-lock order used by the other metadata handlers;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PCM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock PCM");
   End-If;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='MDM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock MDM");
   End-If;
   SQLExec("SELECT VERSION FROM PSMENUDEFN WHERE MENUNAME=:1 FOR UPDATE OF VERSION", &name, &generation);
end-method;

