class CoreOperPageDefn
   method CoreOperPageDefn();

   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   method DeletePagePeopleCodeCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method GetPageStruct() Returns C_JSON_API:JSONObject;
   method BuildRawObject(&p_rec As Record) Returns C_JSON_API:JSONObject;
   method GetControlExt(&p_id As number) Returns C_JSON_API:JSONObject;
   method CreatePageCli(&p_obj As C_JSON_API:JSONObject);
   method ModifyPagePropsCli(&p_obj As C_JSON_API:JSONObject);
   method AddControlCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method DeleteControlCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method FindControlsCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method ModifyControlCli(&p_obj As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method ValidateControlRequest(&req As C_JSON_API:JSONObject, &operation As string) Returns boolean;
   method ValidateBasicProps(&req As C_JSON_API:JSONObject, &rec As Record) Returns boolean;
   method ApplyBasicProps(&req As C_JSON_API:JSONObject, &rec As Record);
   method EnsureBasicExt(&id As number);
   method FlagBit(&bits As number, &mask As number) Returns number;
   method FlagValue(&bits As number, &mask As number, &enabled As number) Returns number;
   method ValidateEditProps(&req As C_JSON_API:JSONObject, &rec As Record) Returns boolean;
   method ApplyEditProps(&req As C_JSON_API:JSONObject, &rec As Record);
   method AddEditProperties(&rec As Record, &ext As C_JSON_API:JSONObject, &obj As C_JSON_API:JSONObject);
   method ValidateLabelProps(&req As C_JSON_API:JSONObject, &rec As Record) Returns boolean;
   method ApplyLabelProps(&req As C_JSON_API:JSONObject, &rec As Record);
   method AddLabelProperties(&rec As Record, &obj As C_JSON_API:JSONObject);
   method ValidateDropDownProps(&req As C_JSON_API:JSONObject, &rec As Record) Returns boolean;
