method CoreOperPageDefn
   &_ErrText = "";
   &_PageName = "";
   &_FullMode = 0;
   &_MetaTable = "";
   &JsonUtil = create C_JSON_API:JsonUtil();
   &CommUtil = create C_COMMONS_PKG:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;


method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local Message &RespMsg;
   Local C_JSON_API:JSONObject &ReqObject, &RespObject;
   Local string &OperationType, &beforeVersion, &afterVersion;
   Local integer &status = 400;
   Local number &lockVersion, &exists;
   Local boolean &writing;
   Local boolean &dry = False;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();

   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      If Not &ReqObject.IsExist("pageName") Then
         &_ErrText = &_ErrText | "pageName is required, ";
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_ErrText);
         Return &RespMsg;
      End-If;
      &_PageName = &ReqObject.GetString("pageName");
      &guard.ValidateName(&_PageName, 18);

      REM v2: full=true(1) 开启全量列输出（struct 增强，2026-09-06）;
      If &ReqObject.IsExist("full") Then
         &_FullMode = &ReqObject.GetNumber("full");
      End-If;

      If Not &ReqObject.IsExist("operationType") Then
         &OperationType = "struct";
      Else
         &OperationType = &ReqObject.GetString("operationType");
      End-If;

      &writing = (&OperationType = "createPage" Or
         &OperationType = "modifyPageProps" Or
         &OperationType = "addControl" Or
         &OperationType = "modifyControl" Or
         &OperationType = "deleteControl" Or
         &OperationType = "applyStructure" Or
         &OperationType = "modifyPeopleCode" Or
         &OperationType = "deletePeopleCode");
      If &ReqObject.IsExist("dryRun") Then
         &dry = &ReqObject.GetBoolean("dryRun");
         If &OperationType <> "deletePeopleCode" And
               &OperationType <> "applyStructure" Then
            throw CreateException(0, 0, "dryRun supports deletePeopleCode and applyStructure only");
         End-If;
      End-If;
      If &writing Then
         REM Serialize page metadata and code writes before checking the snapshot;
         If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PCM' FOR UPDATE OF VERSION", &lockVersion) Then
            throw CreateException(0, 0, "Cannot lock PCM");
         End-If;
         If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PDM' FOR UPDATE OF VERSION", &lockVersion) Then
            throw CreateException(0, 0, "Cannot lock PDM");
         End-If;
         SQLExec("SELECT VERSION FROM PSPNLDEFN WHERE PNLNAME=:1 FOR UPDATE OF VERSION", &_PageName, &lockVersion);
      End-If;
      &beforeVersion = %This.PageVersion();
      If &writing Then
         &status = &guard.Check(&ReqObject, &beforeVersion);
         If &status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: read the original Page snapshot before writing");
         End-If;
         &status = 400;
         SQLExec("SELECT COUNT(*) FROM PSPNLDEFN WHERE PNLNAME=:1", &_PageName, &exists);
         If &OperationType <> "createPage" And
               &OperationType <> "applyStructure" And
               &exists = 0 Then
            throw CreateException(0, 0, "Page not exist");
         End-If;
      End-If;
      If &OperationType = "addControl" Or
            &OperationType = "modifyControl" Then
         If Not %This.ValidateControlRequest(&ReqObject, &OperationType) Then
            throw CreateException(0, 0, &_ErrText);
         End-If;
      End-If;

      Evaluate &OperationType
      When "struct"
         &RespObject = %This.GetPageStruct();
         Break;
      When "viewPeopleCode"
         &RespObject = %This.ViewPagePeopleCodeCli(&ReqObject);
         Break;
      When "deletePeopleCode"
         &RespObject = %This.DeletePagePeopleCodeCli(&ReqObject);
         Break;
      When "modifyPeopleCode"
         %This.ModifyPagePeopleCodeCli(&ReqObject);
         Break;
      When "createPage"
         %This.CreatePageCli(&ReqObject);
         Break;
      When "modifyPageProps"
         %This.ModifyPagePropsCli(&ReqObject);
         Break;
      When "addControl"
         &RespObject = %This.AddControlCli(&ReqObject);
         Break;
      When "deleteControl"
         &RespObject = %This.DeleteControlCli(&ReqObject);
         Break;
      When "findControls"
         &RespObject = %This.FindControlsCli(&ReqObject);
         Break;
      When "modifyControl"
         &RespObject = %This.ModifyControlCli(&ReqObject);
         Break;
      When "applyStructure"
         &RespObject = %This.ApplyStructureCli(&ReqObject);
         Break;
      When-Other
         &_ErrText = &_ErrText | "Unknown operationType: " | &OperationType;
      End-Evaluate;
      If &_ErrText = "" Then
         If (&OperationType = "modifyPeopleCode" Or
               &OperationType = "deletePeopleCode") And
               Not &dry Then
            %This.TouchVersion();
         End-If;
         &afterVersion = %This.PageVersion();
         If Not &writing And
               &beforeVersion <> &afterVersion Then
            &status = 409;
            throw CreateException(0, 0, "VERSION_CONFLICT: Page changed during read");
         End-If;
         If &RespObject = Null Then
            &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
         End-If;
         &RespObject.AddProperty("version", &afterVersion);
         &RespObject.AddProperty("pageVersionControl", 1);
         If &writing Then
            If &dry Then
               SQLExec("rollback");
            Else
               SQLExec("commit");
            End-If;
         End-If;
         &RespMsg = &JsonUtil.CreateSuccessMessage(&responseOperation, &RespObject);
      Else
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_ErrText);
      End-If;
   catch Exception &ex
      SQLExec("rollback");
      &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, &status, &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;


method GetPageStruct
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &PageStruct, &FieldObj;
   Local C_JSON_API:JSONArray &FieldsArr;
   Local Rowset &RsPsPnlField;
   Local Record &PSPNLDEFN, &PSPNLFIELD;
   Local integer &i, &FieldRows;
   Local number &fieldUseRaw;
   Local string &fieldTypeStr;
   Local C_JSON_API:JSONObject &basicExt;

   &PageStruct = CreateObject("C_JSON_API:Factory").NewObject();

   REM Query page definition;
   &PSPNLDEFN = CreateRecord(Record.PSPNLDEFN);
   &PSPNLDEFN.PNLNAME.Value = &_PageName;
   If Not &PSPNLDEFN.SelectByKey() Then
      &PageStruct.AddProperty("pnlName", &_PageName);
      &PageStruct.AddProperty("exists", False);
      &PageStruct.AddProperty("controlPropertyVersion", 7);
      &PageStruct.AddJsonArray("fields", CreateObject("C_JSON_API:Factory").NewArray());
      &PageStruct.AddProperty("fieldCount", 0);
      Return &PageStruct;
   End-If;

   REM Page basic info;
   &PageStruct.AddProperty("controlPropertyVersion", 7);
   &PageStruct.AddProperty("exists", True);
   &PageStruct.AddProperty("pageVersion", &PSPNLDEFN.VERSION.Value);
   &PageStruct.AddProperty("pnlName", &PSPNLDEFN.PNLNAME.Value);
   &PageStruct.AddProperty("descr", &PSPNLDEFN.DESCR.Value);
   &PageStruct.AddProperty("descrLong", &PSPNLDEFN.DESCRLONG.Value);
   &PageStruct.AddProperty("pnlType", &MappingUtil.DecodePnlType(&PSPNLDEFN.PNLTYPE.Value));
   &PageStruct.AddProperty("pnlUse", &PSPNLDEFN.PNLUSE.Value);
   &PageStruct.AddProperty("lastUpdate", "Last updated by: " | &PSPNLDEFN.LASTUPDOPRID.Value | ", " | DateTimeToLocalizedString(&PSPNLDEFN.LASTUPDDTTM.Value, &DateTimeFormat));
   &PageStruct.AddProperty("hasPeopleCode", %This.HasPagePeopleCode());

   REM v2 full mode: PSPNLDEFN 全量列 + PSPNLFIELDEXT 行集;
   If &_FullMode >= 1 Then
      &PageStruct.AddJsonObject("raw", %This.BuildRawObject(&PSPNLDEFN));
   End-If;


   REM Field list;
   &FieldsArr = CreateObject("C_JSON_API:Factory").NewArray();
   &RsPsPnlField = CreateRowset(Record.PSPNLFIELD);
   &RsPsPnlField.Flush();
   &FieldRows = &RsPsPnlField.Fill(" WHERE PNLNAME = :1", &_PageName);
   &RsPsPnlField.Sort(PSPNLFIELD.PNLFLDID, "A");

   For &i = 1 To &FieldRows
      &PSPNLFIELD = &RsPsPnlField(&i).GetRecord(1);
      &FieldObj = CreateObject("C_JSON_API:Factory").NewObject();

      REM Binding;
      &FieldObj.AddProperty("pnlFldId", &PSPNLFIELD.PNLFLDID.Value);
      &FieldObj.AddProperty("recName", &PSPNLFIELD.RECNAME.Value);
      &FieldObj.AddProperty("fieldName", &PSPNLFIELD.FIELDNAME.Value);

      REM Field type;
      &fieldTypeStr = &MappingUtil.DecodePnlFieldType(&PSPNLFIELD.FIELDTYPE.Value, &PSPNLFIELD.PBDISPLAYTYPE.Value);
      &FieldObj.AddProperty("fieldType", &fieldTypeStr);

      REM FIELDUSE bitmask;
      &fieldUseRaw = &PSPNLFIELD.FIELDUSE.Value;
      &FieldObj.AddProperty("fieldUse", &fieldUseRaw);

      REM Full output needs this control's extension even for non-Edit/DDL controls;
      If &_FullMode >= 1 Or
            &PSPNLFIELD.FIELDTYPE.Value = 4 Or
            &PSPNLFIELD.FIELDTYPE.Value = 5 Then
         &basicExt = %This.GetControlExt(&PSPNLFIELD.PNLFLDID.Value);
      End-If;

      If &PSPNLFIELD.FIELDTYPE.Value = 4 Or
            &PSPNLFIELD.FIELDTYPE.Value = 5 Then
         REM AD evidence 05/29 and 43/44: these bits are not Required or Key;
         &FieldObj.AddProperty("displayOnly", %This.FlagBit(&fieldUseRaw, 1));
         &FieldObj.AddProperty("invisible", %This.FlagBit(&fieldUseRaw, 2));
         &FieldObj.AddProperty("displayControl", %This.FlagBit(&fieldUseRaw, 8));
         &FieldObj.AddProperty("relatedField", %This.FlagBit(&fieldUseRaw, 16));
         &FieldObj.AddProperty("relatedDisplay", %This.FlagBit(&fieldUseRaw, 16));
         &FieldObj.AddProperty("multiCurrency", %This.FlagBit(&fieldUseRaw, 32));
         &FieldObj.AddProperty("setComponentChanged", 1 - %This.FlagBit(&PSPNLFIELD.FIELDUSETMP.Value, 8));
         If %This.FlagBit(&PSPNLFIELD.FIELDUSETMP.Value, 4) = 1 Then
            &FieldObj.AddProperty("displayOnlyAppearance", "disabled");
         Else
            &FieldObj.AddProperty("displayOnlyAppearance", "textOnly");
         End-If;
         &FieldObj.AddProperty("pageFieldName", &PSPNLFIELD.PNLFIELDNAME.Value);
         &FieldObj.AddProperty("enableAsAnchor", Value(&PSPNLFIELD.ENABLEASANCHOR.Value));
         Local number &extUse = 0;
         If &basicExt.IsExist("FIELDUSETEMP2") Then
            &extUse = &basicExt.GetNumber("FIELDUSETEMP2");
         End-If;
         &FieldObj.AddProperty("readOnlyScreenReader", %This.FlagBit(&extUse, 65536));
         %This.AddBatchProperties(&PSPNLFIELD, &basicExt, &FieldObj);
      End-If;

      If &PSPNLFIELD.FIELDTYPE.Value = 4 Then
         %This.AddEditProperties(&PSPNLFIELD, &basicExt, &FieldObj);
      End-If;
      If &PSPNLFIELD.FIELDTYPE.Value = 4 Or
            &PSPNLFIELD.FIELDTYPE.Value = 5 Then
         %This.AddLabelProperties(&PSPNLFIELD, &FieldObj);
         %This.AddLayoutProperties(&PSPNLFIELD, &FieldObj);
      End-If;

      If &PSPNLFIELD.FIELDTYPE.Value = 5 Then
         %This.AddDropDownProperties(&PSPNLFIELD, &FieldObj);
      End-If;
      REM Scroll level;
      &FieldObj.AddProperty("occursLevel", &PSPNLFIELD.OCCURSLEVEL.Value);

      REM Label;
      &FieldObj.AddProperty("labelText", &PSPNLFIELD.LBLTEXT.Value);
      &FieldObj.AddProperty("labelType", &PSPNLFIELD.LBLTYPE.Value);
      &FieldObj.AddProperty("labelLoc", &PSPNLFIELD.LBLLOC.Value);

      REM Position and size;
      &FieldObj.AddProperty("fieldLeft", &PSPNLFIELD.FIELDLEFT.Value);
      &FieldObj.AddProperty("fieldTop", &PSPNLFIELD.FIELDTOP.Value);
      &FieldObj.AddProperty("fieldRight", &PSPNLFIELD.FIELDRIGHT.Value);
      &FieldObj.AddProperty("fieldBottom", &PSPNLFIELD.FIELDBOTTOM.Value);
      &FieldObj.AddProperty("editSize", &PSPNLFIELD.EDITSIZE.Value);

      REM v2 full mode: 控件全量原始列 + Fluid 扩展列;
      If &_FullMode >= 1 Then
         Local C_JSON_API:JSONObject &rawObj;
         Local number &msgSet, &msgNum;
         &rawObj = %This.BuildRawObject(&PSPNLFIELD);
         If &PSPNLFIELD.GRDLBLMSGSET.Value <> 0 Or
               &PSPNLFIELD.GRDLBLMSGNUM.Value <> 0 Then
            &msgSet = 0;
            &msgNum = 0;
            SQLExec("SELECT GRDLBLMSGSET, GRDLBLMSGNUM FROM PSPNLFIELD WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &PSPNLFIELD.PNLFLDID.Value, &msgSet, &msgNum);
            &rawObj.AddProperty("GRDLBLMSGSET", &msgSet);
            &rawObj.AddProperty("GRDLBLMSGNUM", &msgNum);
         End-If;
         &FieldObj.AddJsonObject("raw", &rawObj);
         &FieldObj.AddJsonObject("ext", &basicExt);
         Local C_JSON_API:JSONObject &ctlData;
         Local C_JSON_API:JSONArray &btnData;
         &ctlData = %This.GetControlCntrlData(&PSPNLFIELD.PNLFLDID.Value);
         If &ctlData.ChildCount > 0 Then
            &FieldObj.AddJsonObject("cntrldata", &ctlData);
         End-If;
         &btnData = %This.GetControlBtnData(&PSPNLFIELD.PNLFLDID.Value);
         If &btnData.Size > 0 Then
            &FieldObj.AddJsonArray("btndata", &btnData);
         End-If;
      End-If;

      &FieldsArr.AddJsonObjectElement("", &FieldObj);
      &FieldObj = &FieldsArr.GetJsonObject(&FieldsArr.Size);
   End-For;
   &PageStruct.AddJsonArray("fields", &FieldsArr);
   &FieldsArr = &PageStruct.GetJsonArray("fields");

   Return &PageStruct;
end-method;


method BuildRawObject
   /+ &p_rec as Record +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &obj;
   Local Field &fld;
   Local integer &j;
   Local string &fldName;
   Local any &fldVal;

   &obj = CreateObject("C_JSON_API:Factory").NewObject();
   For &j = 1 To &p_rec.FieldCount
      &fld = &p_rec.GetField(&j);
      &fldName = &fld.Name;
      &fldVal = &fld.Value;
      If &fldName = "DESCRLONG" Or
            &fldName = "FFSTYLELONG" Then
         &obj.AddProperty(&fldName, &fldVal);
      Else
         If &fldName = "LASTUPDDTTM" Then
            If &fldVal = "" Then
               &obj.AddProperty(&fldName, "");
            Else
               &obj.AddProperty(&fldName, DateTimeToLocalizedString(&fldVal, &DateTimeFormat));
            End-If;
         Else
            &obj.AddProperty(&fldName, &fldVal);
         End-If;
      End-If;
   End-For;
   Return &obj;
end-method;


method HasPagePeopleCode
   /+ Returns Boolean +/
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &Prog;
   Local string &Code;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Panel, &_PageName);
   &Key.AddItem(Key:Class_Method, "Activate");

   If Not &mgrPeopleCodeProgram.DefnExists(&Key) Then
      Return False;
   End-If;
   &Prog = &mgrPeopleCodeProgram.GetDefn(&Key);
   &Code = &Prog.GetProgram();
   If Len(LTrim(RTrim(&Code))) > 0 Then
      Return True;
   End-If;
   Return False;
end-method;


method ViewPagePeopleCodeCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObj;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;

   &RespObj = CreateObject("C_JSON_API:Factory").NewObject();
   &RespObj.AddProperty("pageName", &_PageName);
   &RespObj.AddProperty("event", "Activate");

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Panel, &_PageName);
   &Key.AddItem(Key:Class_Method, "Activate");

   &RespObj.AddProperty("programExists", &mgrPeopleCodeProgram.DefnExists(&Key));
   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      Local %metadata:PeopleCodeProgram:PeopleCodeProgram &oPeopleCodeProgram;
      &oPeopleCodeProgram = &mgrPeopleCodeProgram.GetDefn(&Key);
      &RespObj.AddProperty("peoplecode", &oPeopleCodeProgram.GetProgram());
      &RespObj.AddProperty("lastUpdate", "Last updated by: " | &oPeopleCodeProgram.LastUpdOprId | ", " | DateTimeToLocalizedString(&oPeopleCodeProgram.LastUpdDttm, &DateTimeFormat));
   Else
      &RespObj.AddProperty("peoplecode", "");
      &RespObj.AddProperty("lastUpdate", "");


   End-If;

   Return &RespObj;
end-method;


method ModifyPagePeopleCodeCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   Local string &PeopleCode, &ErrorMsg;
   Local boolean &CompileResult;
   Local integer &Position1, &Position2;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &Prog = Null;

   If Not &p_obj.IsExist("peoplecode") Then
      &_ErrText = &_ErrText | "peoplecode is required, ";
      Return;
   End-If;
   &PeopleCode = &CommUtil.UnEscapeJSON(&p_obj.GetString("peoplecode"));
   Local string &NonBlankCode = &PeopleCode;
   &NonBlankCode = Substitute(&NonBlankCode, Char(9), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(10), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(11), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(12), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(13), "");
   If Len(LTrim(RTrim(&NonBlankCode))) = 0 Then
      throw CreateException(0, 0, "Empty PeopleCode is not deletion; use deletePeopleCode");
   End-If;

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Panel, &_PageName);
   &Key.AddItem(Key:Class_Method, "Activate");

   If &PeopleCode = "" And
         Not &mgrPeopleCodeProgram.DefnExists(&Key) Then
      Return;
   End-If;

   If &mgrPeopleCodeProgram.DefnExists(&Key) Then
      REM 更新现有代码;
      &Prog = &mgrPeopleCodeProgram.GetDefnToUpdate(&Key);
      &CompileResult = &Prog.UpdateProgram(&PeopleCode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &Prog.UpdateDefn() Then
            &_ErrText = &_ErrText | "Error saving PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;
   Else
      REM 创建新代码;
      &Prog = &mgrPeopleCodeProgram.CreateDefn();
      &Prog.ObjectID#0# = Key:Class_Panel;
      &Prog.ObjectValue#0# = &_PageName;
      &Prog.ObjectID#1# = Key:Class_Method;
      &Prog.ObjectValue#1# = "Activate";
      &CompileResult = &Prog.UpdateProgram(&PeopleCode, &ErrorMsg, &Position1, &Position2);
      If &CompileResult Then
         If Not &Prog.SaveNewDefn() Then
            &_ErrText = &_ErrText | "Error saving new PeopleCode.";
         End-If;
      Else
         &_ErrText = &_ErrText | MsgGetText(158, 20153, "PeopleCode Error") | " - " | &ErrorMsg | " " | &Position1 | " " | &Position2;
      End-If;
   End-If;
end-method;


method CreatePageCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   Local string &Descr, &DescrLong, &Sql;
   Local integer &PnlType;
   Local number &Cnt;
   Local datetime &Now;
   Local string &UserId;

   REM 已存在检查;
   &Cnt = 0;
   &Sql = "SELECT COUNT(*) FROM PSPNLDEFN WHERE PNLNAME = :1";
   SQLExec(&Sql, &_PageName, &Cnt);
   If &Cnt > 0 Then
      &_ErrText = &_ErrText | "page already exists: " | &_PageName;
      Return;
   End-If;

   &Descr = "";
   &DescrLong = "";
   &PnlType = 0;
   If &p_obj.IsExist("descr") Then
      &Descr = &p_obj.GetString("descr");
   End-If;
   If &p_obj.IsExist("comment") Then
      &DescrLong = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
   End-If;
   If &p_obj.IsExist("pnlType") Then
      &PnlType = &p_obj.GetNumber("pnlType");
   End-If;

   &Now = %Datetime;
   &UserId = %UserId;
   REM 用 Record 对象 Insert：规避 SQLExec 的 CLOB/逗号/绑定坑;
   Local Record &RecDefn;
   &RecDefn = CreateRecord(Record.PSPNLDEFN);
   &RecDefn.PNLNAME.Value = &_PageName;
   &RecDefn.GetField(Field.VERSION).Value = 1;
   &RecDefn.GetField(Field.PNLTYPE).Value = &PnlType;
   &RecDefn.GetField(Field.FIELDCOUNT).Value = 0;
   &RecDefn.GetField(Field.MAXPNLFLDID).Value = 0;
   &RecDefn.GetField(Field.GRIDHORZ).Value = 4;
   &RecDefn.GetField(Field.GRIDVERT).Value = 4;
   &RecDefn.GetField(Field.PANELTOP).Value = 0;
   &RecDefn.GetField(Field.PANELLEFT).Value = 0;
   &RecDefn.GetField(Field.PANELRIGHT).Value = 728;
   &RecDefn.GetField(Field.PANELBOTTOM).Value = 367;
   &RecDefn.GetField(Field.PNLUSE).Value = 0;
   &RecDefn.GetField(Field.DEFERPROC).Value = 1;
   &RecDefn.GetField(Field.DESCR).Value = &Descr;
   &RecDefn.GetField(Field.DESCRLONG).Value = &DescrLong;
   &RecDefn.GetField(Field.LASTUPDDTTM).Value = &Now;
   &RecDefn.GetField(Field.LASTUPDOPRID).Value = &UserId;
   If Not &RecDefn.Insert() Then
      &_ErrText = &_ErrText | "insert PSPNLDEFN failed: " | &_PageName;
      Return;
   End-If;
   %This.TouchVersion();
end-method;


method ModifyPagePropsCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   Local string &Sql;
   Local datetime &Now;
   Local string &UserId;

   &Now = %Datetime;
   &UserId = %UserId;
   If &p_obj.IsExist("descr") Then
      &Sql = "UPDATE PSPNLDEFN SET DESCR = :1 WHERE PNLNAME = :2";
      SQLExec(&Sql, &p_obj.GetString("descr"), &_PageName);
   End-If;
   If &p_obj.IsExist("comment") Then
      Local Record &RecDefn2;
      &RecDefn2 = CreateRecord(Record.PSPNLDEFN);
      &RecDefn2.PNLNAME.Value = &_PageName;
      If Not &RecDefn2.SelectByKey() Then
         throw CreateException(0, 0, "Page disappeared before comment update");
      End-If;
      &RecDefn2.DESCRLONG.Value = &CommUtil.UnEscapeJSON(&p_obj.GetString("comment"));
      &RecDefn2.Update();
   End-If;
   If &p_obj.IsExist("pnlType") Then
      &Sql = "UPDATE PSPNLDEFN SET PNLTYPE = :1 WHERE PNLNAME = :2";
      SQLExec(&Sql, &p_obj.GetNumber("pnlType"), &_PageName);
   End-If;
   If &p_obj.IsExist("deferProc") Then
      &Sql = "UPDATE PSPNLDEFN SET DEFERPROC = :1 WHERE PNLNAME = :2";
      SQLExec(&Sql, &p_obj.GetNumber("deferProc"), &_PageName);
   End-If;
   If &p_obj.IsExist("panelRight") Then
      &Sql = "UPDATE PSPNLDEFN SET PANELRIGHT = :1 WHERE PNLNAME = :2";
      SQLExec(&Sql, &p_obj.GetNumber("panelRight"), &_PageName);
   End-If;
   If &p_obj.IsExist("panelBottom") Then
      &Sql = "UPDATE PSPNLDEFN SET PANELBOTTOM = :1 WHERE PNLNAME = :2";
      SQLExec(&Sql, &p_obj.GetNumber("panelBottom"), &_PageName);
   End-If;
   %This.TouchVersion();
end-method;


method GetMaxPnlFldId
   /+ Returns Number +/
   Local number &MaxId;
   &MaxId = 0;
   SQLExec("SELECT MAXPNLFLDID FROM PSPNLDEFN WHERE PNLNAME = :1", &_PageName, &MaxId);
   Return &MaxId;
end-method;


method TouchVersion
   Local number &generation;
   SQLExec("UPDATE PSLOCK SET VERSION=VERSION+1 WHERE OBJECTTYPENAME='PDM'");
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PDM'", &generation);
   SQLExec("UPDATE PSPNLDEFN SET VERSION=:1,LASTUPDDTTM=:2,LASTUPDOPRID=:3 WHERE PNLNAME=:4", &generation, %Datetime, %UserId, &_PageName);
   SQLExec("UPDATE PSVERSION SET VERSION=:1 WHERE OBJECTTYPENAME='PDM'", &generation);
end-method;


method AddControlCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &Resp;
   Local string &CtlType, &RecName, &FieldName, &LabelText, &LabelId, &Sql;
   Local integer &FieldType, &Left, &Top, &Right, &Bottom, &LblType, &LblLoc, &OccursLevel;
   Local number &UseBits, &FieldNum, &NewId;
   Local string &UseDefaultLabel, &OnValue, &OffValue;

   &Resp = CreateObject("C_JSON_API:Factory").NewObject();
   &CtlType = &p_obj.GetString("controlType");
   If &CtlType <> "editBox" And
         &CtlType <> "dropDown" Then
      &_ErrText = "addControl supports validated Classic Edit Box and Drop-Down only";
      Return &Resp;
   End-If;
   If &p_obj.IsExist("occursLevel") Then
      If &p_obj.GetNumber("occursLevel") <> 0 Then
         &_ErrText = "Only validated level 0 creation is supported";
         Return &Resp;
      End-If;
   End-If;
   &RecName = "";
   &FieldName = "";
   &LabelText = "";
   &LabelId = "";
   &UseDefaultLabel = "1";
   &OnValue = "";
   &OffValue = "";
   &Left = 0;
   &Top = 0;
   &Right = 0;
   &Bottom = 0;
   &LblType = 3;
   &LblLoc = 1;
   &OccursLevel = 0;
   &UseBits = 0;
   &FieldNum = - 1;

   Evaluate &CtlType
   When "editBox"
      &FieldType = 4;
   When "longEditBox"
      &FieldType = 6;
   When "dropDown"
      &FieldType = 5;
   When "checkBox"
      &FieldType = 7;
      &LblType = 2;
   When "staticText"
      &FieldType = 0;
      &LblType = 1;
   When "groupBox"
      &FieldType = 2;
      &LblType = 1;
      &UseBits = 67108864;
   When "hrule"
      &FieldType = 23;
      &LblType = 0;
      &UseBits = 2;
   When "subPage"
      &FieldType = 11;
      &LblType = 1;
   When "scrollArea"
      &FieldType = 27;
      &UseBits = 0;
   When "htmlArea"
      &FieldType = 25;
      &LblType = 1;
   When "pushButton"
      &FieldType = 12;
      &LblType = 3;
   When "hyperlink"
      &FieldType = 13;
      &LblType = 3;
   When-Other
      &_ErrText = &_ErrText | "unsupported controlType (batch A/B): " | &CtlType;
      Return &Resp;
   End-Evaluate;

   If &p_obj.IsExist("recName") Then
      &RecName = &p_obj.GetString("recName");
   End-If;
   If &p_obj.IsExist("fieldName") Then
      &FieldName = &p_obj.GetString("fieldName");
   End-If;
   If &p_obj.IsExist("labelText") Then
      &LabelText = &p_obj.GetString("labelText");
   End-If;
   If &p_obj.IsExist("labelId") Then
      &LabelId = &p_obj.GetString("labelId");
   End-If;
   If &p_obj.IsExist("left") Then
      &Left = &p_obj.GetNumber("left");
   End-If;
   If &p_obj.IsExist("top") Then
      &Top = &p_obj.GetNumber("top");
   End-If;
   If &p_obj.IsExist("right") Then
      &Right = &p_obj.GetNumber("right");
   End-If;
   If &p_obj.IsExist("bottom") Then
      &Bottom = &p_obj.GetNumber("bottom");
   End-If;
   If &p_obj.IsExist("occursLevel") Then
      &OccursLevel = &p_obj.GetNumber("occursLevel");
   End-If;
   Local string &SubPnlName, &HtmlText;
   Local number &PbDisplayType;
   &SubPnlName = "";
   &HtmlText = "";
   &PbDisplayType = 0;
   If &p_obj.IsExist("subPnlName") Then
      &SubPnlName = &p_obj.GetString("subPnlName");
   End-If;
   If &p_obj.IsExist("htmlText") Then
      &HtmlText = &CommUtil.UnEscapeJSON(&p_obj.GetString("htmlText"));
   End-If;
   If &p_obj.IsExist("pbDisplayType") Then
      &PbDisplayType = &p_obj.GetNumber("pbDisplayType");
   End-If;
   If &p_obj.IsExist("invisible") Then
      If &p_obj.GetNumber("invisible") = 1 Then
         &UseBits = &UseBits + 2;
      End-If;
   End-If;
   If &p_obj.IsExist("displayOnly") Then
      If &p_obj.GetNumber("displayOnly") = 1 Then
         &UseBits = &UseBits + 1;
      End-If;
   End-If;

   REM 绑定类控件校验 record.field 存在；页面 FIELDNUM 是全页控件顺序，不是记录字段序号;
   If &FieldType = 4 Or
         &FieldType = 6 Or
         &FieldType = 5 Or
         &FieldType = 7 Or
         &FieldType = 2 Or
         &FieldType = 12 Or
         &FieldType = 13 Then
      If &RecName = "" Or
            &FieldName = "" Then
         &_ErrText = &_ErrText | "controlType " | &CtlType | " requires recName + fieldName";
         Return &Resp;
      End-If;
      &Sql = "SELECT FIELDNUM FROM PSRECFIELD WHERE RECNAME = :1 AND FIELDNAME = :2";
      SQLExec(&Sql, &RecName, &FieldName, &FieldNum);
      If &FieldNum = - 1 Then
         &_ErrText = &_ErrText | "record field not found: " | &RecName | "." | &FieldName;
         Return &Resp;
      End-If;
   End-If;

   REM 标签: labelId 优先(RFT), 其次 labelText(字面量), 再退字段默认标签;
   If &LabelId <> "" Then
      &UseDefaultLabel = "1";
      If &CtlType <> "checkBox" Then
         &LblType = 3;
      End-If;
   Else
      If &LabelText <> "" Then
         &UseDefaultLabel = "0";
         If &CtlType <> "checkBox" Then
            &LblType = 1;
         End-If;
      Else
         If &FieldType = 4 Or
               &FieldType = 5 Then
            REM AD 02/21/38 and R native re-save: use the actual base default label;
            Local number &defaultLabelCount = 0;
            SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &FieldName, &defaultLabelCount);
            If &defaultLabelCount <> 1 Then
               &_ErrText = "Unable to resolve one base default label for " | &FieldName | "; supply an explicit label";
               Return &Resp;
            End-If;
            SQLExec("SELECT LABEL_ID,LONGNAME FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &FieldName, &LabelId, &LabelText);
         Else
            If &FieldType <> 0 And
                  &FieldType <> 23 Then
               &LabelId = &FieldName;
            End-If;
         End-If;
      End-If;
   End-If;

   REM checkBox ON/OFF 值;
   If &FieldType = 7 Then
      If &p_obj.IsExist("onValue") Then
         &OnValue = &p_obj.GetString("onValue");
      Else
         &OnValue = "Y";
      End-If;
      If &p_obj.IsExist("offValue") Then
         &OffValue = &p_obj.GetString("offValue");
      Else
         &OffValue = "N";
      End-If;
   End-If;

   &NewId = %This.GetMaxPnlFldId() + 1;
   SQLExec("SELECT COALESCE(MAX(FIELDNUM),0)+1 FROM PSPNLFIELD WHERE PNLNAME=:1", &_PageName, &FieldNum);

   REM 按类型用 Record.Insert 写入（规避 SQLExec 绑定/空值坑）;
   Local Record &FldRec;
   &FldRec = CreateRecord(Record.PSPNLFIELD);
   &FldRec.PNLNAME.Value = &_PageName;
   &FldRec.PNLFLDID.Value = &NewId;
   &FldRec.GetField(Field.FIELDTYPE).Value = &FieldType;
   &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
   &FldRec.GetField(Field.FIELDLEFT).Value = &Left;
   &FldRec.GetField(Field.FIELDTOP).Value = &Top;
   &FldRec.GetField(Field.FIELDRIGHT).Value = &Right;
   &FldRec.GetField(Field.FIELDBOTTOM).Value = &Bottom;
   &FldRec.GetField(Field.LBLLOC).Value = &LblLoc;
   &FldRec.GetField(Field.LBLTEXT).Value = &LabelText;
   &FldRec.GetField(Field.USEDEFAULTLABEL).Value = &UseDefaultLabel;
   &FldRec.GetField(Field.LABEL_ID).Value = &LabelId;
   &FldRec.GetField(Field.FIELDUSE).Value = &UseBits;
   If %This.FlagBit(&UseBits, 2) = 1 Then
      &FldRec.GetField(Field.SECUREINVISIBLE).Value = "1";
   End-If;
   &FldRec.GetField(Field.DEFERPROC).Value = 1;
   &FldRec.GetField(Field.OCCURSLEVEL).Value = &OccursLevel;
   &FldRec.GetField(Field.OCCURSCOUNT1).Value = 1;
   &FldRec.GetField(Field.OCCURSOFFSET1).Value = 20;
   &FldRec.GetField(Field.OCCURSCOUNT2).Value = 1;
   &FldRec.GetField(Field.OCCURSOFFSET2).Value = 20;
   &FldRec.GetField(Field.OCCURSCOUNT3).Value = 1;
   &FldRec.GetField(Field.OCCURSOFFSET3).Value = 20;
   If &FieldType = 4 Or
         &FieldType = 6 Or
         &FieldType = 5 Then
      &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 2097160;
      If &FieldType = 5 Then
         &FldRec.GetField(Field.DSPLFORMAT).Value = 2228224;
      End-If;
      &FldRec.GetField(Field.LBLTYPE).Value = &LblType;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.FIELDNAME).Value = &FieldName;
      &FldRec.GetField(Field.EDITLBLLEFT).Value = &Left - 72;
      &FldRec.GetField(Field.EDITLBLTOP).Value = &Top;
      &FldRec.GetField(Field.EDITLBLRIGHT).Value = &Left - 6;
      &FldRec.GetField(Field.EDITLBLBOTTOM).Value = &Top + 12;
   End-If;
   If &FieldType = 7 Then
      &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 524288;
      &FldRec.GetField(Field.LBLTYPE).Value = &LblType;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.FIELDNAME).Value = &FieldName;
      &FldRec.GetField(Field.ONVALUE).Value = &OnValue;
      &FldRec.GetField(Field.OFFVALUE).Value = &OffValue;
   End-If;
   If &FieldType = 0 Then
      &FldRec.GetField(Field.DSPLFORMAT).Value = 1;
      &FldRec.GetField(Field.LBLTYPE).Value = 1;
   End-If;
   If &FieldType = 2 Then
      &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 524289;
      &FldRec.GetField(Field.LBLTYPE).Value = 1;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.FIELDNAME).Value = &FieldName;
   End-If;
   If &FieldType = 23 Then
      &FldRec.GetField(Field.FIELDRIGHT).Value = &Left + 16;
      &FldRec.GetField(Field.FIELDBOTTOM).Value = &Top + 2;
      &FldRec.GetField(Field.USEDEFAULTLABEL).Value = "1";
      &FldRec.GetField(Field.SECUREINVISIBLE).Value = "1";
   End-If;
   If &FieldType = 11 Then
      REM subPage: SUBPNLNAME 必填，RECNAME 可选（语料实证）;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 1;
      &FldRec.GetField(Field.LBLTYPE).Value = 1;
      &FldRec.GetField(Field.SUBPNLNAME).Value = &SubPnlName;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
   End-If;
   If &FieldType = 27 Then
      REM scrollArea 也占用页面控件顺序，必须位于其子字段之前;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 524288;
      &FldRec.GetField(Field.LBLTYPE).Value = &LblType;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.PTADJHIDDENFIELDS).Value = "1";
   End-If;
   If &FieldType = 25 Then
      REM htmlArea: 语料 CAF_CONFIG_TBL_GEN #42;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 532481;
      &FldRec.GetField(Field.LBLTYPE).Value = 1;
      &FldRec.GetField(Field.USEDEFAULTLABEL).Value = "1";
   End-If;
   If &FieldType = 12 Then
      REM pushButton: 语料 JPM_JP_GROUPS #48/#49;
      &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 540672;
      &FldRec.GetField(Field.LBLTYPE).Value = &LblType;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.FIELDNAME).Value = &FieldName;
   End-If;
   If &FieldType = 13 Then
      REM hyperlink: 语料 JPM_JP_GROUPS #19/#26;
      &FldRec.GetField(Field.FIELDNUM).Value = &FieldNum;
      &FldRec.GetField(Field.DSPLFORMAT).Value = 540672;
      &FldRec.GetField(Field.LBLTYPE).Value = &LblType;
      &FldRec.GetField(Field.RECNAME).Value = &RecName;
      &FldRec.GetField(Field.FIELDNAME).Value = &FieldName;
      &FldRec.GetField(Field.PBDISPLAYTYPE).Value = &PbDisplayType;
   End-If;
   REM 批次B 专属校验 + 辅助表;
   If &FieldType = 11 Then
      If &SubPnlName = "" Then
         &_ErrText = &_ErrText | "subPage requires subPnlName";
         Return &Resp;
      End-If;
      Local number &SubCnt;
      &SubCnt = 0;
      &Sql = "SELECT COUNT(*) FROM PSPNLDEFN WHERE PNLNAME = :1";
      SQLExec(&Sql, &SubPnlName, &SubCnt);
      If &SubCnt = 0 Then
         &_ErrText = &_ErrText | "subpage definition not found: " | &SubPnlName;
         Return &Resp;
      End-If;
   End-If;
   If &FieldType = 27 Then
      If &RecName = "" Then
         &_ErrText = &_ErrText | "scrollArea requires recName (scroll record)";
         Return &Resp;
      End-If;
      Local number &RecCnt;
      &RecCnt = 0;
      &Sql = "SELECT COUNT(*) FROM PSRECDEFN WHERE RECNAME = :1";
      SQLExec(&Sql, &RecName, &RecCnt);
      If &RecCnt = 0 Then
         &_ErrText = &_ErrText | "scroll record not found: " | &RecName;
         Return &Resp;
      End-If;
   End-If;
   If &FieldType = 25 And
         &HtmlText = "" Then
      &_ErrText = &_ErrText | "htmlArea requires htmlText";
      Return &Resp;
   End-If;
   REM AD snapshots 02/21 store explicit zero character flags and automatic label bounds;
   If &FieldType = 4 Or
         &FieldType = 5 Then
      &FldRec.GetField(Field.GRDALLOWCOLSORT).Value = "0";
      &FldRec.GetField(Field.PTADJHIDDENFIELDS).Value = "0";
      &FldRec.GetField(Field.PTCOLLAPSEDATAAREA).Value = "0";
      &FldRec.GetField(Field.PTDFLTVIEWEXPANDED).Value = "0";
      &FldRec.GetField(Field.PTHIDEFIELDS).Value = "0";
      &FldRec.GetField(Field.SHOWCOLHIDEROWS).Value = "0";
      &FldRec.GetField(Field.PTLEBEXPANDFIELD).Value = "0";
      &FldRec.GetField(Field.SHOWTABCNTLBTN).Value = "0";
      &FldRec.GetField(Field.SECUREINVISIBLE).Value = "0";
      &FldRec.GetField(Field.ENABLEASANCHOR).Value = "0";
      &FldRec.GetField(Field.URLENCODEDBYAPP).Value = "0";
      If %This.FlagBit(&UseBits, 2) = 1 Then
         &FldRec.GetField(Field.SECUREINVISIBLE).Value = "1";
      End-If;
      &FldRec.GetField(Field.EDITLBLLEFT).Value = 0;
      &FldRec.GetField(Field.EDITLBLTOP).Value = 0;
      &FldRec.GetField(Field.EDITLBLRIGHT).Value = 0;
      &FldRec.GetField(Field.EDITLBLBOTTOM).Value = 0;
   End-If;
   If Not &FldRec.Insert() Then
      &_ErrText = &_ErrText | "insert PSPNLFIELD failed: " | &CtlType | " pnlFldId=" | &NewId;
      Return &Resp;
   End-If;

   &Sql = "UPDATE PSPNLDEFN SET FIELDCOUNT = FIELDCOUNT + 1, MAXPNLFLDID = :1 WHERE PNLNAME = :2";
   SQLExec(&Sql, &NewId, &_PageName);
   REM 批次B 辅助表;
   If &FieldType = 27 Then
      Local Record &CtlRec;
      &CtlRec = CreateRecord(Record.PSPNLCNTRLDATA);
      &CtlRec.PNLNAME.Value = &_PageName;
      &CtlRec.PNLFLDID.Value = &NewId;
      &CtlRec.GetField(Field.GRIDROWS).Value = 1;
      &CtlRec.GetField(Field.PTGRDLAYOUT).Value = 1;
      &CtlRec.GetField(Field.PTGRDSCROLLBAR).Value = 2;
      &CtlRec.Insert();
   End-If;
   If &FieldType = 25 Then
      Local Record &HtmlRec;
      &HtmlRec = CreateRecord(Record.PSPNLHTMLAREA);
      &HtmlRec.PNLNAME.Value = &_PageName;
      &HtmlRec.PNLFLDID.Value = &NewId;
      &HtmlRec.GetField(Field.HTMLAREA).Value = &HtmlText;
      &HtmlRec.Insert();
   End-If;
   If &FieldType = 4 Or
         &FieldType = 5 Then
      %This.EnsureBasicExt(&NewId);
   End-If;
   %This.TouchVersion();

   &Resp.AddProperty("pnlFldId", &NewId);
   &Resp.AddProperty("fieldType", &FieldType);
   &Resp.AddProperty("controlType", &CtlType);
   Return &Resp;
end-method;


method DeleteControlCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &Resp;
   Local string &Sql;
   Local number &PnlFldId, &Cnt;

   &Resp = CreateObject("C_JSON_API:Factory").NewObject();
   &Cnt = 0;
   &PnlFldId = &p_obj.GetNumber("pnlFldId");
   &Sql = "SELECT COUNT(*) FROM PSPNLFIELD WHERE PNLNAME = :1 AND PNLFLDID = :2";
   SQLExec(&Sql, &_PageName, &PnlFldId, &Cnt);
   If &Cnt = 0 Then
      &_ErrText = &_ErrText | "control not found: pnlFldId=" | &PnlFldId;
      Return &Resp;
   End-If;
   Local number &deleteType;
   SQLExec("SELECT FIELDTYPE FROM PSPNLFIELD WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &PnlFldId, &deleteType);
   If &deleteType <> 4 And
         &deleteType <> 5 Then
      &_ErrText = "deleteControl supports Edit Box/Drop-Down only";
      Return &Resp;
   End-If;
   SQLExec("DELETE FROM PSPNLFIELDLANG WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &PnlFldId);
   &Sql = "DELETE FROM PSPNLFIELD WHERE PNLNAME = :1 AND PNLFLDID = :2";
   SQLExec(&Sql, &_PageName, &PnlFldId);
   REM ext 行清理（ext 谜团未影响本 DELETE，尽力而为）;
   &Sql = "DELETE FROM PSPNLFIELDEXT WHERE PNLNAME = :1 AND PNLFLDID = :2";
   SQLExec(&Sql, &_PageName, &PnlFldId);
   &Sql = "DELETE FROM PSPNLHTMLAREA WHERE PNLNAME = :1 AND PNLFLDID = :2";
   SQLExec(&Sql, &_PageName, &PnlFldId);
   &Sql = "DELETE FROM PSPNLCNTRLDATA WHERE PNLNAME = :1 AND PNLFLDID = :2";
   SQLExec(&Sql, &_PageName, &PnlFldId);
   &Sql = "UPDATE PSPNLDEFN SET FIELDCOUNT = FIELDCOUNT - 1 WHERE PNLNAME = :1";
   SQLExec(&Sql, &_PageName);
   %This.TouchVersion();
   &Resp.AddProperty("deletedPnlFldId", &PnlFldId);
   Return &Resp;
end-method;


method FindControlsCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &Resp, &Item;
   Local C_JSON_API:JSONArray &Arr;
   Local Rowset &Rs;
   Local Record &Rec;
   Local string &RecName, &FieldName, &LabelContains, &Sql;
   Local integer &FieldType, &i, &MatchCnt;
   Local boolean &Ok;

   &Resp = CreateObject("C_JSON_API:Factory").NewObject();
   &Arr = CreateObject("C_JSON_API:Factory").NewArray();
   &RecName = "";
   &FieldName = "";
   &LabelContains = "";
   &FieldType = - 1;
   If &p_obj.IsExist("recName") Then
      &RecName = &p_obj.GetString("recName");
   End-If;
   If &p_obj.IsExist("fieldName") Then
      &FieldName = &p_obj.GetString("fieldName");
   End-If;
   If &p_obj.IsExist("labelContains") Then
      &LabelContains = Upper(&p_obj.GetString("labelContains"));
   End-If;
   If &p_obj.IsExist("fieldType") Then
      &FieldType = &p_obj.GetNumber("fieldType");
   End-If;

   &Rs = CreateRowset(Record.PSPNLFIELD);
   &Rs.Flush();
   &Rs.Fill(" WHERE PNLNAME = :1", &_PageName);
   &Rs.Sort(PSPNLFIELD.PNLFLDID, "A");
   &MatchCnt = 0;
   For &i = 1 To &Rs.ActiveRowCount
      &Rec = &Rs(&i).GetRecord(1);
      &Ok = True;
      If &RecName <> "" And
            Upper(&Rec.RECNAME.Value) <> Upper(&RecName) Then
         &Ok = False;
      End-If;
      If &Ok And
            &FieldName <> "" And
            Upper(&Rec.FIELDNAME.Value) <> Upper(&FieldName) Then
         &Ok = False;
      End-If;
      If &Ok And
            &FieldType <> - 1 And
            &Rec.FIELDTYPE.Value <> &FieldType Then
         &Ok = False;
      End-If;
      If &Ok And
            &LabelContains <> "" Then
         If Find(&LabelContains, Upper(&Rec.LBLTEXT.Value)) = 0 And
               Find(&LabelContains, Upper(&Rec.LABEL_ID.Value)) = 0 Then
            &Ok = False;
         End-If;
      End-If;
      If &Ok Then
         &Item = CreateObject("C_JSON_API:Factory").NewObject();
         &Item.AddProperty("pnlFldId", &Rec.PNLFLDID.Value);
         &Item.AddProperty("fieldType", &Rec.FIELDTYPE.Value);
         &Item.AddProperty("recName", &Rec.RECNAME.Value);
         &Item.AddProperty("fieldName", &Rec.FIELDNAME.Value);
         &Item.AddProperty("labelText", &Rec.LBLTEXT.Value);
         &Item.AddProperty("labelId", &Rec.LABEL_ID.Value);
         &Item.AddProperty("left", &Rec.FIELDLEFT.Value);
         &Item.AddProperty("top", &Rec.FIELDTOP.Value);
         &Arr.AddJsonObjectElement("", &Item);
         &Item = &Arr.GetJsonObject(&Arr.Size);
         &MatchCnt = &MatchCnt + 1;
      End-If;
   End-For;
   &Resp.AddProperty("pageName", &_PageName);
   &Resp.AddProperty("matchCount", &MatchCnt);
   &Resp.AddJsonArray("items", &Arr);
   &Arr = &Resp.GetJsonArray("items");
   Return &Resp;
end-method;


method ModifyControlCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &Resp, &Item;
   Local string &Sql;
   Local Rowset &Rs;
   Local Record &Rec;
   Local number &PnlFldId, &UseBits;
   Local integer &i;
   Local boolean &Found;

   &Resp = CreateObject("C_JSON_API:Factory").NewObject();
   &PnlFldId = &p_obj.GetNumber("pnlFldId");

   &Rs = CreateRowset(Record.PSPNLFIELD);
   &Rs.Flush();
   &i = &Rs.Fill(" WHERE PNLNAME = :1 AND PNLFLDID = :2", &_PageName, &PnlFldId);
   If &i = 0 Then
      &_ErrText = &_ErrText | "control not found: pnlFldId=" | &PnlFldId;
      Return &Resp;
   End-If;
   &Rec = &Rs(1).GetRecord(1);
   If &Rec.FIELDTYPE.Value <> 4 And
         &Rec.FIELDTYPE.Value <> 5 Then
      &_ErrText = "Control writes currently support validated Classic Edit Box and Drop-Down only";
      Return &Resp;
   End-If;
   If Not %This.ValidateBatchProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   If Not %This.ValidateBasicProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   If Not %This.ValidateEditProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   If Not %This.ValidateLabelProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   If Not %This.ValidateDropDownProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   If Not %This.ValidateLayoutProps(&p_obj, &Rec) Then
      Return &Resp;
   End-If;
   %This.ApplyLayoutProps(&p_obj, &Rec);
   &UseBits = &Rec.FIELDUSE.Value;

   If &p_obj.IsExist("left") Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDLEFT = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("left"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("top") Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDTOP = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("top"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("right") Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDRIGHT = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("right"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("bottom") Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDBOTTOM = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("bottom"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("editSize") Then
      &Sql = "UPDATE PSPNLFIELD SET EDITSIZE = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("editSize"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("occursLevel") Then
      &Sql = "UPDATE PSPNLFIELD SET OCCURSLEVEL = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("occursLevel"), &_PageName, &PnlFldId);
   End-If;
   If &Rec.FIELDTYPE.Value <> 4 And
         &Rec.FIELDTYPE.Value <> 5 And
         &p_obj.IsExist("labelText") Then
      &Sql = "UPDATE PSPNLFIELD SET LBLTEXT = :1, USEDEFAULTLABEL = '0' WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetString("labelText"), &_PageName, &PnlFldId);
   End-If;
   If &Rec.FIELDTYPE.Value <> 4 And
         &Rec.FIELDTYPE.Value <> 5 And
         &p_obj.IsExist("labelId") Then
      &Sql = "UPDATE PSPNLFIELD SET LABEL_ID = :1, USEDEFAULTLABEL = '1' WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetString("labelId"), &_PageName, &PnlFldId);
   End-If;
   If &Rec.FIELDTYPE.Value <> 4 And
         &Rec.FIELDTYPE.Value <> 5 And
         &p_obj.IsExist("labelType") Then
      &Sql = "UPDATE PSPNLFIELD SET LBLTYPE = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("labelType"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("labelLoc") Then
      &Sql = "UPDATE PSPNLFIELD SET LBLLOC = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("labelLoc"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("fieldStyle") Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDSTYLE = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetString("fieldStyle"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("labelStyle") Then
      &Sql = "UPDATE PSPNLFIELD SET LABELSTYLE = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetString("labelStyle"), &_PageName, &PnlFldId);
   End-If;
   If &p_obj.IsExist("deferProc") Then
      &Sql = "UPDATE PSPNLFIELD SET DEFERPROC = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &p_obj.GetNumber("deferProc"), &_PageName, &PnlFldId);
   End-If;
   REM AD evidence: Display Only=1, Invisible=2 - Required is rejected before writes;
   If &p_obj.IsExist("invisible") Then
      &UseBits = %This.FlagValue(&UseBits, 2, &p_obj.GetNumber("invisible"));
      If %This.FlagBit(&Rec.FIELDUSE.Value, 2) = 0 And
            &p_obj.GetNumber("invisible") = 1 Then
         SQLExec("UPDATE PSPNLFIELD SET SECUREINVISIBLE = '1' WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &PnlFldId);
      End-If;
   End-If;
   If &Rec.FIELDTYPE.Value = 5 And
         &p_obj.IsExist("invisible") Then
      If &p_obj.GetNumber("invisible") = 0 Then
         SQLExec("UPDATE PSPNLFIELD SET SECUREINVISIBLE='0' WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &PnlFldId);
      End-If;
   End-If;
   If &p_obj.IsExist("displayOnly") Then
      &UseBits = %This.FlagValue(&UseBits, 1, &p_obj.GetNumber("displayOnly"));
   End-If;
   If &UseBits <> &Rec.FIELDUSE.Value Then
      &Sql = "UPDATE PSPNLFIELD SET FIELDUSE = :1 WHERE PNLNAME = :2 AND PNLFLDID = :3";
      SQLExec(&Sql, &UseBits, &_PageName, &PnlFldId);
   End-If;
   REM Re-read after the legacy column updates, then apply the explicitly validated extras;
   If Not &Rec.SelectByKey() Then
      throw CreateException(0, 0, "Control disappeared before applying properties");
   End-If;
   %This.ApplyBasicProps(&p_obj, &Rec);
   If Not &Rec.SelectByKey() Then
      throw CreateException(0, 0, "Control disappeared before Edit properties");
   End-If;
   %This.ApplyEditProps(&p_obj, &Rec);
   If Not &Rec.SelectByKey() Then
      throw CreateException(0, 0, "Control disappeared before Label properties");
   End-If;
   %This.ApplyDropDownProps(&p_obj, &Rec);
   If Not &Rec.SelectByKey() Then
      throw CreateException(0, 0, "Control disappeared before Label properties after Drop-Down properties");
   End-If;
   %This.ApplyLabelProps(&p_obj, &Rec);
   If Not &Rec.SelectByKey() Then
      throw CreateException(0, 0, "Control disappeared before batch properties");
   End-If;
   %This.ApplyBatchProps(&p_obj, &Rec);
   %This.TouchVersion();

   REM 读回;
   &Rs.Flush();
   &Rs.Fill(" WHERE PNLNAME = :1 AND PNLFLDID = :2", &_PageName, &PnlFldId);
   &Found = False;
   If &Rs.ActiveRowCount > 0 Then
      &Rec = &Rs(1).GetRecord(1);
      &Found = True;
   End-If;
   &Resp.AddProperty("pnlFldId", &PnlFldId);
   &Resp.AddProperty("found", &Found);
   If &Found Then
      &Item = CreateObject("C_JSON_API:Factory").NewObject();
      &Item.AddProperty("fieldType", &Rec.FIELDTYPE.Value);
      &Item.AddProperty("recName", &Rec.RECNAME.Value);
      &Item.AddProperty("fieldName", &Rec.FIELDNAME.Value);
      &Item.AddProperty("labelText", &Rec.LBLTEXT.Value);
      &Item.AddProperty("labelId", &Rec.LABEL_ID.Value);
      &Item.AddProperty("left", &Rec.FIELDLEFT.Value);
      &Item.AddProperty("top", &Rec.FIELDTOP.Value);
      &Item.AddProperty("right", &Rec.FIELDRIGHT.Value);
      &Item.AddProperty("bottom", &Rec.FIELDBOTTOM.Value);
      &Item.AddProperty("fieldUse", &Rec.FIELDUSE.Value);
      &Item.AddProperty("occursLevel", &Rec.OCCURSLEVEL.Value);
      &Resp.AddJsonObject("control", &Item);
      &Item = &Resp.GetJsonObject("control");
   End-If;
   Return &Resp;
end-method;


method GetControlExt
   /+ &p_id as Number +/
   /+ Returns C_JSON_API:JSONObject +/
   Local Record &Ext;
   Local C_JSON_API:JSONObject &Result;
   &Result = CreateObject("C_JSON_API:Factory").NewObject();
   &Ext = CreateRecord(Record.PSPNLFIELDEXT);
   &Ext.GetField(Field.PNLNAME).Value = &_PageName;
   &Ext.GetField(Field.PNLFLDID).Value = &p_id;
   If &Ext.SelectByKey() Then
      &Result = %This.BuildRawObject(&Ext);
   End-If;
   Return &Result;
end-method;


method DeletePagePeopleCodeCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObj;
   Local %metadata:Key &Key;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgrPeopleCodeProgram;

   &RespObj = CreateObject("C_JSON_API:Factory").NewObject();
   &RespObj.AddProperty("pageName", &_PageName);
   &RespObj.AddProperty("event", "Activate");

   &mgrPeopleCodeProgram = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   &Key = create %metadata:Key(Key:Class_Panel, &_PageName);
   &Key.AddItem(Key:Class_Method, "Activate");

   Local C_META_DATA_PKG:Utility:PeopleCodeDeletion &deleter = create C_META_DATA_PKG:Utility:PeopleCodeDeletion();
   Return &deleter.Run(&Key, 44, CreateArray(&_PageName, "Activate", " ", " "), &p_obj);
end-method;



method FlagValue
   /+ &bits as Number, +/
   /+ &mask as Number, +/
   /+ &enabled as Number +/
   /+ Returns Number +/
   Local number &present = %This.FlagBit(&bits, &mask);
   If &enabled = 1 And
         &present = 0 Then
      Return &bits + &mask;
   End-If;
   If &enabled = 0 And
         &present = 1 Then
      Return &bits - &mask;
   End-If;
   Return &bits;
end-method;

method ValidateControlRequest
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &operation as String +/
   /+ Returns Boolean +/
   Local array of string &allowed, &binary, &extra;
   Local string &name;
   Local integer &i;
   Local number &n;
   Local boolean &adding = False;
   If &operation = "addControl" Then
      &adding = True;
   End-If;
   &allowed = CreateArray("pageName", "operationType", "expectedVersion", "left", "top", "right", "bottom", "occursLevel", "labelText", "labelId", "invisible", "displayOnly");
   If &adding Then
      &extra = CreateArray("controlType", "recName", "fieldName");
   Else
      &extra = CreateArray("pnlFldId", "labelType", "labelLoc", "fieldStyle", "labelStyle", "deferProc", "displayControl", "multiCurrency", "setComponentChanged", "displayOnlyAppearance", "readOnlyScreenReader", "pageFieldName", "enableAsAnchor", "alignment", "fillCharacter", "password", "inputOnly", "showPromptButton", "autoFill", "spellCheck", "noColon", "firstOccursOnly", "labelAlignment", "useDefaultLabel", "displayedText", "promptField", "labelPosition", "labelLeft", "labelTop", "labelRight", "labelBottom", "moveX", "moveY", "sizeType", "showLabel", "enableWhenPageDisplayOnly", "wrapLongWords", "modifiableByJavaScript", "generateHtml", "popupMenu", "autoDecimal", "currencySymbol", "thousandsSeparator", "displayZero", "showCentury", "showTimeZone");
   End-If;
   For &i = 1 To &extra.Len
      &allowed.Push(&extra [&i]);
   End-For;
   &binary = CreateArray("invisible", "displayOnly", "deferProc", "displayControl", "multiCurrency", "setComponentChanged", "readOnlyScreenReader", "enableAsAnchor", "password", "inputOnly", "showPromptButton", "autoFill", "spellCheck", "noColon", "firstOccursOnly", "useDefaultLabel", "showLabel", "enableWhenPageDisplayOnly", "wrapLongWords", "modifiableByJavaScript", "generateHtml", "autoDecimal", "currencySymbol", "thousandsSeparator", "displayZero", "showCentury", "showTimeZone");
   For &i = 1 To &req.ChildCount
      &name = &req.GetPropertyNameAt(&i);
      If &name = "required" Then
         &_ErrText = "required is not a Page FIELDUSE property; bit 1 means Display Only. Change the Record field constraint separately.";
         Return False;
      End-If;
      If &allowed.Find(&name) = 0 Then
         &_ErrText = "Unsupported control property: " | &name;
         Return False;
      End-If;
      If &binary.Find(&name) > 0 Then
         try
            &n = &req.GetNumber(&name);
         catch Exception &e
            &_ErrText = &name | " requires numeric 0 or 1";
            Return False;
         end-try;
         If &n <> 0 And
               &n <> 1 Then
            &_ErrText = &name | " requires numeric 0 or 1";
            Return False;
         End-If;
      End-If;
   End-For;
   If Not &adding And
         &req.ChildCount <= 4 Then
      &_ErrText = "modifyControl requires at least one property";
      Return False;
   End-If;
   Return True;
end-method;

method ValidateBasicProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local array of string &extra = CreateArray("displayControl", "multiCurrency", "setComponentChanged", "displayOnlyAppearance", "readOnlyScreenReader", "pageFieldName", "enableAsAnchor");
   Local integer &i;
   Local string &name = &rec.PNLFIELDNAME.Value;
   Local number &count = 0;
   For &i = 1 To &extra.Len
      If &req.IsExist(&extra [&i]) And
            &rec.FIELDTYPE.Value <> 4 And
            &rec.FIELDTYPE.Value <> 5 Then
         &_ErrText = &extra [&i] | " currently supports Edit Box and Drop-Down List Box only";
         Return False;
      End-If;
   End-For;
   If &req.IsExist("displayOnlyAppearance") Then
      If &req.GetString("displayOnlyAppearance") <> "textOnly" And
            &req.GetString("displayOnlyAppearance") <> "disabled" Then
         &_ErrText = "displayOnlyAppearance requires textOnly or disabled";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("occursLevel") Then
      If &req.GetNumber("occursLevel") <> &rec.OCCURSLEVEL.Value Then
         &_ErrText = "Changing occursLevel is not supported by current evidence";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("pageFieldName") Then
      &name = &req.GetString("pageFieldName");
      If Len(&name) > 18 Then
         &_ErrText = "pageFieldName maximum length is 18";
         Return False;
      End-If;
      If &name <> "" Then
         SQLExec("SELECT COUNT(*) FROM PSPNLFIELD WHERE PNLNAME=:1 AND PNLFIELDNAME=:2 AND PNLFLDID<>:3", &_PageName, &name, &rec.PNLFLDID.Value, &count);
         If &count > 0 Then
            &_ErrText = "pageFieldName already exists on this Page: " | &name;
            Return False;
         End-If;
      End-If;
   End-If;
   Local number &anchor = Value(&rec.ENABLEASANCHOR.Value);
   If &req.IsExist("enableAsAnchor") Then
      &anchor = &req.GetNumber("enableAsAnchor");
   End-If;
   If (&req.IsExist("pageFieldName") Or
         &req.IsExist("enableAsAnchor")) And
         &anchor = 1 And
         &name = "" Then
      &_ErrText = "enableAsAnchor requires a nonempty pageFieldName";
      Return False;
   End-If;
   Return True;
end-method;

method EnsureBasicExt
   /+ &id as Number +/
   Local Record &ext = CreateRecord(Record.PSPNLFIELDEXT);
   &ext.PNLNAME.Value = &_PageName;
   &ext.PNLFLDID.Value = &id;
   If Not &ext.SelectByKey() Then
      &ext.PNLNAME.Value = &_PageName;
      &ext.PNLFLDID.Value = &id;
      &ext.PARENTPNLFLDID.Value = &_PageName | "$0";
      &ext.PAGEPNLFLDID.Value = &_PageName | "$0";
      &ext.FFSTYLELONG.Value = " | | | | ";
      If Not &ext.Insert() Then
         throw CreateException(0, 0, "Unable to create PSPNLFIELDEXT baseline");
      End-If;
   End-If;
end-method;

method ApplyBasicProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local number &use = &rec.FIELDUSE.Value;
   Local number &temp = &rec.FIELDUSETMP.Value;
   Local Record &ext;
   Local number &extUse;
   If &req.IsExist("displayControl") Then
      &use = %This.FlagValue(&use, 8, &req.GetNumber("displayControl"));
   End-If;
   If &req.IsExist("multiCurrency") Then
      &use = %This.FlagValue(&use, 32, &req.GetNumber("multiCurrency"));
   End-If;
   If &use <> &rec.FIELDUSE.Value Then
      SQLExec("UPDATE PSPNLFIELD SET FIELDUSE=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &use, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("setComponentChanged") Then
      &temp = %This.FlagValue(&temp, 8, 1 - &req.GetNumber("setComponentChanged"));
   End-If;
   If &req.IsExist("displayOnlyAppearance") Then
      If &req.GetString("displayOnlyAppearance") = "disabled" Then
         &temp = %This.FlagValue(&temp, 4, 1);
         If &rec.FIELDTYPE.Value = 5 Then
            &temp = %This.FlagValue(&temp, 64, 0);
         End-If;
      Else
         &temp = %This.FlagValue(&temp, 4, 0);
      End-If;
   End-If;
   If &temp <> &rec.FIELDUSETMP.Value Then
      SQLExec("UPDATE PSPNLFIELD SET FIELDUSETMP=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &temp, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("pageFieldName") Then
      SQLExec("UPDATE PSPNLFIELD SET PNLFIELDNAME=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &req.GetString("pageFieldName"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("enableAsAnchor") Then
      SQLExec("UPDATE PSPNLFIELD SET ENABLEASANCHOR=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &req.GetNumber("enableAsAnchor"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("readOnlyScreenReader") Then
      %This.EnsureBasicExt(&rec.PNLFLDID.Value);
      &ext = CreateRecord(Record.PSPNLFIELDEXT);
      &ext.PNLNAME.Value = &_PageName;
      &ext.PNLFLDID.Value = &rec.PNLFLDID.Value;
      If Not &ext.SelectByKey() Then
         throw CreateException(0, 0, "PSPNLFIELDEXT readback missing");
      End-If;
      &extUse = %This.FlagValue(&ext.FIELDUSETEMP2.Value, 65536, &req.GetNumber("readOnlyScreenReader"));
      SQLExec("UPDATE PSPNLFIELDEXT SET FIELDUSETEMP2=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &extUse, &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;


method ValidateEditProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local array of string &keys = CreateArray("alignment", "fillCharacter", "password", "inputOnly", "showPromptButton", "autoFill", "spellCheck");
   Local integer &i;
   Local boolean &requested = False;
   Local string &alignment;
   Local number &password = %This.FlagBit(&rec.DSPLFORMAT.Value, 32768);
   Local number &spell = %This.FlagBit(&rec.FIELDUSETMP.Value, 2);
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) Then
         &requested = True;
      End-If;
   End-For;
   If Not &requested Then
      Return True;
   End-If;
   If &rec.FIELDTYPE.Value <> 4 Then
      &_ErrText = "Edit Record properties currently support Edit Box only";
      Return False;
   End-If;
   If &req.IsExist("alignment") Then
      &alignment = &req.GetString("alignment");
      If &alignment <> "auto" And
            &alignment <> "left" And
            &alignment <> "right" Then
         &_ErrText = "alignment requires auto, left or right";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("fillCharacter") Then
      If Len(&req.GetString("fillCharacter")) > 1 Then
         &_ErrText = "fillCharacter maximum length is one character";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("password") Then
      &password = &req.GetNumber("password");
   End-If;
   If &req.IsExist("inputOnly") Then
      If &req.GetNumber("inputOnly") = 1 And
            &password <> 1 Then
         &_ErrText = "inputOnly=1 requires final password=1";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("spellCheck") Then
      &spell = &req.GetNumber("spellCheck");
   End-If;
   If &req.IsExist("showPromptButton") Then
      If &req.GetNumber("showPromptButton") = 1 And
            &spell = 1 Then
         &_ErrText = "showPromptButton=1 conflicts with final spellCheck=1";
         Return False;
      End-If;
   End-If;
   Return True;
end-method;

method AddEditProperties
   /+ &rec as Record, +/
   /+ &ext as C_JSON_API:JSONObject, +/
   /+ &obj as C_JSON_API:JSONObject +/
   Local number &bits = &rec.DSPLFORMAT.Value;
   Local number &align = %This.FlagBit(&bits, 1) + 4 * %This.FlagBit(&bits, 4) + 8 * %This.FlagBit(&bits, 8);
   Local number &spell = %This.FlagBit(&rec.FIELDUSETMP.Value, 2);
   Local number &extUse = 0;
   Local number &prompt = 0;
   Local string &alignment = "unknown";
   If &align = 8 Then
      &alignment = "auto";
   End-If;
   If &align = 1 Then
      &alignment = "left";
   End-If;
   If &align = 4 Then
      &alignment = "right";
   End-If;
   If &ext.IsExist("FIELDUSETEMP2") Then
      &extUse = &ext.GetNumber("FIELDUSETEMP2");
   End-If;
   If &spell = 0 And
         %This.FlagBit(&bits, 8388608) = 0 Then
      &prompt = 1;
   End-If;
   &obj.AddProperty("alignment", &alignment);
   &obj.AddProperty("fillCharacter", &rec.DSPLFILL.Value);
   &obj.AddProperty("password", %This.FlagBit(&bits, 32768));
   &obj.AddProperty("inputOnly", %This.FlagBit(&extUse, 512));
   &obj.AddProperty("showPromptButton", &prompt);
   &obj.AddProperty("autoFill", %This.FlagBit(&bits, 512));
   &obj.AddProperty("spellCheck", &spell);
end-method;

method ApplyEditProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local array of string &keys = CreateArray("alignment", "fillCharacter", "password", "inputOnly", "showPromptButton", "autoFill", "spellCheck");
   Local integer &i;
   Local boolean &requested = False;
   Local number &bits = &rec.DSPLFORMAT.Value;
   Local number &temp = &rec.FIELDUSETMP.Value;
   Local number &oldSpell = %This.FlagBit(&temp, 2);
   Local number &spell = &oldSpell;
   Local number &align = 8;
   Local Record &ext;
   Local number &extUse;
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) Then
         &requested = True;
      End-If;
   End-For;
   If Not &requested Then
      Return;
   End-If;
   If &req.IsExist("alignment") Then
      &bits = %This.FlagValue(&bits, 1, 0);
      &bits = %This.FlagValue(&bits, 4, 0);
      &bits = %This.FlagValue(&bits, 8, 0);
      If &req.GetString("alignment") = "left" Then
         &align = 1;
      End-If;
      If &req.GetString("alignment") = "right" Then
         &align = 4;
      End-If;
      &bits = %This.FlagValue(&bits, &align, 1);
   End-If;
   If &req.IsExist("password") Then
      &bits = %This.FlagValue(&bits, 32768, &req.GetNumber("password"));
   End-If;
   If &req.IsExist("autoFill") Then
      &bits = %This.FlagValue(&bits, 512, &req.GetNumber("autoFill"));
   End-If;
   If &req.IsExist("spellCheck") Then
      &spell = &req.GetNumber("spellCheck");
      &temp = %This.FlagValue(&temp, 2, &spell);
      If &spell = 1 Then
         &bits = %This.FlagValue(&bits, 8388608, 0);
      Else
         If &oldSpell = 1 Then
            &bits = %This.FlagValue(&bits, 8388608, 1);
         End-If;
      End-If;
   End-If;
   If &req.IsExist("showPromptButton") Then
      If &spell = 0 Then
         &bits = %This.FlagValue(&bits, 8388608, 1 - &req.GetNumber("showPromptButton"));
      Else
         &bits = %This.FlagValue(&bits, 8388608, 0);
      End-If;
   End-If;
   If &bits <> &rec.DSPLFORMAT.Value Or
         &temp <> &rec.FIELDUSETMP.Value Then
      SQLExec("UPDATE PSPNLFIELD SET DSPLFORMAT=:1,FIELDUSETMP=:2 WHERE PNLNAME=:3 AND PNLFLDID=:4", &bits, &temp, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("fillCharacter") Then
      SQLExec("UPDATE PSPNLFIELD SET DSPLFILL=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &req.GetString("fillCharacter"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("inputOnly") Then
      %This.EnsureBasicExt(&rec.PNLFLDID.Value);
      &ext = CreateRecord(Record.PSPNLFIELDEXT);
      &ext.PNLNAME.Value = &_PageName;
      &ext.PNLFLDID.Value = &rec.PNLFLDID.Value;
      If Not &ext.SelectByKey() Then
         throw CreateException(0, 0, "PSPNLFIELDEXT missing for Input Only");
      End-If;
      &extUse = %This.FlagValue(&ext.FIELDUSETEMP2.Value, 512, &req.GetNumber("inputOnly"));
      SQLExec("UPDATE PSPNLFIELDEXT SET FIELDUSETEMP2=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &extUse, &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;


method ValidateLabelProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local array of string &keys = CreateArray("noColon", "firstOccursOnly", "labelAlignment", "useDefaultLabel");
   Local integer &i;
   Local number &kind = &rec.LBLTYPE.Value;
   Local number &default = Value(&rec.USEDEFAULTLABEL.Value);
   Local number &count = 0;
   Local string &id = &rec.LABEL_ID.Value;
   Local string &align;
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) And
            &rec.FIELDTYPE.Value <> 4 And
            &rec.FIELDTYPE.Value <> 5 Then
         &_ErrText = &keys [&i] | " requires the verified Edit Box/Drop-Down Label implementation";
         Return False;
      End-If;
   End-For;
   If &rec.FIELDTYPE.Value <> 4 And
         &rec.FIELDTYPE.Value <> 5 Then
      Return True;
   End-If;
   If &req.IsExist("labelAlignment") Then
      &align = &req.GetString("labelAlignment");
      If &align <> "left" And
            &align <> "center" And
            &align <> "right" Then
         &_ErrText = "labelAlignment requires left/center/right";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("noColon") And
         &req.IsExist("labelLoc") Then
      &_ErrText = "Supply noColon or raw labelLoc, not both";
      Return False;
   End-If;
   If &req.IsExist("labelType") Then
      &kind = &req.GetNumber("labelType");
      If &kind < 0 Or
            &kind > 3 Or
            &kind <> Int(&kind) Then
         &_ErrText = "Edit Box/Drop-Down labelType requires 0=None, 1=Text, 2=RFT Short, 3=RFT Long";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("labelText") And
         &kind <> 0 And
         &kind <> 1 Then
      &_ErrText = "labelText is editable for None/Text; also supply labelType=1 when leaving an RFT label";
      Return False;
   End-If;
   If &req.IsExist("labelId") Or
         &req.IsExist("useDefaultLabel") Then
      If &kind <> 2 And
            &kind <> 3 Then
         &_ErrText = "Label ID/default selection requires RFT Short or RFT Long";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("labelId") Then
      &id = &req.GetString("labelId");
      &default = 0;
      If &req.IsExist("useDefaultLabel") And
            &req.GetNumber("useDefaultLabel") = 1 Then
         &_ErrText = "Explicit labelId conflicts with useDefaultLabel=1";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("useDefaultLabel") Then
      &default = &req.GetNumber("useDefaultLabel");
   End-If;
   If (&kind = 2 Or
         &kind = 3) And
         (&req.IsExist("labelType") Or
            &req.IsExist("labelId") Or
            &req.IsExist("useDefaultLabel")) Then
      If &default = 1 Then
         SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &rec.FIELDNAME.Value, &count);
      Else
         SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND LABEL_ID=:2", &rec.FIELDNAME.Value, &id, &count);
      End-If;
      If &count <> 1 Then
         &_ErrText = "Unable to resolve one selected base field label";
         Return False;
      End-If;
   End-If;
   Return True;
end-method;

method ApplyLabelProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local number &bits = &rec.DSPLFORMAT.Value;
   Local number &loc = &rec.LBLLOC.Value;
   Local number &kind = &rec.LBLTYPE.Value;
   Local number &default = Value(&rec.USEDEFAULTLABEL.Value);
   Local string &id = &rec.LABEL_ID.Value;
   Local string &text = &rec.LBLTEXT.Value;
   Local string &longText, &shortText, &align;
   Local number &alignBit;
   If &rec.FIELDTYPE.Value <> 4 And
         &rec.FIELDTYPE.Value <> 5 Then
      Return;
   End-If;
   If &req.IsExist("firstOccursOnly") Then
      &bits = %This.FlagValue(&bits, 4194304, &req.GetNumber("firstOccursOnly"));
   End-If;
   If &req.IsExist("labelAlignment") Then
      &align = &req.GetString("labelAlignment");
      &alignBit = 524288;
      If &align = "center" Then
         &alignBit = 1048576;
      End-If;
      If &align = "right" Then
         &alignBit = 2097152;
      End-If;
      &bits = %This.FlagValue(&bits, 524288, 0);
      &bits = %This.FlagValue(&bits, 1048576, 0);
      &bits = %This.FlagValue(&bits, 2097152, 0);
      &bits = %This.FlagValue(&bits, &alignBit, 1);
   End-If;
   If &req.IsExist("noColon") Then
      &loc = %This.FlagValue(&loc, 1, &req.GetNumber("noColon"));
   End-If;
   If &req.IsExist("labelType") Then
      &kind = &req.GetNumber("labelType");
   End-If;
   If &req.IsExist("labelText") Then
      &text = &req.GetString("labelText");
   End-If;
   If &req.IsExist("labelId") Then
      &id = &req.GetString("labelId");
      &default = 0;
   End-If;
   If &req.IsExist("useDefaultLabel") Then
      &default = &req.GetNumber("useDefaultLabel");
   End-If;
   If (&kind = 2 Or
         &kind = 3) And
         (&req.IsExist("labelType") Or
            &req.IsExist("labelId") Or
            &req.IsExist("useDefaultLabel")) Then
      If &default = 1 Then
         SQLExec("SELECT LABEL_ID,LONGNAME,SHORTNAME FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &rec.FIELDNAME.Value, &id, &longText, &shortText);
      Else
         SQLExec("SELECT LONGNAME,SHORTNAME FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND LABEL_ID=:2", &rec.FIELDNAME.Value, &id, &longText, &shortText);
      End-If;
      &text = &longText;
      If &kind = 2 Then
         &text = &shortText;
      End-If;
   End-If;
   If &bits <> &rec.DSPLFORMAT.Value Or
         &loc <> &rec.LBLLOC.Value Then
      SQLExec("UPDATE PSPNLFIELD SET DSPLFORMAT=:1,LBLLOC=:2 WHERE PNLNAME=:3 AND PNLFLDID=:4", &bits, &loc, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &kind <> &rec.LBLTYPE.Value Or
         &text <> &rec.LBLTEXT.Value Or
         &id <> &rec.LABEL_ID.Value Or
         &default <> Value(&rec.USEDEFAULTLABEL.Value) Then
      SQLExec("UPDATE PSPNLFIELD SET LBLTYPE=:1,LBLTEXT=:2,LABEL_ID=:3,USEDEFAULTLABEL=:4 WHERE PNLNAME=:5 AND PNLFLDID=:6", &kind, &text, &id, String(&default), &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;

method AddLabelProperties
   /+ &rec as Record, +/
   /+ &obj as C_JSON_API:JSONObject +/
   Local number &bits = &rec.DSPLFORMAT.Value;
   Local number &selection = %This.FlagBit(&bits, 524288) + 2 * %This.FlagBit(&bits, 1048576) + 4 * %This.FlagBit(&bits, 2097152);
   Local string &alignment = "unknown";
   If &selection = 1 Then
      &alignment = "left";
   End-If;
   If &selection = 2 Then
      &alignment = "center";
   End-If;
   If &selection = 4 Then
      &alignment = "right";
   End-If;
   &obj.AddProperty("labelId", &rec.LABEL_ID.Value);
   &obj.AddProperty("useDefaultLabel", Value(&rec.USEDEFAULTLABEL.Value));
   &obj.AddProperty("noColon", %This.FlagBit(&rec.LBLLOC.Value, 1));
   &obj.AddProperty("firstOccursOnly", %This.FlagBit(&bits, 4194304));
   &obj.AddProperty("labelAlignment", &alignment);
end-method;

method ValidateDropDownProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local string &mode = "prompt";
   Local number &selection = %This.FlagBit(&rec.DSPLFORMAT.Value, 131072) + 2 * %This.FlagBit(&rec.DSPLFORMAT.Value, 262144);
   Local string &metaTable;
   Local string &field = &rec.PROMPTFIELD.Value;
   Local number &count = 0;
   If Not &req.IsExist("displayedText") And
         Not &req.IsExist("promptField") Then
      Return True;
   End-If;
   If &rec.FIELDTYPE.Value <> 5 Then
      &_ErrText = "displayedText/promptField require Drop-Down List Box";
      Return False;
   End-If;
   If &selection = 1 Then
      &mode = "xlatShort";
   End-If;
   If &selection = 2 Then
      &mode = "xlatLong";
   End-If;
   If &req.IsExist("displayedText") Then
      &mode = &req.GetString("displayedText");
      If &mode <> "xlatShort" And
            &mode <> "xlatLong" And
            &mode <> "prompt" Then
         &_ErrText = "displayedText requires xlatShort/xlatLong/prompt";
         Return False;
      End-If;
   Else
      If &selection = 3 Then
         &_ErrText = "Specify displayedText to replace an unknown display mode";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("promptField") Then
      &field = &req.GetString("promptField");
      If &mode <> "prompt" Then
         &_ErrText = "promptField requires Prompt Table Field display mode";
         Return False;
      End-If;
   End-If;
   If &mode = "prompt" Then
      SQLExec("SELECT EDITTABLE FROM PSRECFIELDDB WHERE RECNAME=:1 AND FIELDNAME=:2", &rec.RECNAME.Value, &rec.FIELDNAME.Value, &metaTable);
      &metaTable = RTrim(LTrim(&metaTable));
      If &metaTable = "" Then
         If &field <> "" Then
            &_ErrText = "Record field has no resolved prompt table";
            Return False;
         End-If;
      Else
         If &field = "" Then
            &_ErrText = "Supply explicit promptField for this prompt table; AD automatic selection is not yet generalized";
            Return False;
         End-If;
         REM Current AD choices match prompt table List Box Item fields;
         SQLExec("SELECT COUNT(*) FROM PSRECFIELDDB WHERE RECNAME=:1 AND FIELDNAME=:2 AND MOD(TRUNC(USEEDIT/32),2)=1", &metaTable, &field, &count);
         If &count <> 1 Then
            &_ErrText = "promptField must resolve to one List Box Item field in the derived prompt table";
            Return False;
         End-If;
      End-If;
   End-If;
   Return True;
end-method;

method ApplyDropDownProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local number &bits = &rec.DSPLFORMAT.Value;
   Local string &field = &rec.PROMPTFIELD.Value;
   Local string &mode;
   If Not &req.IsExist("displayedText") And
         Not &req.IsExist("promptField") Then
      Return;
   End-If;
   If &req.IsExist("displayedText") Then
      &mode = &req.GetString("displayedText");
      &bits = %This.FlagValue(&bits, 131072, 0);
      &bits = %This.FlagValue(&bits, 262144, 0);
      If &mode = "xlatShort" Then
         &bits = %This.FlagValue(&bits, 131072, 1);
      End-If;
      If &mode = "xlatLong" Then
         &bits = %This.FlagValue(&bits, 262144, 1);
      End-If;
      If &mode <> "prompt" Then
         &field = "";
      End-If;
   End-If;
   If &req.IsExist("promptField") Then
      &field = &req.GetString("promptField");
   End-If;
   If &bits <> &rec.DSPLFORMAT.Value Or
         &field <> &rec.PROMPTFIELD.Value Then
      SQLExec("UPDATE PSPNLFIELD SET DSPLFORMAT=:1,PROMPTFIELD=:2 WHERE PNLNAME=:3 AND PNLFLDID=:4", &bits, &field, &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;

method AddDropDownProperties
   /+ &rec as Record, +/
   /+ &obj as C_JSON_API:JSONObject +/
   Local number &selection = %This.FlagBit(&rec.DSPLFORMAT.Value, 131072) + 2 * %This.FlagBit(&rec.DSPLFORMAT.Value, 262144);
   Local string &mode = "unknown";
   Local string &metaTable;
   Evaluate &selection
   When 0
      &mode = "prompt";
      Break;
   When 1
      &mode = "xlatShort";
      Break;
   When 2
      &mode = "xlatLong";
      Break;
   End-Evaluate;
   SQLExec("SELECT EDITTABLE FROM PSRECFIELDDB WHERE RECNAME=:1 AND FIELDNAME=:2", &rec.RECNAME.Value, &rec.FIELDNAME.Value, &metaTable);
   &obj.AddProperty("displayedText", &mode);
   &obj.AddProperty("promptField", &rec.PROMPTFIELD.Value);
   &obj.AddProperty("promptTable", RTrim(LTrim(&metaTable)));
end-method;

method ValidateLayoutProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local array of string &keys = CreateArray("labelPosition", "labelLeft", "labelTop", "labelRight", "labelBottom", "moveX", "moveY", "sizeType");
   Local array of string &bounds = CreateArray("labelLeft", "labelTop", "labelRight", "labelBottom");
   Local array of string &rawKeys = CreateArray("left", "top", "right", "bottom", "editSize", "sizeType");
   Local array of any &values = CreateArrayAny(&rec.EDITLBLLEFT.Value, &rec.EDITLBLTOP.Value, &rec.EDITLBLRIGHT.Value, &rec.EDITLBLBOTTOM.Value);
   Local integer &i;
   Local integer &count = 0;
   Local boolean &requested = False;
   Local boolean &moving;
   Local string &sizeType;
   Local number &fieldMode = &rec.FIELDSIZETYPE.Value;
   Local array of any &fieldBounds = CreateArrayAny(&rec.FIELDLEFT.Value, &rec.FIELDTOP.Value, &rec.FIELDRIGHT.Value, &rec.FIELDBOTTOM.Value);
   Local integer &fieldCount = 0;
   Local string &position;
   Local number &mode = &rec.LABELSIZETYPE.Value;
   Local number &dx = 0;
   Local number &dy = 0;
   &moving = False;
   If &req.IsExist("moveX") Or
         &req.IsExist("moveY") Then
      &moving = True;
   End-If;
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) Then
         &requested = True;
      End-If;
   End-For;
   If Not &requested Then
      Return True;
   End-If;
   If &rec.FIELDTYPE.Value <> 4 And
         &rec.FIELDTYPE.Value <> 5 Then
      &_ErrText = "Layout properties currently require Edit Box or Drop-Down List Box";
      Return False;
   End-If;
   If &req.IsExist("sizeType") Then
      &sizeType = &req.GetString("sizeType");
      Evaluate &sizeType
      When "average"
         &fieldMode = 0;
         Break;
      When "maximum"
         &fieldMode = 1;
         Break;
      When "custom"
         &fieldMode = 2;
         Break;
      When-Other
         &_ErrText = "sizeType requires average/maximum/custom";
         Return False;
      End-Evaluate;
      For &i = 1 To 4
         If &req.IsExist(&rawKeys [&i]) Then
            &fieldCount = &fieldCount + 1;
            &fieldBounds [&i] = &req.GetNumber(&rawKeys [&i]);
         End-If;
      End-For;
      If &fieldMode <> &rec.FIELDSIZETYPE.Value And
            &fieldCount <> 4 Then
         &_ErrText = "Changing sizeType requires explicit left/top/right/bottom; AD measured bounds are not inferred";
         Return False;
      End-If;
      For &i = 1 To 4
         If &fieldBounds [&i] < 0 Or
               &fieldBounds [&i] > 32767 Or
               Int(&fieldBounds [&i]) <> &fieldBounds [&i] Then
            &_ErrText = "Field bounds require integers from 0 to 32767";
            Return False;
         End-If;
      End-For;
      If &fieldMode = 2 Then
         If &fieldBounds [3] <= &fieldBounds [1] Or
               &fieldBounds [4] <= &fieldBounds [2] Then
            &_ErrText = "Custom field size requires positive width and height";
            Return False;
         End-If;
      End-If;
   End-If;
   If &req.IsExist("labelPosition") Then
      &position = &req.GetString("labelPosition");
      Evaluate &position
      When "left"
         &mode = 0;
         Break;
      When "custom"
         &mode = 1;
         Break;
      When "top"
         &mode = 2;
         Break;
      When-Other
         &_ErrText = "labelPosition requires left/custom/top";
         Return False;
      End-Evaluate;
   End-If;
   For &i = 1 To &bounds.Len
      If &req.IsExist(&bounds [&i]) Then
         &count = &count + 1;
         &values [&i] = &req.GetNumber(&bounds [&i]);
      End-If;
   End-For;
   If &count <> 0 And
         &count <> 4 Then
      &_ErrText = "Supply all four label bounds together";
      Return False;
   End-If;
   If &mode <> &rec.LABELSIZETYPE.Value And
         &count <> 4 Then
      &_ErrText = "Changing labelPosition requires explicit four label bounds; AD font measurement is not inferred";
      Return False;
   End-If;
   If &count = 4 Then
      If &mode <> 1 And
            Not &req.IsExist("labelPosition") Then
         &_ErrText = "Independent label bounds require Custom position";
         Return False;
      End-If;
      For &i = 1 To &values.Len
         If &values [&i] < 0 Or
               &values [&i] > 32767 Or
               Int(&values [&i]) <> &values [&i] Then
            &_ErrText = "Label bounds require integers from 0 to 32767";
            Return False;
         End-If;
      End-For;
      If &values [3] < &values [1] Or
            &values [4] < &values [2] Then
         &_ErrText = "Label bounds cannot have negative width or height";
         Return False;
      End-If;
      If &mode = 1 Then
         If &values [3] = &values [1] Or
               &values [4] = &values [2] Then
            &_ErrText = "Custom label bounds require positive width and height";
            Return False;
         End-If;
      End-If;
   End-If;
   If &moving Then
      If &rec.LABELSIZETYPE.Value <> 1 Or
            &rec.FIELDSIZETYPE.Value <> 2 Or
            &count <> 0 Or
            &req.IsExist("labelPosition") Then
         &_ErrText = "moveX/moveY require existing Custom field size and label position; cannot combine with label layout";
         Return False;
      End-If;
      For &i = 1 To &rawKeys.Len
         If &req.IsExist(&rawKeys [&i]) Then
            &_ErrText = "moveX/moveY cannot combine with raw field coordinates or editSize";
            Return False;
         End-If;
      End-For;
      If &req.IsExist("moveX") Then
         &dx = &req.GetNumber("moveX");
      End-If;
      If &req.IsExist("moveY") Then
         &dy = &req.GetNumber("moveY");
      End-If;
      If Int(&dx) <> &dx Or
            Int(&dy) <> &dy Then
         &_ErrText = "moveX/moveY require integer coordinate deltas";
         Return False;
      End-If;
      &values = CreateArrayAny(&rec.FIELDLEFT.Value + &dx, &rec.FIELDTOP.Value + &dy, &rec.FIELDRIGHT.Value + &dx, &rec.FIELDBOTTOM.Value + &dy, &rec.EDITLBLLEFT.Value + &dx, &rec.EDITLBLTOP.Value + &dy, &rec.EDITLBLRIGHT.Value + &dx, &rec.EDITLBLBOTTOM.Value + &dy);
      For &i = 1 To &values.Len
         If &values [&i] < 0 Or
               &values [&i] > 32767 Then
            &_ErrText = "Moved field and label bounds must remain from 0 to 32767";
            Return False;
         End-If;
      End-For;
   End-If;
   Return True;
end-method;

method ApplyLayoutProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local number &dx = 0;
   Local number &dy = 0;
   Local number &mode = &rec.LABELSIZETYPE.Value;
   Local string &position;
   Local number &fieldMode;
   If &req.IsExist("sizeType") Then
      &position = &req.GetString("sizeType");
      If &position = "average" Then
         &fieldMode = 0;
      End-If;
      If &position = "maximum" Then
         &fieldMode = 1;
      End-If;
      If &position = "custom" Then
         &fieldMode = 2;
      End-If;
      SQLExec("UPDATE PSPNLFIELD SET FIELDSIZETYPE=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &fieldMode, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("moveX") Or
         &req.IsExist("moveY") Then
      If &req.IsExist("moveX") Then
         &dx = &req.GetNumber("moveX");
      End-If;
      If &req.IsExist("moveY") Then
         &dy = &req.GetNumber("moveY");
      End-If;
      REM Explicit coordinate translation, without UI grid snapping;
      SQLExec("UPDATE PSPNLFIELD SET FIELDLEFT=FIELDLEFT+:1,FIELDRIGHT=FIELDRIGHT+:1,FIELDTOP=FIELDTOP+:2,FIELDBOTTOM=FIELDBOTTOM+:2,EDITLBLLEFT=EDITLBLLEFT+:1,EDITLBLRIGHT=EDITLBLRIGHT+:1,EDITLBLTOP=EDITLBLTOP+:2,EDITLBLBOTTOM=EDITLBLBOTTOM+:2 WHERE PNLNAME=:3 AND PNLFLDID=:4", &dx, &dy, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("labelPosition") Then
      &position = &req.GetString("labelPosition");
      If &position = "left" Then
         &mode = 0;
      End-If;
      If &position = "custom" Then
         &mode = 1;
      End-If;
      If &position = "top" Then
         &mode = 2;
      End-If;
      SQLExec("UPDATE PSPNLFIELD SET LABELSIZETYPE=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &mode, &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("labelLeft") Then
      SQLExec("UPDATE PSPNLFIELD SET EDITLBLLEFT=:1,EDITLBLTOP=:2,EDITLBLRIGHT=:3,EDITLBLBOTTOM=:4 WHERE PNLNAME=:5 AND PNLFLDID=:6", &req.GetNumber("labelLeft"), &req.GetNumber("labelTop"), &req.GetNumber("labelRight"), &req.GetNumber("labelBottom"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;

method AddLayoutProperties
   /+ &rec as Record, +/
   /+ &obj as C_JSON_API:JSONObject +/
   Local string &position = "unknown";
   Evaluate &rec.LABELSIZETYPE.Value
   When 0
      &position = "left";
      Break;
   When 1
      &position = "custom";
      Break;
   When 2
      &position = "top";
      Break;
   End-Evaluate;
   &obj.AddProperty("labelPosition", &position);
   &position = "unknown";
   Evaluate &rec.FIELDSIZETYPE.Value
   When 0
      &position = "average";
      Break;
   When 1
      &position = "maximum";
      Break;
   When 2
      &position = "custom";
      Break;
   End-Evaluate;
   &obj.AddProperty("sizeType", &position);
   &obj.AddProperty("labelLeft", &rec.EDITLBLLEFT.Value);
   &obj.AddProperty("labelTop", &rec.EDITLBLTOP.Value);
   &obj.AddProperty("labelRight", &rec.EDITLBLRIGHT.Value);
   &obj.AddProperty("labelBottom", &rec.EDITLBLBOTTOM.Value);
end-method;


method PageRows
   /+ &rows as Rowset, +/
   /+ &order as String +/
   /+ Returns String +/
   Local integer &n, &i, &j;
   Local Record &rec;
   Local string &state, &v;
   &n = &rows.Fill("WHERE PNLNAME=:1 " | &order, &_PageName);
   &state = String(&n);
   For &i = 1 To &n
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &v = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&v)) | ":" | &v;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;

method PageVersion
   /+ Returns String +/
   Local string &state = "P1|" | &_PageName;
   Local number &exists, &generation;
   Local C_JSON_API:JSONObject &code;
   SQLExec("SELECT COUNT(*) FROM PSPNLDEFN WHERE PNLNAME=:1", &_PageName, &exists);
   If &exists = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PDM'", &generation);
      &state = &state | "ABSENT:" | String(&generation);
   End-If;
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLACEGRDAXIS), "ORDER BY PNLNAME,PNLFLDID,FIELDNAME");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLACEGRDDATA), "ORDER BY PNLNAME,PNLFLDID,ACEMODELID,ACECOLLNAME");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLACTIVEX), "ORDER BY PNLNAME,PNLFLDID,ACTIVEXDATASEQ");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLBTNDATA), "ORDER BY PNLNAME,PNLFLDID,PTBTNCLASSTYPE,PTBTNFIELDTYPE");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLBTNLANG), "ORDER BY PNLNAME,PNLFLDID,PTBTNCLASSTYPE,PTBTNFIELDTYPE,LANGUAGE_CD");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLCNTRLDATA), "ORDER BY PNLNAME,PNLFLDID");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLCTLDATALNG), "ORDER BY PNLNAME,PNLFLDID,LANGUAGE_CD");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLDEFN), "ORDER BY PNLNAME");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLDEFNLANG), "ORDER BY PNLNAME,LANGUAGE_CD");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLDEL), "ORDER BY PNLNAME,VERSION");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLFIELD), "ORDER BY PNLNAME,PNLFLDID");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLFIELDEXT), "ORDER BY PNLNAME,PNLFLDID");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLFIELDLANG), "ORDER BY PNLNAME,PNLFLDID,LANGUAGE_CD");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLHTMLAREA), "ORDER BY PNLNAME,PNLFLDID");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLHTMLLANG), "ORDER BY PNLNAME,PNLFLDID,LANGUAGE_CD");
   &state = &state | %This.PageRows(CreateRowset(Record.PSPNLTREECTRL), "ORDER BY PNLNAME,TREECTRLID,TREELVLNUM,PARENTNODENUM,NODENUM");
   &code = %This.ViewPagePeopleCodeCli(CreateObject("C_JSON_API:Factory").NewObject());
   &state = &state | "|PC:" | String(&code.GetBoolean("programExists")) | ":" | &code.GetString("peoplecode");
   Return "p1:" | HashSHA256(&state);
end-method;

method ValidateBatchProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   /+ Returns Boolean +/
   Local array of string &ddl = CreateArray("wrapLongWords", "modifiableByJavaScript", "generateHtml", "popupMenu");
   Local array of string &numeric = CreateArray("autoDecimal", "currencySymbol", "thousandsSeparator");
   Local integer &i;
   Local number &type, &invisible, &disabled, &found;
   &invisible = %This.FlagBit(&rec.FIELDUSE.Value, 2);
   &disabled = %This.FlagBit(&rec.FIELDUSETMP.Value, 4);
   If &req.IsExist("invisible") Then
      &invisible = &req.GetNumber("invisible");
   End-If;
   For &i = 1 To &ddl.Len
      If &req.IsExist(&ddl [&i]) And
            &rec.FIELDTYPE.Value <> 5 Then
         &_ErrText = &ddl [&i] | " is validated for Drop-Down only";
         Return False;
      End-If;
   End-For;
   If &req.IsExist("enableWhenPageDisplayOnly") And
         &rec.FIELDTYPE.Value <> 4 Then
      &_ErrText = "enableWhenPageDisplayOnly is validated for Edit Box only";
      Return False;
   End-If;
   If &req.IsExist("showLabel") Or
         &req.IsExist("modifiableByJavaScript") Or
         &req.IsExist("generateHtml") Then
      If &invisible <> 1 Then
         &_ErrText = "showLabel/modifiableByJavaScript/generateHtml require final invisible=1";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("displayOnlyAppearance") Then
      &disabled = 0;
      If &req.GetString("displayOnlyAppearance") = "disabled" Then
         &disabled = 1;
      End-If;
   End-If;
   If &req.IsExist("wrapLongWords") Then
      If &req.GetNumber("wrapLongWords") = 1 And
            &disabled = 1 Then
         &_ErrText = "wrapLongWords=1 requires final textOnly appearance";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("popupMenu") Then
      If &req.GetString("popupMenu") <> "" Then
         SQLExec("SELECT COUNT(*) FROM PSMENUDEFN WHERE MENUNAME=:1 AND MENUTYPE=1", &req.GetString("popupMenu"), &found);
         If &found <> 1 Then
            &_ErrText = "popupMenu must name an existing popup menu";
            Return False;
         End-If;
      End-If;
   End-If;
   SQLExec("SELECT FIELDTYPE FROM PSDBFIELD WHERE FIELDNAME=:1", &rec.FIELDNAME.Value, &type);
   For &i = 1 To &numeric.Len
      If &req.IsExist(&numeric [&i]) Then
         If &rec.FIELDTYPE.Value <> 4 Or
               &type <> 2 Then
            &_ErrText = &numeric [&i] | " is validated for numeric Edit Box fields only";
            Return False;
         End-If;
      End-If;
   End-For;
   If &req.IsExist("displayZero") Then
      If &rec.FIELDTYPE.Value <> 4 Or
            (&type <> 0 And
               &type <> 2) Then
         &_ErrText = "displayZero is validated for character/numeric Edit Box only";
         Return False;
      End-If;
   End-If;
   If &req.IsExist("showCentury") Or
         &req.IsExist("showTimeZone") Then
      If &rec.FIELDTYPE.Value <> 4 Or
            &type <> 4 Then
         &_ErrText = "showCentury/showTimeZone are validated for date Edit Box only";
         Return False;
      End-If;
   End-If;
   Return True;
end-method;

method ApplyBatchProps
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &rec as Record +/
   Local number &use = &rec.FIELDUSE.Value;
   Local number &temp = &rec.FIELDUSETMP.Value;
   Local number &format = &rec.DSPLFORMAT.Value;
   Local array of string &keys = CreateArray("autoDecimal", "currencySymbol", "thousandsSeparator", "displayZero", "showCentury", "showTimeZone");
   Local array of number &masks = CreateArray(1024, 16, 32, 128, 65536, 536870912);
   Local integer &i;
   Local Record &ext;
   Local number &bits;
   If &req.IsExist("showLabel") Then
      &use = %This.FlagValue(&use, 1024, &req.GetNumber("showLabel"));
   End-If;
   If &req.IsExist("enableWhenPageDisplayOnly") Then
      &use = %This.FlagValue(&use, 262144, &req.GetNumber("enableWhenPageDisplayOnly"));
   End-If;
   If &req.IsExist("wrapLongWords") Then
      &temp = %This.FlagValue(&temp, 64, &req.GetNumber("wrapLongWords"));
   End-If;
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) Then
         &format = %This.FlagValue(&format, &masks [&i], &req.GetNumber(&keys [&i]));
      End-If;
   End-For;
   SQLExec("UPDATE PSPNLFIELD SET FIELDUSE=:1,FIELDUSETMP=:2,DSPLFORMAT=:3 WHERE PNLNAME=:4 AND PNLFLDID=:5", &use, &temp, &format, &_PageName, &rec.PNLFLDID.Value);
   If &req.IsExist("modifiableByJavaScript") Then
      SQLExec("UPDATE PSPNLFIELD SET SECUREINVISIBLE=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", 1 - &req.GetNumber("modifiableByJavaScript"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("popupMenu") Then
      SQLExec("UPDATE PSPNLFIELD SET POPUPMENU=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &req.GetString("popupMenu"), &_PageName, &rec.PNLFLDID.Value);
   End-If;
   If &req.IsExist("generateHtml") Then
      %This.EnsureBasicExt(&rec.PNLFLDID.Value);
      &ext = CreateRecord(Record.PSPNLFIELDEXT);
      &ext.PNLNAME.Value = &_PageName;
      &ext.PNLFLDID.Value = &rec.PNLFLDID.Value;
      If Not &ext.SelectByKey() Then
         throw CreateException(0, 0, "EXT disappeared");
      End-If;
      &bits = %This.FlagValue(&ext.FIELDUSETEMP2.Value, 32, &req.GetNumber("generateHtml"));
      SQLExec("UPDATE PSPNLFIELDEXT SET FIELDUSETEMP2=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", &bits, &_PageName, &rec.PNLFLDID.Value);
   End-If;
end-method;

method AddBatchProperties
   /+ &rec as Record, +/
   /+ &ext as C_JSON_API:JSONObject, +/
   /+ &obj as C_JSON_API:JSONObject +/
   Local number &format = &rec.DSPLFORMAT.Value;
   Local array of string &keys = CreateArray("autoDecimal", "currencySymbol", "thousandsSeparator", "displayZero", "showCentury", "showTimeZone");
   Local array of number &masks = CreateArray(1024, 16, 32, 128, 65536, 536870912);
   Local integer &i;
   Local number &type;
   Local number &bits = 0;
   &obj.AddProperty("showLabel", %This.FlagBit(&rec.FIELDUSE.Value, 1024));
   If &rec.FIELDTYPE.Value = 4 Then
      &obj.AddProperty("enableWhenPageDisplayOnly", %This.FlagBit(&rec.FIELDUSE.Value, 262144));
      SQLExec("SELECT FIELDTYPE FROM PSDBFIELD WHERE FIELDNAME=:1", &rec.FIELDNAME.Value, &type);
      For &i = 1 To &keys.Len
         If (&i <= 3 And
               &type = 2) Or
               (&i = 4 And
                  (&type = 0 Or
                     &type = 2)) Or
               (&i >= 5 And
                  &type = 4) Then
            &obj.AddProperty(&keys [&i], %This.FlagBit(&format, &masks [&i]));
         End-If;
      End-For;
   Else
      &obj.AddProperty("wrapLongWords", %This.FlagBit(&rec.FIELDUSETMP.Value, 64));
      &obj.AddProperty("modifiableByJavaScript", 1 - Value(&rec.SECUREINVISIBLE.Value));
      &obj.AddProperty("popupMenu", &rec.POPUPMENU.Value);
      If &ext.IsExist("FIELDUSETEMP2") Then
         &bits = &ext.GetNumber("FIELDUSETEMP2");
      End-If;
      &obj.AddProperty("generateHtml", %This.FlagBit(&bits, 32));
   End-If;
end-method;

method FlagBit
   /+ &bits as Number, +/
   /+ &mask as Number +/
   /+ Returns Number +/
   Local number &positive = &bits;
   Local number &pair;
   If &positive < 0 Then
      &positive = &positive + 4294967296;
   End-If;
   &pair = &positive / (2 * &mask);
   Return Int(2 * (&pair - Int(&pair)));
end-method;




method ValidateTree
   /+ &typeList as String, +/
   /+ &levelList as String, +/
   /+ &colsList as String, +/
   /+ &n as Integer +/
   Local integer &i, &k, &type, &level, &curLevel, &cols, &consume, &colType, &colLevel;
   Local integer &open0, &open1, &open2, &open3;
   Local integer &ctype0, &ctype1, &ctype2, &ctype3;
   Local integer &child0, &child1, &child2, &child3;
   Local boolean &seen1, &seen2, &seen3, &hasParent;
   If &n < 1 Then
      Return;
   End-If;
   &curLevel = %This.NthNum(&levelList, 1);
   If &curLevel <> 0 Then
      throw CreateException(0, 0, "first control must sit at level 0");
   End-If;
   &open0 = 0;
   &open1 = 0;
   &open2 = 0;
   &open3 = 0;
   &child0 = 0;
   &child1 = 0;
   &child2 = 0;
   &child3 = 0;
   &seen1 = False;
   &seen2 = False;
   &seen3 = False;
   &i = 1;
   While &i <= &n
      &type = %This.NthNum(&typeList, &i);
      &level = %This.NthNum(&levelList, &i);
      If &level > &curLevel + 1 Then
         throw CreateException(0, 0, "control " | String(&i) | " skips a level: " | String(&curLevel) | " -> " | String(&level));
      End-If;
      REM leaving a branch closes it and forgets that it ever had a container;
      If &level < 3 Then
         If &open3 = 1 Then
            If &ctype3 = 27 And
                  &child3 = 0 Then
               throw CreateException(0, 0, "scroll area at level 3 has no child control");
            End-If;
            &open3 = 0;
         End-If;
         &seen3 = False;
      End-If;
      If &level < 2 Then
         If &open2 = 1 Then
            If &ctype2 = 27 And
                  &child2 = 0 Then
               throw CreateException(0, 0, "scroll area at level 2 has no child control");
            End-If;
            &open2 = 0;
         End-If;
         &seen2 = False;
      End-If;
      If &level < 1 Then
         If &open1 = 1 Then
            If &ctype1 = 27 And
                  &child1 = 0 Then
               throw CreateException(0, 0, "scroll area at level 1 has no child control");
            End-If;
            &open1 = 0;
         End-If;
         &seen1 = False;
      End-If;
      If &type = 19 Or
            &type = 27 Then
         REM container at this level;
         If &level > 0 Then
            &hasParent = False;
            If &level = 1 Then
               If &open0 = 1 Then
                  If &ctype0 <> 27 Then
                     throw CreateException(0, 0, "control " | String(&i) | ": a grid cannot contain another container");
                  End-If;
                  &hasParent = True;
                  &child0 = &child0 + 1;
               End-If;
            Else
               If &level = 2 Then
                  If &open1 = 1 Then
                     If &ctype1 <> 27 Then
                        throw CreateException(0, 0, "control " | String(&i) | ": a grid cannot contain another container");
                     End-If;
                     &hasParent = True;
                     &child1 = &child1 + 1;
                  End-If;
               Else
                  If &open2 = 1 Then
                     If &ctype2 <> 27 Then
                        throw CreateException(0, 0, "control " | String(&i) | ": a grid cannot contain another container");
                     End-If;
                     &hasParent = True;
                     &child2 = &child2 + 1;
                  End-If;
               End-If;
            End-If;
            If Not &hasParent And
                  &level > 1 Then
               throw CreateException(0, 0, "control " | String(&i) | " at level " | String(&level) | " cannot be nested here");
            End-If;
         End-If;
         REM sibling container at the same level closes the previous one;
         If &level = 0 Then
            If &open0 = 1 Then
               If &ctype0 = 27 And
                     &child0 = 0 Then
                  throw CreateException(0, 0, "scroll area at level 0 has no child control");
               End-If;
            End-If;
            &open0 = 1;
            &ctype0 = &type;
            &child0 = 0;
         Else
            If &level = 1 Then
               If &open1 = 1 Then
                  If &ctype1 = 27 And
                        &child1 = 0 Then
                     throw CreateException(0, 0, "scroll area at level 1 has no child control");
                  End-If;
               End-If;
               &open1 = 1;
               &ctype1 = &type;
               &child1 = 0;
               &seen1 = True;
            Else
               If &level = 2 Then
                  If &open2 = 1 Then
                     If &ctype2 = 27 And
                           &child2 = 0 Then
                        throw CreateException(0, 0, "scroll area at level 2 has no child control");
                     End-If;
                  End-If;
                  &open2 = 1;
                  &ctype2 = &type;
                  &child2 = 0;
                  &seen2 = True;
               Else
                  If &open3 = 1 Then
                     If &ctype3 = 27 And
                           &child3 = 0 Then
                        throw CreateException(0, 0, "scroll area at level 3 has no child control");
                     End-If;
                  End-If;
                  &open3 = 1;
                  &ctype3 = &type;
                  &child3 = 0;
                  &seen3 = True;
               End-If;
            End-If;
         End-If;
         If &type = 19 Then
            REM a grid owns the next &cols controls at the same level and then closes;
            &cols = %This.NthNum(&colsList, &i);
            If &cols < 1 Then
               throw CreateException(0, 0, "grid at control " | String(&i) | " requires GRDCOLUMNCOUNT >= 1");
            End-If;
            &consume = &i + 1;
            &k = 1;
            While &k <= &cols
               If &consume > &n Then
                  throw CreateException(0, 0, "grid at control " | String(&i) | " declares " | String(&cols) | " columns but the list ends");
               End-If;
               &colLevel = %This.NthNum(&levelList, &consume);
               &colType = %This.NthNum(&typeList, &consume);
               If &colLevel <> &level Then
                  throw CreateException(0, 0, "grid column " | String(&consume) | " must share the grid level " | String(&level));
               End-If;
               If &colType <> 4 And
                     &colType <> 5 And
                     &colType <> 12 Then
                  throw CreateException(0, 0, "grid column " | String(&consume) | " must be an edit box, drop-down or button");
               End-If;
               &consume = &consume + 1;
               &k = &k + 1;
            End-While;
            If &level = 0 Then
               &open0 = 0;
            Else
               If &level = 1 Then
                  &open1 = 0;
               Else
                  If &level = 2 Then
                     &open2 = 0;
                  Else
                     &open3 = 0;
                  End-If;
               End-If;
            End-If;
            &curLevel = &level;
            &i = &consume;
         Else
            &curLevel = &level;
            &i = &i + 1;
         End-If;
      Else
         REM leaf;
         If &level = 0 Then
            If &open0 = 1 Then
               &child0 = &child0 + 1;
            End-If;
         Else
            If &level = 1 Then
               If &open1 = 1 Then
                  &child1 = &child1 + 1;
               Else
                  If Not &seen1 Then
                     throw CreateException(0, 0, "control " | String(&i) | " at level 1 has no container at that level");
                  End-If;
               End-If;
            Else
               If &level = 2 Then
                  If &open2 = 1 Then
                     &child2 = &child2 + 1;
                  Else
                     If Not &seen2 Then
                        throw CreateException(0, 0, "control " | String(&i) | " at level 2 has no container at that level");
                     End-If;
                  End-If;
               Else
                  If &open3 = 1 Then
                     &child3 = &child3 + 1;
                  Else
                     If Not &seen3 Then
                        throw CreateException(0, 0, "control " | String(&i) | " at level 3 has no container at that level");
                     End-If;
                  End-If;
               End-If;
            End-If;
         End-If;
         &curLevel = &level;
         &i = &i + 1;
      End-If;
   End-While;
   If &open0 = 1 And
         &ctype0 = 27 And
         &child0 = 0 Then
      throw CreateException(0, 0, "scroll area at level 0 has no child control");
   End-If;
   If &open1 = 1 And
         &ctype1 = 27 And
         &child1 = 0 Then
      throw CreateException(0, 0, "scroll area at level 1 has no child control");
   End-If;
   If &open2 = 1 And
         &ctype2 = 27 And
         &child2 = 0 Then
      throw CreateException(0, 0, "scroll area at level 2 has no child control");
   End-If;
   If &open3 = 1 And
         &ctype3 = 27 And
         &child3 = 0 Then
      throw CreateException(0, 0, "scroll area at level 3 has no child control");
   End-If;
end-method;


method ApplyStructureCli
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &Resp;
   Local C_JSON_API:JSONObject &Item;
   Local C_JSON_API:JSONObject &Raw;
   Local C_JSON_API:JSONObject &PageIn;
   Local C_JSON_API:JSONArray &FieldsArr;
   Local C_JSON_API:JSONArray &BtnArr;
   Local Record &PageRec;
   Local Record &FldRec;
   Local Record &ExtRec;
   Local Record &CtlRec;
   Local Record &BtnRec;
   Local SQL &cur;
   Local integer &i, &j, &k, &n, &type, &level, &cnt, &exists, &pos, &cols, &curLevel, &consume, &extRows;
   Local number &pnlId, &maxId, &delCount, &existingId, &assoc;
   Local string &mode, &itemId, &key, &recName, &fieldName, &pnlIdList, &editTable;
   Local string &typeList, &levelList, &colsList, &finalIdList;
   Local boolean &deleteUnlisted, &dup, &hasPageIn, &isNew;

   &Resp = CreateObject("C_JSON_API:Factory").NewObject();
   &mode = "sync";
   If &p_obj.IsExist("mode") Then
      &mode = &p_obj.GetString("mode");
   End-If;
   If &mode <> "create" And
         &mode <> "sync" Then
      throw CreateException(0, 0, "mode must be create or sync");
   End-If;
   &deleteUnlisted = False;
   If &p_obj.IsExist("deleteUnlisted") Then
      &deleteUnlisted = &p_obj.GetBoolean("deleteUnlisted");
   End-If;
   If Not &p_obj.IsExist("fields") Or
         Not &p_obj.IsJsonArray("fields") Then
      throw CreateException(0, 0, "fields array is required");
   End-If;
   &FieldsArr = &p_obj.GetJsonArray("fields");
   &n = &FieldsArr.Size;
   If &n > 500 Then
      throw CreateException(0, 0, "too many controls in one request");
   End-If;

   REM ---- 1. validate every control ----;
   &pnlIdList = ",";
   &typeList = ",";
   &levelList = ",";
   &colsList = ",";
   For &i = 1 To &n
      &Item = &FieldsArr.GetJsonObject(&i);
      If &Item = Null Then
         throw CreateException(0, 0, "fields[" | String(&i) | "] must be an object");
      End-If;
      For &k = 1 To &Item.ChildCount
         &key = &Item.GetPropertyNameAt(&k);
         If &key <> "id" And
               &key <> "pnlFldId" And
               &key <> "raw" And
               &key <> "ext" And
               &key <> "cntrldata" And
               &key <> "btndata" Then
            throw CreateException(0, 0, "unknown control property: " | &key);
         End-If;
      End-For;
      If Not &Item.IsExist("id") Then
         throw CreateException(0, 0, "fields[" | String(&i) | "] requires id");
      End-If;
      &itemId = &Item.GetString("id");
      If Len(&itemId) = 0 Or
            Len(&itemId) > 64 Then
         throw CreateException(0, 0, "control id length must be 1..64");
      End-If;
      &dup = False;
      For &k = 1 To &i - 1
         If &FieldsArr.GetJsonObject(&k).GetString("id") = &itemId Then
            &dup = True;
         End-If;
      End-For;
      If &dup Then
         throw CreateException(0, 0, "duplicate control id: " | &itemId);
      End-If;
      If Not &Item.IsExist("raw") Or
            Not &Item.IsJsonObject("raw") Then
         throw CreateException(0, 0, "control requires a raw object: " | &itemId);
      End-If;
      &Raw = &Item.GetJsonObject("raw");
      If Not &Raw.IsExist("FIELDTYPE") Then
         throw CreateException(0, 0, "control requires FIELDTYPE: " | &itemId);
      End-If;
      &type = %This.NumOf(&Raw, "FIELDTYPE");
      If &type <> 4 And
            &type <> 5 And
            &type <> 12 And
            &type <> 2 And
            &type <> 19 And
            &type <> 23 And
            &type <> 27 Then
         throw CreateException(0, 0, "unsupported FIELDTYPE " | String(&type) | " for " | &itemId);
      End-If;
      &level = 0;
      If &Raw.IsExist("OCCURSLEVEL") Then
         &level = %This.NumOf(&Raw, "OCCURSLEVEL");
      End-If;
      If &level < 0 Or
            &level > 3 Then
         throw CreateException(0, 0, "OCCURSLEVEL must be 0..3: " | &itemId);
      End-If;
      &recName = "";
      &fieldName = "";
      If &Raw.IsExist("RECNAME") Then
         &recName = &Raw.GetAsString("RECNAME");
      End-If;
      If &Raw.IsExist("FIELDNAME") Then
         &fieldName = &Raw.GetAsString("FIELDNAME");
      End-If;
      &cols = 0;
      If &Raw.IsExist("GRDCOLUMNCOUNT") Then
         &cols = %This.NumOf(&Raw, "GRDCOLUMNCOUNT");
      End-If;
      If &type = 4 Or
            &type = 5 Or
            &type = 12 Or
            &type = 2 Then
         If &recName = "" Or
               &fieldName = "" Then
            throw CreateException(0, 0, "control requires RECNAME and FIELDNAME: " | &itemId);
         End-If;
         &cnt = 0;
         SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE RECNAME=:1 AND FIELDNAME=:2", &recName, &fieldName, &cnt);
         If &cnt <> 1 Then
            throw CreateException(0, 0, "record field not found: " | &recName | "." | &fieldName);
         End-If;
      Else
         If &type = 19 Then
            If &recName = "" Then
               throw CreateException(0, 0, "grid requires RECNAME: " | &itemId);
            End-If;
            &cnt = 0;
            SQLExec("SELECT COUNT(*) FROM PSRECDEFN WHERE RECNAME=:1", &recName, &cnt);
            If &cnt <> 1 Then
               throw CreateException(0, 0, "grid record not found: " | &recName);
            End-If;
            If &cols < 1 Then
               throw CreateException(0, 0, "grid requires GRDCOLUMNCOUNT >= 1: " | &itemId);
            End-If;
         Else
            If &type = 27 Then
               If &recName <> "" Then
                  &cnt = 0;
                  SQLExec("SELECT COUNT(*) FROM PSRECDEFN WHERE RECNAME=:1", &recName, &cnt);
                  If &cnt <> 1 Then
                     throw CreateException(0, 0, "scroll record not found: " | &recName);
                  End-If;
               End-If;
            Else
               If &recName <> "" Or
                     &fieldName <> "" Then
                  throw CreateException(0, 0, "horizontalRule cannot bind a record or field");
               End-If;
            End-If;
         End-If;
      End-If;
      &pnlId = 0;
      If &Item.IsExist("pnlFldId") Then
         &pnlId = %This.NumOf(&Item, "pnlFldId");
         If &pnlId < 1 Then
            &pnlId = 0;
         End-If;
      End-If;
      If &mode = "create" And
            &pnlId <> 0 Then
         throw CreateException(0, 0, "pnlFldId must be omitted when creating a page");
      End-If;
      If &pnlId <> 0 Then
         If Find("," | String(&pnlId) | ",", &pnlIdList) > 0 Then
            throw CreateException(0, 0, "duplicate pnlFldId in request: " | String(&pnlId));
         End-If;
      End-If;
      &pnlIdList = &pnlIdList | String(&pnlId) | ",";
      &typeList = &typeList | String(&type) | ",";
      &levelList = &levelList | String(&level) | ",";
      &colsList = &colsList | String(&cols) | ",";
   End-For;

   REM ---- 2. hierarchy check ----;
   %This.ValidateTree(&typeList, &levelList, &colsList, &n);

   REM ---- 3. page existence ----;
   &exists = 0;
   SQLExec("SELECT COUNT(*) FROM PSPNLDEFN WHERE PNLNAME=:1", &_PageName, &exists);
   If &mode = "create" And
         &exists <> 0 Then
      throw CreateException(0, 0, "page already exists: " | &_PageName);
   End-If;
   If &mode = "sync" And
         &exists = 0 Then
      throw CreateException(0, 0, "Page not exist");
   End-If;
   If &exists <> 0 Then
      For &i = 1 To &n
         &pnlId = %This.NthNum(&pnlIdList, &i);
         If &pnlId <> 0 Then
            &cnt = 0;
            SQLExec("SELECT COUNT(*) FROM PSPNLFIELD WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &pnlId, &cnt);
            If &cnt <> 1 Then
               throw CreateException(0, 0, "control not found on page: pnlFldId=" | String(&pnlId));
            End-If;
         End-If;
      End-For;
   End-If;

   REM ---- 4. page header ----;
   &hasPageIn = False;
   &PageIn = Null;
   If &p_obj.IsExist("page") Then
      If Not &p_obj.IsJsonObject("page") Then
         throw CreateException(0, 0, "page must be an object");
      End-If;
      &PageIn = &p_obj.GetJsonObject("page");
      &hasPageIn = True;
   End-If;
   If &exists = 0 Then
      &PageRec = CreateRecord(Record.PSPNLDEFN);
      &PageRec.PNLNAME.Value = &_PageName;
      &PageRec.VERSION.Value = 1;
      &PageRec.PNLTYPE.Value = 0;
      &PageRec.GetField(Field.FIELDCOUNT).Value = 0;
      &PageRec.MAXPNLFLDID.Value = 0;
      &PageRec.GRIDHORZ.Value = 4;
      &PageRec.GRIDVERT.Value = 4;
      &PageRec.PANELTOP.Value = 0;
      &PageRec.PANELLEFT.Value = 0;
      &PageRec.PANELRIGHT.Value = 728;
      &PageRec.PANELBOTTOM.Value = 367;
      &PageRec.PNLUSE.Value = 0;
      &PageRec.DEFERPROC.Value = 1;
      &PageRec.DESCR.Value = Substring(&_PageName, 1, 30);
      &PageRec.DESCRLONG.Value = "";
      &PageRec.LASTUPDDTTM.Value = %Datetime;
      &PageRec.LASTUPDOPRID.Value = %UserId;
      If &hasPageIn Then
         If Not %This.ApplyRowValues(&PageRec, &PageIn, "PSPNLDEFN") Then
            throw CreateException(0, 0, &_ErrText);
         End-If;
      End-If;
      %This.ValidateStyleName(&PageRec.PNLSTYLE.Value, "PNLSTYLE");
      If Not &PageRec.Insert() Then
         throw CreateException(0, 0, "insert PSPNLDEFN failed");
      End-If;
   Else
      &PageRec = CreateRecord(Record.PSPNLDEFN);
      &PageRec.PNLNAME.Value = &_PageName;
      If Not &PageRec.SelectByKey() Then
         throw CreateException(0, 0, "page disappeared before update");
      End-If;
      If &hasPageIn Then
         If Not %This.ApplyRowValues(&PageRec, &PageIn, "PSPNLDEFN") Then
            throw CreateException(0, 0, &_ErrText);
         End-If;
         %This.ValidateStyleName(&PageRec.PNLSTYLE.Value, "PNLSTYLE");
         If Not &PageRec.Update() Then
            throw CreateException(0, 0, "update PSPNLDEFN failed");
         End-If;
      End-If;
   End-If;

   REM ---- 5. apply controls ----;
   &maxId = 0;
   &finalIdList = ",";
   SQLExec("SELECT NVL(MAXPNLFLDID,0) FROM PSPNLDEFN WHERE PNLNAME=:1", &_PageName, &maxId);
   For &i = 1 To &n
      &Item = &FieldsArr.GetJsonObject(&i);
      &Raw = &Item.GetJsonObject("raw");
      &type = %This.NumOf(&Raw, "FIELDTYPE");
      &pnlId = %This.NthNum(&pnlIdList, &i);
      &isNew = False;
      If &pnlId = 0 Then
         &maxId = &maxId + 1;
         &pnlId = &maxId;
         &isNew = True;
      End-If;
      &finalIdList = &finalIdList | String(&pnlId) | ",";
      &FldRec = CreateRecord(Record.PSPNLFIELD);
      &FldRec.PNLNAME.Value = &_PageName;
      &FldRec.PNLFLDID.Value = &pnlId;
      &FldRec.FIELDNUM.Value = &i;
      If Not &isNew Then
         If Not &FldRec.SelectByKey() Then
            throw CreateException(0, 0, "control disappeared: pnlFldId=" | String(&pnlId));
         End-If;
      End-If;
      REM AD baseline: occurs count/offset default to 1/20 for new controls only;
      If &isNew Then
         &FldRec.GetField(Field.OCCURSCOUNT1).Value = 1;
         &FldRec.GetField(Field.OCCURSOFFSET1).Value = 20;
         &FldRec.GetField(Field.OCCURSCOUNT2).Value = 1;
         &FldRec.GetField(Field.OCCURSOFFSET2).Value = 20;
         &FldRec.GetField(Field.OCCURSCOUNT3).Value = 1;
         &FldRec.GetField(Field.OCCURSOFFSET3).Value = 20;
      End-If;
      If Not %This.ApplyRowValues(&FldRec, &Raw, "PSPNLFIELD") Then
         throw CreateException(0, 0, &_ErrText);
      End-If;
      &FldRec.FIELDNUM.Value = &i;
      If &type = 4 Or
            &type = 5 Then
         %This.ResolveDefaultLabel(&FldRec);
      End-If;
      %This.ValidateStyleName(&FldRec.FIELDSTYLE.Value, "FIELDSTYLE");
      %This.ValidateStyleName(&FldRec.LABELSTYLE.Value, "LABELSTYLE");
      If &type = 19 Then
         %This.ValidateStyleName(&FldRec.GRDODDROWSTYLE.Value, "GRDODDROWSTYLE");
         %This.ValidateStyleName(&FldRec.GRDEVENROWSTYLE.Value, "GRDEVENROWSTYLE");
         %This.ValidateStyleName(&FldRec.GRDACTIVETABSTYLE.Value, "GRDACTIVETABSTYLE");
         %This.ValidateStyleName(&FldRec.GRDINACTIVETABSTYL.Value, "GRDINACTIVETABSTYL");
         %This.ValidateStyleName(&FldRec.GRDNAVBARSTYLE.Value, "GRDNAVBARSTYLE");
         %This.ValidateStyleName(&FldRec.GRDLABELSTYLE.Value, "GRDLABELSTYLE");
      End-If;
      If &FldRec.PNLFIELDNAME.Value <> "" Then
         If Len(&FldRec.PNLFIELDNAME.Value) > 18 Then
            throw CreateException(0, 0, "PNLFIELDNAME maximum length is 18: " | &FldRec.PNLFIELDNAME.Value);
         End-If;
      End-If;
      &assoc = &FldRec.ASSOCFIELDNUM.Value;
      If &assoc <> 0 Then
         If &assoc < 1 Or
               &assoc > &n Or
               &assoc = &i Then
            throw CreateException(0, 0, "ASSOCFIELDNUM must reference another control: " | String(&assoc));
         End-If;
      End-If;
      If &type = 5 And
            &FldRec.PROMPTFIELD.Value <> "" Then
         &editTable = "";
         SQLExec("SELECT EDITTABLE FROM PSRECFIELD WHERE RECNAME=:1 AND FIELDNAME=:2", &FldRec.RECNAME.Value, &FldRec.FIELDNAME.Value, &editTable);
         If &editTable = "" Then
            throw CreateException(0, 0, "PROMPTFIELD requires a record field with an edit table");
         End-If;
         &cnt = 0;
         SQLExec("SELECT COUNT(*) FROM PSRECFIELD WHERE RECNAME=:1 AND FIELDNAME=:2", &editTable, &FldRec.PROMPTFIELD.Value, &cnt);
         If &cnt <> 1 Then
            throw CreateException(0, 0, "PROMPTFIELD is not in the prompt table: " | &FldRec.PROMPTFIELD.Value);
         End-If;
      End-If;
      If &isNew Then
         If Not &FldRec.Insert() Then
            throw CreateException(0, 0, "insert PSPNLFIELD failed: pnlFldId=" | String(&pnlId));
         End-If;
      Else
         If Not &FldRec.Update() Then
            throw CreateException(0, 0, "update PSPNLFIELD failed: pnlFldId=" | String(&pnlId));
         End-If;
      End-If;
      If &Raw.IsExist("GRDLBLMSGSET") Then
         SQLExec("UPDATE PSPNLFIELD SET GRDLBLMSGSET=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("GRDLBLMSGSET")), &_PageName, &pnlId);
      End-If;
      If &Raw.IsExist("GRDLBLMSGNUM") Then
         SQLExec("UPDATE PSPNLFIELD SET GRDLBLMSGNUM=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("GRDLBLMSGNUM")), &_PageName, &pnlId);
      End-If;
      If &Raw.IsExist("EDITLBLLEFT") Then
         SQLExec("UPDATE PSPNLFIELD SET EDITLBLLEFT=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("EDITLBLLEFT")), &_PageName, &pnlId);
      End-If;
      If &Raw.IsExist("EDITLBLTOP") Then
         SQLExec("UPDATE PSPNLFIELD SET EDITLBLTOP=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("EDITLBLTOP")), &_PageName, &pnlId);
      End-If;
      If &Raw.IsExist("EDITLBLRIGHT") Then
         SQLExec("UPDATE PSPNLFIELD SET EDITLBLRIGHT=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("EDITLBLRIGHT")), &_PageName, &pnlId);
      End-If;
      If &Raw.IsExist("EDITLBLBOTTOM") Then
         SQLExec("UPDATE PSPNLFIELD SET EDITLBLBOTTOM=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Raw.GetAsString("EDITLBLBOTTOM")), &_PageName, &pnlId);
      End-If;
      &extRows = 0;
      &ExtRec = CreateRecord(Record.PSPNLFIELDEXT);
      &ExtRec.PNLNAME.Value = &_PageName;
      &ExtRec.PNLFLDID.Value = &pnlId;
      If &ExtRec.SelectByKey() Then
         &extRows = 1;
      End-If;
      If &extRows = 0 Then
         &ExtRec = CreateRecord(Record.PSPNLFIELDEXT);
         &ExtRec.PNLNAME.Value = &_PageName;
         &ExtRec.PNLFLDID.Value = &pnlId;
         &ExtRec.PARENTPNLFLDID.Value = &_PageName | "$0";
         &ExtRec.PAGEPNLFLDID.Value = &_PageName | "$0";
         If &type = 27 Or
               &type = 23 Then
            &ExtRec.FFSTYLELONG.Value = " ";
         Else
            &ExtRec.FFSTYLELONG.Value = " | | | | ";
         End-If;
      End-If;
      If &Item.IsExist("ext") Then
         If Not %This.ApplyRowValues(&ExtRec, &Item.GetJsonObject("ext"), "PSPNLFIELDEXT") Then
            throw CreateException(0, 0, &_ErrText);
         End-If;
      End-If;
      If &extRows = 0 Then
         If Not &ExtRec.Insert() Then
            throw CreateException(0, 0, "insert PSPNLFIELDEXT failed: pnlFldId=" | String(&pnlId));
         End-If;
      Else
         If &Item.IsExist("ext") Then
            If Not &ExtRec.Update() Then
               throw CreateException(0, 0, "update PSPNLFIELDEXT failed: pnlFldId=" | String(&pnlId));
            End-If;
         End-If;
      End-If;
      If &Item.IsExist("cntrldata") Then
         &CtlRec = CreateRecord(Record.PSPNLCNTRLDATA);
         &CtlRec.PNLNAME.Value = &_PageName;
         &CtlRec.PNLFLDID.Value = &pnlId;
         &extRows = 0;
         If &CtlRec.SelectByKey() Then
            &extRows = 1;
         End-If;
         If &extRows = 0 Then
            &CtlRec = CreateRecord(Record.PSPNLCNTRLDATA);
            &CtlRec.PNLNAME.Value = &_PageName;
            &CtlRec.PNLFLDID.Value = &pnlId;
         End-If;
         If Not %This.ApplyRowValues(&CtlRec, &Item.GetJsonObject("cntrldata"), "PSPNLCNTRLDATA") Then
            throw CreateException(0, 0, &_ErrText);
         End-If;
         If &extRows = 0 Then
            If Not &CtlRec.Insert() Then
               throw CreateException(0, 0, "insert PSPNLCNTRLDATA failed: pnlFldId=" | String(&pnlId));
            End-If;
         Else
            If Not &CtlRec.Update() Then
               throw CreateException(0, 0, "update PSPNLCNTRLDATA failed: pnlFldId=" | String(&pnlId));
            End-If;
         End-If;
         If &Item.GetJsonObject("cntrldata").IsExist("PTGRDLAYOUT") Then
            SQLExec("UPDATE PSPNLCNTRLDATA SET PTGRDLAYOUT=:1 WHERE PNLNAME=:2 AND PNLFLDID=:3", Value(&Item.GetJsonObject("cntrldata").GetAsString("PTGRDLAYOUT")), &_PageName, &pnlId);
         End-If;
      End-If;
      If &Item.IsExist("btndata") Then
         SQLExec("DELETE FROM PSPNLBTNDATA WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &pnlId);
         &BtnArr = &Item.GetJsonArray("btndata");
         For &k = 1 To &BtnArr.Size
            &BtnRec = CreateRecord(Record.PSPNLBTNDATA);
            &BtnRec.PNLNAME.Value = &_PageName;
            &BtnRec.PNLFLDID.Value = &pnlId;
            If Not %This.ApplyRowValues(&BtnRec, &BtnArr.GetJsonObject(&k), "PSPNLBTNDATA") Then
               throw CreateException(0, 0, &_ErrText);
            End-If;
            If Not &BtnRec.Insert() Then
               throw CreateException(0, 0, "insert PSPNLBTNDATA failed: pnlFldId=" | String(&pnlId));
            End-If;
         End-For;
      End-If;
   End-For;

   REM ---- 6. remove unlisted controls ----;
   &delCount = 0;
   SQLExec("SELECT COUNT(*) FROM PSPNLFIELD WHERE PNLNAME=:1 AND INSTR(:2, ',' || TO_CHAR(PNLFLDID) || ',') = 0", &_PageName, &finalIdList, &delCount);
   If &delCount > 0 Then
      If Not &deleteUnlisted Then
         throw CreateException(0, 0, String(&delCount) | " controls are not listed; pass deleteUnlisted=true to remove them");
      End-If;
      &cur = CreateSQL("SELECT PNLFLDID FROM PSPNLFIELD WHERE PNLNAME=:1 AND INSTR(:2, ',' || TO_CHAR(PNLFLDID) || ',') = 0 ORDER BY FIELDNUM", &_PageName, &finalIdList);
      While &cur.Fetch(&existingId)
         %This.DeleteControlRows(&existingId);
      End-While;
   End-If;

   REM ---- 7. counters ----;
   &maxId = 0;
   SQLExec("SELECT NVL(MAX(PNLFLDID),0) FROM PSPNLFIELD WHERE PNLNAME=:1", &_PageName, &maxId);
   SQLExec("UPDATE PSPNLDEFN SET FIELDCOUNT=:1, MAXPNLFLDID=:2 WHERE PNLNAME=:3", &n, &maxId, &_PageName);
   %This.TouchVersion();

   &Resp.AddProperty("pageName", &_PageName);
   &Resp.AddProperty("mode", &mode);
   &Resp.AddProperty("fieldCount", &n);
   &Resp.AddProperty("deleted", &delCount);
   &Resp.AddProperty("pnlFldIds", &finalIdList);
   Return &Resp;
end-method;



method NthNum
   /+ &list as String, +/
   /+ &idx as Integer +/
   /+ Returns Number +/
   Local integer &i, &p, &q;
   Local string &token;
   &p = 1;
   If Substring(&list, 1, 1) = "," Then
      &p = 2;
   End-If;
   For &i = 1 To &idx
      &q = Find(",", &list, &p);
      If &q = 0 Then
         Return 0;
      End-If;
      If &i = &idx Then
         &token = Substring(&list, &p, &q - &p);
         If &token = "" Then
            Return 0;
         End-If;
         Return Value(&token);
      End-If;
      &p = &q + 1;
   End-For;
   Return 0;
end-method;


method LoadMeta
   /+ &metaTable as String +/
   Local SQL &cur;
   Local string &n, &k;
   Local number &l;
   If &_MetaTable = &metaTable Then
      Return;
   End-If;
   &_MetaTable = &metaTable;
   &_MetaNames = CreateArrayRept("", 0);
   &_MetaKinds = CreateArrayRept("", 0);
   &_MetaLens = CreateArrayRept(0, 0);
   &cur = CreateSQL("SELECT COLUMN_NAME, DATA_TYPE, NVL(DATA_LENGTH,0) FROM USER_TAB_COLUMNS WHERE TABLE_NAME=:1 ORDER BY COLUMN_ID", &metaTable);
   While &cur.Fetch(&n, &k, &l)
      &_MetaNames.Push(&n);
      &_MetaKinds.Push(&k);
      &_MetaLens.Push(&l);
   End-While;
   Local integer &metaCount;
   &metaCount = 0;
   try
      &metaCount = &_MetaNames.Len;
   catch Exception &e
      &metaCount = 0;
   end-try;
   If &metaCount = 0 Then
      throw CreateException(0, 0, "cannot read column metadata for " | &metaTable);
   End-If;
end-method;


method ApplyRowValues
   /+ &rec as Record, +/
   /+ &values as C_JSON_API:JSONObject, +/
   /+ &metaTable as String +/
   /+ Returns Boolean +/
   Local integer &i, &j, &metaPos;
   Local string &name, &val, &kind;
   Local number &num, &maxLen;
   Local Field &fld;
   Local boolean &found, &skipAssign;

   %This.LoadMeta(&metaTable);
   For &i = 1 To &values.ChildCount
      &name = &values.GetPropertyNameAt(&i);
      If &metaTable = "PSPNLFIELDEXT" And
            (&name = "PARENTPNLFLDID" Or
               &name = "PAGEPNLFLDID") Then
         &_ErrText = "column is derived from the page name: " | &name;
         Return False;
      End-If;
      If &name = "PNLNAME" Or
            &name = "PNLFLDID" Or
            &name = "FIELDNUM" Or
            &name = "VERSION" Or
            &name = "LASTUPDDTTM" Or
            &name = "LASTUPDOPRID" Or
            &name = "FIELDCOUNT" Or
            &name = "MAXPNLFLDID" Then
         &_ErrText = "column is managed by the API: " | &name;
         Return False;
      End-If;
      &metaPos = 0;
      For &j = 1 To &_MetaNames.Len
         If &_MetaNames [&j] = &name Then
            &metaPos = &j;
            Break;
         End-If;
      End-For;
      If &metaPos = 0 Then
         &_ErrText = "unknown column for " | &metaTable | ": " | &name;
         Return False;
      End-If;
      &kind = &_MetaKinds [&metaPos];
      &maxLen = &_MetaLens [&metaPos];
      &found = False;
      For &j = 1 To &rec.FieldCount
         If &rec.GetField(&j).Name = &name Then
            &fld = &rec.GetField(&j);
            &found = True;
            Break;
         End-If;
      End-For;
      If Not &found Then
         &_ErrText = "column not part of record " | &metaTable | ": " | &name;
         Return False;
      End-If;
      &val = &values.GetAsString(&name);
      If &kind = "NUMBER" Then
         try
            &num = Value(&val);
         catch Exception &ex
            &_ErrText = &name | " requires a numeric value";
            Return False;
         end-try;
         &skipAssign = False;
         If &name = "GRDLBLMSGSET" Or
               &name = "GRDLBLMSGNUM" Then
            &skipAssign = True;
         End-If;
         If &name = "EDITLBLLEFT" Or
               &name = "EDITLBLTOP" Or
               &name = "EDITLBLRIGHT" Or
               &name = "EDITLBLBOTTOM" Or
               &name = "PTGRDLAYOUT" Then
            If &num < 0 Then
               &skipAssign = True;
            End-If;
         End-If;
         If Not &skipAssign Then
            &fld.Value = &num;
         End-If;
      Else
         If &kind = "DATE" Or
               &kind = "TIMESTAMP(6)" Then
            &_ErrText = "date columns are not writable: " | &name;
            Return False;
         End-If;
         If (&kind = "CHAR" Or
               &kind = "VARCHAR2") And
               Len(&val) > &maxLen Then
            &_ErrText = &name | " exceeds column length " | String(&maxLen);
            Return False;
         End-If;
         &fld.Value = &val;
      End-If;
   End-For;
   Return True;
end-method;





method DeleteControlRows
   /+ &id as Number +/
   SQLExec("DELETE FROM PSPNLFIELDEXT WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLCNTRLDATA WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLCTLDATALNG WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLBTNDATA WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLBTNLANG WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLFIELDLANG WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLHTMLAREA WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLHTMLLANG WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
   SQLExec("DELETE FROM PSPNLFIELD WHERE PNLNAME=:1 AND PNLFLDID=:2", &_PageName, &id);
end-method;


method NumOf
   /+ &obj as C_JSON_API:JSONObject, +/
   /+ &name as String +/
   /+ Returns Number +/
   Local number &v;
   try
      &v = Value(&obj.GetAsString(&name));
   catch Exception &ex
      throw CreateException(0, 0, "numeric value required: " | &name);
   end-try;
   Return &v;
end-method;


method GetControlCntrlData
   /+ &id as Number +/
   /+ Returns C_JSON_API:JSONObject +/
   Local Record &rec;
   &rec = CreateRecord(Record.PSPNLCNTRLDATA);
   &rec.PNLNAME.Value = &_PageName;
   &rec.PNLFLDID.Value = &id;
   If Not &rec.SelectByKey() Then
      Return CreateObject("C_JSON_API:Factory").NewObject();
   End-If;
   Return %This.BuildRawObject(&rec);
end-method;


method GetControlBtnData
   /+ &id as Number +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &arr;
   Local C_JSON_API:JSONObject &obj;
   Local Rowset &rs;
   Local Record &rec;
   Local integer &n, &i, &j;
   &arr = CreateObject("C_JSON_API:Factory").NewArray();
   &rs = CreateRowset(Record.PSPNLBTNDATA);
   &rs.Flush();
   &n = &rs.Fill(" WHERE PNLNAME = :1 AND PNLFLDID = :2", &_PageName, &id);
   &rs.Sort(PSPNLBTNDATA.PTBTNCLASSTYPE, "A");
   For &i = 1 To &n
      &rec = &rs(&i).GetRecord(1);
      &obj = CreateObject("C_JSON_API:Factory").NewObject();
      For &j = 1 To &rec.FieldCount
         &obj.AddProperty(&rec.GetField(&j).Name, &rec.GetField(&j).Value);
      End-For;
      &arr.AddJsonObjectElement("", &obj);
      &obj = &arr.GetJsonObject(&arr.Size);
   End-For;
   Return &arr;
end-method;


method ResolveDefaultLabel
   /+ &rec as Record +/
   Local number &cnt;
   Local string &lblId, &lblText;
   If &rec.USEDEFAULTLABEL.Value <> "1" Or
         &rec.LABEL_ID.Value <> "" Then
      Return;
   End-If;
   &cnt = 0;
   SQLExec("SELECT COUNT(*) FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &rec.FIELDNAME.Value, &cnt);
   If &cnt <> 1 Then
      throw CreateException(0, 0, "unable to resolve one default label for " | &rec.FIELDNAME.Value);
   End-If;
   &lblId = "";
   &lblText = "";
   SQLExec("SELECT LABEL_ID,LONGNAME FROM PSDBFLDLABL WHERE FIELDNAME=:1 AND DEFAULT_LABEL=1", &rec.FIELDNAME.Value, &lblId, &lblText);
   &rec.LABEL_ID.Value = &lblId;
   &rec.LBLTEXT.Value = &lblText;
end-method;


method ValidateStyleName
   /+ &columnValue as String, +/
   /+ &columnLabel as String +/
   Local number &cnt;
   If &columnValue = "" Then
      Return;
   End-If;
   &cnt = 0;
   SQLExec("SELECT COUNT(*) FROM PSSTYLEDEFN WHERE STYLENAME=:1", &columnValue, &cnt);
   If &cnt <> 1 Then
      throw CreateException(0, 0, &columnLabel | " references an unknown style: " | &columnValue);
   End-If;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import C_META_DATA_PKG:Utility:NativeAdapter;
import C_META_DATA_PKG:Utility:ManagedVersion;

class CoreOperPortalRegistry
   method CoreOperPortalRegistry();
   method Execute(&message As Message, &responseOperation As string) Returns Message;
end-class;

method CoreOperPortalRegistry
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   Local C_META_DATA_PKG:Utility:ManagedVersion &guard = create C_META_DATA_PKG:Utility:ManagedVersion();
   Local C_JSON_API:JSONObject &req, &result;
   try
      &req = &json.GetRootObject(&message.GetContentString());
      If Not &req.IsExist("operationType") Or
            Not &req.IsExist("kind") Then
         throw CreateException(0, 0, "operationType and kind are required");
      End-If;
      If &req.GetString("kind") <> "portal" Then
         throw CreateException(0, 0, "Kind is not supported by this endpoint");
      End-If;
      &result = &guard.Run(&req);
      Return &json.CreateSuccessMessage(&responseOperation, &result);
   catch Exception &ex
      SQLExec("rollback");
      Return &json.CreateFailedMessage(&responseOperation, &guard.Status, &ex.ToString());
   end-try;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_META_DATA_PKG:Utility:DefinitionVersion;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import %metadata:*;
import %metadata:ProjectDefn:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;

/* 操作Project定义(PSPROJECTDEFN/PSPROJECTITEM)的IB Handler */
class CoreOperProjectDefn
   method CoreOperProjectDefn();

   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   method VersionRows(&rows As Rowset, &where As string, &name As string) Returns string;
   method DefinitionVersion(&name As string) Returns string;
   method LockDefinition(&name As string);
   method CreateProject(&p_projectName As string, &p_descr As string, &p_descrLong As string) Returns boolean;
   method InsertProjectItem(&p_projectName As string, &p_objectType As integer, &p_objectValue1 As string, &p_objectValue2 As string, &p_objectValue3 As string, &p_objectValue4 As string, &p_upgradeAction As integer, &p_takeAction As integer) Returns boolean;
   method ModifyProject(&p_projectName As string, &p_descr As string, &p_descrLong As string, &p_hasDescr As boolean, &p_hasComment As boolean, &p_adDefaults As boolean) Returns boolean;
   method TouchProject(&p_projectName As string) Returns boolean;
   method ViewProjectStruct(&p_projectName As string) Returns C_JSON_API:JSONObject;
   method MaintainProjectItem(&p_obj As C_JSON_API:JSONObject, &p_delete As boolean) Returns boolean;
   method ValidateProjectAction(&p_objectType As number, &p_upgradeAction As number) Returns boolean;


   instance string &_errText;
   instance boolean &_reinserted;
   instance boolean &_itemChanged;
   instance C_JSON_API:JsonUtil &JsonUtil;
   instance C_COMMONS_PKG:CommonUtil &CommUtil;
end-class;

method CoreOperProjectDefn
   &_errText = "";
   &JsonUtil = create C_JSON_API:JsonUtil();
   &CommUtil = create C_COMMONS_PKG:CommonUtil();
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local Message &RespMsg;
   Local C_JSON_API:JSONObject &ReqObject, &RespObject;
   Local string &OperationType, &ProjectName, &Descr, &DescrLong;
   Local string &ObjectValue1, &ObjectValue2, &ObjectValue3, &ObjectValue4;
   Local integer &ObjectType, &UpgradeAction, &TakeAction;
   Local boolean &Result;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &beforeVersion, &afterVersion;
   Local integer &status;
   Local boolean &writing, &dry;


   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());
      &RespObject = CreateObject("C_JSON_API:Factory").NewObject();

      If Not &ReqObject.IsExist("projectName") Then
         &_errText = &_errText | "projectName is required";
      End-If;

      If &_errText <> "" Then
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
         Return &RespMsg;
      End-If;

      &ProjectName = &ReqObject.GetString("projectName");
      If None(&ProjectName) Or
            Len(&ProjectName) > 30 Then
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, "projectName must contain 1 to 30 characters");
         Return &RespMsg;
      End-If;
      If &ReqObject.IsExist("descr") Then
         If Len(&ReqObject.GetString("descr")) > 30 Then
            SQLExec("rollback");
            &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, "descr must not exceed 30 characters");
            Return &RespMsg;
         End-If;
      End-If;
      &TakeAction = 1;

      If &ReqObject.IsExist("operationType") Then
         &OperationType = &ReqObject.GetString("operationType");
      Else
         &OperationType = "createProject";
      End-If;

      Local array of string &allowed = CreateArray("struct", "createProject", "modifyProject", "insertItem", "updateItem", "deleteItem");
      If &allowed.Find(&OperationType) = 0 Then
         Return &JsonUtil.CreateFailedMessage(&responseOperation, 400, "Unsupported operationType");
      End-If;
      &writing = (&OperationType <> "struct");
      &dry = False;
      If &ReqObject.IsExist("dryRun") Then
         &dry = &ReqObject.GetBoolean("dryRun");
      End-If;
      If &writing Then
         %This.LockDefinition(&ProjectName);
      End-If;
      &beforeVersion = %This.DefinitionVersion(&ProjectName);
      If &writing Then
         &status = &guard.Check(&ReqObject, &beforeVersion);
         If &status <> 0 Then
            SQLExec("rollback");
            Return &JsonUtil.CreateFailedMessage(&responseOperation, &status, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original snapshot");
         End-If;
      End-If;
      &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
      Evaluate &OperationType
      When "createProject"
         /* 创建Project */
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("comment") Then
            &DescrLong = &ReqObject.GetString("comment");
            &DescrLong = &CommUtil.UnEscapeJSON(&DescrLong);
         End-If;
         &Result = %This.CreateProject(&ProjectName, &Descr, &DescrLong);
         &RespObject.AddProperty("projectName", &ProjectName);
         &RespObject.AddProperty("created", &Result);
         Break;
      When "insertItem"
         /* 插入定义到Project */
         If Not &ReqObject.IsExist("objectType") Then
            &_errText = &_errText | "objectType is required";
         End-If;
         If &_errText <> "" Then
            SQLExec("rollback");
            &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
            Return &RespMsg;
         End-If;
         &ObjectType = &ReqObject.GetNumber("objectType");
         If &ReqObject.GetNumber("objectType") < 0 Or
               &ReqObject.GetNumber("objectType") <> Int(&ReqObject.GetNumber("objectType")) Then
            &_errText = "objectType must be a nonnegative integer";
            Break;
         End-If;
         If &ReqObject.IsExist("objectValue1") Then
            &ObjectValue1 = &ReqObject.GetString("objectValue1");
         End-If;
         If &ReqObject.IsExist("objectValue2") Then
            &ObjectValue2 = &ReqObject.GetString("objectValue2");
         End-If;
         If &ReqObject.IsExist("objectValue3") Then
            &ObjectValue3 = &ReqObject.GetString("objectValue3");
         End-If;
         If &ReqObject.IsExist("objectValue4") Then
            &ObjectValue4 = &ReqObject.GetString("objectValue4");
         End-If;
         If &ReqObject.IsExist("upgradeAction") Then
            If Not %This.ValidateProjectAction(&ReqObject.GetNumber("objectType"), &ReqObject.GetNumber("upgradeAction")) Then
               SQLExec("rollback");
               &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
               Return &RespMsg;
            End-If;
            &UpgradeAction = &ReqObject.GetNumber("upgradeAction");
         End-If;
         If &ReqObject.IsExist("takeAction") Then
            If &ReqObject.GetNumber("takeAction") <> 0 And
                  &ReqObject.GetNumber("takeAction") <> 1 Then
               &_errText = "takeAction must be 0 or 1";
               Break;
            End-If;
            &TakeAction = &ReqObject.GetNumber("takeAction");
         End-If;
         &Result = %This.InsertProjectItem(&ProjectName, &ObjectType, &ObjectValue1, &ObjectValue2, &ObjectValue3, &ObjectValue4, &UpgradeAction, &TakeAction);
         &RespObject.AddProperty("projectName", &ProjectName);
         &RespObject.AddProperty("inserted", &Result);
         &RespObject.AddProperty("reinserted", &_reinserted);
         &RespObject.AddProperty("changed", &_itemChanged);
         Break;
      When "updateItem"
         &Result = %This.MaintainProjectItem(&ReqObject, False);
         &RespObject.AddProperty("updated", &Result);
         Break;
      When "deleteItem"
         &Result = %This.MaintainProjectItem(&ReqObject, True);
         &RespObject.AddProperty("deleted", &Result);
         Break;
      When "modifyProject"
         /* 修改Project描述、详细描述 */
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("comment") Then
            &DescrLong = &ReqObject.GetString("comment");
            &DescrLong = &CommUtil.UnEscapeJSON(&DescrLong);
         End-If;
         Local boolean &AdDefaults = False;
         If &ReqObject.IsExist("adDefaults") Then
            &AdDefaults = &ReqObject.GetBoolean("adDefaults");
         End-If;
         &Result = %This.ModifyProject(&ProjectName, &Descr, &DescrLong, &ReqObject.IsExist("descr"), &ReqObject.IsExist("comment"), &AdDefaults);
         &RespObject.AddProperty("projectName", &ProjectName);
         &RespObject.AddProperty("modified", &Result);
         Break;
      When "struct"
         /*** 查看Project结构（条目列表） ***/
         &RespObject = %This.ViewProjectStruct(&ProjectName);
         Break;
      When-Other
         &_errText = &_errText | "Unknown operationType: " | &OperationType | ". Supported: createProject, insertItem, updateItem, deleteItem, modifyProject, struct";
      End-Evaluate;

      If &_errText <> "" Then
         SQLExec("rollback");
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
      Else
         &afterVersion = %This.DefinitionVersion(&ProjectName);
         If Not &writing And
               &beforeVersion <> &afterVersion Then
            SQLExec("rollback");
            Return &JsonUtil.CreateFailedMessage(&responseOperation, 409, "VERSION_CONFLICT: definition changed during read");
         End-If;
         &RespObject.AddProperty("beforeVersion", &beforeVersion);
         &RespObject.AddProperty("version", &afterVersion);
         &RespObject.AddProperty("projectVersionControl", 1);
         If &writing Then
            &RespObject.AddProperty("dryRun", &dry);
            If &dry Then
               SQLExec("rollback");
            Else
               SQLExec("commit");
            End-If;
         End-If;
         &RespMsg = &JsonUtil.CreateSuccessMessage(&responseOperation, &RespObject);
      End-If;
   catch Exception &ex
      SQLExec("rollback");
      SQLExec("rollback");
      &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 500, "Error: " | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method CreateProject
   /+ &p_projectName as String, +/
   /+ &p_descr as String, +/
   /+ &p_descrLong as String +/
   /+ Returns Boolean +/
   Local %metadata:ProjectDefn:ProjectDefn_Manager &manager = create %metadata:ProjectDefn:ProjectDefn_Manager();
   Local %metadata:Key &key = create %metadata:Key(Key:Class_Project, &p_projectName);
   Local %metadata:ProjectDefn:ProjectDefn &defn;
   Local integer &i;
   If Find(Substring(&p_projectName, 1, 1), "ABCDEFGHIJKLMNOPQRSTUVWXYZ") = 0 Then
      &_errText = "Project name must start with an uppercase letter";
      Return False;
   End-If;
   For &i = 1 To Len(&p_projectName)
      If Find(Substring(&p_projectName, &i, 1), "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-") = 0 Then
         &_errText = "Project name contains a character not allowed by Application Designer";
         Return False;
      End-If;
   End-For;
   If &manager.DefnExists(&key) Then
      &_errText = &_errText | "project already exists: " | &p_projectName;
      Return False;
   End-If;
   &defn = &manager.CreateDefn();
   &defn.ProjectName = &p_projectName;
   &defn.LanguageCd = %Language;
   &defn.ProjectDescr = &p_descr;
   &defn.DescrLong = &p_descrLong;
   &defn.KeepTgt = 31;
   &defn.CommitLimit = 50;
   &defn.ReportFilter = 16232832;
   &defn.CompareType = 1;
   If Not &defn.ValidateDefn() Then
      &_errText = "Project validation failed";
      Return False;
   End-If;
   If Not &defn.SaveNewDefn() Then
      &_errText = "Project save failed";
      Return False;
   End-If;
   Return True;
end-method;

method InsertProjectItem
   /+ &p_projectName as String, +/
   /+ &p_objectType as Integer, +/
   /+ &p_objectValue1 as String, +/
   /+ &p_objectValue2 as String, +/
   /+ &p_objectValue3 as String, +/
   /+ &p_objectValue4 as String, +/
   /+ &p_upgradeAction as Integer, +/
   /+ &p_takeAction as Integer +/
   /+ Returns Boolean +/
   Local Record &item = CreateRecord(Record.PSPROJECTITEM);
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &resolver = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   Local array of integer &ids;
   Local array of string &keyValues;
   Local string &exists;
   Local integer &i;
   SQLExec("SELECT 'Y' FROM PSPROJECTDEFN WHERE PROJECTNAME = :1", &p_projectName, &exists);
   If &exists <> "Y" Then
      &_errText = &_errText | "project does not exist: " | &p_projectName;
      Return False;
   End-If;
   If &p_objectValue1 = "" Then
      &_errText = "objectValue1 is required";
      Return False;
   End-If;
   If Len(&p_objectValue1) > 30 Or
         Len(&p_objectValue2) > 30 Or
         Len(&p_objectValue3) > 30 Or
         Len(&p_objectValue4) > 30 Then
      &_errText = "Each Project object value must not exceed 30 characters";
      Return False;
   End-If;
   If &p_objectType = 30 Then
      If &p_objectValue2 = "" Then
         &p_objectValue2 = "0";
      End-If;
      If &p_objectValue2 <> "0" And
            &p_objectValue2 <> "1" And
            &p_objectValue2 <> "2" Then
         &_errText = "SQL objectValue2 must be 0, 1 or 2";
         Return False;
      End-If;
   End-If;
   If &p_takeAction <> 0 And
         &p_takeAction <> 1 Then
      &_errText = "takeAction must be 0 or 1";
      Return False;
   End-If;
   If Not %This.ValidateProjectAction(&p_objectType, &p_upgradeAction) Then
      Return False;
   End-If;
   If &p_objectValue2 = "" Then
      &p_objectValue2 = " ";
   End-If;
   If &p_objectValue3 = "" Then
      &p_objectValue3 = " ";
   End-If;
   If &p_objectValue4 = "" Then
      &p_objectValue4 = " ";
   End-If;
   &keyValues = CreateArray(&p_objectValue1, &p_objectValue2, &p_objectValue3, &p_objectValue4);
   /* Empty resolver slots mean no subkey; keep stored blanks and compound keys intact. */
   For &i = 1 To 4
      If None(&keyValues [&i]) Then
         &keyValues [&i] = "";
      End-If;
   End-For;
   &ids = &resolver.GetObjectIDs(&p_objectType, &keyValues);
   If &p_objectType = 57 And
         &p_upgradeAction <> 1 Then
      Local object &packageManager = CreateObject("%metadata:AppPackageDefn:AppPackageDefn_Manager");
      Local object &packageKey = CreateObject("%metadata:Key", &ids [1], &p_objectValue1);
      ObjectDoMethod(&packageKey, "AddItem", &ids [2], &p_objectValue2);
      ObjectDoMethod(&packageKey, "AddItem", &ids [3], &p_objectValue3);
      If &p_objectValue4 <> " " Or
            Not ObjectDoMethodArray(&packageManager, "DefnExists", CreateArrayAny(&packageKey)) Then
         &_errText = "Application Package key does not reference an existing definition; use Package / Root / Qualify Path, not class path segments";
         Return False;
      End-If;
   End-If;
   &item.GetField(Field.PROJECTNAME).Value = &p_projectName;
   &item.GetField(Field.OBJECTTYPE).Value = &p_objectType;
   &item.GetField(Field.OBJECTVALUE1).Value = &p_objectValue1;
   &item.GetField(Field.OBJECTVALUE2).Value = &p_objectValue2;
   &item.GetField(Field.OBJECTVALUE3).Value = &p_objectValue3;
   &item.GetField(Field.OBJECTVALUE4).Value = &p_objectValue4;
   &_reinserted = &item.SelectByKey();
   &_itemChanged = (&_reinserted = False);
   If Not &_reinserted Then
      /* SelectByKey clears the Record on a miss, including its key fields. */
      &item.GetField(Field.PROJECTNAME).Value = &p_projectName;
      &item.GetField(Field.OBJECTTYPE).Value = &p_objectType;
      &item.GetField(Field.OBJECTVALUE1).Value = &p_objectValue1;
      &item.GetField(Field.OBJECTVALUE2).Value = &p_objectValue2;
      &item.GetField(Field.OBJECTVALUE3).Value = &p_objectValue3;
      &item.GetField(Field.OBJECTVALUE4).Value = &p_objectValue4;
   End-If;
   For &i = 1 To 4
      If &_reinserted And
            &item.GetField(@("Field.OBJECTID" | &i)).Value <> &ids [&i] Then
         &_errText = "Existing Project item has different object IDs at position " | &i | ": stored=" | &item.GetField(@("Field.OBJECTID" | &i)).Value | ", native=" | &ids [&i] | "; remove the exact invalid item before reinserting";
         Return False;
      End-If;
      &item.GetField(@("Field.OBJECTID" | &i)).Value = &ids [&i];
   End-For;
   If &item.GetField(Field.SOURCESTATUS).Value <> 0 Or
         &item.GetField(Field.TARGETSTATUS).Value <> 0 Or
         &item.GetField(Field.UPGRADEACTION).Value <> &p_upgradeAction Or
         &item.GetField(Field.TAKEACTION).Value <> &p_takeAction Or
         &item.GetField(Field.COPYDONE).Value <> 0 Then
      &_itemChanged = True;
   End-If;
   If &_itemChanged Then
      /* Native save loads its item list before the direct row mutation. */
      If Not %This.TouchProject(&p_projectName) Then
         Return False;
      End-If;
      &item.GetField(Field.SOURCESTATUS).Value = 0;
      &item.GetField(Field.TARGETSTATUS).Value = 0;
      &item.GetField(Field.UPGRADEACTION).Value = &p_upgradeAction;
      &item.GetField(Field.TAKEACTION).Value = &p_takeAction;
      &item.GetField(Field.COPYDONE).Value = 0;
      If &_reinserted Then
         If Not &item.Update() Then
            &_errText = "Project item reinsertion failed";
            Return False;
         End-If;
      Else
         &item.GetField(Field.NODETYPE).Value = 0;
         If Not &item.Insert() Then
            &_errText = "Project item insertion failed";
            Return False;
         End-If;
      End-If;

   End-If;
   Return (&_reinserted = False);
end-method;

method ModifyProject
   /+ &p_projectName as String, +/
   /+ &p_descr as String, +/
   /+ &p_descrLong as String, +/
   /+ &p_hasDescr as Boolean, +/
   /+ &p_hasComment as Boolean, +/
   /+ &p_adDefaults as Boolean +/
   /+ Returns Boolean +/
   Local %metadata:ProjectDefn:ProjectDefn_Manager &manager = create %metadata:ProjectDefn:ProjectDefn_Manager();
   Local %metadata:Key &key = create %metadata:Key(Key:Class_Project, &p_projectName);
   Local %metadata:ProjectDefn:ProjectDefn &defn;
   If Not &manager.DefnExists(&key) Then
      &_errText = &_errText | "project does not exist: " | &p_projectName;
      Return False;
   End-If;
   &defn = &manager.GetDefnToUpdate(&key);
   If &p_hasDescr Then
      &defn.ProjectDescr = &p_descr;
   End-If;
   If &p_hasComment Then
      &defn.DescrLong = &p_descrLong;
   End-If;
   If &p_adDefaults Then
      &defn.KeepTgt = 31;
      &defn.CommitLimit = 50;
      &defn.ReportFilter = 16232832;
      &defn.CompareType = 1;
      &defn.TargetOrientation = 0;
   End-If;
   If Not &defn.ValidateDefn() Then
      &_errText = "Project validation failed";
      Return False;
   End-If;
   If Not &defn.UpdateDefn() Then
      &_errText = "Project update failed";
      Return False;
   End-If;
   Return True;
end-method;

method TouchProject
   /+ &p_projectName as String +/
   /+ Returns Boolean +/
   Local %metadata:ProjectDefn:ProjectDefn_Manager &manager = create %metadata:ProjectDefn:ProjectDefn_Manager();
   Local %metadata:Key &key = create %metadata:Key(Key:Class_Project, &p_projectName);
   Local %metadata:ProjectDefn:ProjectDefn &defn = &manager.GetDefnToUpdate(&key);
   If Not &defn.UpdateDefn() Then
      &_errText = "Project header update failed";
      Return False;
   End-If;
   Return True;
end-method;

method ViewProjectStruct
   /+ &p_projectName as String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObject, &Header;
   Local Record &HeaderRecord;
   Local integer &i;
   Local C_JSON_API:JSONArray &Items;
   Local SQL &Sql;
   Local string &Exists, &ObjectValue1, &ObjectValue2, &ObjectValue3, &ObjectValue4;
   Local integer &ObjectType, &ObjectId1, &ObjectId2, &ObjectId3, &ObjectId4, &UpgradeAction, &TakeAction, &CopyDone, &NodeType, &SourceStatus, &TargetStatus;

   &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
   &Items = CreateObject("C_JSON_API:Factory").NewArray();
   &Exists = "";
   SQLExec("SELECT 'Y' FROM PSPROJECTDEFN WHERE PROJECTNAME = :1", &p_projectName, &Exists);
   If &Exists <> "Y" Then
      &RespObject.AddProperty("projectName", &p_projectName);
      &RespObject.AddProperty("exists", False);
      &RespObject.AddJsonArray("items", &Items);
      &Items = &RespObject.GetJsonArray("items");
      Return &RespObject;
   End-If;

   &RespObject.AddProperty("exists", True);
   &Header = CreateObject("C_JSON_API:Factory").NewObject();
   &HeaderRecord = CreateRecord(Record.PSPROJECTDEFN);
   &HeaderRecord.GetField(Field.PROJECTNAME).Value = &p_projectName;
   &HeaderRecord.SelectByKey();
   For &i = 1 To &HeaderRecord.FieldCount
      &Header.AddProperty(&HeaderRecord.GetField(&i).Name, String(&HeaderRecord.GetField(&i).Value));
   End-For;
   &RespObject.AddJsonObject("header", &Header);
   &Header = &RespObject.GetJsonObject("header");
   &Sql = CreateSQL("SELECT OBJECTTYPE, OBJECTID1, OBJECTVALUE1, OBJECTID2, OBJECTVALUE2, OBJECTID3, OBJECTVALUE3, OBJECTID4, OBJECTVALUE4, UPGRADEACTION, TAKEACTION, COPYDONE, NODETYPE, SOURCESTATUS, TARGETSTATUS FROM PSPROJECTITEM WHERE PROJECTNAME = :1 ORDER BY OBJECTTYPE, OBJECTVALUE1, OBJECTVALUE2, OBJECTVALUE3, OBJECTVALUE4", &p_projectName);
   While &Sql.Fetch(&ObjectType, &ObjectId1, &ObjectValue1, &ObjectId2, &ObjectValue2, &ObjectId3, &ObjectValue3, &ObjectId4, &ObjectValue4, &UpgradeAction, &TakeAction, &CopyDone, &NodeType, &SourceStatus, &TargetStatus)
      Local C_JSON_API:JSONObject &ItemObj = CreateObject("C_JSON_API:Factory").NewObject();
      &ItemObj.AddProperty("objectType", &ObjectType);
      &ItemObj.AddProperty("objectId1", &ObjectId1);
      &ItemObj.AddProperty("objectValue1", &ObjectValue1);
      &ItemObj.AddProperty("objectId2", &ObjectId2);
      &ItemObj.AddProperty("objectValue2", &ObjectValue2);
      &ItemObj.AddProperty("objectId3", &ObjectId3);
      &ItemObj.AddProperty("objectValue3", &ObjectValue3);
      &ItemObj.AddProperty("objectId4", &ObjectId4);
      &ItemObj.AddProperty("objectValue4", &ObjectValue4);
      &ItemObj.AddProperty("upgradeAction", &UpgradeAction);
      &ItemObj.AddProperty("takeAction", &TakeAction);
      &ItemObj.AddProperty("copyDone", &CopyDone);
      &ItemObj.AddProperty("nodeType", &NodeType);
      &ItemObj.AddProperty("sourceStatus", &SourceStatus);
      &ItemObj.AddProperty("targetStatus", &TargetStatus);
      &Items.AddJsonObjectElement("", &ItemObj);
      &ItemObj = &Items.GetJsonObject(&Items.Size);
   End-While;

   &RespObject.AddProperty("projectName", &p_projectName);
   &RespObject.AddJsonArray("items", &Items);
   &Items = &RespObject.GetJsonArray("items");
   Return &RespObject;
end-method;


method MaintainProjectItem
   /+ &p_obj as C_JSON_API:JSONObject, +/
   /+ &p_delete as Boolean +/
   /+ Returns Boolean +/
   Local Record &Item;
   Local integer &i;
   Local string &IdName, &ValueName, &Value;
   Local boolean &Saved, &Changed;
   &Item = CreateRecord(Record.PSPROJECTITEM);
   If Not &p_obj.IsExist("objectType") Then
      &_errText = "objectType is required";
      Return False;
   End-If;
   &Item.GetField(Field.PROJECTNAME).Value = &p_obj.GetString("projectName");
   &Item.GetField(Field.OBJECTTYPE).Value = &p_obj.GetNumber("objectType");
   For &i = 1 To 4
      &IdName = "objectId" | &i;
      &ValueName = "objectValue" | &i;
      If Not &p_obj.IsExist(&IdName) Or
            Not &p_obj.IsExist(&ValueName) Then
         &_errText = "All objectId1..4 and objectValue1..4 are required for an exact item key";
         Return False;
      End-If;
      &Item.GetField(@("Field.OBJECTID" | &i)).Value = &p_obj.GetNumber(&IdName);
      &Value = &p_obj.GetString(&ValueName);
      If &Value = "" Then
         &Value = " ";
      End-If;
      &Item.GetField(@("Field.OBJECTVALUE" | &i)).Value = &Value;
   End-For;
   If Not &Item.SelectByKey() Then
      &_errText = "Project item not found for exact key";
      Return False;
   End-If;
   For &i = 1 To 4
      If &Item.GetField(@("Field.OBJECTID" | &i)).Value <> &p_obj.GetNumber("objectId" | &i) Then
         &_errText = "Project item not found for exact object IDs";
         Return False;
      End-If;
   End-For;
   If &p_delete Then
      If Not %This.TouchProject(&p_obj.GetString("projectName")) Then
         Return False;
      End-If;
      &Saved = &Item.Delete();
   Else
      If Not &p_obj.IsExist("takeAction") And
            Not &p_obj.IsExist("upgradeAction") And
            Not &p_obj.IsExist("copyDone") Then
         &_errText = "upgradeAction, takeAction or copyDone is required";
         Return False;
      End-If;
      If &p_obj.IsExist("takeAction") Then
         If &p_obj.GetNumber("takeAction") <> 0 And
               &p_obj.GetNumber("takeAction") <> 1 Then
            &_errText = "takeAction must be 0 or 1";
            Return False;
         End-If;
         If &Item.GetField(Field.TAKEACTION).Value <> &p_obj.GetNumber("takeAction") Then
            &Changed = True;
         End-If;
         &Item.GetField(Field.TAKEACTION).Value = &p_obj.GetNumber("takeAction");
      End-If;
      If &p_obj.IsExist("upgradeAction") Then
         If Not %This.ValidateProjectAction(&p_obj.GetNumber("objectType"), &p_obj.GetNumber("upgradeAction")) Then
            Return False;
         End-If;
         If &Item.GetField(Field.UPGRADEACTION).Value <> &p_obj.GetNumber("upgradeAction") Then
            &Changed = True;
         End-If;
         &Item.GetField(Field.UPGRADEACTION).Value = &p_obj.GetNumber("upgradeAction");
      End-If;
      If &p_obj.IsExist("copyDone") Then
         If &p_obj.GetNumber("copyDone") <> 0 And
               &p_obj.GetNumber("copyDone") <> 1 Then
            &_errText = "copyDone must be 0 or 1";
            Return False;
         End-If;
         If &Item.GetField(Field.COPYDONE).Value <> &p_obj.GetNumber("copyDone") Then
            &Changed = True;
         End-If;
         &Item.GetField(Field.COPYDONE).Value = &p_obj.GetNumber("copyDone");
      End-If;
      If Not &Changed Then
         Return True;
      End-If;
      If Not %This.TouchProject(&p_obj.GetString("projectName")) Then
         Return False;
      End-If;
      &Saved = &Item.Update();
   End-If;
   If Not &Saved Then
      &_errText = "Project item maintenance failed";
      Return False;
   End-If;

   Return True;
end-method;


method ValidateProjectAction
   /+ &p_objectType as Number, +/
   /+ &p_upgradeAction as Number +/
   /+ Returns Boolean +/
   If &p_upgradeAction <> 0 And
         &p_upgradeAction <> 1 And
         &p_upgradeAction <> 2 And
         &p_upgradeAction <> 3 Then
      &_errText = "upgradeAction must be 0 through 3";
      Return False;
   End-If;
   Return True;
end-method;


method VersionRows
   /+ &rows as Rowset, +/
   /+ &where as String, +/
   /+ &name as String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &count = &rows.Fill(&where, &name);
   &state = String(&count);
   For &i = 1 To &count
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;



method DefinitionVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "prj1:" | String(Len(&name)) | ":" | &name | "|" | %Language;
   Local integer &present;
   Local number &generation;
   SQLExec("SELECT COUNT(*) FROM PSPROJECTDEFN WHERE PROJECTNAME=:1", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PJM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   &state = &state | "|PSPROJECTDEFN:" | %This.VersionRows(CreateRowset(Record.PSPROJECTDEFN), "WHERE PROJECTNAME=:1 ", &name);
   &state = &state | "|PSPROJECTITEM:" | %This.VersionRows(CreateRowset(Record.PSPROJECTITEM), "WHERE PROJECTNAME=:1 ORDER BY OBJECTTYPE,OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,OBJECTVALUE4", &name);
   &state = &state | "|PSPROJECTDEL:" | %This.VersionRows(CreateRowset(Record.PSPROJECTDEL), "WHERE PROJECTNAME=:1 ORDER BY VERSION", &name);
   &state = &state | "|PSPROJECTDEP:" | %This.VersionRows(CreateRowset(Record.PSPROJECTDEP), "WHERE PROJECTNAME=:1 ORDER BY UPDATE_ID", &name);
   &state = &state | "|PSPROJECTINC:" | %This.VersionRows(CreateRowset(Record.PSPROJECTINC), "WHERE PROJECTNAME=:1 ORDER BY UPDATE_ID", &name);
   Return "prj1:" | HashSHA256(&state);
end-method;

method LockDefinition
   /+ &name as String +/
   Local number &generation;
   Local SQL &cursor;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PJM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock PJM");
   End-If;
   &cursor = CreateSQL("SELECT VERSION FROM PSPROJECTDEFN WHERE PROJECTNAME=:1 FOR UPDATE OF VERSION", &name);
   While &cursor.Fetch(&generation)
   End-While;
   &cursor = CreateSQL("SELECT OBJECTTYPE FROM PSPROJECTITEM WHERE PROJECTNAME=:1 ORDER BY OBJECTTYPE,OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,OBJECTVALUE4 FOR UPDATE OF COPYDONE", &name);
   While &cursor.Fetch(&generation)
   End-While;
end-method;

