class CoreOperSqlDefn
   method CoreOperSqlDefn();

   method Execute(&message As Message, &responseOperation As string) Returns Message;
private
   method VersionRows(&rows As Rowset, &where As string, &name As string) Returns string;
   method DefinitionVersion(&name As string) Returns string;
   method LockDefinition(&name As string);
