end-class;

method CoreOperSqlDefn
   &_errText = "";
   &JsonUtil = create C_JSON_API:JsonUtil();
   &CommUtil = create C_COMMONS_PKG:CommonUtil();
   &MappingUtil = create C_META_DATA_PKG:Utility:MappingUtil();
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local Message &RespMsg;
   Local C_JSON_API:JSONObject &ReqObject, &RespObject;
   Local C_JSON_API:JSONArray &Statements;
   Local string &OperationType, &SqlId, &SqlText, &Market, &DbType, &Descr, &DescrLong;
   Local date &Effdt;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &beforeVersion, &afterVersion;
   Local integer &status;
   Local boolean &writing, &dry;


   try
      &ReqObject = &JsonUtil.GetRootObject(&message.GetContentString());

      If Not &ReqObject.IsExist("sqlId") Then
         &_errText = &_errText | "sqlId is required,";
      End-If;

      /* 参数有误 */
      If &_errText <> "" Then
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
         Return &RespMsg;
      End-If;

      If &ReqObject.IsExist("operationType") Then
         &OperationType = &ReqObject.GetString("operationType");
      Else
         &OperationType = "view";
      End-If;

      &_sqlId = &ReqObject.GetString("sqlId");
      If Len(&_sqlId) = 0 Or
            Len(&_sqlId) > 30 Then
         Return &JsonUtil.CreateFailedMessage(&responseOperation, 400, "sqlId must contain 1 to 30 characters");
      End-If;

      Local array of string &allowed = CreateArray("view", "create", "modify");
      If &allowed.Find(&OperationType) = 0 Then
         Return &JsonUtil.CreateFailedMessage(&responseOperation, 400, "Unsupported operationType");
      End-If;
      &writing = (&OperationType <> "view");
      &dry = False;
      If &ReqObject.IsExist("dryRun") Then
         &dry = &ReqObject.GetBoolean("dryRun");
      End-If;
      If &writing Then
         %This.LockDefinition(&_sqlId);
      End-If;
      &beforeVersion = %This.DefinitionVersion(&_sqlId);
      If &writing Then
         &status = &guard.Check(&ReqObject, &beforeVersion);
         If &status <> 0 Then
            SQLExec("rollback");
            Return &JsonUtil.CreateFailedMessage(&responseOperation, &status, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original snapshot");
         End-If;
      End-If;
      &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
      Evaluate &OperationType
      When "view"
         /*** View SQL ***/
         &RespObject = %This.ViewSqlDefn();
         Break;
      When "create"
         /*** Create SQL ***/
         If &ReqObject.IsExist("statements") Then
            &Statements = &ReqObject.GetJsonArray("statements");
            If &Statements.Size < 1 Then
               &_errText = &_errText | "statements is invalid";
            End-If;
         Else
            &_errText = &_errText | "statements is required for create operation";
         End-If;
         If &_errText <> "" Then
            SQLExec("rollback");
            &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
            Return &RespMsg;
         End-If;
         %This.CreateSqlDefn(&Statements);
         Break;
      When "modify"
         /*** Modify SQL ***/
         If Not &ReqObject.IsExist("market") Then
            &_errText = &_errText | "market is required for modify operation,";
         End-If;
         If Not &ReqObject.IsExist("dbType") Then
            &_errText = &_errText | "dbType is required for modify operation,";
         End-If;
         If Not &ReqObject.IsExist("effdt") Then
            &_errText = &_errText | "effdt is required for modify operation,";
         End-If;
         &Market = &ReqObject.GetString("market");
         &DbType = &ReqObject.GetString("dbType");
         &Effdt = Date(&ReqObject.GetString("effdt"));
         If &ReqObject.IsExist("descr") Then
            &Descr = &ReqObject.GetString("descr");
         End-If;
         If &ReqObject.IsExist("comment") Then
            &DescrLong = &ReqObject.GetString("comment");
            &DescrLong = &CommUtil.UnEscapeJSON(&DescrLong);
         End-If;
         If &ReqObject.IsExist("sqlText") Then
            &SqlText = &ReqObject.GetString("sqlText");
            &SqlText = &CommUtil.UnEscapeJSON(&SqlText);
         End-If;

         If &_errText <> "" Then
            SQLExec("rollback");
            &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
            Return &RespMsg;
         End-If;
         %This.ModifySqlDefn(&Market, &DbType, &Effdt, &Descr, &DescrLong, &SqlText);
         Break;
      When-Other
         &_errText = &_errText | "Unknown operationType: " | &OperationType | ". Supported: view, modify";
      End-Evaluate;

      If &_errText <> "" Then
         SQLExec("rollback");
         &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 400, &_errText);
      Else
         &afterVersion = %This.DefinitionVersion(&_sqlId);
         If Not &writing And
               &beforeVersion <> &afterVersion Then
            SQLExec("rollback");
            Return &JsonUtil.CreateFailedMessage(&responseOperation, 409, "VERSION_CONFLICT: definition changed during read");
         End-If;
         &RespObject.AddProperty("beforeVersion", &beforeVersion);
         &RespObject.AddProperty("version", &afterVersion);
         &RespObject.AddProperty("sqlVersionControl", 1);
         If &writing Then
            &RespObject.AddProperty("dryRun", &dry);
            If &dry Then
               SQLExec("rollback");
            Else
               SQLExec("commit");
            End-If;
         End-If;
         &RespMsg = &JsonUtil.CreateSuccessMessage(&responseOperation, &RespObject);
      End-If;
   catch Exception &ex
      SQLExec("rollback");
      SQLExec("rollback");
      &RespMsg = &JsonUtil.CreateFailedMessage(&responseOperation, 500, "Error: " | &ex.ToString());
   end-try;

   Return &RespMsg;
end-method;

method ViewSqlDefn
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &RespObject, &SQLStatement;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local string &SqlText = "";
   Local integer &i;
   Local C_JSON_API:JSONArray &Statements;

   &RespObject = CreateObject("C_JSON_API:Factory").NewObject();
   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId, Key:Class_SqlType, &SQLType);

   If Not &mgr.DefnExists(&key) Then
      &RespObject.AddProperty("sqlId", &_sqlId);
      &RespObject.AddProperty("sqlType", &SQLType);
      &RespObject.AddProperty("exists", False);
      &RespObject.AddJsonArray("statements", CreateObject("C_JSON_API:Factory").NewArray());
      Return &RespObject;
   End-If;

   &RespObject.AddProperty("exists", True);
   &defn = &mgr.GetDefn(&key);
   &Statements = CreateObject("C_JSON_API:Factory").NewArray();

   &RespObject.AddProperty("sqlId", &defn.SqlId);
   &RespObject.AddProperty("sqlType", &defn.SqlType);
   &RespObject.AddProperty("lastUpdate", "Last updated by: " | &defn.LastUpdOprId | ", " | DateTimeToLocalizedString(&defn.LastUpdDttm, &DateTimeFormat));
   &RespObject.AddJsonArray("statements", &Statements);
   &Statements = &RespObject.GetJsonArray("statements");

   /*** Concatenate all statement rows ***/
   For &i = 1 To &defn.Count_StmtT
      &stmtdefn = &defn.Get_StmtT(&i);
      &SQLStatement = CreateObject("C_JSON_API:Factory").NewObject();
      &SQLStatement.AddProperty("market", &stmtdefn.Market);
      &SQLStatement.AddProperty("dbType", &stmtdefn.DbType);
      &SQLStatement.AddProperty("effdt", &stmtdefn.EffDt);
      &SQLStatement.AddProperty("sqlText", &stmtdefn.SqlText);
      &SQLStatement.AddProperty("descr", &stmtdefn.Descr);
      &SQLStatement.AddProperty("comment", &stmtdefn.DescrLong);
      &Statements.AddJsonObjectElement("", &SQLStatement);
      &SQLStatement = &Statements.GetJsonObject(&Statements.Size);
   End-For;

   Return &RespObject;
end-method;

method CreateSqlDefn
   /+ &p_statements as C_JSON_API:JSONArray +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local integer &i, &DbTypeCode;
   Local C_JSON_API:JSONObject &StatementObj;
   Local string &Market, &DbType, &SqlText, &Descr, &DescrLong;
   Local date &Effdt;

   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId);
   &key.AddItem(Key:Class_SqlType, &SQLType);

   If &mgr.DefnExists(&key) Then
      &_errText = &_errText | "sql already exist";
      Return;
   End-If;

   &defn = &mgr.CreateDefn();
   &defn.SqlId = &_sqlId;
   &defn.SqlType = &SQLType;
   For &i = 1 To &p_statements.Size
      &StatementObj = &p_statements.GetJsonObject(&i);
      If &StatementObj.IsExist("market") Then
         &Market = &StatementObj.GetString("market");
      Else
         &Market = "GBL";
      End-If;
      If &StatementObj.IsExist("dbType") Then
         &DbType = &StatementObj.GetString("dbType");
         &DbTypeCode = &MappingUtil.GetDbTypeCode(&DbType);
      Else
         &DbType = "";
         &DbTypeCode = &MappingUtil.GetDbTypeCode(&DbType);
      End-If;
      If &StatementObj.IsExist("effdt") Then
         &Effdt = Date(&StatementObj.GetString("effdt"));
      Else
         &Effdt = Date3(1900, 1, 1);
      End-If;
      If &StatementObj.IsExist("sqlText") Then
         &SqlText = &CommUtil.UnEscapeJSON(&StatementObj.GetString("sqlText"));
         &SqlText = &CommUtil.ReplaceWithRegex(&SqlText, "\s+", " ");
      Else
         &_errText = &_errText | "sqlText is required";
         Return;
      End-If;
      If &StatementObj.IsExist("descr") Then
         &Descr = &StatementObj.GetString("descr");
      End-If;
      If &StatementObj.IsExist("comment") Then
         &DescrLong = &CommUtil.UnEscapeJSON(&StatementObj.GetString("comment"));
      End-If;
      &stmtdefn = &defn.Append_StmtT(&i - 1);
      &stmtdefn.Market = &Market;
      &stmtdefn.DbType = &DbTypeCode;
      &stmtdefn.EffDt = &Effdt;
      &stmtdefn.SqlText = &SqlText;
      If All(&Descr) Then
         &stmtdefn.Descr = &Descr;
      End-If;
      If All(&DescrLong) Then
         &stmtdefn.DescrLong = &DescrLong;
      End-If;
   End-For;

   If Not &defn.SaveNewDefn() Then
      &_errText = &_errText | "create sql failed";
   End-If;
end-method;

method ModifySqlDefn
   /+ &p_market as String, +/
   /+ &p_dbType as String, +/
   /+ &p_effdt as Date, +/
   /+ &p_descr as String, +/
   /+ &p_descrLong as String, +/
   /+ &sqlText as String +/
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager &mgr;
   Local %metadata:SqlRepositoryDefn:SqlRepositoryDefn &defn;
   Local %metadata:SqlRepositoryDefn:SrmStmt &stmtdefn;
   Local %metadata:Key &key;
   Local integer &i, &DbTypeCode;
   Local boolean &Matched = False;

   /* 初始化变量 */
   If None(&p_market) Then
      &p_market = "GBL";
   End-If;

   If None(&p_effdt) Then
      &p_effdt = Date3(1900, 1, 1);
   End-If;

   &DbTypeCode = &MappingUtil.GetDbTypeCode(&p_dbType);
   &mgr = create %metadata:SqlRepositoryDefn:SqlRepositoryDefn_Manager();
   &key = create %metadata:Key(Key:Class_Sql, &_sqlId, Key:Class_SqlType, &SQLType);

   If Not &mgr.DefnExists(&key) Then
      throw CreateException(0, 0, "SQL definition not found: " | &_sqlId | " (type=" | &SQLType | ")");
   End-If;

   &defn = &mgr.GetDefnToUpdate(&key);

   For &i = 1 To &defn.Count_StmtT
      &stmtdefn = &defn.Get_StmtT(&i);
      If &stmtdefn.Market = &p_market And
            &stmtdefn.DbType = &DbTypeCode And
            &stmtdefn.EffDt = &p_effdt Then
         &Matched = True;
         If All(&p_descr) Then
            &stmtdefn.Descr = &p_descr;
         End-If;
         If All(&p_descrLong) Then
            &stmtdefn.DescrLong = &p_descrLong;
         End-If;
         If All(&sqlText) Then
            &sqlText = &CommUtil.ReplaceWithRegex(&sqlText, "\s+", " ");
            &stmtdefn.SqlText = &sqlText;
         End-If;
      End-If;
   End-For;

   If Not &Matched Then
      &_errText = "SQL Statement not found for market/dbType/effdt";
      Return;
   End-If;

   If Not &defn.UpdateDefn() Then
      &_errText = &_errText | "modify sql failed";
   End-If;
end-method;


method VersionRows
   /+ &rows as Rowset, +/
   /+ &where as String, +/
   /+ &name as String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &count = &rows.Fill(&where, &name);
   &state = String(&count);
   For &i = 1 To &count
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;



method DefinitionVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "sql1:" | String(Len(&name)) | ":" | &name | "|" | %Language;
   Local integer &present;
   Local number &generation;
   SQLExec("SELECT COUNT(*) FROM PSSQLDEFN WHERE SQLID=:1 AND SQLTYPE='0'", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SRM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   &state = &state | "|PSSQLDEFN:" | %This.VersionRows(CreateRowset(Record.PSSQLDEFN), "WHERE SQLID=:1 AND SQLTYPE='0'", &name);
   &state = &state | "|PSSQLTEXTDEFN:" | %This.VersionRows(CreateRowset(Record.PSSQLTEXTDEFN), "WHERE SQLID=:1 AND SQLTYPE='0' ORDER BY MARKET,DBTYPE,EFFDT,SEQNUM", &name);
   &state = &state | "|PSSQLDESCR:" | %This.VersionRows(CreateRowset(Record.PSSQLDESCR), "WHERE SQLID=:1 AND SQLTYPE='0' ORDER BY MARKET,DBTYPE,EFFDT", &name);
   &state = &state | "|PSSQLLANG:" | %This.VersionRows(CreateRowset(Record.PSSQLLANG), "WHERE SQLID=:1 AND SQLTYPE='0' ORDER BY MARKET,DBTYPE,EFFDT,LANGUAGE_CD", &name);
   &state = &state | "|PSSQLHASH:" | %This.VersionRows(CreateRowset(Record.PSSQLHASH), "WHERE SQLID=:1 AND SQLTYPE='0' ORDER BY MARKET,DBTYPE,EFFDT", &name);
   &state = &state | "|PSSQLDEL:" | %This.VersionRows(CreateRowset(Record.PSSQLDEL), "WHERE SQLID=:1 AND SQLTYPE='0' ORDER BY VERSION", &name);
   Return "sql1:" | HashSHA256(&state);
end-method;

method LockDefinition
   /+ &name as String +/
   Local number &generation;
   Local SQL &cursor;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SRM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock SRM");
   End-If;
   &cursor = CreateSQL("SELECT VERSION FROM PSSQLDEFN WHERE SQLID=:1 AND SQLTYPE='0' FOR UPDATE OF VERSION", &name);
   While &cursor.Fetch(&generation)
   End-While;
end-method;

import C_JSON_API:*;
import PS_PT:Integration:IRequestHandler;
import C_JSON_API:JsonUtil;
import C_COMMONS_PKG:CommonUtil;
import C_META_DATA_PKG:Utility:NativeAdapter;
import C_META_DATA_PKG:Utility:DefinitionVersion;

class CoreOperStylesheetDefn
   method CoreOperStylesheetDefn();
   method VersionRows(&rows As Rowset, &where As string, &name As string) Returns string;
   method BlobVersion(&name As string, &translated As boolean) Returns string;
   method ContentVersion(&name As string) Returns string;
   method LockContent(&name As string);
   method Execute(&message As Message, &responseOperation As string) Returns Message;
end-class;

method CoreOperStylesheetDefn
end-method;

method Execute
   /+ &message as Message, +/
   /+ &responseOperation as String +/
   /+ Returns Message +/
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   Local C_JSON_API:JSONObject &req, &result;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local string &name, &action, &beforeVersion, &afterVersion;
   Local integer &status = 400;
   Local integer &present;
   Local boolean &writing, &dry;
   try
      &req = &json.GetRootObject(&message.GetContentString());
      If Not &req.IsExist("operationType") Or
            Not &req.IsExist("kind") Then
         throw CreateException(0, 0, "operationType and kind are required");
      End-If;
      If &req.GetString("kind") <> "stylesheet" Then
         throw CreateException(0, 0, "Kind is not supported by this endpoint");
      End-If;
      If Len(&message.GetContentString()) > 262144 Then
         throw CreateException(0, 0, "Request exceeds 262144 characters");
      End-If;
      Local integer &ri;
      Local string &requestField;
      Local array of string &allowed = CreateArray("kind", "name", "operationType", "properties", "collections", "dryRun", "expectedState", "expectedVersion");
      For &ri = 1 To &req.ChildCount
         &requestField = &req.GetPropertyNameAt(&ri);
         If &allowed.Find(&requestField) = 0 Then
            throw CreateException(0, 0, "Unknown request property: " | &requestField);
         End-If;
      End-For;
      If Not &req.IsExist("name") Then
         throw CreateException(0, 0, "name is required");
      End-If;
      &name = &req.GetString("name");
      &action = &req.GetString("operationType");
      If Len(&name) = 0 Or
            Len(&name) > 30 Then
         throw CreateException(0, 0, "Definition name must have 1-30 characters");
      End-If;
      &allowed = CreateArray("view", "struct", "exists", "create", "modify");
      If &allowed.Find(&action) = 0 Then
         throw CreateException(0, 0, "Unsupported content operation");
      End-If;
      &writing = (&action = "create" Or
         &action = "modify");
      &dry = False;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      If &writing Then
         &guard.ValidateName(&name, 30);
         %This.LockContent(&name);
      End-If;
      &beforeVersion = %This.ContentVersion(&name);
      If &writing Then
         &status = &guard.Check(&req, &beforeVersion);
         If &status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original content snapshot");
         End-If;
         &status = 400;
      End-If;
      SQLExec("SELECT COUNT(*) FROM PSSTYLSHEETDEFN WHERE STYLESHEETNAME=:1 ", &name, &present);
      If &action = "exists" Or
            ((&action = "view" Or
               &action = "struct") And
               &present = 0) Then
         &result = CreateObject("C_JSON_API:Factory").NewObject();
         &result.AddProperty("exists", (&present > 0));
      Else
         &result = &engine.Run(&req);
         If &action = "view" Or
               &action = "struct" Then
            &result.AddProperty("exists", True);
         End-If;
      End-If;
      &afterVersion = %This.ContentVersion(&name);
      If Not &writing And
            &beforeVersion <> &afterVersion Then
         &status = 409;
         throw CreateException(0, 0, "VERSION_CONFLICT: content changed during read; read again");
      End-If;
      &result.AddProperty("beforeVersion", &beforeVersion);
      &result.AddProperty("version", &afterVersion);
      &result.AddProperty("stylesheetVersionControl", 1);
      If &writing Then
         If &dry Then
            SQLExec("rollback");
         Else
            SQLExec("commit");
         End-If;
      End-If;
      Return &json.CreateSuccessMessage(&responseOperation, &result);
   catch Exception &ex
      SQLExec("rollback");
      Return &json.CreateFailedMessage(&responseOperation, &status, &ex.ToString());
   end-try;
end-method;


method VersionRows
   /+ &rows as Rowset, +/
   /+ &where as String, +/
   /+ &name as String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &count = &rows.Fill(&where, &name);
   &state = String(&count);
   For &i = 1 To &count
      &rec = &rows(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;

method BlobVersion
   /+ &name as String, +/
   /+ &translated as Boolean +/
   /+ Returns String +/
   Local SQL &cursor;
   Local number &alt, &seq, &length, &offset;
   Local string &language, &chunk, &state;
   &state = "";
   If &translated Then
      &cursor = CreateSQL("SELECT ALTCONTNUM,SEQNUM,LANGUAGE_CD,DBMS_LOB.GETLENGTH(CONTDATA) FROM PSCONTENTLANG WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM,LANGUAGE_CD,SEQNUM", &name);
   Else
      &cursor = CreateSQL("SELECT ALTCONTNUM,SEQNUM,' ',DBMS_LOB.GETLENGTH(CONTDATA) FROM PSCONTENT WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM,SEQNUM", &name);
   End-If;
   While &cursor.Fetch(&alt, &seq, &language, &length)
      &state = &state | "|" | String(&alt) | ":" | String(&seq) | ":" | &language | ":" | String(&length);
      &offset = 1;
      While &offset <= &length
         If &translated Then
            SQLExec("SELECT RAWTOHEX(DBMS_LOB.SUBSTR(CONTDATA,2000,:1)) FROM PSCONTENTLANG WHERE CONTNAME=:2 AND CONTTYPE=9 AND ALTCONTNUM=:3 AND SEQNUM=:4 AND LANGUAGE_CD=:5", &offset, &name, &alt, &seq, &language, &chunk);
         Else
            SQLExec("SELECT RAWTOHEX(DBMS_LOB.SUBSTR(CONTDATA,2000,:1)) FROM PSCONTENT WHERE CONTNAME=:2 AND CONTTYPE=9 AND ALTCONTNUM=:3 AND SEQNUM=:4", &offset, &name, &alt, &seq, &chunk);
         End-If;
         &state = &state | ":" | HashSHA256(&chunk);
         &offset = &offset + 2000;
      End-While;
   End-While;
   Return HashSHA256(&state);
end-method;

method ContentVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "CSS1|" | &name | "|" | %Language;
   Local integer &present;
   Local number &generation;
   SQLExec("SELECT COUNT(*) FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=9", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='CRM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEFN), "WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEFNLANG), "WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM,LANGUAGE_CD", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSCONTDEL), "WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM,VERSION", &name);
   &state = &state | %This.BlobVersion(&name, False) | %This.BlobVersion(&name, True);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLSHEETDEFN), "WHERE STYLESHEETNAME=:1 ORDER BY STYLESHEETNAME", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLEDFNLANG), "WHERE STYLESHEETNAME=:1 ORDER BY LANGUAGE_CD", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLSHEETDEL), "WHERE STYLESHEETNAME=:1 ORDER BY VERSION", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLECLASS), "WHERE STYLESHEETNAME=:1 ORDER BY STYLECLASSNAME", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLECLSLANG), "WHERE STYLESHEETNAME=:1 ORDER BY STYLECLASSNAME,LANGUAGE_CD", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLECLASSFNT), "WHERE STYLESHEETNAME=:1 ORDER BY STYLECLASSNAME,SEQNUM", &name);
   &state = &state | %This.VersionRows(CreateRowset(Record.PSSTYLEFNTLANG), "WHERE STYLESHEETNAME=:1 ORDER BY STYLECLASSNAME,LANGUAGE_CD,SEQNUM", &name);

   Return "css1:" | HashSHA256(&state);
end-method;

method LockContent
   /+ &name as String +/
   Local number &generation;
   Local SQL &cursor;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='CRM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock CRM");
   End-If;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SSM' FOR UPDATE OF VERSION", &generation) Then
      throw CreateException(0, 0, "Cannot lock SSM");
   End-If;
   SQLExec("SELECT VERSION FROM PSSTYLSHEETDEFN WHERE STYLESHEETNAME=:1 FOR UPDATE OF VERSION", &name, &generation);
   &cursor = CreateSQL("SELECT VERSION FROM PSCONTDEFN WHERE CONTNAME=:1 AND CONTTYPE=9 ORDER BY ALTCONTNUM FOR UPDATE OF VERSION", &name);
   While &cursor.Fetch(&generation)
   End-While;
end-method;

import C_JSON_API:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;

/* Snapshot tokens describe one definition, including its native children. */
class DefinitionVersion
   method DefinitionVersion();
   method FieldVersion(&name As string) Returns string;
   method RecordVersion(&name As string) Returns string;
   method Lock();
   method Check(&req As C_JSON_API:JSONObject, &actual As string) Returns integer;
   method ValidateName(&name As string, &maximum As integer);
   method ProjectItem(&typ As integer, &values As array of string, &deleted As boolean) Returns C_JSON_API:JSONObject;
private
   method Rows(&rs As Rowset, &where As string, &name As string) Returns string;
end-class;

method DefinitionVersion
end-method;

method ValidateName
   /+ &name as String, +/
   /+ &maximum as Integer +/
   Local integer &i;
   Local string &ch;
   If Len(&name) = 0 Or
         Len(&name) > &maximum Then
      throw CreateException(0, 0, "Invalid definition name length");
   End-If;
   For &i = 1 To Len(&name)
      &ch = Substring(&name, &i, 1);
      If Find(&ch, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") = 0 Then
         If &i = 1 Or
               Find(&ch, "0123456789_") = 0 Then
            throw CreateException(0, 0, "Definition names require uppercase letters, digits or underscores, starting with a letter");
         End-If;
      End-If;
   End-For;
end-method;

method Rows
   /+ &rs as Rowset, +/
   /+ &where as String, +/
   /+ &name as String +/
   /+ Returns String +/
   Local integer &n, &i, &j;
   Local Record &rec;
   Local string &state, &value;
   &n = &rs.Fill(&where, &name);
   &state = String(&n);
   For &i = 1 To &n
      &rec = &rs(&i).GetRecord(1);
      For &j = 1 To &rec.FieldCount
         &value = String(&rec.GetField(&j).Value);
         &state = &state | "|" | &rec.GetField(&j).Name | ":" | String(Len(&value)) | ":" | &value;
      End-For;
   End-For;
   Return HashSHA256(&state);
end-method;

method FieldVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "F1|" | &name;
   Local integer &present;
   Local number &generation;
   SQLExec("SELECT COUNT(*) FROM PSDBFIELD WHERE FIELDNAME=:1", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='RDM'", &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   SQLExec("SELECT COUNT(*) FROM PSXLATDEFN WHERE FIELDNAME=:1", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='XTM'", &generation);
      &state = &state | "|XLAT_ABSENT:" | String(&generation);
   End-If;
   &state = &state | %This.Rows(CreateRowset(Record.PSDBFIELD), "WHERE FIELDNAME=:1", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSDBFIELDLANG), "WHERE FIELDNAME=:1 ORDER BY LANGUAGE_CD", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSDBFLDLABL), "WHERE FIELDNAME=:1 ORDER BY LABEL_ID", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSDBFLDLABLLANG), "WHERE FIELDNAME=:1 ORDER BY LABEL_ID,LANGUAGE_CD", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSXLATDEFN), "WHERE FIELDNAME=:1", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSXLATITEM), "WHERE FIELDNAME=:1 ORDER BY FIELDVALUE,EFFDT", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSXLATITEMLANG), "WHERE FIELDNAME=:1 ORDER BY FIELDVALUE,EFFDT,LANGUAGE_CD", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSPTCONTEXT), "WHERE OBJECTVALUE1=:1 ORDER BY RECNAME,OBJECTVALUE2,OBJECTVALUE3,OBJECTVALUE4", &name);
   Return "f1:" | HashSHA256(&state);
end-method;

method RecordVersion
   /+ &name as String +/
   /+ Returns String +/
   Local string &state = "R1|" | &name;
   Local SQL &cursor;
   Local string &field, &event;
   Local number &v;
   Local integer &present;
   SQLExec("SELECT COUNT(*) FROM PSRECDEFN WHERE RECNAME=:1", &name, &present);
   If &present = 0 Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='RDM'", &v);
      &state = &state | "|ABSENT:" | String(&v);
   End-If;
   &state = &state | %This.Rows(CreateRowset(Record.PSRECDEFN), "WHERE RECNAME=:1", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECDEFNLANG), "WHERE RECNAME=:1 ORDER BY LANGUAGE_CD", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECFIELD), "WHERE RECNAME=:1 ORDER BY FIELDNUM,FIELDNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECFIELDDB), "WHERE RECNAME=:1 ORDER BY FIELDNUM,FIELDNAME,RECNAME_PARENT", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSINDEXDEFN), "WHERE RECNAME=:1 ORDER BY INDEXID", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSKEYDEFN), "WHERE RECNAME=:1 ORDER BY INDEXID,KEYPOSN", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECTBLSPC), "WHERE RECNAME=:1 ORDER BY DBNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECDDLPARM), "WHERE RECNAME=:1 ORDER BY PLATFORMID,SIZINGSET,PARMNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSIDXDDLPARM), "WHERE RECNAME=:1 ORDER BY INDEXID,PLATFORMID,SIZINGSET,PARMNAME", &name);
   /* Referenced field/subrecord saves must also invalidate a downloaded view. */
   &state = &state | %This.Rows(CreateRowset(Record.PSDBFIELD), "WHERE FIELDNAME IN (SELECT FIELDNAME FROM PSRECFIELDDB WHERE RECNAME=:1) ORDER BY FIELDNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSXLATDEFN), "WHERE FIELDNAME IN (SELECT FIELDNAME FROM PSRECFIELDDB WHERE RECNAME=:1) ORDER BY FIELDNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSRECDEFN), "WHERE RECNAME IN (SELECT RECNAME_PARENT FROM PSRECFIELDDB WHERE RECNAME=:1) ORDER BY RECNAME", &name);
   /* A subrecord edit may change each parent's expansion and programs. */
   &state = &state | %This.Rows(CreateRowset(Record.PSRECDEFN), "WHERE RECNAME IN (SELECT RECNAME FROM PSRECFIELD WHERE SUBRECORD='Y' START WITH FIELDNAME=:1 AND SUBRECORD='Y' CONNECT BY NOCYCLE PRIOR RECNAME=FIELDNAME AND SUBRECORD='Y') ORDER BY RECNAME", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSSQLDEFN), "WHERE SQLID=:1 AND SQLTYPE='2'", &name);
   &state = &state | %This.Rows(CreateRowset(Record.PSSQLTEXTDEFN), "WHERE SQLID=:1 AND SQLTYPE='2' ORDER BY MARKET,DBTYPE,EFFDT", &name);
   Local string &dependency;
   &cursor = CreateSQL("SELECT DISTINCT OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,VERSION FROM PSPCMPROG WHERE OBJECTID1=1 AND OBJECTID2=2 AND OBJECTID3=12 AND OBJECTVALUE1 IN (SELECT :1 FROM DUAL UNION SELECT FIELDNAME FROM PSRECFIELD WHERE SUBRECORD='Y' START WITH RECNAME=:1 CONNECT BY NOCYCLE PRIOR FIELDNAME=RECNAME AND PRIOR SUBRECORD='Y') ORDER BY OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,VERSION", &name);
   While &cursor.Fetch(&dependency, &field, &event, &v)
      &state = &state | "|PC:" | &dependency | ":" | &field | ":" | &event | "=" | String(&v);
   End-While;
   &cursor = CreateSQL("SELECT DISTINCT OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,VERSION FROM PSPCMPROG WHERE OBJECTID1=1 AND OBJECTID2=2 AND OBJECTID3=12 AND OBJECTVALUE1 IN (SELECT RECNAME FROM PSRECFIELD WHERE SUBRECORD='Y' START WITH FIELDNAME=:1 AND SUBRECORD='Y' CONNECT BY NOCYCLE PRIOR RECNAME=FIELDNAME AND SUBRECORD='Y') ORDER BY OBJECTVALUE1,OBJECTVALUE2,OBJECTVALUE3,VERSION", &name);
   Local string &parent;
   While &cursor.Fetch(&parent, &field, &event, &v)
      &state = &state | "|PPC:" | &parent | ":" | &field | ":" | &event | "=" | String(&v);
   End-While;
   Return "r1:" | HashSHA256(&state);
end-method;

method Lock
   Local number &v;
   /* Keep compare and save in one transaction, including native child saves. */
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='RDM' FOR UPDATE OF VERSION", &v) Then
      throw CreateException(0, 0, "Cannot lock RDM");
   End-If;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='PCM' FOR UPDATE OF VERSION", &v) Then
      throw CreateException(0, 0, "Cannot lock PCM");
   End-If;
   If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SRM' FOR UPDATE OF VERSION", &v) Then
      throw CreateException(0, 0, "Cannot lock SRM");
   End-If;
end-method;

method Check
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &actual as String +/
   /+ Returns Integer +/
   If Not &req.IsExist("expectedVersion") Then
      Return 428;
   End-If;
   If Len(&req.GetString("expectedVersion")) = 0 Then
      Return 428;
   End-If;
   If &req.GetString("expectedVersion") <> &actual Then
      Return 409;
   End-If;
   Return 0;
end-method;

method ProjectItem
   /+ &typ as Integer, +/
   /+ &values as Array of String, +/
   /+ &deleted as Boolean +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &resolver = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   Local array of integer &ids = &resolver.GetObjectIDs(&typ, &values);
   Local C_JSON_API:JSONObject &item = CreateObject("C_JSON_API:Factory").NewObject();
   Local integer &i;
   &item.AddProperty("objectType", &typ);
   &item.AddProperty("deleted", &deleted);
   For &i = 1 To 4
      &item.AddProperty("objectId" | &i, &ids [&i]);
      &item.AddProperty("objectValue" | &i, &values [&i]);
   End-For;
   Return &item;
end-method;

