method Rows
   /+ &table as String, +/
   /+ &where as String, +/
   /+ &binds as Array of String +/
   /+ Returns String +/
   Local integer &count, &i, &j;
   Local string &order, &state, &value, &fieldName, &selectList, &usableOrder;
   Local SQL &schema, &cursor;
   Local array of string &fieldNames = CreateArrayRept("", 0);
   Local array of string &orderNames;
   Local array of any &sqlBinds = CreateArrayAny();
   Local array of any &values = CreateArrayAny();
   Evaluate &table
   When "PSAUTHWS"
      &order = "CLASSID,IB_OPERATIONNAME,AUTHORIZEDACTIONS";
      Break;
   When "PSCLASSDEFN"
      &order = "CLASSID,VERSION,CLASSDEFNDESC,TIMEOUTMINUTES,DEFAULTBPM,STARTAPPSERVER,ALLOWPSWDEMAIL,LASTUPDDTTM,LASTUPDOPRID";
