      &order = "IB_SERVICENAME,VERSION,IB_NAMESPACE,IB_ALIASNAME,IB_PSOFTSERVICE,IB_REST_SERVICE,PT_OPEN_API,PTIBAPPLNAME,IBEXTERNALUSERID,IBEXTERNALPWD,TOKENTYPE,PTIB_APPSRVGRP,LASTUPDDTTM,LASTUPDOPRID,OBJECTOWNERID,DESCR";
      Break;
   When "PSSERVICEDEL"
      &order = "IB_SERVICENAME,VERSION";
      Break;
   When "PSSERVICELANG"
      &order = "IB_SERVICENAME,LANGUAGE_CD,DESCR";
      Break;
   When "PSSERVICEOPR"
      &order = "IB_SERVICENAME,IB_OPERATIONNAME";
      Break;
   When "PSSERVICEUDDI"
      &order = "IB_SERVICENAME,IB_UDDIKEY";
      Break;

   When-Other
      throw CreateException(0, 0, "Unsupported version table");
   End-Evaluate;
   /* The whitelist above is fixed; the target dictionary supplies only its
      real columns. SQL.Fetch avoids 8.55 Rowset CLOB/None conversion failures. */
   &schema = CreateSQL("SELECT FIELDNAME FROM PSRECFIELDDB WHERE RECNAME=:1 ORDER BY FIELDNUM", &table);
   While &schema.Fetch(&fieldName)
      &fieldNames.Push(&fieldName);
   End-While;
   &schema.Close();
   If &fieldNames.Len = 0 Then
      If CreateArray("PSIBOPRROOT", "PSIBURITRAN", "PSIBURITRNLANG", "PSOPRURIDATA", "PSPRSMHIDDEN").Find(&table) > 0 Then
         Return HashSHA256(&table | ":not-delivered");
      End-If;
      throw CreateException(0, 0, "Required version record is not delivered: " | &table);
   End-If;
   For &i = 1 To &fieldNames.Len
      If &i > 1 Then
         &selectList = &selectList | ",";
      End-If;
      &selectList = &selectList | &fieldNames [&i];
   End-For;
   &orderNames = Split(&order, ",");
   For &i = 1 To &orderNames.Len
      If &fieldNames.Find(&orderNames [&i]) > 0 Then
         If Len(&usableOrder) > 0 Then
            &usableOrder = &usableOrder | ",";
         End-If;
         &usableOrder = &usableOrder | &orderNames [&i];
      End-If;
   End-For;
   If None(&usableOrder) Then
      throw CreateException(0, 0, "Version record has no supported ordering key: " | &table);
   End-If;
   For &i = 1 To &binds.Len
      &sqlBinds.Push(&binds [&i]);
   End-For;
   &state = &table;
   &count = 0;
   &cursor = CreateSQL("SELECT " | &selectList | " FROM " | &table | " " | &where | " ORDER BY " | &usableOrder, &sqlBinds);
   try
      While &cursor.Fetch(&values)
         &count = &count + 1;
         For &j = 1 To &fieldNames.Len
            &value = String(&values [&j]);
            &state = &state | "|" | &fieldNames [&j] | ":" | String(Len(&value)) | ":" | &value;
         End-For;
      End-While;
      &cursor.Close();
   catch Exception &readError
      &cursor.Close();
      throw &readError;
   end-try;
   &state = &table | ":" | String(&count) | &state;
   Return HashSHA256(&state);
end-method;

method Keys
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local array of string &keys = CreateArray("kind", "name", "Versionname", "Handlername", "Effdt", "PortalName", "RefType", "permissionList", "language");
   Local integer &i;
   Local number &messageNumber;
   For &i = 1 To &keys.Len
      If &req.IsExist(&keys [&i]) Then
         &out.AddProperty(&keys [&i], &req.GetString(&keys [&i]));
      End-If;
   End-For;
   If &req.IsExist("messageNumber") Then
      &messageNumber = &req.GetNumber("messageNumber");
      &out.AddProperty("messageNumber", &messageNumber);
   End-If;
   Return &out;
end-method;

method Present
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns Boolean +/
   Local string &kind = &req.GetString("kind");
   Local string &name = &req.GetString("name");
   Local integer &n;
   Evaluate &kind
   When "service"
      SQLExec("SELECT COUNT(*) FROM PSSERVICE WHERE IB_SERVICENAME=:1", &name, &n);
      Break;
   When "operation"
      SQLExec("SELECT COUNT(*) FROM PSOPERATION WHERE IB_OPERATIONNAME=:1", &name, &n);
      Break;
   When "version"
      SQLExec("SELECT COUNT(*) FROM PSOPRVERDFN WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", &name, &req.GetString("Versionname"), &n);
      Break;
   When "handler"
      SQLExec("SELECT COUNT(*) FROM PSOPRHDLR WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", &name, &req.GetString("Handlername"), &n);
      Break;
   When "routing"
      SQLExec("SELECT COUNT(*) FROM PSIBRTNGDEFN WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", &name, &req.GetString("Effdt"), &n);
      Break;
   When "permission"
      SQLExec("SELECT COUNT(*) FROM PSOPERATION WHERE IB_OPERATIONNAME=:1", &name, &n);
      Break;
   When "catalog"
      SQLExec("SELECT COUNT(*) FROM PSMSGSETDEFN WHERE MESSAGE_SET_NBR=:1", &name, &n);
      Break;
   When "portal"
      SQLExec("SELECT COUNT(*) FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", &req.GetString("PortalName"), &req.GetString("RefType"), &name, &n);
      Break;

   When-Other
      throw CreateException(0, 0, "Unsupported version kind");
   End-Evaluate;
   Return (&n > 0);
end-method;

method Lock
   /+ &kind as String +/
   Local array of string &locks;
   Local number &generation;
   Local integer &i;
   If &kind = "catalog" Then
      &locks = CreateArray("PPC");
   Else
      If &kind = "portal" Then
         &locks = CreateArray("PRSM");
      Else
         &locks = CreateArray("OPRM", "OPRVM", "OPRHM", "RTDM", "SRVM", "CLM");
      End-If;
   End-If;
   For &i = 1 To &locks.Len
      If Not SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME=:1 FOR UPDATE OF VERSION", &locks [&i], &generation) Then
         throw CreateException(0, 0, "Cannot acquire metadata version lock");
      End-If;
   End-For;
end-method;

method Version
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns String +/
   Local string &kind = &req.GetString("kind");
   Local string &name = &req.GetString("name");
   Local string &state, &prefix, &lock, &owner, &where;
   Local C_JSON_API:JSONObject &identity = CreateObject("C_JSON_API:Factory").NewObject();
   Local array of string &identityFields = CreateArray("kind", "name", "Versionname", "Handlername", "Effdt", "PortalName", "RefType", "permissionList", "language");
   Local integer &identityIndex;
   Local number &generation;
   For &identityIndex = 1 To &identityFields.Len
      If &req.IsExist(&identityFields [&identityIndex]) Then
         &identity.AddProperty(&identityFields [&identityIndex], &req.GetString(&identityFields [&identityIndex]));
      End-If;
   End-For;
   &state = "M1|" | &identity.ToString() | "|" | %Language | "|" | %Language_Base;
   Evaluate &kind
   When "service"
      &prefix = "svc1:";
      &lock = "SRVM";
      &state = &state | %This.Rows("PSSERVICE", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSSERVICELANG", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSSERVICEOPR", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATION", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSSERVICEUDDI", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSSERVICEDEL", "WHERE IB_SERVICENAME=:1", CreateArray(&name));
      Break;
   When "operation"
      &prefix = "ib1:";
      &lock = "OPRM";
      &state = &state | %This.Rows("PSOPERATION", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONLANG", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONURI", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSIBOPRROOT", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSIBURITRAN", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSIBURITRNLANG", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRURIDATA", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONDEL", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDFN", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDFNLANG", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDFNPARM", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRGENRTGPARM", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERQUEPARM", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVDCONTTYPE", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVDPARMTYPE", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDEPLOY", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDPLYDAT", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDPLYVER", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRVERDFNDEL", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRHDLR", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRHDLRLANG", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONAC", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONAE", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONCI", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPERATIONDMS", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSOPRHDLRDEL", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSAUTHWS", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSSERVICEOPR", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSIBRTNGDEFN", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSIBRTNGSUBDEFN", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSRTNGDFNPARM", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSRTNGDFNCONPRP", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSRTNGDFNLANG", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSRTNGDFNPROP", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSRTNGDFNPROPLG", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSIBRTNGDEFNDEL", "WHERE ROUTINGDEFNNAME IN (SELECT ROUTINGDEFNNAME FROM PSIBRTNGDEFN WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      &state = &state | %This.Rows("PSCLASSDEFN", "WHERE CLASSID IN (SELECT CLASSID FROM PSAUTHWS WHERE IB_OPERATIONNAME=:1)", CreateArray(&name));
      Break;
   When "version"
      &prefix = "ib1:";
      &lock = "OPRVM";
      &state = &state | %This.Rows("PSOPRVERDFN", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDFNLANG", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDFNPARM", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRGENRTGPARM", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERQUEPARM", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVDCONTTYPE", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVDPARMTYPE", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDEPLOY", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDPLYDAT", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDPLYVER", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      &state = &state | %This.Rows("PSOPRVERDFNDEL", "WHERE IB_OPERATIONNAME=:1 AND VERSIONNAME=:2", CreateArray(&name, &req.GetString("Versionname")));
      Break;
   When "handler"
      &prefix = "ib1:";
      &lock = "OPRHM";
      &state = &state | %This.Rows("PSOPRHDLR", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPRHDLRLANG", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPERATIONAC", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPERATIONAE", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPERATIONCI", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPERATIONDMS", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      &state = &state | %This.Rows("PSOPRHDLRDEL", "WHERE IB_OPERATIONNAME=:1 AND HANDLERNAME=:2", CreateArray(&name, &req.GetString("Handlername")));
      Break;
   When "routing"
      &prefix = "ib1:";
      &lock = "RTDM";
      &state = &state | %This.Rows("PSIBRTNGDEFN", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSIBRTNGSUBDEFN", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSRTNGDFNPARM", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSRTNGDFNCONPRP", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSRTNGDFNLANG", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSRTNGDFNPROP", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSRTNGDFNPROPLG", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      &state = &state | %This.Rows("PSIBRTNGDEFNDEL", "WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", CreateArray(&name, &req.GetString("Effdt")));
      Break;
   When "permission"
      &prefix = "ib1:";
      &lock = "CLM";
      &state = &state | %This.Rows("PSCLASSDEFN", "WHERE CLASSID=:1", CreateArray(&req.GetString("permissionList")));
      &state = &state | %This.Rows("PSAUTHWS", "WHERE CLASSID=:1", CreateArray(&req.GetString("permissionList")));
      &state = &state | %This.Rows("PSOPERATION", "WHERE IB_OPERATIONNAME=:1", CreateArray(&name));
      Break;
   When "catalog"
      &prefix = "cat1:";
      &lock = "PPC";
      &state = &state | %This.Rows("PSMSGSETDEFN", "WHERE MESSAGE_SET_NBR=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSMSGSETLANG", "WHERE MESSAGE_SET_NBR=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSMSGCATDEFN", "WHERE MESSAGE_SET_NBR=:1", CreateArray(&name));
      &state = &state | %This.Rows("PSMSGCATLANG", "WHERE MESSAGE_SET_NBR=:1", CreateArray(&name));
      Break;
   When "portal"
      &prefix = "por1:";
      &lock = "PRSM";
      &state = &state | %This.Rows("PSPRSMDEFN", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMDEFNLANG", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMATTR", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMATTRLANG", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMATTRVAL", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMATTRVALNG", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMPERM", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMHIDDEN", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMCTRBEXCL", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMDEL", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMSYSATTR", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMSYSATTRVL", "WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMDEFN", "WHERE PORTAL_NAME=:1 AND (PORTAL_OBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 START WITH PORTAL_OBJNAME=:2 AND PORTAL_NAME=:1 CONNECT BY NOCYCLE PRIOR PORTAL_PRNTOBJNAME=PORTAL_OBJNAME AND PORTAL_NAME=:1) OR PORTAL_OBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 AND PORTAL_PRNTOBJNAME=:2))", CreateArray(&req.GetString("PortalName"), &name));
      &state = &state | %This.Rows("PSPRSMPERM", "WHERE PORTAL_NAME=:1 AND (PORTAL_OBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 START WITH PORTAL_OBJNAME=:2 AND PORTAL_NAME=:1 CONNECT BY NOCYCLE PRIOR PORTAL_PRNTOBJNAME=PORTAL_OBJNAME AND PORTAL_NAME=:1) OR PORTAL_OBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 AND PORTAL_PRNTOBJNAME=:2))", CreateArray(&req.GetString("PortalName"), &name));
      &state = &state | %This.Rows("PSPRSMDEFN", "WHERE PORTAL_LINK_PORTAL=:1 AND PORTAL_LINKOBJNAME=:2", CreateArray(&req.GetString("PortalName"), &name));
      &state = &state | %This.Rows("PSPRSMDEFN", "WHERE (PORTAL_NAME,PORTAL_OBJNAME) IN (SELECT PORTAL_LINK_PORTAL,PORTAL_LINKOBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3)", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      &state = &state | %This.Rows("PSPRSMPERM", "WHERE (PORTAL_NAME,PORTAL_OBJNAME) IN (SELECT PORTAL_LINK_PORTAL,PORTAL_LINKOBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME=:1 AND PORTAL_REFTYPE=:2 AND PORTAL_OBJNAME=:3)", CreateArray(&req.GetString("PortalName"), &req.GetString("RefType"), &name));
      Break;

   When-Other
      throw CreateException(0, 0, "Unsupported version kind");
   End-Evaluate;
   If Not %This.Present(&req) Then
      SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME=:1", &lock, &generation);
      &state = &state | "|ABSENT:" | String(&generation);
   End-If;
   Return &prefix | HashSHA256(&state);
end-method;

method Apply
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_META_DATA_PKG:Utility:NativeAdapter &engine = create C_META_DATA_PKG:Utility:NativeAdapter();
   If &req.GetString("kind") = "catalog" And
         &req.IsExist("language") Then
      Local C_META_DATA_PKG:Utility:CatalogLanguageAdapter &translations = create C_META_DATA_PKG:Utility:CatalogLanguageAdapter();
      Return &translations.Run(&req);
   End-If;
   If &req.GetString("kind") = "service" And
         &req.GetString("operationType") = "delete" Then
      &_serviceDeleteEngine = create C_META_DATA_PKG:Utility:NativeAdapter();
      Return &_serviceDeleteEngine.Run(&req);
   End-If;
   Return &engine.Run(&req);
end-method;

method RefreshServiceCache
   /+ &serviceName as String, +/
   /+ &observedService as Number, +/
   /+ &observedSystem as Number +/
   Local number &serviceGeneration, &systemGeneration;
   /* A native delete can publish an in-process cache generation before rollback.
      Advance cache generations beyond both the rolled-back and observed values;
      preserve logical attributes; advance the restored definition version so
      cached tombstones cannot mask an older restored row. */
   SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SRVM' FOR UPDATE OF VERSION", &serviceGeneration);
   If &serviceGeneration < &observedService Then
      &serviceGeneration = &observedService;
   End-If;
   &serviceGeneration = &serviceGeneration + 1;
   SQLExec("UPDATE PSLOCK SET VERSION=:1 WHERE OBJECTTYPENAME='SRVM'", &serviceGeneration);
   SQLExec("UPDATE PSSERVICE SET VERSION=:1 WHERE IB_SERVICENAME=:2", &serviceGeneration, &serviceName);
   SQLExec("UPDATE PSVERSION SET VERSION=:1 WHERE OBJECTTYPENAME='SRVM'", &serviceGeneration);
   SQLExec("SELECT VERSION FROM PSVERSION WHERE OBJECTTYPENAME='SYS' FOR UPDATE OF VERSION", &systemGeneration);
   If &systemGeneration < &observedSystem Then
      &systemGeneration = &observedSystem;
   End-If;
   &systemGeneration = &systemGeneration + 1;
   SQLExec("UPDATE PSVERSION SET VERSION=:1 WHERE OBJECTTYPENAME='SYS'", &systemGeneration);
   SQLExec("commit");
end-method;

method Decorate
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &data as C_JSON_API:JSONObject, +/
   /+ &before as String +/
   /+ Returns C_JSON_API:JSONObject +/
   &data.AddProperty("beforeVersion", &before);
   &data.AddProperty("version", %This.Version(&req));
   &data.AddProperty("managedVersionControl", 1);
   &data.AddJsonObject("versionKeys", %This.Keys(&req));
   If &req.GetString("kind") = "service" Then
      &data.AddProperty("serviceDeleteVersion", 1);
   End-If;
   Return &data;
end-method;

method Read
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &view = %This.Keys(&req);
   Local C_JSON_API:JSONObject &result;
   Local Rowset &ownedRows;
   Local Record &ownedRecord;
   Local C_JSON_API:JSONArray &ownedNames;
   Local integer &ownedCount, &ownedIndex;
   Local C_COMMONS_PKG:CommonUtil &ownedUtil = create C_COMMONS_PKG:CommonUtil();
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local string &before = %This.Version(&req);
   Local boolean &exists = %This.Present(&req);
   If Not &exists Then
      &result = CreateObject("C_JSON_API:Factory").NewObject();
      &result.AddProperty("exists", &exists);
      If &req.GetString("kind") = "catalog" Then
         &result.AddJsonArray("messages", CreateObject("C_JSON_API:Factory").NewArray());
         &result.AddJsonArray("allTranslations", CreateObject("C_JSON_API:Factory").NewArray());
      End-If;
   Else
      If &req.GetString("operationType") = "exists" And
            &req.GetString("kind") <> "permission" Then
         &view.AddProperty("operationType", "exists");
      Else
         &view.AddProperty("operationType", "view");
      End-If;
      If &req.GetString("kind") = "catalog" Then
         &view = &json.GetRootObject(&view.ToString());
      End-If;
      &result = %This.Apply(&view);
      If Not &result.IsExist("exists") Then
         &result.AddProperty("exists", True);
      End-If;
   End-If;
   If &req.GetString("kind") = "service" Then
      &ownedNames = CreateObject("C_JSON_API:Factory").NewArray();
      &ownedRows = CreateRowset(Record.PSOPERATION);
      &ownedCount = &ownedRows.Fill("WHERE IB_SERVICENAME=:1 ORDER BY IB_OPERATIONNAME", &req.GetString("name"));
      For &ownedIndex = 1 To &ownedCount
         &ownedRecord = &ownedRows.GetRow(&ownedIndex).GetRecord(Record.PSOPERATION);
         &ownedNames.AddElement(String(&ownedRecord.GetField(Field.IB_OPERATIONNAME).Value));
      End-For;
      &result.AddJsonArray("ownedOperations", &ownedNames);
      &ownedNames = &result.GetJsonArray("ownedOperations");
   End-If;
   If &before <> %This.Version(&req) Then
      %This.Status = 409;
      throw CreateException(0, 0, "VERSION_CONFLICT: definition changed during read");
   End-If;
   Return %This.Decorate(&req, &result, &before);
end-method;

method Run
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &action = &req.GetString("operationType");
   Local string &before;
   Local boolean &dry = False;
   Local boolean &serviceDeleteAttempted = False;
   Local number &observedService, &observedServiceLock, &observedSystem;
   Local C_JSON_API:JSONObject &result;
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   &_serviceDeleteEngine = Null;
   If &action = "view" Or
         &action = "struct" Or
         &action = "exists" Then
      Return %This.Read(&req);
   End-If;
   If &action = "validate" Then
      Return %This.Apply(&req);
   End-If;
   If &action = "workflow" Then
      Return %This.Workflow(&req);
   End-If;
   If CreateArray("create", "createSet", "modify", "delete", "deleteChild").Find(&action) = 0 Then
      throw CreateException(0, 0, "Unsupported versioned operation");
   End-If;
   try
      %This.Lock(&req.GetString("kind"));
      &before = %This.Version(&req);
      %This.Status = &guard.Check(&req, &before);
      If %This.Status <> 0 Then
         throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: use the original snapshot");
      End-If;
      %This.Status = 400;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      &result = %This.Apply(&req);
      &result = %This.Decorate(&req, &result, &before);
      If &dry Then
         SQLExec("rollback");
      Else
         SQLExec("commit");
      End-If;
      Return &result;
   catch Exception &ex
      If &_serviceDeleteEngine <> Null Then
         &serviceDeleteAttempted = &_serviceDeleteEngine.ServiceDeleteAttempted;
      End-If;
      If &serviceDeleteAttempted Then
         SQLExec("SELECT VERSION FROM PSLOCK WHERE OBJECTTYPENAME='SRVM'", &observedServiceLock);
         SQLExec("SELECT VERSION FROM PSVERSION WHERE OBJECTTYPENAME='SRVM'", &observedService);
         SQLExec("SELECT VERSION FROM PSVERSION WHERE OBJECTTYPENAME='SYS'", &observedSystem);
         If &observedService < &observedServiceLock Then
            &observedService = &observedServiceLock;
         End-If;
      End-If;
      SQLExec("rollback");
      If &serviceDeleteAttempted Then
         try
            %This.RefreshServiceCache(&req.GetString("name"), &observedService, &observedSystem);
         catch Exception &cacheError
            SQLExec("rollback");
            throw CreateException(0, 0, "Service delete rolled back; cache invalidation failed: " | &cacheError.ToString());
         end-try;
      End-If;
      throw &ex;
   end-try;
end-method;

method Workflow
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   Local C_JSON_API:JSONArray &steps = &req.GetJsonArray("steps");
   Local C_JSON_API:JSONArray &results = CreateObject("C_JSON_API:Factory").NewArray();
   Local C_JSON_API:JSONObject &step, &result, &view;
   Local string &before, &kind, &owner;
   Local integer &i;
   Local boolean &dry = False;
   try
      If &req.GetString("kind") <> "operation" Then
         throw CreateException(0, 0, "Workflow root must be an operation");
      End-If;
      If &steps.Size < 1 Or
            &steps.Size > 200 Then
         throw CreateException(0, 0, "Workflow requires 1-200 exact steps");
      End-If;
      %This.Lock("operation");
      &before = %This.Version(&req);
      %This.Status = &guard.Check(&req, &before);
      If %This.Status <> 0 Then
         throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: original workflow root");
      End-If;
      %This.Status = 400;
      If &req.IsExist("dryRun") Then
         &dry = &req.GetBoolean("dryRun");
      End-If;
      For &i = 1 To &steps.Size
         &step = &steps.GetJsonObject(&i);
         &kind = &step.GetString("kind");
         If CreateArray("operation", "version", "handler", "routing", "permission").Find(&kind) = 0 Then
            throw CreateException(0, 0, "Unsupported workflow definition");
         End-If;
         &owner = &step.GetString("name");
         If &kind = "routing" Then
            If &step.GetString("operationType") = "create" Then
               &owner = &step.GetJsonObject("properties").GetString("Operationname");
            Else
               SQLExec("SELECT IB_OPERATIONNAME FROM PSIBRTNGDEFN WHERE ROUTINGDEFNNAME=:1 AND EFFDT=TO_DATE(:2,'YYYY-MM-DD')", &step.GetString("name"), &step.GetString("Effdt"), &owner);
            End-If;
         End-If;
         If &owner <> &req.GetString("name") Then
            throw CreateException(0, 0, "Workflow step belongs to another operation");
         End-If;
         %This.Status = &guard.Check(&step, %This.Version(&step));
         If %This.Status <> 0 Then
            throw CreateException(0, 0, "EXPECTED_VERSION_REQUIRED or VERSION_CONFLICT: original workflow step");
         End-If;
         %This.Status = 400;
      End-For;
      %This.Status = 400;
      For &i = 1 To &steps.Size
         &step = &steps.GetJsonObject(&i);
         &step.AddProperty("dryRun", &dry);
         If &dry And
               &step.GetString("kind") = "permission" And
               Not %This.Present(&step) Then
            Local integer &permissionPresent;
            SQLExec("SELECT COUNT(*) FROM PSCLASSDEFN WHERE CLASSID=:1", &step.GetString("permissionList"), &permissionPresent);
            If &permissionPresent <> 1 Or
                  (&step.GetNumber("access") <> 0 And
                     &step.GetNumber("access") <> 4) Then
               throw CreateException(0, 0, "Existing permission list and supported access are required");
            End-If;
            &result = CreateObject("C_JSON_API:Factory").NewObject();
            &result.AddProperty("dryRun", True);
         Else
            &result = %This.Apply(&step);
         End-If;
         &results.AddJsonObjectElement("", &result);
         &result = &results.GetJsonObject(&results.Size);
      End-For;
      Local C_JSON_API:JSONArray &states = CreateObject("C_JSON_API:Factory").NewArray();
      For &i = 1 To &steps.Size
         &step = &steps.GetJsonObject(&i);
         &view = %This.Keys(&step);
         &view.AddProperty("operationType", "struct");
         &states.AddJsonObjectElement("", %This.Read(&view));
      End-For;
      &result = CreateObject("C_JSON_API:Factory").NewObject();
      &result.AddProperty("dryRun", &dry);
      &result.AddJsonArray("results", &results);
      &results = &result.GetJsonArray("results");
      &result.AddJsonArray("states", &states);
      &states = &result.GetJsonArray("states");
      &result = %This.Decorate(&req, &result, &before);
      If &dry Then
         SQLExec("rollback");
      Else
         SQLExec("commit");
      End-If;
      Return &result;
   catch Exception &ex
      SQLExec("rollback");
      throw &ex;
   end-try;
end-method;

class MappingUtil
   method MappingUtil();

   method GetFieldTypeName(&p_code As integer, &p_format As integer) Returns string;
   method GetDbTypeName(&p_value As string) Returns string;
   method GetDbTypeCode(&p_value As string) Returns integer;
   method DecodePnlType(&p_pnlType As number) Returns string;
   method DecodePnlFieldType(&p_fieldType As number, &p_displayType As number) Returns string;
end-class;

method MappingUtil

end-method;

method GetFieldTypeName
   /+ &p_code as Integer, +/
   /+ &p_format as Integer +/
   /+ Returns String +/
   Local string &FieldTypeName;

   Evaluate &p_code
   When 0
      &FieldTypeName = "character";
      Break;
   When 1
      &FieldTypeName = "long character";
      Break;
   When 2
      &FieldTypeName = "number";
      Break;
   When 3
      &FieldTypeName = "signed number";
      Break;
   When 4
      &FieldTypeName = "date";
      Break;
   When 5
      &FieldTypeName = "time";
      Break;
   When 6
      &FieldTypeName = "datetime";
      Break;
   When 8
      If &p_format = 16 Then
         &FieldTypeName = "attachment";
      Else
         &FieldTypeName = "image";
      End-If;
   When 9
      &FieldTypeName = "imageReference";
   End-Evaluate;

   Return &FieldTypeName;
end-method;

method GetDbTypeName
   /+ &p_value as String +/
   /+ Returns String +/
   Local string &DbName;

   Evaluate &p_value
   When ""
      /* Default */
      &DbName = "default";
      Break;
   When "1"
      /* DB2 */
      &DbName = "DB2";
      Break;
   When "2"
      /* Oracle */
      &DbName = "ORACLE";
      Break;
   When "3"
      /* Informix */
      &DbName = "INFORMIX";
      Break;
   When "4"
      /* DB2Unix */
      &DbName = "DB2UNIX";
      Break;
   When "5"
      /* TimesTen */
      &DbName = "TIMESTEN";
      Break;
   When "6"
      /* Sybase */
      &DbName = "SYBASE";
      Break;
   When "7"
      /* Microsoft */
      &DbName = "MICROSOFT";
      Break;
   When-Other
      throw CreateException(0, 0, "Unknow dbType: " | &p_value);
   End-Evaluate;

   Return &DbName;
end-method;

method GetDbTypeCode
   /+ &p_value as String +/
   /+ Returns Integer +/
   Local integer &DbTypeCode;

   Evaluate Upper(LTrim(RTrim(&p_value)))
   When ""
   When "DEFAULT"
   When "32"
      /* Default */
      &DbTypeCode = 32;
      Break;
   When "1"
   When "DB2"
   When "49"
      /* DB2 */
      &DbTypeCode = 49;
      Break;
   When "2"
   When "ORACLE"
   When "50"
      /* Oracle */
      &DbTypeCode = 50;
      Break;
   When "3"
   When "INFORMIX"
   When "51"
      /* Informix */
      &DbTypeCode = 51;
      Break;
   When "4"
   When "DB2UNIX"
   When "52"
      /* DB2Unix */
      &DbTypeCode = 52;
      Break;
   When "5"
   When "TIMESTEN"
   When "53"
      /* TimesTen */
      &DbTypeCode = 53;
      Break;
   When "6"
   When "SYBASE"
   When "54"
      /* Sybase */
      &DbTypeCode = 54;
      Break;
   When "7"
   When "MICROSOFT"
   When "55"
      /* Microsoft */
      &DbTypeCode = 55;
      Break;
   When-Other
      throw CreateException(0, 0, "Unsupported dbType: " | &p_value);
   End-Evaluate;

   Return &DbTypeCode;
end-method;

method DecodePnlType
   /+ &p_pnlType as Number +/
   /+ Returns String +/
   Evaluate &p_pnlType
   When 0
      Return "standard";
   When 1
      Return "subPage";
   When 2
      Return "secondary";
   When-Other
      Return "unknown(" | &p_pnlType | ")";
   End-Evaluate;
end-method;

method DecodePnlFieldType
   /+ &p_fieldType as Number, +/
   /+ &p_displayType as Number +/
   /+ Returns String +/
   Evaluate &p_fieldType
   When 0
      Return "staticText";
   When 1
      Return "frame";
   When 2
      Return "groupBox";
   When 3
      Return "staticImage";
   When 4
      Return "editBox";
   When 5
      Return "dropDownList";
   When 6
      Return "longEditBox";
   When 7
      Return "checkBox";
   When 8
      Return "radioButton";
   When 9
      Return "image";
   When 10
      Return "scrollBar";
   When 11
      Return "subPage";
   When 12
      If &p_displayType = 1 Then
         Return "Hyperlink (peoplecode)";
      Else
         Return "pushButton (peoplecode)";
      End-If;
   When 13
      If &p_displayType = 1 Then
         Return "Hyperlink (scrollAction)";
      Else
         Return "pushButton (scrollAction)";
      End-If;
   When 14
      If &p_displayType = 1 Then
         Return "Hyperlink (toolbarAction)";
      Else
         Return "pushButton (toolbarAction)";
      End-If;
   When 15
      If &p_displayType = 1 Then
         Return "Hyperlink (External Link)";
      Else
         Return "pushButton (External Link)";
      End-If;
   When 16
      If &p_displayType = 1 Then
         Return "Hyperlink (Internal Link)";
      Else
         Return "pushButton (Internal Link)";
      End-If;
   When 17
      If &p_displayType = 1 Then
         Return "Hyperlink (Process)";
      Else
         Return "pushButton (Process)";
      End-If;
   When 18
      Return "secondaryPage";
   When 19
      Return "grid";
   When 20
      Return "tree";
   When 21
      If &p_displayType = 1 Then
         Return "Hyperlink (SecondaryPage)";
      Else
         Return "pushButton (SecondaryPage)";
      End-If;
   When 23
      Return "horizontalRule";
   When 24
      Return "tabSeparator";
   When 25
      Return "HTMLArea";
   When 26
      If &p_displayType = 1 Then
         Return "Hyperlink (PromptAction)";
      Else
         Return "pushButton (PromptAction)";
      End-If;
   When 27
      Return "scrollArea";
   When 29
      If &p_displayType = 1 Then
         Return "Hyperlink (PageAnchor)";
      Else
         Return "pushButton (PageAnchor)";
      End-If;
   When 30
      Return "chart";
   When 31
      If &p_displayType = 1 Then
         Return "Hyperlink (InstantMessaging)";
      Else
         Return "pushButton (InstantMessaging)";
      End-If;
   When 32
      Return "analyticGrid";
   When-Other
      Return "unknown(" | &p_fieldType | ")";
   End-Evaluate;
end-method;

import C_JSON_API:*;
import %metadata:Key;
import C_META_DATA_PKG:Utility:DefinitionVersion;
import %metadata:PeopleCodeProgram:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_COMMONS_PKG:CommonUtil;

class MenuCodeAdapter
   method MenuCodeAdapter();
   method Run(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
end-class;

method MenuCodeAdapter
end-method;

method Run
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &name = &req.GetString("name");
   Local string &bar = &req.GetString("BarName");
   Local string &item = &req.GetString("ItemName");
   Local string &action = &req.GetString("operationType");
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   Local array of integer &menuIDs = &objectKeys.GetObjectIDs(6, CreateArray(&name, " ", " ", " "));
   Local object &menuKey = CreateObject("%metadata:Key", &menuIDs [1], &name);
   Local object &menuMgr = CreateObject("%metadata:MenuDefn:MenuDefn_Manager");
   If Not ObjectDoMethodArray(&menuMgr, "DefnExists", CreateArrayAny(&menuKey)) Then
      throw CreateException(0, 0, "Menu does not exist");
   End-If;
   Local object &menu = ObjectDoMethodArray(&menuMgr, "GetDefnToUpdate", CreateArrayAny(&menuKey));
   If ObjectGetProperty(&menu, "Menutype") <> 1 Then
      throw CreateException(0, 0, "ItemSelected PeopleCode requires a Pop-up menu");
   End-If;
   Local integer &i;
   Local boolean &found = False;
   Local object &mit;
   For &i = 1 To ObjectGetProperty(&menu, "Count_Mit")
      &mit = ObjectDoMethodArray(&menu, "Get_Mit", CreateArrayAny(&i));
      If ObjectGetProperty(&mit, "BarName") = &bar And
            ObjectGetProperty(&mit, "ItemName") = &item Then
         &found = True;
         Break;
      End-If;
   End-For;
   If Not &found Then
      throw CreateException(0, 0, "Exact menu bar/item does not exist");
   End-If;
   Local array of integer &ids = &objectKeys.GetObjectIDs(9, CreateArray(&name, &bar, &item, "ItemSelected"));
   Local %metadata:Key &key = create %metadata:Key(&ids [1], &name);
   &key.AddItem(&ids [2], &bar);
   &key.AddItem(&ids [3], &item);
   &key.AddItem(&ids [4], "ItemSelected");
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgr = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &prog;
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   Local boolean &exists = &mgr.DefnExists(&key);
   Local boolean &dry = False;
   Local string &before = "";
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   If &exists Then
      &prog = &mgr.GetDefnToUpdate(&key);
      &before = &prog.GetProgram();
   End-If;
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   &out.AddProperty("exists", &exists);
   &out.AddProperty("programExists", &exists);
   &out.AddProperty("BarName", &bar);
   &out.AddProperty("ItemName", &item);
   &out.AddProperty("event", "ItemSelected");
   Local C_META_DATA_PKG:Utility:DefinitionVersion &guard = create C_META_DATA_PKG:Utility:DefinitionVersion();
   &out.AddJsonObject("projectItem", &guard.ProjectItem(9, CreateArray(&name, &bar, &item, "ItemSelected"), False));
   &out.AddProperty("peoplecode", &before);
   If &action = "viewCode" Then
      Return &out;
   End-If;
   If Not &req.IsExist("expectedCode") Then
      throw CreateException(0, 0, "Menu PeopleCode write requires expectedCode from the original viewCode snapshot");
   End-If;
   If &req.GetString("expectedCode") <> &before Then
      throw CreateException(0, 0, "Menu PeopleCode changed since snapshot");
   End-If;
   If &action = "deleteCode" Then
      If Not &exists Then
         throw CreateException(0, 0, "Menu PeopleCode does not exist");
      End-If;
      If Not &dry Then
         If Not &mgr.DeleteDefn(&key) Then
            throw CreateException(0, 0, "DeleteDefn failed for menu PeopleCode");
         End-If;
         If &mgr.DefnExists(&key) Then
            throw CreateException(0, 0, "Menu PeopleCode still exists after deletion");
         End-If;
      End-If;
      &out.AddProperty("deleted", ( Not &dry));
      &out.AddProperty("dryRun", &dry);
      Return &out;
   End-If;
   If &action <> "modifyCode" Then
      throw CreateException(0, 0, "Unknown menu PeopleCode action");
   End-If;
   Local string &code = &req.GetString("peoplecode");
   Local string &NonBlankCode = &code;
   &NonBlankCode = Substitute(&NonBlankCode, Char(9), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(10), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(11), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(12), "");
   &NonBlankCode = Substitute(&NonBlankCode, Char(13), "");
   If Len(LTrim(RTrim(&NonBlankCode))) = 0 Then
      throw CreateException(0, 0, "Empty PeopleCode is not deletion; use deleteCode");
   End-If;
   If Not &exists Then
      &prog = &mgr.CreateDefn();
      &prog.ObjectID#0# = &ids [1];
      &prog.ObjectValue#0# = &name;
      &prog.ObjectID#1# = &ids [2];
      &prog.ObjectValue#1# = &bar;
      &prog.ObjectID#2# = &ids [3];
      &prog.ObjectValue#2# = &item;
      &prog.ObjectID#3# = &ids [4];
      &prog.ObjectValue#3# = "ItemSelected";
   End-If;
   Local string &error;
   Local integer &start, &finish;
   If Not &prog.UpdateProgram(&code, &error, &start, &finish) Then
      throw CreateException(0, 0, "PeopleCode compile failed: " | &error | " positions " | &start | "," | &finish);
   End-If;
   If Not &dry Then
      If &exists Then
         If Not &prog.UpdateDefn() Then
            throw CreateException(0, 0, "PeopleCode UpdateDefn failed");
         End-If;
      Else
         If Not &prog.SaveNewDefn() Then
            throw CreateException(0, 0, "PeopleCode SaveNewDefn failed");
         End-If;
      End-If;
      &prog = &mgr.GetDefn(&key);
   End-If;
   &out.AddProperty("afterCode", &prog.GetProgram());
   &out.AddProperty("dryRun", &dry);
   Return &out;
end-method;

import C_JSON_API:*;
import C_JSON_API:JsonUtil;
import C_META_DATA_PKG:Utility:SqlTextGuard;

class MetadataAccess
   method MetadataAccess();
   method Check(&message As Message, &operation As string, &defaultAction As string, &allowed As array of string) Returns string;
end-class;

method MetadataAccess
end-method;

method Check
   /+ &message as Message, +/
   /+ &operation as String, +/
   /+ &defaultAction as String, +/
   /+ &allowed as Array of String +/
   /+ Returns String +/
   Local C_META_DATA_PKG:Utility:SqlTextGuard &security = create C_META_DATA_PKG:Utility:SqlTextGuard();
   Local C_JSON_API:JsonUtil &json = create C_JSON_API:JsonUtil();
   Local C_JSON_API:JSONObject &req;
   Local string &action = &defaultAction;
   If Not &security.Authorized(&operation) Then
      Return "OPERATION_PERMISSION_DENIED: current user has no Full permission for " | &operation;
   End-If;
   &req = &json.GetRootObject(&message.GetContentString());
   If &req.IsExist("operationType") Then
      &action = &req.GetString("operationType");
      If &action = "" Then
         &action = &defaultAction;
      End-If;
   End-If;
   If &allowed.Find(&action) = 0 Then
      Return "ACCESS_MODE_DENIED: operationType is not allowed by this read/write endpoint";
   End-If;
   Return "";
end-method;

import C_JSON_API:*;
import %metadata:Key;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_COMMONS_PKG:CommonUtil;

class NativeAdapter
   method NativeAdapter();
   method Run(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   property boolean ServiceDeleteAttempted;
private
   method ReadFields(&obj As object, &fields As array of string) Returns C_JSON_API:JSONObject;
   method PatchFields(&obj As object, &patch As C_JSON_API:JSONObject, &fields As array of string, &keys As array of string);
   method Snapshot(&obj As object, &fields As array of string, &collections As array of string, &childFields As array of string) Returns C_JSON_API:JSONObject;
   method CheckPortalContent(&obj As object, &mgr As object, &ids As array of integer);
   method SyncServiceMembership(&operationName As string, &oldService As string, &newService As string);
   method ChildKey(&obj As object, &row As C_JSON_API:JSONObject, &keyNames As string) Returns string;
   method ValidateCI(&defn As object);
   method HasField(&recordName As string, &fieldName As string) Returns boolean;
end-class;

method NativeAdapter
   %This.ServiceDeleteAttempted = False;
end-method;

method HasField
   /+ &recordName as String, +/
   /+ &fieldName as String +/
   /+ Returns Boolean +/
   Local number &found;
   SQLExec("SELECT COUNT(*) FROM PSRECFIELDDB WHERE RECNAME=:1 AND FIELDNAME=:2", &recordName, &fieldName, &found);
   Return (&found = 1);
end-method;

method ValidateCI
   /+ &defn as Object +/
   Local array of string &pages = CreateArrayRept("", 0);
   Local array of string &records = CreateArrayRept("", 0);
   Local array of string &collections = CreateArray("PS_ROOT");
   Local SQL &cursor;
   Local string &pageName, &subPage, &recordName, &itemName, &parentName;
   Local integer &i, &j, &typ, &depth;
   Local object &item, &ancestor;
   Local string &ancestorName;
   &cursor = CreateSQL("SELECT PNLNAME FROM PSPNLGROUP WHERE PNLGRPNAME=:1 AND MARKET=:2", ObjectGetProperty(&defn, "BcPanelGroup"), ObjectGetProperty(&defn, "BcMarket"));
   While &cursor.Fetch(&pageName)
      If &pages.Find(&pageName) = 0 Then
         &pages.Push(&pageName);
      End-If;
   End-While;
   &cursor.Close();
   &i = 1;
   While &i <= &pages.Len
      If &pages.Len > 1000 Then
         throw CreateException(0, 0, "CI component contains more than 1000 pages/subpages");
      End-If;
      &cursor = CreateSQL("SELECT DISTINCT RECNAME, SUBPNLNAME FROM PSPNLFIELD WHERE PNLNAME=:1", &pages [&i]);
      While &cursor.Fetch(&recordName, &subPage)
         If All(&recordName) And
               &records.Find(&recordName) = 0 Then
            &records.Push(&recordName);
         End-If;
         If All(&subPage) And
               &pages.Find(&subPage) = 0 Then
            &pages.Push(&subPage);
         End-If;
      End-While;
      &cursor.Close();
      &i = &i + 1;
   End-While;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Pit")
      &item = ObjectDoMethodArray(&defn, "Get_Pit", CreateArrayAny(&i));
      &typ = ObjectGetProperty(&item, "PropertyType");
      If &typ = 3 Then
         &itemName = ObjectGetProperty(&item, "BcItemName");
         If None(&itemName) Or
               &collections.Find(&itemName) > 0 Then
            throw CreateException(0, 0, "CI collection names must be nonempty and unique");
         End-If;
         &collections.Push(&itemName);
      End-If;
   End-For;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Pit")
      &item = ObjectDoMethodArray(&defn, "Get_Pit", CreateArrayAny(&i));
      &typ = ObjectGetProperty(&item, "PropertyType");
      &recordName = ObjectGetProperty(&item, "RecName");
      &parentName = ObjectGetProperty(&item, "ParentCollection");
      If ObjectGetProperty(&item, "Seq") < 1 Then
         throw CreateException(0, 0, "CI mapping Seq must be positive");
      End-If;
      If &collections.Find(&parentName) = 0 Then
         throw CreateException(0, 0, "CI mapping parent collection does not exist: " | &parentName);
      End-If;
      &ancestorName = &parentName;
      &depth = 0;
      While &ancestorName <> "PS_ROOT"
         &depth = &depth + 1;
         If &depth > &collections.Len Then
            throw CreateException(0, 0, "CI collection hierarchy contains a cycle");
         End-If;
         For &j = 1 To ObjectGetProperty(&defn, "Count_Pit")
            &ancestor = ObjectDoMethodArray(&defn, "Get_Pit", CreateArrayAny(&j));
            If ObjectGetProperty(&ancestor, "PropertyType") = 3 And
                  ObjectGetProperty(&ancestor, "BcItemName") = &ancestorName Then
               &ancestorName = ObjectGetProperty(&ancestor, "ParentCollection");
               Break;
            End-If;
         End-For;
      End-While;
      If &typ = 3 Or
            &typ = 4 Then
         If &records.Find(&recordName) = 0 Then
            throw CreateException(0, 0, "CI mapping record is not in the component pages/subpages: " | &recordName);
         End-If;
      Else
         If &recordName <> ObjectGetProperty(&defn, "BcSearchRec") And
               &recordName <> ObjectGetProperty(&defn, "BcAddSearchRec") Then
            throw CreateException(0, 0, "CI key record does not match search/add-search record");
         End-If;
      End-If;
   End-For;
end-method;

method ReadFields
   /+ &obj as Object, +/
   /+ &fields as Array of String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local integer &i;
   Local string &field, &name;
   Local any &value;
   Local C_COMMONS_PKG:CommonUtil &jsonUtil = create C_COMMONS_PKG:CommonUtil();
   For &i = 1 To &fields.Len
      &field = &fields [&i];
      &name = Substitute(Substitute(Substitute(Substitute(&field, "#", ""), "@", ""), "!", ""), "~", "");
      If &field = "Values~" Then
         Local C_JSON_API:JSONArray &values = CreateObject("C_JSON_API:Factory").NewArray();
         Local integer &vi;
         Local object &valueObj;
         For &vi = 1 To ObjectGetProperty(&obj, "Count_AttrValue")
            &valueObj = ObjectDoMethodArray(&obj, "Get_AttrValue", CreateArrayAny(&vi));
            &values.AddElement(String(ObjectGetProperty(&valueObj, "AttrValue")));
         End-For;
         &out.AddJsonArray("Values", &values);
         &values = &out.GetJsonArray("Values");
         Continue;
      End-If;
      &value = ObjectGetProperty(&obj, &name);
      If Find("@", &field) > 0 Then
         &out.AddProperty(&name, DateTimeToLocalizedString(&value, "yyyy-MM-dd"));
      Else
         If Find("#", &field) > 0 Or
               Find("!", &field) > 0 Then
            &out.AddProperty(&name, &value);
         Else
            &out.AddProperty(&name, String(&value));
         End-If;
      End-If;
   End-For;
   Return &out;
end-method;

method PatchFields
   /+ &obj as Object, +/
   /+ &patch as C_JSON_API:JSONObject, +/
   /+ &fields as Array of String, +/
   /+ &keys as Array of String +/
   Local integer &i, &j, &at;
   Local string &name, &field;
   Local any &value;
   For &i = 1 To &patch.ChildCount
      &name = &patch.GetPropertyNameAt(&i);
      &at = 0;
      For &j = 1 To &fields.Len
         If Substitute(Substitute(Substitute(Substitute(&fields [&j], "#", ""), "@", ""), "!", ""), "~", "") = &name Or
               (&fields [&j] = "Values~" And
                  &name = "Values") Then
            &at = &j;
         End-If;
      End-For;
      If &at = 0 Then
         throw CreateException(0, 0, "Unknown property: " | &name | " allowed " | &fields.Join(","));
      End-If;
      &field = &fields [&at];
      If &field = "Values~" Then
         Local C_JSON_API:JSONArray &newValues = &patch.GetJsonArray("Values");
         If &newValues.Size > 1 Then
            throw CreateException(0, 0, "Portal attributes require one string value for PIA compatibility; separate logical values with semicolons");
         End-If;
         Local integer &vi, &vc;
         Local object &valueObj;
         &vc = ObjectGetProperty(&obj, "Count_AttrValue");
         For &vi = &vc To 1 Step - 1
            ObjectDoMethodArray(&obj, "Delete_AttrValue", CreateArrayAny(&vi));
         End-For;
         &valueObj = ObjectDoMethodArray(&obj, "Append_AttrValue", CreateArrayAny(0));
         ObjectSetProperty(&valueObj, "AttrSeqNbr", 1);
         If &newValues.Size = 0 Then
            ObjectSetProperty(&valueObj, "AttrValue", "");
         Else
            ObjectSetProperty(&valueObj, "AttrValue", &newValues.GetString(1));
         End-If;
         Continue;
      End-If;
      If Find("#", &field) > 0 Then
         &value = &patch.GetNumber(&name);
         If &value <> Int(&value) Then
            throw CreateException(0, 0, "Integer property required: " | &name);
         End-If;
      Else
         If Find("@", &field) > 0 Then
            &value = Date(&patch.GetString(&name));
         Else
            If Find("!", &field) > 0 Then
               &value = &patch.GetBoolean(&name);
            Else
               &value = &patch.GetString(&name);
            End-If;
         End-If;
      End-If;
      If &keys.Find(&name) > 0 Then
         If String(ObjectGetProperty(&obj, &name)) <> String(&value) Then
            throw CreateException(0, 0, "Key cannot be changed: " | &name);
         End-If;
      Else
         ObjectSetProperty(&obj, &name, &value);
      End-If;
   End-For;
end-method;

method Snapshot
   /+ &obj as Object, +/
   /+ &fields as Array of String, +/
   /+ &collections as Array of String, +/
   /+ &childFields as Array of String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONObject &out = %This.ReadFields(&obj, &fields);
   Local C_JSON_API:JSONArray &rows;
   Local object &child;
   Local array of string &names;
   Local integer &i, &j, &count;
   For &i = 1 To &collections.Len
      &rows = CreateObject("C_JSON_API:Factory").NewArray();
      &count = ObjectGetProperty(&obj, "Count_" | &collections [&i]);
      &names = Split(&childFields [&i], " ");
      For &j = 1 To &count
         &child = ObjectDoMethodArray(&obj, "Get_" | &collections [&i], CreateArrayAny(&j));
         &rows.AddJsonObjectElement("", %This.ReadFields(&child, &names));
      End-For;
      &out.AddJsonArray(&collections [&i], &rows);
      &rows = &out.GetJsonArray(&collections [&i]);
   End-For;
   Return &out;
end-method;

method ChildKey
   /+ &obj as Object, +/
   /+ &row as C_JSON_API:JSONObject, +/
   /+ &keyNames as String +/
   /+ Returns String +/
   Local array of string &parts = Split(&keyNames, "|");
   Local string &out = "";
   Local string &value;
   Local integer &i;
   For &i = 1 To &parts.Len
      If &row = Null Then
         &value = String(ObjectGetProperty(&obj, &parts [&i]));
      Else
         &value = &row.GetAsString(&parts [&i]);
      End-If;
      If None(&value) Then
         throw CreateException(0, 0, "Child key is required: " | &parts [&i]);
      End-If;
      &out = &out | Len(&value) | ":" | &value;
   End-For;
   Return &out;
end-method;

method CheckPortalContent
   /+ &obj as Object, +/
   /+ &mgr as Object, +/
   /+ &ids as Array of Integer +/
   Local integer &attributeIndex;
   Local object &attribute;
   For &attributeIndex = 1 To ObjectGetProperty(&obj, "Count_Attr")
      &attribute = ObjectDoMethodArray(&obj, "Get_Attr", CreateArrayAny(&attributeIndex));
      If ObjectGetProperty(&attribute, "Count_AttrValue") <> 1 Then
         throw CreateException(0, 0, "Portal attribute " | String(ObjectGetProperty(&attribute, "AttrName")) | " on " | String(ObjectGetProperty(&obj, "ObjName")) | " must have exactly one native value row for PIA compatibility. Keep one string value; separate logical values with semicolons.");
      End-If;
   End-For;
   If ObjectGetProperty(&obj, "IsLink") Then
      Local object &contentKey = CreateObject("%metadata:Key", &ids [1], String(ObjectGetProperty(&obj, "LinksPortalName")));
      ObjectDoMethod(&contentKey, "AddItem", &ids [2], "C");
      ObjectDoMethod(&contentKey, "AddItem", &ids [3], String(ObjectGetProperty(&obj, "LinksObjectName")));
      If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&contentKey)) Then
         throw CreateException(0, 0, "Link target does not exist");
      End-If;
      Local object &content = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&contentKey));
      If ObjectGetProperty(&content, "IsLink") Then
         throw CreateException(0, 0, "A link cannot target another link");
      End-If;
      %This.CheckPortalContent(&content, &mgr, &ids);
   End-If;
end-method;

method SyncServiceMembership
   /+ &operationName as String, +/
   /+ &oldService as String, +/
   /+ &newService as String +/
   Local object &serviceManager = CreateObject("%metadata:ServiceDefn:ServiceDefn_Manager");
   Local array of string &serviceNames = CreateArray(&newService, &oldService);
   Local object &serviceKey, &service, &member;
   Local integer &si, &mi, &memberCount, &memberIndex;
   Local boolean &changed;
   For &si = 1 To &serviceNames.Len
      If None(&serviceNames [&si]) Or
            (&si = 2 And
               &oldService = &newService) Then
         Continue;
      End-If;
      &serviceKey = create %metadata:Key(key:Class_ServiceName, &serviceNames [&si]);
      If Not ObjectDoMethodArray(&serviceManager, "DefnExists", CreateArrayAny(&serviceKey)) Then
         If &si = 1 Then
            throw CreateException(0, 0, "Parent service does not exist");
         Else
            Continue;
         End-If;
      End-If;
      &service = ObjectDoMethodArray(&serviceManager, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      &memberCount = ObjectGetProperty(&service, "Count_Serviceopr");
      &memberIndex = 0;
      &changed = False;
      For &mi = 1 To &memberCount
         &member = ObjectDoMethodArray(&service, "Get_Serviceopr", CreateArrayAny(&mi));
         If ObjectGetProperty(&member, "Operationname") = &operationName Then
            &memberIndex = &mi;
            Break;
         End-If;
      End-For;
      If &si = 1 And
            &memberIndex = 0 Then
         &member = ObjectDoMethodArray(&service, "Append_Serviceopr", CreateArrayAny(&memberCount));
         ObjectSetProperty(&member, "Operationname", &operationName);
         &changed = True;
      Else
         If &si = 2 And
               &memberIndex > 0 Then
            If Not ObjectDoMethodArray(&service, "Delete_Serviceopr", CreateArrayAny(&memberIndex)) Then
               throw CreateException(0, 0, "Service membership deletion failed");
            End-If;
            &changed = True;
         End-If;
      End-If;
      If &changed And
            Not ObjectDoMethodArray(&service, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Service membership save failed");
      End-If;
      &service = ObjectDoMethodArray(&serviceManager, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      &memberIndex = 0;
      For &mi = 1 To ObjectGetProperty(&service, "Count_Serviceopr")
         &member = ObjectDoMethodArray(&service, "Get_Serviceopr", CreateArrayAny(&mi));
         If ObjectGetProperty(&member, "Operationname") = &operationName Then
            &memberIndex = &mi;
            Break;
         End-If;
      End-For;
      If (&si = 1 And
            &memberIndex = 0) Or
            (&si = 2 And
               &memberIndex > 0) Then
         throw CreateException(0, 0, "Service membership readback failed");
      End-If;
   End-For;
end-method;

method Run
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &kind = &req.GetString("kind");
   If &kind = "permission" Then
      Local object &security = CreateObject("C_META_DATA_PKG:Utility:OperationSecurityAdapter");
      Return ObjectDoMethodArray(&security, "Run", CreateArrayAny(&req));
   End-If;
   If &kind = "catalog" Then
      Local object &catalog = CreateObject("C_META_DATA_PKG:Utility:CatalogAdapter");
      Return ObjectDoMethodArray(&catalog, "Run", CreateArrayAny(&req));
   End-If;
   Local string &action = &req.GetString("operationType");
   Local string &name = &req.GetString("name");
   Local string &className, &collection, &childKey, &childName, &keyProp, &saveMethod;
   Local object &mgr, &defn, &child;
   Local object &key;
   Local C_JSON_API:JSONObject &before, &after, &result, &patch, &row, &childPatches;
   Local C_JSON_API:JSONArray &rows;
   Local array of string &fields, &collections, &childFields, &childKeys, &keys, &names;
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &objectKeys;
   Local integer &i, &j, &n, &count, &found;
   Local boolean &exists, &ok;
   Local boolean &dryRun = False;
   If &kind = "menu" And
         (&action = "viewCode" Or
            &action = "modifyCode" Or
            &action = "deleteCode") Then
      Local object &menuCode = CreateObject("C_META_DATA_PKG:Utility:MenuCodeAdapter");
      Return ObjectDoMethodArray(&menuCode, "Run", CreateArrayAny(&req));
   End-If;
   If None(&name) Or
         Len(&name) > 30 Then
      throw CreateException(0, 0, "Definition name must have 1-30 characters");
   End-If;
   &collections = CreateArrayRept("", 0);
   &childFields = CreateArrayRept("", 0);
   &childKeys = CreateArrayRept("", 0);
   &keys = CreateArrayRept("", 0);
   Evaluate &kind
   When "image"
      &className = "ContentDefn";
      &keyProp = "ContName";
      &fields = CreateArray("ContName", "ContType#", "ContFmt", "Descr", "LanguageCd", "ObjectOwnerId", "ContStrData");
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &imageIDs = &objectKeys.GetObjectIDs(49, CreateArray(&name, "1", " ", " "));
      &key = CreateObject("%metadata:Key", &imageIDs [1], &name, &imageIDs [2], "1");
      &keys.Push("ContType");
      Break;
   When "html"
      &className = "ContentDefn";
      &keyProp = "ContName";
      &fields = CreateArray("ContName", "ContType#", "Descr", "LanguageCd", "ObjectOwnerId", "ContStrData");
      &key = create %metadata:Key(key:Class_Html, &name, key:Class_ContentType, "4");
      &keys.Push("ContType");
      Break;
   When "stylesheet"
      &className = "StylesheetDefn";
      &keyProp = "StyleSheetName";
      &fields = CreateArray("StyleSheetName", "StyleSheetType#", "Descr", "LanguageCd", "ObjectOwnerId", "ParentStyleSheet", "ExtStyleSheetStr");
      &key = create %metadata:Key(key:Class_StyleSheet, &name);
      Break;
   When "ci"
      &className = "CompInterfaceDefn";
      &keyProp = "BcName";
      &fields = CreateArray("BcName", "BcDisplayName", "BcDescr", "BcPanelGroup", "BcMarket", "BcMenuName", "BcSearchRec", "BcAddSearchRec", "StandardMethods#", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &ciIDs = &objectKeys.GetObjectIDs(32, CreateArray(&name, " ", " ", " "));
      &key = CreateObject("%metadata:Key", &ciIDs [1], &name);
      &collections.Push("Pit");
      &childFields.Push("PropertyType# ParentCollection BcItemName Seq# Access# ScrollLevel# ScrollNum# ScrollName RecName SubRecName FieldName ShortComment DevicePersistence#");
      &childKeys.Push("Seq");
      Break;
   When "service"
      &className = "ServiceDefn";
      &keyProp = "Ib_servicename";
      &fields = CreateArray("Ib_servicename", "Ib_namespace", "Ib_aliasname", "RestService#", "Psftservice_flag", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      If %This.HasField("PSSERVICE", "PTIB_APPSRVGRP") Then
         &fields.Push("Ptibappsrvgrp");
      End-If;
      If %This.HasField("PSSERVICE", "PTIBAPPLNAME") Then
         &fields.Push("Ptibapplname");
      End-If;
      If %This.HasField("PSSERVICE", "PT_OPEN_API") Then
         &fields.Push("OpenAPI#");
      End-If;
      &key = create %metadata:Key(key:Class_ServiceName, &name);
      &collections.Push("Serviceopr");
      &childFields.Push("Operationname");
      &childKeys.Push("Operationname");
      Break;
   When "operation"
      &className = "OperationDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Servicename", "Defaultversion", "Rtngtype", "Userpwdreq", "RequestStatus", "ActiveDataGuard#", "ThinkTime#", "ConNav#", "Restmethod", "RestService#", "RestBaseurl", "RestOverride#", "Ib_aliasname", "Messagename", "Messageversion", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &key = create %metadata:Key(key:Class_OperationName, &name);
      &collections.Push("Operationuritemplate");
      If %This.HasField("PSOPERATIONURI", "IBTRANSACTIONID") Then
         &childFields.Push("URISeq# URITemplate RootResource Ibtransactionid");
      Else
         &childFields.Push("URISeq# URITemplate");
      End-If;
      &childKeys.Push("URISeq");
      &collections.Push("Operationhandler");
      &childFields.Push("Handlername Handlerid Active_flag Seqnumber#");
      &childKeys.Push("Handlername");
      &collections.Push("Operationversion");
      &childFields.Push("Versionname");
      &childKeys.Push("Versionname");
      Break;
   When "version"
      &className = "OperationVersionDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Versionname", "Active_flag", "Validation", "Nr_flag", "Syncnonblock", "Export_flag", "Multi_queue", "Clientimplement", "ExcludeToken", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Versionname");
      &key = create %metadata:Key(key:Class_OperationName, &name, key:Class_VersionName, &req.GetString("Versionname"));
      &collections.Push("Oprverdfnparm");
      &childFields.Push("Parametername Messagename Messageversion HTTPStatusCode# ContentType Queuename Xfrmname Outxfrmname");
      &childKeys.Push("Parametername");
      &collections.Push("Oprvgenrtgparm");
      &childFields.Push("Parametername Routingdefnname");
      &childKeys.Push("Parametername");
      Break;
   When "handler"
      &className = "OperationHandlerDefn";
      &keyProp = "Operationname";
      &fields = CreateArray("Operationname", "Handlername", "Handlerid", "Handlertype", "Active_flag", "Seqnumber#", "Rollback_flag", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Handlername");
      &key = create %metadata:Key(key:Class_OperationName, &name, key:Class_HandlerName, &req.GetString("Handlername"));
      &collections.Push("Operationac");
      &childFields.Push("Packageid Packageroot Qualifypath Classname Methodname");
      &childKeys.Push("Classname");
      Break;
   When "routing"
      &className = "RoutingDefn";
      &keyProp = "Routingdefnname";
      &fields = CreateArray("Routingdefnname", "Effdt@", "Eff_status", "Sendernodename", "Receivernodename", "Operationname", "Operationversion", "Rtngtype", "Restmethod", "LocalIndication#", "Generated", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &keys.Push("Effdt");
      &key = create %metadata:Key(key:Class_RoutingDefnName, &name, key:Class_EffDt, String(Date(&req.GetString("Effdt"))));
      &collections.Push("Ibrtngsubdefn");
      &childFields.Push("Seqnum# Direction Rtngtype Sendernodename Receivernodename Aliasname");
      &childKeys.Push("Seqnum");
      &collections.Push("Rtngdfnparm");
      &childFields.Push("Parametername Sendernodename Receivernodename Aliasname Operationversion");
      &childKeys.Push("Parametername");
      Break;
   When "menu"
      &className = "MenuDefn";
      &keyProp = "Menuname";
      &fields = CreateArray("Menuname", "Menutype#", "MenuLabel", "MenuGroup", "MenuOrder#", "GroupOrder#", "Installed!", "GroupSep!", "MenuSep!", "Descr", "Descrlong", "LanguageCd", "ObjectOwnerId");
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &menuIDs = &objectKeys.GetObjectIDs(6, CreateArray(&name, " ", " ", " "));
      &key = CreateObject("%metadata:Key", &menuIDs [1], &name);
      &collections.Push("Mit");
      &childFields.Push("BarName BarLabel ItemName ItemLabel ItemType# PnlGrpName Market ItemNum# AllowedActions# DisplayOnly! SearchRecName AddSearchRecName SearchPnlName");
      &childKeys.Push("BarName|ItemName");
      Break;
   When "portal"
      &className = "PortalRegStructDefn";
      &keyProp = "ObjName";
      &fields = CreateArray("PortalName", "RefType", "ObjName", "PrntObjName", "SeqNum#", "LabelName", "CntPrvName", "CrefUsageType", "CrefTemplateType", "CrefStorageType", "CrefURLType", "Descr", "Product", "EffectiveDate", "CreationDate", "ExpirationDate", "TemplateName", "StorageName", "IsPublic#", "LinksPortalName", "LinksObjectName", "URISeg1", "URISeg2", "URISeg3", "URISeg4", "Fluid!", "SmallFFOpt!", "IsVisible!", "URLLogical", "IsLink!");
      Local string &portalName = &req.GetString("PortalName");
      Local string &refType = &req.GetString("RefType");
      If &refType <> "F" And
            &refType <> "C" Then
         throw CreateException(0, 0, "RefType must be F or C; links use C with IsLink true");
      End-If;
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local array of integer &portalIDs = &objectKeys.GetObjectIDs(55, CreateArray(&portalName, &refType, &name, " "));
      &key = CreateObject("%metadata:Key", &portalIDs [1], &portalName);
      ObjectDoMethod(&key, "AddItem", &portalIDs [2], &refType);
      ObjectDoMethod(&key, "AddItem", &portalIDs [3], &name);
      &keys.Push("PortalName");
      &keys.Push("RefType");
      &keys.Push("IsLink");
      &collections.Push("Attr");
      &childFields.Push("AttrName AttrNameDsply Values~");
      &childKeys.Push("AttrName");
      &collections.Push("Permission");
      &childFields.Push("PermType PermName IsCascade!");
      &childKeys.Push("PermType|PermName");
      &collections.Push("InheritPermission");
      &childFields.Push("PermType PermName IsCascade!");
      &childKeys.Push("PermType|PermName");
      &collections.Push("ChildFldr");
      &childFields.Push("ObjName SeqNum#");
      &childKeys.Push("ObjName");
      &collections.Push("ChildCref");
      &childFields.Push("ObjName SeqNum#");
      &childKeys.Push("ObjName");
      Break;
   When-Other
      throw CreateException(0, 0, "Unsupported metadata kind");
   End-Evaluate;
   &keys.Push(&keyProp);
   If &kind = "version" Or
         &kind = "handler" Then
      Local string &secondaryKey = &req.GetString(&keys [1]);
      If None(&secondaryKey) Or
            Len(&secondaryKey) > 30 Then
         throw CreateException(0, 0, "Version/handler key must have 1-30 characters");
      End-If;
   End-If;
   &mgr = CreateObject("%metadata:" | &className | ":" | &className | "_Manager");
   &exists = ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key));
   If &action = "exists" Then
      &result = CreateObject("C_JSON_API:Factory").NewObject();
      &result.AddProperty("exists", &exists);
      Return &result;
   End-If;
   If &action = "create" Then
      If &exists Then
         throw CreateException(0, 0, "Definition already exists");
      End-If;
      If &kind = "image" Then
         If Not &req.IsExist("sourceName") Then
            throw CreateException(0, 0, "Image creation requires an existing source SVG definition");
         End-If;
         &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
         Local array of integer &sourceImageIDs = &objectKeys.GetObjectIDs(49, CreateArray(&req.GetString("sourceName"), "1", " ", " "));
         Local object &sourceImageKey = CreateObject("%metadata:Key", &sourceImageIDs [1], &req.GetString("sourceName"), &sourceImageIDs [2], "1");
         &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&sourceImageKey));
      Else
         &defn = ObjectDoMethodArray(&mgr, "CreateDefn", CreateArrayAny());
      End-If;
      ObjectSetProperty(&defn, &keyProp, &name);
      If &kind = "html" Then
         ObjectSetProperty(&defn, "ContType", 4);
         ObjectSetProperty(&defn, "LanguageCd", %Language);
      End-If;
      If &kind = "image" Then
         ObjectSetProperty(&defn, "ContType", 1);
         ObjectSetProperty(&defn, "ContFmt", "svg");
         ObjectSetProperty(&defn, "LanguageCd", %Language);
      End-If;
      If &kind = "stylesheet" Then
         ObjectSetProperty(&defn, "StyleSheetType", 2);
         ObjectSetProperty(&defn, "LanguageCd", %Language);
      End-If;
      If &kind = "portal" Then
         ObjectSetProperty(&defn, "PortalName", &req.GetString("PortalName"));
         ObjectSetProperty(&defn, "RefType", &req.GetString("RefType"));
         ObjectSetProperty(&defn, "IsVisible", True);
         ObjectSetProperty(&defn, "EffectiveDate", "1900-01-01");
         ObjectSetProperty(&defn, "CreationDate", DateTimeToLocalizedString(%Date, "yyyy-MM-dd"));
         If &req.GetString("RefType") = "C" Then
            ObjectSetProperty(&defn, "CrefUsageType", "TARG");
            ObjectSetProperty(&defn, "CrefStorageType", "RMTE");
            ObjectSetProperty(&defn, "CrefTemplateType", "HTML");
         End-If;
         If &req.IsExist("properties") Then
            &patch = &req.GetJsonObject("properties");
            If &patch.IsExist("IsLink") Then
               ObjectSetProperty(&defn, "IsLink", &patch.GetBoolean("IsLink"));
            End-If;
         End-If;
      End-If;
      If &kind = "version" Or
            &kind = "handler" Then
         ObjectSetProperty(&defn, &keys [1], &req.GetString(&keys [1]));
      End-If;
      If &kind = "routing" Then
         ObjectSetProperty(&defn, "Effdt", Date(&req.GetString("Effdt")));
      End-If;
   Else
      If Not &exists Then
         throw CreateException(0, 0, "Definition does not exist");
      End-If;
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
   End-If;
   &before = %This.Snapshot(&defn, &fields, &collections, &childFields);
   If &kind = "portal" And
         &action <> "create" Then
      If ObjectGetProperty(&defn, "IsLink") Then
         try
            %This.CheckPortalContent(&defn, &mgr, &portalIDs);
         catch Exception &linkPreflightEx
            If &action <> "validate" Then
               throw &linkPreflightEx;
            End-If;
            Local C_JSON_API:JSONObject &invalidLink = CreateObject("C_JSON_API:Factory").NewObject();
            Local C_COMMONS_PKG:CommonUtil &linkPreflightUtil = create C_COMMONS_PKG:CommonUtil();
            &invalidLink.AddProperty("valid", False);
            &invalidLink.AddProperty("error", &linkPreflightEx.ToString());
            Return &invalidLink;
         end-try;
      End-If;
      Local ApiObject &checkRegistry = %Session.GetPortalRegistry();
      &checkRegistry.Open(&req.GetString("PortalName"));
      Local ApiObject &checkPortalObj;
      If &req.GetString("RefType") = "F" Then
         &checkPortalObj = &checkRegistry.FindFolderByName(&name);
      Else
         If ObjectGetProperty(&defn, "IsLink") Then
            &checkPortalObj = &checkRegistry.FindCRefLinkByName(&name);
         Else
            &checkPortalObj = &checkRegistry.FindCRefByName(&name);
         End-If;
      End-If;
      If &checkPortalObj = Null Then
         throw CreateException(0, 0, "Portal object could not be loaded");
      End-If;
      If Not &checkPortalObj.Authorized Then
         throw CreateException(0, 0, "User is not authorized for portal object");
      End-If;
      If &action = "validate" Then
         Local C_JSON_API:JSONObject &validation = CreateObject("C_JSON_API:Factory").NewObject();
         Local C_JSON_API:JSONArray &runtimeRows = CreateObject("C_JSON_API:Factory").NewArray();
         Local ApiObject &runtimeCref, &runtimeCollection, &runtimeLink;
         Local boolean &runtimeValid = True;
         try
            %This.CheckPortalContent(&defn, &mgr, &portalIDs);
            If &req.GetString("RefType") = "F" Then
               Local integer &preIndex;
               Local object &preChild, &preKey, &preDefn;
               For &preIndex = 1 To ObjectGetProperty(&defn, "Count_ChildCref")
                  &preChild = ObjectDoMethodArray(&defn, "Get_ChildCref", CreateArrayAny(&preIndex));
                  &preKey = CreateObject("%metadata:Key", &portalIDs [1], &req.GetString("PortalName"));
                  ObjectDoMethod(&preKey, "AddItem", &portalIDs [2], "C");
                  ObjectDoMethod(&preKey, "AddItem", &portalIDs [3], String(ObjectGetProperty(&preChild, "ObjName")));
                  &preDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&preKey));
                  %This.CheckPortalContent(&preDefn, &mgr, &portalIDs);
               End-For;
            End-If;
         catch Exception &preEx
            Local C_COMMONS_PKG:CommonUtil &preUtil = create C_COMMONS_PKG:CommonUtil();
            &validation.AddProperty("valid", False);
            &validation.AddProperty("error", &preEx.ToString());
            &checkRegistry.Close();
            Return &validation;
         end-try;
         If &req.GetString("RefType") = "F" Then
            &runtimeCollection = &checkPortalObj.ContentRefs;
            &runtimeCref = &runtimeCollection.First();
         Else
            &runtimeCref = &checkRegistry.FindCRefByName(&name);
         End-If;
         Local C_COMMONS_PKG:CommonUtil &runtimeUtil = create C_COMMONS_PKG:CommonUtil();
         While &runtimeCref <> Null
            Local C_JSON_API:JSONObject &runtimeRow = CreateObject("C_JSON_API:Factory").NewObject();
            &runtimeRow.AddProperty("name", &runtimeCref.Name);
            try
               &runtimeRow.AddProperty("label", &runtimeCref.Label);
               &runtimeRow.AddProperty("node", String(&runtimeCref.NodeName));
               If &runtimeCref.IsLink Then
                  &runtimeLink = &checkRegistry.FindCRefLinkByName(&runtimeCref.Name);
                  If &runtimeLink = Null Then
                     throw CreateException(0, 0, "Content reference link could not be loaded");
                  End-If;
               End-If;
               &runtimeRow.AddProperty("qualifiedURL", String(&runtimeCref.QualifiedURL));
               If &runtimeCref.IsLink Then
                  &runtimeRow.AddProperty("linkCount", &runtimeLink.Links.Count);
               Else
                  &runtimeRow.AddProperty("linkCount", &runtimeCref.Links.Count);
               End-If;
               &runtimeRow.AddProperty("valid", True);
            catch Exception &runtimeEx
               &runtimeValid = False;
               &runtimeRow.AddProperty("valid", False);
               &runtimeRow.AddProperty("error", &runtimeEx.ToString());
            end-try;
            &runtimeRows.AddJsonObjectElement("", &runtimeRow);
            &runtimeRow = &runtimeRows.GetJsonObject(&runtimeRows.Size);
            If &req.GetString("RefType") = "F" Then
               &runtimeCref = &runtimeCollection.Next();
            Else
               Break;
            End-If;
         End-While;
         &checkRegistry.Close();
         &validation.AddProperty("valid", &runtimeValid);
         &validation.AddJsonArray("content", &runtimeRows);
         &runtimeRows = &validation.GetJsonArray("content");
         Return &validation;
      End-If;
      &checkRegistry.Close();
   End-If;
   If &action = "view" Or
         &action = "struct" Then
      Local C_COMMONS_PKG:CommonUtil &stateUtil = create C_COMMONS_PKG:CommonUtil();
      &before.AddProperty("stateToken", &before.ToString());
      Return &before;
   End-If;
   If &kind = "service" Or
         &kind = "operation" Then
      If &action = "create" Then
         ObjectSetProperty(&defn, "RestService", 2);
      Else
         If ObjectGetProperty(&defn, "RestService") <> 2 And
               ObjectGetProperty(&defn, "RestService") <> 0 Then
            throw CreateException(0, 0, "Only SOAP and REST Provider definitions can be modified");
         End-If;
      End-If;
   End-If;
   If &kind = "stylesheet" And
         &action <> "create" Then
      If ObjectGetProperty(&defn, "StyleSheetType") <> 2 Then
         throw CreateException(0, 0, "Only free-form StyleSheetType=2 can be modified");
      End-If;
   End-If;
   If (&kind = "html" Or
         &kind = "stylesheet" Or
         &kind = "ci") And
         Not &req.IsExist("expectedVersion") And
         &action <> "create" Then
      If Not &req.IsExist("expectedState") Then
         throw CreateException(0, 0, "expectedState is required; read a fresh definition before writing");
      End-If;
   End-If;
   If &kind = "operation" And
         &action <> "create" Then
      If (ObjectGetProperty(&defn, "RestService") <> 2 And
            ObjectGetProperty(&defn, "RestService") <> 0) Or
            ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Only synchronous SOAP and REST Provider operations can be modified");
      End-If;
   End-If;
   If &kind = "version" Or
         &kind = "handler" Or
         &kind = "routing" Then
      Local string &ownerOp = &name;
      If &kind = "routing" Then
         If &action = "create" Then
            &ownerOp = &req.GetJsonObject("properties").GetString("Operationname");
         Else
            &ownerOp = ObjectGetProperty(&defn, "Operationname");
         End-If;
      End-If;
      Local object &ownerManager = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
      Local object &ownerKey = create %metadata:Key(key:Class_OperationName, &ownerOp);
      If ObjectDoMethodArray(&ownerManager, "DefnExists", CreateArrayAny(&ownerKey)) Then
         Local object &ownerDefn = ObjectDoMethodArray(&ownerManager, "GetDefnToUpdate", CreateArrayAny(&ownerKey));
         If (ObjectGetProperty(&ownerDefn, "RestService") <> 2 And
               ObjectGetProperty(&ownerDefn, "RestService") <> 0) Or
               ObjectGetProperty(&ownerDefn, "Rtngtype") <> "S" Then
            throw CreateException(0, 0, "Parent operation must be synchronous SOAP or REST Provider");
         End-If;
      Else
         If Not (&req.IsExist("dryRun") And
               &req.GetBoolean("dryRun")) Then
            throw CreateException(0, 0, "Parent operation does not exist");
         End-If;
      End-If;
   End-If;
   If &kind = "portal" And
         &name = "PORTAL_ROOT_OBJECT" Then
      throw CreateException(0, 0, "Portal root is read-only");
   End-If;
   If &req.IsExist("expectedState") And
         &req.GetString("expectedState") <> &before.ToString() Then
      throw CreateException(0, 0, "Definition changed since snapshot; read again");
   End-If;
   If &req.IsExist("dryRun") Then
      &dryRun = &req.GetBoolean("dryRun");
   End-If;
   If &action = "delete" Then
      If &kind <> "service" And
            &kind <> "operation" And
            &kind <> "version" And
            &kind <> "handler" And
            &kind <> "routing" And
            &kind <> "portal" Then
         throw CreateException(0, 0, "Whole-definition deletion is not enabled for this kind");
      End-If;
      If &kind = "service" Then
         For &i = 1 To &req.ChildCount
            &collection = &req.GetPropertyNameAt(&i);
            If CreateArray("kind", "name", "operationType", "expectedVersion", "expectedState", "dryRun").Find(&collection) = 0 Then
               throw CreateException(0, 0, "Service delete accepts only its exact key, original version and dryRun; cascade and patches are not supported");
            End-If;
         End-For;
         SQLExec("SELECT COUNT(*) FROM PSOPERATION WHERE IB_SERVICENAME=:1", &name, &count);
         If &count <> 0 Or
               ObjectGetProperty(&defn, "Count_Serviceopr") <> 0 Then
            throw CreateException(0, 0, "Service is not empty; delete or move its Service Operations first");
         End-If;
      End-If;
      If &kind = "portal" And
            &req.GetString("RefType") <> "C" Then
         throw CreateException(0, 0, "Portal folder deletion is disabled, including empty folders");
      End-If;
      If &kind = "portal" And
            Not ObjectGetProperty(&defn, "IsLink") Then
         Local Rowset &referencingLinks = CreateRowset(Record.PSPRSMDEFN);
         If &referencingLinks.Fill("WHERE PORTAL_LINKOBJNAME = :1 AND PORTAL_LINK_PORTAL = :2", &name, &req.GetString("PortalName")) > 0 Then
            throw CreateException(0, 0, "CREF has referencing links; delete those exact links first");
         End-If;
      End-If;
      If Not &dryRun Then
         If &kind = "service" Then
            %This.ServiceDeleteAttempted = True;
         End-If;
         &ok = ObjectDoMethodArray(&mgr, "DeleteDefn", CreateArrayAny(&key));
         If Not &ok Then
            throw CreateException(0, 0, "Native DeleteDefn failed");
         End-If;
         If ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
            throw CreateException(0, 0, "Definition still exists after native deletion");
         End-If;
         If &kind = "operation" Then
            %This.SyncServiceMembership(&name, &before.GetString("Servicename"), "");
            Local object &cleanup = CreateObject("C_META_DATA_PKG:Utility:OperationSecurityAdapter");
            ObjectDoMethodArray(&cleanup, "Cleanup", CreateArrayAny(&name));
         End-If;
      End-If;
      &result = CreateObject("C_JSON_API:Factory").NewObject();
      &result.AddProperty("deleted", ( Not &dryRun));
      &result.AddProperty("dryRun", &dryRun);
      &result.AddJsonObject("before", &before);
      &before = &result.GetJsonObject("before");
      Return &result;
   End-If;
   If &action <> "create" And
         &action <> "modify" And
         &action <> "deleteChild" Then
      throw CreateException(0, 0, "Unsupported operationType");
   End-If;
   If &req.IsExist("properties") Then
      &patch = &req.GetJsonObject("properties");
      %This.PatchFields(&defn, &patch, &fields, &keys);
   End-If;
   If &req.IsExist("collections") Then
      &childPatches = &req.GetJsonObject("collections");
      For &i = 1 To &childPatches.ChildCount
         &collection = &childPatches.GetPropertyNameAt(&i);
         If (&kind = "service" And
               &collection = "Serviceopr") Or
               (&kind = "operation" And
                  (&collection = "Operationhandler" Or
                     &collection = "Operationversion")) Then
            throw CreateException(0, 0, "Derived definition references are read-only; create/modify the child definition instead");
         End-If;
         If &kind = "portal" And
               &collection <> "Attr" And
               &collection <> "Permission" Then
            throw CreateException(0, 0, "Portal navigation/inherited collections are read-only");
         End-If;
         &n = &collections.Find(&collection);
         If &n = 0 Then
            throw CreateException(0, 0, "Unsupported collection: " | &collection);
         End-If;
         &rows = &childPatches.GetJsonArray(&collection);
         &names = Split(&childFields [&n], " ");
         &childKey = &childKeys [&n];
         Local array of string &patchKeys = CreateArrayRept("", 0);
         For &j = 1 To &rows.Size
            &row = &rows.GetJsonObject(&j);
            If &kind = "menu" And
                  (&row.IsExist("AllowedActions") Or
                     &row.IsExist("AddSearchRecName")) Then
               throw CreateException(0, 0, "AllowedActions and AddSearchRecName are read-only in the native menu API");
            End-If;
            &childName = %This.ChildKey( Null, &row, &childKey);
            If &patchKeys.Find(&childName) > 0 Then
               throw CreateException(0, 0, "Duplicate child key in patch: " | &childName);
            End-If;
            &patchKeys.Push(&childName);
            &count = ObjectGetProperty(&defn, "Count_" | &collection);
            &found = 0;
            Local integer &k;
            For &k = 1 To &count
               &child = ObjectDoMethodArray(&defn, "Get_" | &collection, CreateArrayAny(&k));
               If %This.ChildKey(&child, Null, &childKey) = &childName Then
                  &found = &k;
                  Break;
               End-If;
            End-For;
            If &action = "deleteChild" Then
               If &found = 0 Then
                  throw CreateException(0, 0, "Child does not exist");
               End-If;
               &ok = ObjectDoMethodArray(&defn, "Delete_" | &collection, CreateArrayAny(&found));
               If Not &ok Then
                  throw CreateException(0, 0, "Native child deletion failed");
               End-If;
            Else
               If &found = 0 Then
                  &child = ObjectDoMethodArray(&defn, "Append_" | &collection, CreateArrayAny(&count));
               End-If;
               %This.PatchFields(&child, &row, &names, CreateArrayRept("", 0));
               If &kind = "menu" And
                     &found > 0 Then
                  ObjectSetProperty(&child, "Status", 1);
               End-If;
            End-If;
         End-For;
      End-For;
   End-If;
   &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
   If &kind = "stylesheet" Then
      Local string &parentSheet = ObjectGetProperty(&defn, "ParentStyleSheet");
      If ObjectGetProperty(&defn, "StyleSheetType") <> 2 Or
            All(&parentSheet) Then
         throw CreateException(0, 0, "This release writes standalone free-form stylesheets only: StyleSheetType=2, ParentStyleSheet empty");
      End-If;
   End-If;
   If &kind = "ci" Then
      Local Record &ciComponent = CreateRecord(Record.PSPNLGRPDEFN);
      &ciComponent.PNLGRPNAME.Value = ObjectGetProperty(&defn, "BcPanelGroup");
      &ciComponent.MARKET.Value = ObjectGetProperty(&defn, "BcMarket");
      If Not &ciComponent.SelectByKey() Then
         throw CreateException(0, 0, "CI component/market does not exist");
      End-If;
      Local number &stdMethods = ObjectGetProperty(&defn, "StandardMethods");
      If &stdMethods < 0 Or
            &stdMethods > 31 Then
         throw CreateException(0, 0, "StandardMethods must be a 0..31 bitmask");
      End-If;
      Local integer &ciIndex, &ciType, &ciMatches;
      Local string &ciRecord, &ciField;
      For &ciIndex = 1 To ObjectGetProperty(&defn, "Count_Pit")
         &child = ObjectDoMethodArray(&defn, "Get_Pit", CreateArrayAny(&ciIndex));
         &ciType = ObjectGetProperty(&child, "PropertyType");
         If &ciType < 1 Or
               &ciType > 5 Then
            throw CreateException(0, 0, "CI PropertyType must be 1..5 (keys, collection, property)");
         End-If;
         &ciRecord = ObjectGetProperty(&child, "RecName");
         &ciField = ObjectGetProperty(&child, "FieldName");
         If All(&ciField) Then
            &ciMatches = 0;
            SQLExec("SELECT COUNT(*) FROM PSRECFIELDALL WHERE RECNAME=:1 AND FIELDNAME=:2", &ciRecord, &ciField, &ciMatches);
            If &ciMatches <> 1 Then
               throw CreateException(0, 0, "CI mapping record/field does not exist: " | &ciRecord | "." | &ciField);
            End-If;
         End-If;
      End-For;
      %This.ValidateCI(&defn);
   End-If;
   If &kind = "service" Or
         &kind = "operation" Then
      If ObjectGetProperty(&defn, "RestService") <> 2 And
            ObjectGetProperty(&defn, "RestService") <> 0 Then
         throw CreateException(0, 0, "RestService must be 0 (SOAP) or 2 (REST Provider)");
      End-If;
   End-If;
   If (&kind = "service" Or
         &kind = "operation") And
         &action <> "create" Then
      If &after.GetNumber("RestService") <> &before.GetNumber("RestService") Then
         throw CreateException(0, 0, "Changing the protocol of an existing definition is not supported");
      End-If;
   End-If;
   If &kind = "operation" Then
      Local string &restMethod = ObjectGetProperty(&defn, "Restmethod");
      If ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Rtngtype must be S (synchronous)");
      End-If;
      If ObjectGetProperty(&defn, "RestService") = 2 And
            &restMethod <> "GET" And
            &restMethod <> "POST" And
            &restMethod <> "PUT" And
            &restMethod <> "DELETE" And
            &restMethod <> "PATCH" Then
         throw CreateException(0, 0, "Unsupported REST method");
      End-If;
      If ObjectGetProperty(&defn, "RestService") = 0 Then
         If All(&restMethod) Or
               (Len(RTrim(String(ObjectGetProperty(&defn, "RestBaseurl")))) > 0) Or
               ObjectGetProperty(&defn, "Count_Operationuritemplate") > 0 Then
            throw CreateException(0, 0, "SOAP operations cannot contain REST methods or URI templates");
         End-If;
      End-If;
      Local object &serviceMgr = CreateObject("%metadata:ServiceDefn:ServiceDefn_Manager");
      Local object &serviceKey = create %metadata:Key(key:Class_ServiceName, String(ObjectGetProperty(&defn, "Servicename")));
      If Not ObjectDoMethodArray(&serviceMgr, "DefnExists", CreateArrayAny(&serviceKey)) Then
         throw CreateException(0, 0, "Parent service does not exist");
      End-If;
      Local object &parentServiceDefn = ObjectDoMethodArray(&serviceMgr, "GetDefnToUpdate", CreateArrayAny(&serviceKey));
      If ObjectGetProperty(&parentServiceDefn, "RestService") <> ObjectGetProperty(&defn, "RestService") Then
         throw CreateException(0, 0, "Parent service protocol must match the operation");
      End-If;
   End-If;
   If &kind = "menu" Then
      If ObjectGetProperty(&defn, "Menutype") <> 0 And
            ObjectGetProperty(&defn, "Menutype") <> 1 Then
         throw CreateException(0, 0, "Menutype must be 0 (Standard) or 1 (Pop-up)");
      End-If;
      Local integer &mi;
      Local Record &componentRec;
      Local string &componentName;
      For &mi = 1 To ObjectGetProperty(&defn, "Count_Mit")
         &child = ObjectDoMethodArray(&defn, "Get_Mit", CreateArrayAny(&mi));
         &componentName = ObjectGetProperty(&child, "PnlGrpName");
         If All(&componentName) Then
            &componentRec = CreateRecord(Record.PSPNLGRPDEFN);
            &componentRec.PNLGRPNAME.Value = &componentName;
            &componentRec.MARKET.Value = ObjectGetProperty(&child, "Market");
            If Not &componentRec.SelectByKey() Then
               throw CreateException(0, 0, "Menu references a missing component/market");
            End-If;
         End-If;
      End-For;
   End-If;
   If &kind = "version" Then
      If &ownerDefn <> Null Then
         If ObjectGetProperty(&ownerDefn, "RestService") = 0 Then
            Local array of string &soapParams = CreateArrayRept("", 0);
            For &i = 1 To ObjectGetProperty(&defn, "Count_Oprverdfnparm")
               &child = ObjectDoMethodArray(&defn, "Get_Oprverdfnparm", CreateArrayAny(&i));
               Local string &soapParam = ObjectGetProperty(&child, "Parametername");
               If CreateArray("REQUEST", "RESPONSE", "Z_FAULT").Find(&soapParam) = 0 Then
                  throw CreateException(0, 0, "SOAP parameters must be REQUEST, RESPONSE or Z_FAULT");
               End-If;
               If ObjectGetProperty(&child, "HTTPStatusCode") <> 0 Or
                     (Len(RTrim(String(ObjectGetProperty(&child, "ContentType")))) > 0) Then
                  throw CreateException(0, 0, "SOAP message bindings do not use REST status/content-type properties");
               End-If;
               &soapParams.Push(&soapParam);
            End-For;
            If &soapParams.Find("REQUEST") = 0 Or
                  &soapParams.Find("RESPONSE") = 0 Then
               throw CreateException(0, 0, "Synchronous SOAP requires REQUEST and RESPONSE messages");
            End-If;
         End-If;
      End-If;
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local object &msgManager = CreateObject("%metadata:MessageDefn:MessageDefn_Manager");
      Local object &msgKey, &messageDefn, &messageVersion;
      Local array of integer &messageIDs;
      Local string &messageName, &messageVersionName;
      Local integer &mp, &mv;
      Local boolean &versionFound;
      For &mp = 1 To ObjectGetProperty(&defn, "Count_Oprverdfnparm")
         &child = ObjectDoMethodArray(&defn, "Get_Oprverdfnparm", CreateArrayAny(&mp));
         &messageName = ObjectGetProperty(&child, "Messagename");
         &messageVersionName = ObjectGetProperty(&child, "Messageversion");
         If None(&messageName) Or
               None(&messageVersionName) Then
            throw CreateException(0, 0, "Message bindings require message name and version");
         End-If;
         &messageIDs = &objectKeys.GetObjectIDs(37, CreateArray(&messageName, " ", " ", " "));
         &msgKey = CreateObject("%metadata:Key", &messageIDs [1], &messageName);
         If Not ObjectDoMethodArray(&msgManager, "DefnExists", CreateArrayAny(&msgKey)) Then
            throw CreateException(0, 0, "Referenced Message does not exist");
         End-If;
         &messageDefn = ObjectDoMethodArray(&msgManager, "GetDefnToUpdate", CreateArrayAny(&msgKey));
         &versionFound = False;
         For &mv = 1 To ObjectGetProperty(&messageDefn, "Count_Mvt")
            &messageVersion = ObjectDoMethodArray(&messageDefn, "Get_Mvt", CreateArrayAny(&mv));
            If ObjectGetProperty(&messageVersion, "VerName") = &messageVersionName Then
               &versionFound = True;
               Break;
            End-If;
         End-For;
         If Not &versionFound Then
            throw CreateException(0, 0, "Referenced Message version does not exist");
         End-If;
      End-For;
   End-If;
   If &kind = "handler" Then
      If ObjectGetProperty(&defn, "Handlertype") <> "ApplicationClass" Or
            ObjectGetProperty(&defn, "Handlerid") <> "RQST" Then
         throw CreateException(0, 0, "Provider requires an Application Class request handler");
      End-If;
      Local object &classKey;
      Local object &classManager = CreateObject("%metadata:PeopleCodeProgram:PeopleCodeProgram_Manager");
      Local array of string &qualifiers;
      Local integer &hi, &hq;
      For &hi = 1 To ObjectGetProperty(&defn, "Count_Operationac")
         &child = ObjectDoMethodArray(&defn, "Get_Operationac", CreateArrayAny(&hi));
         &classKey = create %metadata:Key(key:Class_ApplicationPackage, String(ObjectGetProperty(&child, "Packageroot")));
         Local string &qualifierPath = ObjectGetProperty(&child, "Qualifypath");
         If All(&qualifierPath) Then
            &qualifiers = Split(&qualifierPath, ":");
            If &qualifiers.Len > 2 Then
               throw CreateException(0, 0, "Application Class qualifier depth exceeds PeopleTools limit");
            End-If;
            For &hq = 1 To &qualifiers.Len
               If &hq = 1 Then
                  ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationPackage1, &qualifiers [&hq]);
               Else
                  ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationPackage2, &qualifiers [&hq]);
               End-If;
            End-For;
         End-If;
         ObjectDoMethod(&classKey, "AddItem", key:Class_ApplicationClass, String(ObjectGetProperty(&child, "Classname")));
         ObjectDoMethod(&classKey, "AddItem", key:Class_Method, "OnExecute");
         If Not ObjectDoMethodArray(&classManager, "DefnExists", CreateArrayAny(&classKey)) Then
            throw CreateException(0, 0, "Referenced Application Class does not exist");
         End-If;
         If ObjectGetProperty(&child, "Methodname") <> "OnRequest" Then
            throw CreateException(0, 0, "Request handler method must be OnRequest");
         End-If;
      End-For;
   End-If;
   If &kind = "routing" Then
      If &ownerDefn <> Null Then
         If ObjectGetProperty(&ownerDefn, "RestService") = 0 And
               (Len(RTrim(String(ObjectGetProperty(&defn, "Restmethod")))) > 0) Then
            throw CreateException(0, 0, "SOAP routing cannot contain a REST method");
         End-If;
      End-If;
      If ObjectGetProperty(&defn, "Rtngtype") <> "S" Then
         throw CreateException(0, 0, "Only synchronous routing is supported");
      End-If;
      &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
      Local object &nodeManager = CreateObject("%metadata:NodeDefn:NodeDefn_Manager");
      Local object &nodeKey;
      Local array of integer &nodeIDs;
      Local array of string &nodeNames = CreateArray(String(ObjectGetProperty(&defn, "Sendernodename")), String(ObjectGetProperty(&defn, "Receivernodename")));
      Local integer &ni;
      For &ni = 1 To &nodeNames.Len
         If &nodeNames [&ni] <> "~~ANY~~" Then
            &nodeIDs = &objectKeys.GetObjectIDs(35, CreateArray(&nodeNames [&ni], " ", " ", " "));
            &nodeKey = CreateObject("%metadata:Key", &nodeIDs [1], &nodeNames [&ni]);
            If Not ObjectDoMethodArray(&nodeManager, "DefnExists", CreateArrayAny(&nodeKey)) Then
               throw CreateException(0, 0, "Referenced IB Node does not exist");
            End-If;
         End-If;
      End-For;
   End-If;
   If &kind = "portal" Then
      %This.CheckPortalContent(&defn, &mgr, &portalIDs);
      Local string &parentName = ObjectGetProperty(&defn, "PrntObjName");
      If None(&parentName) Then
         throw CreateException(0, 0, "PrntObjName is required");
      End-If;
      Local object &parentKey, &parentDefn;
      Local array of string &visited = CreateArrayRept("", 0);
      Local ApiObject &registry = %Session.GetPortalRegistry();
      &registry.Open(&req.GetString("PortalName"));
      Local ApiObject &parentFolder = &registry.FindFolderByName(&parentName);
      If &parentFolder = Null Then
         throw CreateException(0, 0, "Parent folder does not exist");
      End-If;
      If Not &parentFolder.Authorized Then
         throw CreateException(0, 0, "User is not authorized for parent folder");
      End-If;
      If &action <> "create" Then
         Local ApiObject &portalObj;
         If &req.GetString("RefType") = "F" Then
            &portalObj = &registry.FindFolderByName(&name);
         Else
            If ObjectGetProperty(&defn, "IsLink") Then
               &portalObj = &registry.FindCRefLinkByName(&name);
            Else
               &portalObj = &registry.FindCRefByName(&name);
            End-If;
         End-If;
         If &portalObj = Null Then
            throw CreateException(0, 0, "Portal object could not be loaded");
         End-If;
         If Not &portalObj.Authorized Then
            throw CreateException(0, 0, "User is not authorized for portal object");
         End-If;
      End-If;
      While All(&parentName)
         If &parentName = &name Or
               &visited.Find(&parentName) > 0 Then
            throw CreateException(0, 0, "Portal parent would create a cycle");
         End-If;
         &visited.Push(&parentName);
         &parentKey = CreateObject("%metadata:Key", &portalIDs [1], &req.GetString("PortalName"));
         ObjectDoMethod(&parentKey, "AddItem", &portalIDs [2], "F");
         ObjectDoMethod(&parentKey, "AddItem", &portalIDs [3], &parentName);
         &parentDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&parentKey));
         &parentName = ObjectGetProperty(&parentDefn, "PrntObjName");
      End-While;
      Local string &portalLabel = ObjectGetProperty(&defn, "LabelName");
      If None(&portalLabel) Then
         throw CreateException(0, 0, "LabelName is required");
      End-If;
      If ObjectGetProperty(&defn, "IsPublic") <> 0 And
            ObjectGetProperty(&defn, "IsPublic") <> 1 Then
         throw CreateException(0, 0, "IsPublic must be 0 or 1");
      End-If;
      Local integer &pi;
      Local string &permissionType;
      Local Record &permissionRec;
      For &pi = 1 To ObjectGetProperty(&defn, "Count_Permission")
         &child = ObjectDoMethodArray(&defn, "Get_Permission", CreateArrayAny(&pi));
         &permissionType = ObjectGetProperty(&child, "PermType");
         If &permissionType = "P" Then
            &permissionRec = CreateRecord(Record.PSCLASSDEFN);
            &permissionRec.CLASSID.Value = ObjectGetProperty(&child, "PermName");
         Else
            If &permissionType <> "R" Then
               throw CreateException(0, 0, "PermType must be P (Permission List) or R (Role)");
            End-If;
            &permissionRec = CreateRecord(Record.PSROLEDEFN);
            &permissionRec.ROLENAME.Value = ObjectGetProperty(&child, "PermName");
         End-If;
         If Not &permissionRec.SelectByKey() Then
            throw CreateException(0, 0, "Portal permission principal does not exist");
         End-If;
         If &req.GetString("RefType") <> "F" And
               ObjectGetProperty(&child, "IsCascade") Then
            throw CreateException(0, 0, "Only folder permissions may cascade");
         End-If;
      End-For;
      If ObjectGetProperty(&defn, "CrefUsageType") = "LINK" Then
         Local object &targetKey = CreateObject("%metadata:Key", &portalIDs [1], String(ObjectGetProperty(&defn, "LinksPortalName")));
         ObjectDoMethod(&targetKey, "AddItem", &portalIDs [2], "C");
         ObjectDoMethod(&targetKey, "AddItem", &portalIDs [3], String(ObjectGetProperty(&defn, "LinksObjectName")));
         If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&targetKey)) Then
            throw CreateException(0, 0, "Link target does not exist");
         End-If;
         Local object &targetDefn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&targetKey));
         If ObjectGetProperty(&targetDefn, "IsLink") Then
            throw CreateException(0, 0, "A link cannot target another link");
         End-If;
         ObjectSetProperty(&defn, "CrefURLType", ObjectGetProperty(&targetDefn, "CrefURLType"));
         ObjectSetProperty(&defn, "CrefTemplateType", ObjectGetProperty(&targetDefn, "CrefTemplateType"));
         ObjectSetProperty(&defn, "CrefStorageType", ObjectGetProperty(&targetDefn, "CrefStorageType"));
         ObjectSetProperty(&defn, "CntPrvName", ObjectGetProperty(&targetDefn, "CntPrvName"));
         Local string &linkURL = ObjectGetProperty(&targetDefn, "URLLogical");
         Local string &linkFragment = "";
         Local integer &fragmentAt = Find("#", &linkURL);
         If &fragmentAt > 0 Then
            &linkFragment = Substring(&linkURL, &fragmentAt, Len(&linkURL) - &fragmentAt + 1);
            &linkURL = Substring(&linkURL, 1, &fragmentAt - 1);
         End-If;
         If Find("?", &linkURL) > 0 Then
            &linkURL = &linkURL | "&";
         Else
            &linkURL = &linkURL | "?";
         End-If;
         ObjectSetProperty(&defn, "URLLogical", &linkURL | "pslnkid=" | &name | &linkFragment);
         &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
      End-If;
      &registry.Close();
   End-If;
   If Not &dryRun Then
      If &kind = "html" Or
            &kind = "stylesheet" Or
            &kind = "ci" Then
         &ok = ObjectDoMethodArray(&defn, "ValidateDefn", CreateArrayAny());
         If Not &ok Then
            throw CreateException(0, 0, "Native ValidateDefn failed; definition was not saved");
         End-If;
      End-If;
      If &action = "create" Then
         &saveMethod = "SaveNewDefn";
      Else
         &saveMethod = "UpdateDefn";
      End-If;
      &ok = ObjectDoMethodArray(&defn, &saveMethod, CreateArrayAny());
      If Not &ok Then
         throw CreateException(0, 0, "Native " | &saveMethod | " failed");
      End-If;
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
      &after = %This.Snapshot(&defn, &fields, &collections, &childFields);
      If &kind = "operation" Then
         %This.SyncServiceMembership(&name, &before.GetString("Servicename"), &after.GetString("Servicename"));
      End-If;
      If &kind = "menu" And
            &action = "deleteChild" And
            &req.IsExist("collections") Then
         Local C_JSON_API:JSONObject &deletedCollections = &req.GetJsonObject("collections");
         If &deletedCollections.IsExist("Mit") Then
            Local C_JSON_API:JSONArray &deletedItems = &deletedCollections.GetJsonArray("Mit");
            If &objectKeys = Null Then
               &objectKeys = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
            End-If;
            Local object &pcManager = CreateObject("%metadata:PeopleCodeProgram:PeopleCodeProgram_Manager");
            Local object &pcKey;
            Local array of integer &pcIDs;
            Local integer &di;
            Local string &deletedBar, &deletedItem;
            For &di = 1 To &deletedItems.Size
               &row = &deletedItems.GetJsonObject(&di);
               &deletedBar = &row.GetString("BarName");
               &deletedItem = &row.GetString("ItemName");
               &pcIDs = &objectKeys.GetObjectIDs(9, CreateArray(&name, &deletedBar, &deletedItem, "ItemSelected"));
               &pcKey = CreateObject("%metadata:Key", &pcIDs [1], &name);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [2], &deletedBar);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [3], &deletedItem);
               ObjectDoMethod(&pcKey, "AddItem", &pcIDs [4], "ItemSelected");
               If ObjectDoMethodArray(&pcManager, "DefnExists", CreateArrayAny(&pcKey)) Then
                  If Not ObjectDoMethodArray(&pcManager, "DeleteDefn", CreateArrayAny(&pcKey)) Then
                     throw CreateException(0, 0, "Menu item saved, but owned PeopleCode deletion failed");
                  End-If;
                  If ObjectDoMethodArray(&pcManager, "DefnExists", CreateArrayAny(&pcKey)) Then
                     throw CreateException(0, 0, "Deleted menu item still owns PeopleCode");
                  End-If;
               End-If;
            End-For;
         End-If;
      End-If;
   End-If;
   &result = CreateObject("C_JSON_API:Factory").NewObject();
   &result.AddProperty("dryRun", &dryRun);
   &result.AddJsonObject("before", &before);
   &before = &result.GetJsonObject("before");
   &result.AddJsonObject("after", &after);
   &after = &result.GetJsonObject("after");
   Return &result;
end-method;

import %metadata:ProjectDefn:*;

/* Resolve native key types without loading, naming, or saving a Project. */
class ObjectKeyResolver
   method ObjectKeyResolver();
   method GetObjectIDs(&objectType As integer, &objectValues As array of string) Returns array of integer;
private
   instance %metadata:ProjectDefn:ProjectDefn &keySource;
end-class;

method ObjectKeyResolver
   Local %metadata:ProjectDefn:ProjectDefn_Manager &manager = create %metadata:ProjectDefn:ProjectDefn_Manager();
   &keySource = &manager.CreateDefn();
end-method;

method GetObjectIDs
   /+ &objectType as Integer, +/
   /+ &objectValues as Array of String +/
   /+ Returns Array of Integer +/
   If &objectType < 0 Then
      throw CreateException(0, 0, "ObjectType must be nonnegative");
   End-If;
   If &objectValues = Null Then
      throw CreateException(0, 0, "ObjectValues are required");
   End-If;
   If &objectValues.Len <> 4 Then
      throw CreateException(0, 0, "ObjectValues must contain all four key positions; use blanks for unused positions");
   End-If;
   Local array of integer &ids = &keySource.GetObjectIDs(&objectType, &objectValues);
   If &ids = Null Then
      throw CreateException(0, 0, "Native ObjectID resolution returned no result");
   End-If;
   If &ids.Len <> 4 Then
      throw CreateException(0, 0, "Native ObjectID resolution must return four key positions");
   End-If;
   If &ids [1] <= 0 Then
      throw CreateException(0, 0, "Native ObjectID resolution returned an invalid primary key type");
   End-If;
   Return &ids;
end-method;

import C_JSON_API:*;
import %metadata:Key;
import C_COMMONS_PKG:CommonUtil;

class OperationSecurityAdapter
   method OperationSecurityAdapter();
   method Run(&req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
   method Cleanup(&operation As string) Returns integer;
private
   method Read(&defn As object, &operation As string, &permissionList As string) Returns C_JSON_API:JSONObject;
end-class;

method OperationSecurityAdapter
end-method;

method Read
   /+ &defn as Object, +/
   /+ &operation as String, +/
   /+ &permissionList as String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local integer &i;
   Local integer &access = 0;
   Local boolean &exists = False;
   Local object &row;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Awst")
      &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&i));
      If ObjectGetProperty(&row, "WSOperationName") = &operation Then
         &access = ObjectGetProperty(&row, "AuthActions");
         &exists = True;
         Break;
      End-If;
   End-For;
   Local C_JSON_API:JSONObject &out = CreateObject("C_JSON_API:Factory").NewObject();
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   &out.AddProperty("operationName", &operation);
   &out.AddProperty("permissionList", &permissionList);
   &out.AddProperty("exists", &exists);
   &out.AddProperty("access", &access);
   Return &out;
end-method;

method Cleanup
   /+ &operation as String +/
   /+ Returns Integer +/
   Local object &opMgr = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
   Local object &opKey = create %metadata:Key(Key:Class_OperationName, &operation);
   If ObjectDoMethodArray(&opMgr, "DefnExists", CreateArrayAny(&opKey)) Then
      throw CreateException(0, 0, "Permission cleanup requires an already deleted operation");
   End-If;
   Local Rowset &rows = CreateRowset(Record.PSAUTHWS);
   Local integer &count = &rows.Fill("WHERE IB_OPERATIONNAME = :1", &operation);
   Local integer &i, &j;
   Local Record &access;
   Local object &mgr = CreateObject("%metadata:PermissionListDefn:PermissionListDefn_Manager");
   Local object &key, &defn, &row;
   For &i = 1 To &count
      &access = &rows.GetRow(&i).GetRecord(Record.PSAUTHWS);
      &key = create %metadata:Key(Key:Class_Class, String(&access.CLASSID.Value));
      &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
      For &j = ObjectGetProperty(&defn, "Count_Awst") To 1 Step - 1
         &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&j));
         If ObjectGetProperty(&row, "WSOperationName") = &operation Then
            If Not ObjectDoMethodArray(&defn, "Delete_Awst", CreateArrayAny(&j)) Then
               throw CreateException(0, 0, "Native permission cleanup failed");
            End-If;
         End-If;
      End-For;
      If Not ObjectDoMethodArray(&defn, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Permission List update failed during cleanup");
      End-If;
   End-For;
   Return &count;
end-method;

method Run
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local string &operation = &req.GetString("name");
   Local string &permissionList = &req.GetString("permissionList");
   Local string &action = &req.GetString("operationType");
   Local object &opMgr = CreateObject("%metadata:OperationDefn:OperationDefn_Manager");
   Local object &opKey = create %metadata:Key(Key:Class_OperationName, &operation);
   If Not ObjectDoMethodArray(&opMgr, "DefnExists", CreateArrayAny(&opKey)) Then
      throw CreateException(0, 0, "Operation does not exist");
   End-If;
   Local object &op = ObjectDoMethodArray(&opMgr, "GetDefnToUpdate", CreateArrayAny(&opKey));
   If (ObjectGetProperty(&op, "RestService") <> 2 And
         ObjectGetProperty(&op, "RestService") <> 0) Or
         ObjectGetProperty(&op, "Rtngtype") <> "S" Then
      throw CreateException(0, 0, "Only synchronous SOAP and REST Provider operations are supported");
   End-If;
   Local object &mgr = CreateObject("%metadata:PermissionListDefn:PermissionListDefn_Manager");
   Local object &key = create %metadata:Key(Key:Class_Class, &permissionList);
   If Not ObjectDoMethodArray(&mgr, "DefnExists", CreateArrayAny(&key)) Then
      throw CreateException(0, 0, "Existing Permission List is required");
   End-If;
   Local object &defn = ObjectDoMethodArray(&mgr, "GetDefnToUpdate", CreateArrayAny(&key));
   Local C_JSON_API:JSONObject &before = %This.Read(&defn, &operation, &permissionList);
   Local C_COMMONS_PKG:CommonUtil &util = create C_COMMONS_PKG:CommonUtil();
   If &action = "view" Or
         &action = "struct" Then
      &before.AddProperty("stateToken", &before.ToString());
      Return &before;
   End-If;
   If &action <> "modify" Then
      throw CreateException(0, 0, "Use modify to set operation access");
   End-If;
   Local number &newAccess = &req.GetNumber("access");
   If &newAccess <> 0 And
         &newAccess <> 4 Then
      throw CreateException(0, 0, "Access must be 0 (none) or 4 (full)");
   End-If;
   If &req.IsExist("expectedState") And
         &req.GetString("expectedState") <> &before.ToString() Then
      throw CreateException(0, 0, "Operation permission changed since snapshot");
   End-If;
   Local boolean &dry = False;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   Local boolean &changed = False;
   If Not &before.GetBoolean("exists") Or
         &before.GetNumber("access") <> &newAccess Then
      &changed = True;
   End-If;
   Local integer &i;
   Local integer &found = 0;
   Local object &row;
   For &i = 1 To ObjectGetProperty(&defn, "Count_Awst")
      &row = ObjectDoMethodArray(&defn, "Get_Awst", CreateArrayAny(&i));
      If ObjectGetProperty(&row, "WSOperationName") = &operation Then
         &found = &i;
         Break;
      End-If;
   End-For;
   If &changed Then
      If &found = 0 Then
         &row = ObjectDoMethodArray(&defn, "Append_Awst", CreateArrayAny(ObjectGetProperty(&defn, "Count_Awst")));
         ObjectSetProperty(&row, "WSOperationName", &operation);
      End-If;
      ObjectSetProperty(&row, "AuthActions", &newAccess);
   End-If;
   Local C_JSON_API:JSONObject &after = %This.Read(&defn, &operation, &permissionList);
   If Not &dry And
         &changed Then
      If Not ObjectDoMethodArray(&defn, "UpdateDefn", CreateArrayAny()) Then
         throw CreateException(0, 0, "Native Permission List update failed");
      End-If;
      /* The CLM manager may retain the pre-save cache until the IB commit. Read
     the exact persisted row here; CLI performs another request after commit. */
      Local Record &saved = CreateRecord(Record.PSAUTHWS);
      &saved.CLASSID.Value = &permissionList;
      &saved.IB_OPERATIONNAME.Value = &operation;
      If Not &saved.SelectByKey() Or
            &saved.AUTHORIZEDACTIONS.Value <> &newAccess Then
         throw CreateException(0, 0, "Operation permission readback failed");
      End-If;
   End-If;
   Local C_JSON_API:JSONObject &result = CreateObject("C_JSON_API:Factory").NewObject();
   &result.AddProperty("dryRun", &dry);
   &result.AddProperty("changed", &changed);
   &result.AddJsonObject("before", &before);
   &before = &result.GetJsonObject("before");
   &result.AddJsonObject("after", &after);
   &after = &result.GetJsonObject("after");
   Return &result;
end-method;

import C_JSON_API:*;
import %metadata:Key;
import %metadata:PeopleCodeProgram:*;
import C_META_DATA_PKG:Utility:ObjectKeyResolver;
import C_COMMONS_PKG:CommonUtil;

/* Delete one native program; the caller builds its complete native key. */
class PeopleCodeDeletion
   method PeopleCodeDeletion();
   method Run(&key As %metadata:Key, &projectType As integer, &values As array of string, &req As C_JSON_API:JSONObject) Returns C_JSON_API:JSONObject;
end-class;

method PeopleCodeDeletion
end-method;

method Run
   /+ &key as %Metadata:Key, +/
   /+ &projectType as Integer, +/
   /+ &values as Array of String, +/
   /+ &req as C_JSON_API:JSONObject +/
   /+ Returns C_JSON_API:JSONObject +/
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager &mgr;
   Local %metadata:PeopleCodeProgram:PeopleCodeProgram &prog;
   Local C_META_DATA_PKG:Utility:ObjectKeyResolver &resolver;
   Local C_COMMONS_PKG:CommonUtil &util;
   Local C_JSON_API:JSONObject &out, &item;
   Local array of integer &ids;
   Local boolean &dry;
   Local string &before, &expected;
   Local integer &i;

   If Not &req.IsExist("expectedCode") Then
      throw CreateException(0, 0, "deletePeopleCode requires expectedCode from a fresh viewPeopleCode snapshot");
   End-If;
   &mgr = create %metadata:PeopleCodeProgram:PeopleCodeProgram_Manager();
   If Not &mgr.DefnExists(&key) Then
      throw CreateException(0, 0, "PeopleCode program does not exist");
   End-If;
   &util = create C_COMMONS_PKG:CommonUtil();
   &prog = &mgr.GetDefn(&key);
   &before = &prog.GetProgram();
   &expected = &util.UnEscapeJSON(&req.GetString("expectedCode"));
   If &before <> &expected Then
      throw CreateException(0, 0, "PeopleCode changed since snapshot; read again before deleting");
   End-If;
   &dry = False;
   If &req.IsExist("dryRun") Then
      &dry = &req.GetBoolean("dryRun");
   End-If;
   &resolver = create C_META_DATA_PKG:Utility:ObjectKeyResolver();
   &ids = &resolver.GetObjectIDs(&projectType, &values);
   &item = CreateObject("C_JSON_API:Factory").NewObject();
   &item.AddProperty("objectType", &projectType);
   For &i = 1 To 4
      &item.AddProperty("objectId" | &i, &ids [&i]);
      &item.AddProperty("objectValue" | &i, &values [&i]);
   End-For;
   If Not &dry Then
      If Not &mgr.DeleteDefn(&key) Then
         throw CreateException(0, 0, "PeopleCode DeleteDefn failed; inspect current state before retrying");
      End-If;
      If &mgr.DefnExists(&key) Then
         throw CreateException(0, 0, "PeopleCode program still exists after DeleteDefn");
      End-If;
   End-If;
   &out = CreateObject("C_JSON_API:Factory").NewObject();
   &out.AddProperty("deleted", ( Not &dry));
   &out.AddProperty("dryRun", &dry);
   &out.AddProperty("programExists", &mgr.DefnExists(&key));
   &out.AddJsonObject("projectItem", &item);
   &item = &out.GetJsonObject("projectItem");
   Return &out;
end-method;

import C_JSON_API:*;

/* 说明：Record Field Property的选项都存储与PSRECFIELD表的USEEDIT\USEEDIT2两个字段中
         使用2的幂次方相加来记录系统勾选了哪些属性
         此类用于计算和还原UseEdit，并按AD GUI的限制规则校验API请求。
         2026-09-05:
           1. PersistInMenu 从USEEDIT数组移到USEEDIT2数组（GUI实测其存储于USEEDIT2高位，带符号-2147483648）；
           2. GetFieldPropertyByUseEdit 支持负数（高位置位）解码，且未知位一律扣减避免贪婪分解错位；
           3. GetUseEdit2ByFieldProperty 写入时高位转为带符号负数；
           4. 新增 ValidateFieldProperty：按 Application Designer GUI 的置灰/联动规则校验 fieldProperty 请求。 */
class RecordUseEdit
   method RecordUseEdit();

   method GetRecordUseProperty(&p_recuse As integer) Returns C_JSON_API:JSONArray;
   method GetRecuseByRecordUseProperty(&p_arr As C_JSON_API:JSONArray) Returns integer;
   method GetFieldPropertyByUseEdit(&p_useEdit As number, &p_useEdit2 As number) Returns C_JSON_API:JSONArray;
   method GetUseEditByFieldProperty(&p_obj As C_JSON_API:JSONObject) Returns number;
   method GetUseEdit2ByFieldProperty(&p_arr As C_JSON_API:JSONArray) Returns number;
   method ValidateFieldProperty(&p_FieldProperty As C_JSON_API:JSONArray, &p_FieldTypeName As string, &p_EditTable As string, &p_DefGuiControl As integer, &p_HasXlat As boolean, &p_IsSubRecord As boolean) Returns string;
private
   instance array of string &_RecordUsePropName;
   instance array of string &_RecFieldPropName;
   instance array of string &_RecFieldPropName2;
   instance array of number &_RecFieldPropNumber;
end-class;

method RecordUseEdit
   &_RecordUsePropName = CreateArray("Add", "Change", "Delete", "Selective");
   &_RecFieldPropName = CreateArray("Key", "DuplicateOrderKey", "SystemMaintainedField", "AuditFieldAdd", "AlternateSearchKey", "ListBoxItem", "DescendingKey", "AuditFieldChange", "RequiredField", "TranslateTableEdit", "AuditFieldDelete", "SearchKey", "ReasonableDate", "Yes/NoTableEdit", "PromptTableEdit", "Auto-Update", "UnKnown", "UnKnown", "FromSearchField", "ThroughSearchField", "1/0TableEdit", "DisableAdvancedSearchOptions", "UnKnown", "RegularField", "DefaultSearchField", "UnKnown", "UnKnown", "AllowSearchEventsForPromptDialogs", "SearchEdit", "DisplayInAutocompleteWindow", "EnableAutocompleteWhenUsedInSearchRecord", "UnKnown");
   &_RecFieldPropName2 = CreateArray("UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "DisableAutocompleteForThisField", "UnKnown", "UnKnown", "InMemory", "UnKnown", "UnKnown", "UnKnown", "DoNotTraceValue", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "UnKnown", "PersistInMenu");
   &_RecFieldPropNumber = CreateArray(1, 2, 4, 8, 16, 32, 64, 128, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576, 2097152, 4194304, 8388608, 16777216, 33554432, 67108864, 134217728, 268435456, 536870912, 1073741824, 2147483648);
end-method;

method GetRecordUseProperty
   /+ &p_recuse as Integer +/
   /+ Returns C_JSON_API:JSONArray +/
   Local C_JSON_API:JSONArray &RecuseArr;
   Local integer &i;

   &RecuseArr = CreateObject("C_JSON_API:Factory").NewArray();
   For &i = 4 To 1 Step - 1
      If &p_recuse >= &_RecFieldPropNumber [&i] Then
         &p_recuse = &p_recuse - &_RecFieldPropNumber [&i];
         &RecuseArr.AddElement(&_RecordUsePropName [&i]);
      End-If;
   End-For;

   Return &RecuseArr;
end-method;

method GetRecuseByRecordUseProperty
   /+ &p_arr as C_JSON_API:JSONArray +/
   /+ Returns Integer +/
   Local integer &Recuse, &i, &j;
   Local string &PropertyName;

   &Recuse = 0;
   If None(&p_arr) Then
      Return &Recuse;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecordUsePropName.Len
         If &PropertyName = &_RecordUsePropName [&j] Then
            &Recuse = &Recuse + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   Return &Recuse;
end-method;

method GetFieldPropertyByUseEdit
   /+ &p_useEdit as Number, +/
   /+ &p_useEdit2 as Number +/
   /+ Returns C_JSON_API:JSONArray +/
   Local integer &i;
   Local C_JSON_API:JSONArray &FieldProperty;

   &FieldProperty = CreateObject("C_JSON_API:Factory").NewArray();

   REM 高位带符号：DB中USEEDIT/USEEDIT2占用2^31位时为负数，先转回无符号再贪婪分解;
   If &p_useEdit < 0 Then
      &p_useEdit = &p_useEdit + 4294967296;
   End-If;
   If &p_useEdit2 < 0 Then
      &p_useEdit2 = &p_useEdit2 + 4294967296;
   End-If;

   For &i = &_RecFieldPropNumber.Len To 1 Step - 1
      If &p_useEdit >= &_RecFieldPropNumber [&i] Then
         &p_useEdit = &p_useEdit - &_RecFieldPropNumber [&i];
         If &_RecFieldPropName [&i] <> "UnKnown" And
               &_RecFieldPropName [&i] <> "RegularField" Then
            &FieldProperty.AddElement(&_RecFieldPropName [&i]);
         End-If;
      End-If;
   End-For;

   For &i = &_RecFieldPropNumber.Len To 1 Step - 1
      If &p_useEdit2 >= &_RecFieldPropNumber [&i] Then
         &p_useEdit2 = &p_useEdit2 - &_RecFieldPropNumber [&i];
         If &_RecFieldPropName2 [&i] <> "UnKnown" Then
            &FieldProperty.AddElement(&_RecFieldPropName2 [&i]);
         End-If;
      End-If;
   End-For;
   Return &FieldProperty;
end-method;

method GetUseEditByFieldProperty
   /+ &p_obj as C_JSON_API:JSONObject +/
   /+ Returns Number +/
   Local number &UseEdit;
   Local integer &i, &j;
   Local string &PropertyName, &LabelId, &SubRecord;
   Local C_JSON_API:JSONArray &p_arr;

   &UseEdit = 0;
   If None(&p_obj) Then
      Return &UseEdit;
   End-If;

   &SubRecord = &p_obj.GetString("subRecord");
   &LabelId = &p_obj.GetString("labelId");
   &p_arr = &p_obj.GetJsonArray("fieldProperty");

   If &SubRecord <> "Y" And
         None(&LabelId) Then
      &UseEdit = 8388608;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecFieldPropName.Len
         If &PropertyName = &_RecFieldPropName [&j] Then
            &UseEdit = &UseEdit + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   REM 防御：USEEDIT不应用到2^31位，若意外超出转为带符号;
   If &UseEdit >= 2147483648 Then
      &UseEdit = &UseEdit - 4294967296;
   End-If;

   Return &UseEdit;
end-method;

method GetUseEdit2ByFieldProperty
   /+ &p_arr as C_JSON_API:JSONArray +/
   /+ Returns Number +/
   Local number &UseEdit2;
   Local integer &i, &j;
   Local string &PropertyName;

   &UseEdit2 = 0;
   If None(&p_arr) Then
      Return &UseEdit2;
   End-If;

   For &i = 1 To &p_arr.Size
      &PropertyName = &p_arr.GetString(&i);
      For &j = 1 To &_RecFieldPropName2.Len
         If &PropertyName = &_RecFieldPropName2 [&j] Then
            &UseEdit2 = &UseEdit2 + &_RecFieldPropNumber [&j];
            Break;
         End-If;
      End-For;
   End-For;

   REM PersistInMenu占用2^31高位：按DB带符号存储规则转成负数;
   If &UseEdit2 >= 2147483648 Then
      &UseEdit2 = &UseEdit2 - 4294967296;
   End-If;

   Return &UseEdit2;
end-method;

method ValidateFieldProperty
   /+ &p_FieldProperty as C_JSON_API:JSONArray, +/
   /+ &p_FieldTypeName as String, +/
   /+ &p_EditTable as String, +/
   /+ &p_DefGuiControl as Integer, +/
   /+ &p_HasXlat as Boolean, +/
   /+ &p_IsSubRecord as Boolean +/
   /+ Returns String +/
   REM 校验规则与 Application Designer 的 Record Field Properties 对话框保持一致：;
   REM GUI中置灰（不可勾选）的组合在此拒绝；GUI中可勾选的组合在此放行。;
   Local string &Err, &Prop;
   Local integer &i;
   Local boolean &IsKey, &IsDupKey, &IsAltKey, &IsSearchKey, &IsSearchEdit, &IsDescKey, &IsLBI, &IsFrom, &IsThrough, &IsDefaultSearch, &IsDisableAdv, &IsAllowSearchEvt, &IsAuditAdd, &IsAuditChg, &IsAuditDel, &IsSysMaint, &IsDoNotTrace, &IsRequired, &IsTranslate, &IsReasonable, &IsYN, &IsPrompt, &IsAutoUpdate, &Is10, &IsDisplay, &IsEnableAC, &IsDisableAC, &IsPersistMenu, &IsRegularField, &IsInMemory, &IsUnKnownName;

   &IsKey = False;
   &IsDupKey = False;
   &IsAltKey = False;
   &IsSearchKey = False;
   &IsSearchEdit = False;
   &IsDescKey = False;
   &IsLBI = False;
   &IsFrom = False;
   &IsThrough = False;
   &IsDefaultSearch = False;
   &IsDisableAdv = False;
   &IsAllowSearchEvt = False;
   &IsAuditAdd = False;
   &IsAuditChg = False;
   &IsAuditDel = False;
   &IsSysMaint = False;
   &IsDoNotTrace = False;
   &IsRequired = False;
   &IsTranslate = False;
   &IsReasonable = False;
   &IsYN = False;
   &IsPrompt = False;
   &IsAutoUpdate = False;
   &Is10 = False;
   &IsDisplay = False;
   &IsEnableAC = False;
   &IsDisableAC = False;
   &IsPersistMenu = False;
   &IsRegularField = False;
   &IsInMemory = False;
   &IsUnKnownName = False;

   If &p_IsSubRecord And
         &p_FieldProperty.Size > 0 Then
      &Err = &Err | "subrecord reference fields cannot have field properties (AD does not allow editing them), ";
      Return &Err;
   End-If;

   For &i = 1 To &p_FieldProperty.Size
      &Prop = &p_FieldProperty.GetString(&i);
      Evaluate &Prop
      When "Key"
         &IsKey = True;
         Break;
      When "DuplicateOrderKey"
         &IsDupKey = True;
         Break;
      When "SystemMaintainedField"
         &IsSysMaint = True;
         Break;
      When "DoNotTraceValue"
         &IsDoNotTrace = True;
         Break;
      When "AuditFieldAdd"
         &IsAuditAdd = True;
         Break;
      When "AlternateSearchKey"
         &IsAltKey = True;
         Break;
      When "ListBoxItem"
         &IsLBI = True;
         Break;
      When "DescendingKey"
         &IsDescKey = True;
         Break;
      When "AuditFieldChange"
         &IsAuditChg = True;
         Break;
      When "RequiredField"
         &IsRequired = True;
         Break;
      When "TranslateTableEdit"
         &IsTranslate = True;
         Break;
      When "AuditFieldDelete"
         &IsAuditDel = True;
         Break;
      When "SearchKey"
         &IsSearchKey = True;
         Break;
      When "ReasonableDate"
         &IsReasonable = True;
         Break;
      When "Yes/NoTableEdit"
         &IsYN = True;
         Break;
      When "PromptTableEdit"
         &IsPrompt = True;
         Break;
      When "Auto-Update"
         &IsAutoUpdate = True;
         Break;
      When "FromSearchField"
         &IsFrom = True;
         Break;
      When "ThroughSearchField"
         &IsThrough = True;
         Break;
      When "1/0TableEdit"
         &Is10 = True;
         Break;
      When "DisableAdvancedSearchOptions"
         &IsDisableAdv = True;
         Break;
      When "DefaultSearchField"
         &IsDefaultSearch = True;
         Break;
      When "AllowSearchEventsForPromptDialogs"
         &IsAllowSearchEvt = True;
         Break;
      When "SearchEdit"
         &IsSearchEdit = True;
         Break;
      When "DisplayInAutocompleteWindow"
         &IsDisplay = True;
         Break;
      When "EnableAutocompleteWhenUsedInSearchRecord"
         &IsEnableAC = True;
         Break;
      When "DisableAutocompleteForThisField"
         &IsDisableAC = True;
         Break;
      When "PersistInMenu"
         &IsPersistMenu = True;
         Break;
      When "RegularField"
         &IsRegularField = True;
         Break;
      When "InMemory"
         &IsInMemory = True;
         Break;
      When-Other
         &IsUnKnownName = True;
      End-Evaluate;
   End-For;

   If &IsUnKnownName Then
      &Err = &Err | "unknown fieldProperty name (see 06-record-defn-api.md for the supported list), ";
   End-If;
   If &IsRegularField Then
      &Err = &Err | "RegularField is an internal storage marker (use-default-label bit) and cannot be set explicitly, ";
   End-If;
   If &IsInMemory Then
      &Err = &Err | "InMemory requires the Oracle In-Memory Column Store option on the record definition; AD disables this check box when the option is unavailable, ";
   End-If;

   REM 字段类型家族（与各类型字段属性面板截图一致）;
   Local boolean &IsChar, &IsNbr, &IsSign, &IsDate, &IsTime, &IsDtTm, &IsLong, &IsImage, &IsImageRef, &IsAttachment;
   &IsChar = (&p_FieldTypeName = "character");
   &IsNbr = (&p_FieldTypeName = "number");
   &IsSign = (&p_FieldTypeName = "signed number");
   &IsDate = (&p_FieldTypeName = "date");
   &IsTime = (&p_FieldTypeName = "time");
   &IsDtTm = (&p_FieldTypeName = "datetime");
   &IsLong = (&p_FieldTypeName = "long character");
   &IsImage = (&p_FieldTypeName = "image");
   &IsImageRef = (&p_FieldTypeName = "imageReference");
   &IsAttachment = (&p_FieldTypeName = "attachment");

   Local boolean &HasKeyGroup, &IsDateFamily, &IsSearchableType, &IsEditTypeType, &IsRequiredType, &IsDisplayType, &IsAutoUpdateType;
   REM Key/LBI/搜索组/Audit组：Long Char、Image、Attachment 的面板没有这些组（ImageRef有）;
   &HasKeyGroup = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm Or
      &IsImageRef);
   REM Date/Time/DateTime;
   &IsDateFamily = (&IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsSearchableType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm Or
      &IsImageRef);
   &IsEditTypeType = (&IsChar Or
      &IsNbr Or
      &IsSign);
   &IsRequiredType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsDisplayType = (&IsChar Or
      &IsNbr Or
      &IsSign Or
      &IsDate Or
      &IsTime Or
      &IsDtTm);
   &IsAutoUpdateType = &IsDateFamily;

   If &HasKeyGroup = False Then
      If &IsKey Or
            &IsDupKey Or
            &IsAltKey Or
            &IsSearchKey Or
            &IsSearchEdit Or
            &IsDescKey Or
            &IsLBI Or
            &IsFrom Or
            &IsThrough Or
            &IsDefaultSearch Or
            &IsDisableAdv Or
            &IsAllowSearchEvt Then
         &Err = &Err | "key/search group properties are not available for field type " | &p_FieldTypeName | " (AD does not show them), ";
      End-If;
      If &IsAuditAdd Or
            &IsAuditChg Or
            &IsAuditDel Then
         &Err = &Err | "audit properties are not available for field type " | &p_FieldTypeName | ", ";
      End-If;
   End-If;
   If (&IsImage Or
         &IsAttachment) And
         &IsDoNotTrace Then
      &Err = &Err | "Do Not Trace Value is not available for field type " | &p_FieldTypeName | ", ";
   End-If;

   REM Key依赖链（GUI置灰规则）;
   If &IsSearchKey And
         &IsKey = False Then
      &Err = &Err | "Search Key requires Key (grayed out until Key is checked), ";
   End-If;
   If &IsSearchEdit And
         &IsSearchKey = False Then
      &Err = &Err | "Search Edit requires Search Key (grayed out until Search Key is checked), ";
   End-If;
   If &IsDescKey And
         &IsKey = False And
         &IsAltKey = False And
         &IsSearchKey = False Then
      &Err = &Err | "Descending Key requires Key, Alternate Search Key or Search Key (grayed out otherwise), ";
   End-If;
   If &IsDefaultSearch And
         &IsSearchKey = False And
         &IsAltKey = False Then
      &Err = &Err | "Default Search Field requires Search Key or Alternate Search Key (grayed out otherwise), ";
   End-If;
   If &IsFrom And
         &IsThrough Then
      &Err = &Err | "From Search Field and Through Search Field are mutually exclusive, ";
   End-If;

   REM Table Edit 类型互斥（GUI为单选）与类型限制;
   Local integer &TableEditCount;
   &TableEditCount = 0;
   If &IsYN Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &IsPrompt Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &IsTranslate Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &Is10 Then
      &TableEditCount = &TableEditCount + 1;
   End-If;
   If &TableEditCount > 1 Then
      &Err = &Err | "only one Table Edit type (Yes/No, Prompt, Translate, 1/0) can be selected, ";
   End-If;
   If &IsYN And
         &IsChar = False Then
      &Err = &Err | "Yes/No Table Edit is only available for character fields, ";
   End-If;
   If &Is10 And
         &IsNbr = False And
         &IsSign = False Then
      &Err = &Err | "1/0 Table Edit is only available for number fields, ";
   End-If;
   If &IsTranslate And
         &IsChar = False Then
      &Err = &Err | "Translate Table Edit is only available for character fields, ";
   End-If;
   If &IsTranslate And
         &p_HasXlat = False Then
      &Err = &Err | "Translate Table Edit requires the field to have translate values (Xlat), ";
   End-If;
   If &IsPrompt And
         &IsEditTypeType = False Then
      &Err = &Err | "PromptTableEdit property is only available for character/number fields (date/time/datetime can set a prompt table without the bit, GUI keeps USEEDIT unchanged), ";
   End-If;

   If &IsRequired And
         &IsRequiredType = False Then
      &Err = &Err | "Required is not available for field type " | &p_FieldTypeName | " (Image/ImageReference/Attachment/Long Character do not have it), ";
   End-If;
   If &IsReasonable And
         &IsDate = False Then
      &Err = &Err | "Reasonable Date is only available for date fields, ";
   End-If;
   If &IsAutoUpdate And
         &IsAutoUpdateType = False Then
      &Err = &Err | "Auto-Update is only available for date/time/datetime fields, ";
   End-If;

   REM Autocomplete Configuration（GUI置灰规则，2026-09-05实测）;
   If &IsEnableAC Then
      If &IsChar = False Then
         &Err = &Err | "Enable Autocomplete when used in Search Record is only available for character fields, ";
      End-If;
      If &IsSearchKey = False And
            &IsAltKey = False Then
         &Err = &Err | "Enable Autocomplete when used in Search Record requires Search Key or Alternate Search Key, ";
      End-If;
      If &p_DefGuiControl <> 99 And
            &p_DefGuiControl <> 4 Then
         &Err = &Err | "Enable Autocomplete when used in Search Record requires Default Page Control = Edit Box or System Default, ";
      End-If;
   End-If;
   If &IsDisableAC And
         &p_EditTable = "" Then
      &Err = &Err | "Disable Autocomplete for this field requires the field to have a prompt table (Edit Type = Table Edit with a prompt table), ";
   End-If;
   If &IsDisplay Then
      If &IsDisplayType = False Then
         &Err = &Err | "Display in Autocomplete Window is not available for field type " | &p_FieldTypeName | ", ";
      End-If;
      If &IsLBI = False Then
         &Err = &Err | "Display in Autocomplete Window requires List Box Item, ";
      End-If;
      If &IsSearchKey Or
            &IsAltKey Then
         &Err = &Err | "Display in Autocomplete Window requires the field NOT to be a search item (it is auto-cleared when Search Key/Alternate Search Key is checked), ";
      End-If;
   End-If;
   If &IsPersistMenu And
         &IsLBI = False Then
      &Err = &Err | "Persist in Menu requires List Box Item (grayed out otherwise), ";
   End-If;

   Return &Err;
end-method;

import C_JSON_API:*;

/* SQL lexical/request guard. Mirror: scripts/sql_execution.py.
   This is input validation, not a database read-only security boundary. */
class SqlTextGuard
   method SqlTextGuard();
   method Validate(&req As C_JSON_API:JSONObject, &write As boolean);
   method Authorized(&operation As string) Returns boolean;
   method ParseRequest(&body As string) Returns C_JSON_API:JSONObject;
   property string Text;
   property string ExecutionText;
   property string Source;
   property string StatementType;
   property string SqlId;
   property array of any Binds;
   property array of string Columns;
   property integer MaxRows;
   property boolean AllowAllRows;
private
   method StringNode(&node As C_JSON_API:JSONNode, &label As string) Returns string;
   method Scan(&write As boolean);
   method WordChar(&ch As string) Returns boolean;
   method HasNul(&inputText As string) Returns boolean;
   method Prepare();
   method Decode(&value As string) Returns string;
   instance string &SlashToken;
end-class;

method SqlTextGuard
   &Binds = CreateArrayAny();
   &Columns = CreateArrayRept("", 0);
   &MaxRows = 200;
   &AllowAllRows = False;
end-method;

method Authorized
   /+ &operation as String +/
   /+ Returns Boolean +/
   Local integer &count = 0;
   /* IB can retain a grant after PermissionList save. Recheck persisted effective
      grants on every invocation using the authenticated token user. */
   SQLExec("SELECT COUNT(*) FROM PSAUTHWS A WHERE A.IB_OPERATIONNAME=:1 AND A.AUTHORIZEDACTIONS=4 AND (A.CLASSID IN (SELECT C.CLASSID FROM PSROLECLASS C, PSROLEUSER U WHERE C.ROLENAME=U.ROLENAME AND U.ROLEUSER=:2) OR A.CLASSID IN (SELECT OPRCLASS FROM PSOPRDEFN WHERE OPRID=:2))", &operation, %OperatorId, &count);
   If &count > 0 Then
      Return True;
   End-If;
   Return False;
end-method;

method ParseRequest
   /+ &body as String +/
   /+ Returns C_JSON_API:JSONObject +/
   Local C_JSON_API:JSONParser &parser = CreateObject("C_JSON_API:Factory").NewParser();
   Local string &safeBody;
   Local boolean &ok;
   /* Native JSON strings can truncate at U+0000. Protect literal backslashes
      before inspecting NUL escapes, then restore strings after type validation. */
   &SlashToken = "__PSQ_" | UuidGen() | "__";
   While Find(&SlashToken, &body) > 0
      &SlashToken = "__PSQ_" | UuidGen() | "__";
   End-While;
   &safeBody = Substitute(&body, Char(92) | Char(92), &SlashToken);
   If Find(Char(92) | "u0000", &safeBody) > 0 Then
      throw CreateException(0, 0, "Request contains NUL");
   End-If;
   &safeBody = Substitute(&safeBody, Char(92) | "u005c", &SlashToken);
   &safeBody = Substitute(&safeBody, Char(92) | "u005C", &SlashToken);
   &ok = &parser.Parse(&safeBody);
   If Not &ok Then
      throw CreateException(0, 0, "Invalid JSON request");
   End-If;
   Return &parser.GetRootObject();
end-method;

method Decode
   /+ &value as String +/
   /+ Returns String +/
   If Len(&SlashToken) > 0 Then
      Return Substitute(&value, &SlashToken, Char(92));
   End-If;
   Return &value;
end-method;

method StringNode
   /+ &node as C_JSON_API:JSONNode, +/
   /+ &label as String +/
   /+ Returns String +/
   If &node.GetNodeType() <> 3 Or
         &node.GetValueType() <> 6 Then
      throw CreateException(0, 0, &label | " must be a JSON string");
   End-If;
   Local string &value = %This.Decode(&node.GetString());
   If %This.HasNul(&value) Then
      throw CreateException(0, 0, &label | " contains NUL");
   End-If;
   Return &value;
end-method;

method HasNul
   /+ &inputText as String +/
   /+ Returns Boolean +/
   Local integer &i;
   For &i = 1 To Len(&inputText)
      If Code(Substring(&inputText, &i, 1)) = 0 Then
         Return True;
      End-If;
   End-For;
   Return False;
end-method;

method Prepare
   Local integer &i = 1;
   Local string &ch;
   While &i <= Len(&Text)
      &ch = Substring(&Text, &i, 1);
      If &ch = " " Or
            &ch = Char(9) Or
            &ch = Char(10) Or
            &ch = Char(13) Then
         &i = &i + 1;
         Continue;
      End-If;
      If Substring(&Text, &i, 2) = "--" Then
         While &i <= Len(&Text) And
               Substring(&Text, &i, 1) <> Char(10) And
               Substring(&Text, &i, 1) <> Char(13)
            If Substring(&Text, &i, 1) = "%" Then
               throw CreateException(0, 0, "PeopleCode meta-SQL is not supported in comments");
            End-If;
            &i = &i + 1;
         End-While;
         Continue;
      End-If;
      If Substring(&Text, &i, 2) = "/*" Then
         &i = &i + 2;
         While &i < Len(&Text) And
               Substring(&Text, &i, 2) <> "*/"
            &i = &i + 1;
         End-While;
         &i = &i + 2;
         Continue;
      End-If;
      Break;
   End-While;
   &ExecutionText = Substring(&Text, &i, Len(&Text));
end-method;

method WordChar
   /+ &ch as String +/
   /+ Returns Boolean +/
   If (&ch >= "A" And
         &ch <= "Z") Or
         (&ch >= "a" And
            &ch <= "z") Or
         (&ch >= "0" And
            &ch <= "9") Or
         &ch = "_" Or
         &ch = "$" Or
         &ch = "#" Then
      Return True;
   End-If;
   Return False;
end-method;

method Validate
   /+ &req as C_JSON_API:JSONObject, +/
   /+ &write as Boolean +/
   Local C_JSON_API:JSONNode &node;
   Local C_JSON_API:JSONArray &arr;
   Local integer &i, &j, &n;
   Local number &rows;
   Local string &name, &value, &ch;
   Local boolean &hasSql, &hasId;
   For &i = 1 To &req.ChildCount
      &name = &req.GetPropertyNameAt(&i);
      If &name <> "sql" And
            &name <> "binds" And
            Not ((&write And
               &name = "allowAllRows") Or
               ( Not &write And
                  (&name = "sqlId" Or
                     &name = "maxRows" Or
                     &name = "columns"))) Then
         throw CreateException(0, 0, "Unknown request property: " | &name);
      End-If;
   End-For;
   &hasSql = &req.IsExist("sql");
   &hasId = &req.IsExist("sqlId");
   If (&hasSql And
         &hasId) Or
         ( Not &hasSql And
            Not &hasId) Or
         (&write And
            Not &hasSql) Then
      throw CreateException(0, 0, "Provide exactly one sql or sqlId; writes require sql");
   End-If;
   &Source = "sql";
   If &hasId Then
      &node = &req.GetJsonNode("sqlId");
      &SqlId = %This.StringNode(&node, "sqlId");
      If Len(&SqlId) = 0 Or
            Len(&SqlId) > 30 Then
         throw CreateException(0, 0, "sqlId must be an ASCII SQL identifier of 1..30 characters");
      End-If;
      For &i = 1 To Len(&SqlId)
         &ch = Substring(&SqlId, &i, 1);
         If Not ((&ch >= "A" And
               &ch <= "Z") Or
               (&ch >= "a" And
                  &ch <= "z") Or
               (&i > 1 And
                  ((&ch >= "0" And
                     &ch <= "9") Or
                     &ch = "_"))) Then
            throw CreateException(0, 0, "sqlId must be an ASCII SQL identifier");
         End-If;
      End-For;
      &SqlId = Upper(&SqlId);
      &n = 0;
      SQLExec("SELECT COUNT(*) FROM PSSQLDEFN WHERE SQLID=:1 AND SQLTYPE=0", &SqlId, &n);
      If &n = 0 Then
         throw CreateException(0, 0, "SQL definition does not exist");
      End-If;
      /* Native resolution chooses current platform/as-of date. Validate and execute
         this exact text; do not classify a guessed GBL/default variant then GetSQL. */
      &Text = FetchSQL(&SqlId);
      &Source = "sqlId";
   Else
      &node = &req.GetJsonNode("sql");
      &Text = %This.StringNode(&node, "sql");
   End-If;
   &Binds = CreateArrayAny();
   If &req.IsExist("binds") Then
      &node = &req.GetJsonNode("binds");
      If Not &node.IsJsonArray() Then
         throw CreateException(0, 0, "binds must be an array");
      End-If;
      &arr = &node.GetJsonArray();
      If &arr.Size > 64 Then
         throw CreateException(0, 0, "binds exceeds 64 strings");
      End-If;
      For &i = 1 To &arr.Size
         If &arr.GetType(&i) <> 6 Then
            throw CreateException(0, 0, "binds entries must be JSON strings");
         End-If;
         &value = %This.Decode(&arr.GetString(&i));
         If Len(&value) > 4000 Or
               %This.HasNul(&value) Then
            throw CreateException(0, 0, "bind exceeds 4000 characters or contains NUL");
         End-If;
         &Binds.Push(&value);
      End-For;
   End-If;
   &AllowAllRows = False;
   If &write And
         &req.IsExist("allowAllRows") Then
      &node = &req.GetJsonNode("allowAllRows");
      If &node.GetNodeType() <> 3 Or
            &node.GetValueType() <> 5 Then
         throw CreateException(0, 0, "allowAllRows must be boolean");
      End-If;
      &AllowAllRows = &req.GetBoolean("allowAllRows");
   End-If;
   &MaxRows = 200;
   &Columns = CreateArrayRept("", 0);
   If Not &write Then
      If &req.IsExist("maxRows") Then
         &node = &req.GetJsonNode("maxRows");
         &n = &node.GetValueType();
         If &node.GetNodeType() <> 3 Or
               &n < 1 Or
               &n > 4 Then
            throw CreateException(0, 0, "maxRows must be an integer");
         End-If;
         &rows = &node.GetNumber();
         If &rows <> Int(&rows) Or
               &rows < 1 Or
               &rows > 1000 Then
            throw CreateException(0, 0, "maxRows must be an integer from 1 to 1000");
         End-If;
         &MaxRows = &rows;
      End-If;
      If &req.IsExist("columns") Then
         &node = &req.GetJsonNode("columns");
         If Not &node.IsJsonArray() Then
            throw CreateException(0, 0, "columns must be an array");
         End-If;
         &arr = &node.GetJsonArray();
         If &arr.Size < 1 Or
               &arr.Size > 128 Then
            throw CreateException(0, 0, "columns must contain 1..128 strings");
         End-If;
         For &i = 1 To &arr.Size
            If &arr.GetType(&i) <> 6 Then
               throw CreateException(0, 0, "columns entries must be JSON strings");
            End-If;
            &value = %This.Decode(&arr.GetString(&i));
            If Len(LTrim(RTrim(&value))) = 0 Or
                  Len(&value) > 128 Or
                  %This.HasNul(&value) Then
               throw CreateException(0, 0, "columns entries must be nonblank, at most 128 characters, without NUL");
            End-If;
            &Columns.Push(&value);
         End-For;
      End-If;
   End-If;
   %This.Scan(&write);
end-method;

method Scan
   /+ &write as Boolean +/
   Local integer &i, &j, &start, &depth, &at, &position;
   Local string &ch, &quote, &close, &word, &digits;
   Local boolean &closed, &hasWhere;
   Local array of string &words = CreateArrayRept("", 0);
   Local array of number &depths = CreateArrayRept(0, 0);
   Local array of number &positions = CreateArrayRept(0, 64);
   Local array of string &forbidden = Split("CREATE ALTER DROP TRUNCATE GRANT REVOKE COMMENT RENAME ANALYZE AUDIT NOAUDIT BEGIN DECLARE COMMIT ROLLBACK SAVEPOINT CALL EXEC EXECUTE LOCK", " ");
   If Len(LTrim(RTrim(&Text))) = 0 Or
         Len(&Text) > 20000 Or
         %This.HasNul(&Text) Then
      throw CreateException(0, 0, "sql must be a nonblank string of at most 20000 characters without NUL");
   End-If;
   If Find(";", &Text) > 0 Then
      throw CreateException(0, 0, "Semicolons are not allowed, including inside strings/comments");
   End-If;
   If &write And
         Find("C_AI_SQLAUD", Upper(&Text)) > 0 Then
      throw CreateException(0, 0, "Direct audit writes are not supported");
   End-If;
   &i = 1;
   &depth = 0;
   While &i <= Len(&Text)
      &ch = Substring(&Text, &i, 1);
      If Substring(&Text, &i, 2) = "--" Then
         While &i <= Len(&Text) And
               Substring(&Text, &i, 1) <> Char(10) And
               Substring(&Text, &i, 1) <> Char(13)
            If Substring(&Text, &i, 1) = "%" Then
               throw CreateException(0, 0, "PeopleCode meta-SQL is not supported in comments");
            End-If;
            &i = &i + 1;
         End-While;
         Continue;
      End-If;
      If Substring(&Text, &i, 2) = "/*" Then
         &j = &i + 2;
         While &j < Len(&Text) And
               Substring(&Text, &j, 2) <> "*/"
            If Substring(&Text, &j, 1) = "%" Then
               throw CreateException(0, 0, "PeopleCode meta-SQL is not supported in comments");
            End-If;
            &j = &j + 1;
         End-While;
         If &j >= Len(&Text) Then
            throw CreateException(0, 0, "Unclosed SQL comment");
         End-If;
         &i = &j + 2;
         Continue;
      End-If;
      If (&ch = "q" Or
            &ch = "Q") And
            Substring(&Text, &i + 1, 1) = "'" Then
         &quote = Substring(&Text, &i + 2, 1);
         &close = &quote;
         If &quote = "[" Then
            &close = "]";
         End-If;
         If &quote = "{" Then
            &close = "}";
         End-If;
         If &quote = "(" Then
            &close = ")";
         End-If;
         If &quote = "<" Then
            &close = ">";
         End-If;
         If &quote = "" Or
               &quote = "'" Or
               &quote = " " Or
               &quote = Char(9) Or
               &quote = Char(10) Or
               &quote = Char(13) Then
            throw CreateException(0, 0, "Invalid q literal delimiter");
         End-If;
         &j = &i + 3;
         While &j < Len(&Text) And
               Substring(&Text, &j, 2) <> &close | "'"
            &j = &j + 1;
         End-While;
         If &j >= Len(&Text) Then
            throw CreateException(0, 0, "Unclosed q literal");
         End-If;
         &i = &j + 2;
         Continue;
      End-If;
      If &ch = "'" Or
            &ch = Char(34) Then
         &quote = &ch;
         &closed = False;
         &i = &i + 1;
         While &i <= Len(&Text)
            If &quote = Char(34) And
                  Substring(&Text, &i, 1) = "%" Then
               throw CreateException(0, 0, "PeopleCode meta-SQL is not supported in identifiers");
            End-If;
            If Substring(&Text, &i, 1) = &quote Then
               If Substring(&Text, &i + 1, 1) = &quote Then
                  &i = &i + 2;
                  Continue;
               End-If;
               &closed = True;
               &i = &i + 1;
               Break;
            End-If;
            &i = &i + 1;
         End-While;
         If Not &closed Then
            throw CreateException(0, 0, "Unclosed SQL quote");
         End-If;
         Continue;
      End-If;
      If &ch = "%" Then
         throw CreateException(0, 0, "PeopleCode meta-SQL is not supported");
      End-If;
      If &ch = "(" Then
         &depth = &depth + 1;
         &i = &i + 1;
         Continue;
      End-If;
      If &ch = ")" Then
         &depth = &depth - 1;
         If &depth < 0 Then
            throw CreateException(0, 0, "Unbalanced SQL parentheses");
         End-If;
         &i = &i + 1;
         Continue;
      End-If;
      If &ch = ":" Then
         &j = &i + 1;
         &digits = "";
         While &j <= Len(&Text)
            &ch = Substring(&Text, &j, 1);
            If &ch < "0" Or
                  &ch > "9" Then
               Break;
            End-If;
            &digits = &digits | &ch;
            &j = &j + 1;
         End-While;
         If &digits = "" Or
               Left(&digits, 1) = "0" Or
               Len(&digits) > 2 Then
            throw CreateException(0, 0, "Only numeric binds :1..:64 are supported");
         End-If;
         &ch = Substring(&Text, &j, 1);
         If %This.WordChar(&ch) Then
            throw CreateException(0, 0, "Only numeric binds :1..:64 are supported");
         End-If;
         &position = Value(&digits);
         If &position > 64 Then
            throw CreateException(0, 0, "Bind position exceeds 64");
         End-If;
         &positions [&position] = 1;
         &i = &j;
         Continue;
      End-If;
      If (&ch >= "A" And
            &ch <= "Z") Or
            (&ch >= "a" And
               &ch <= "z") Or
            &ch = "_" Then
         &start = &i;
         &i = &i + 1;
         While &i <= Len(&Text)
            &ch = Substring(&Text, &i, 1);
            If Not %This.WordChar(&ch) Then
               Break;
            End-If;
            &i = &i + 1;
         End-While;
         &words.Push(Upper(Substring(&Text, &start, &i - &start)));
         &depths.Push(&depth);
         Continue;
      End-If;
      &i = &i + 1;
   End-While;
   If &depth <> 0 Then
      throw CreateException(0, 0, "Unbalanced SQL parentheses");
   End-If;
   If &words.Len = 0 Then
      throw CreateException(0, 0, "SQL must begin with a statement keyword");
   End-If;
   &StatementType = &words [1];
   If &depths [1] <> 0 Or
         (&write And
            &StatementType <> "INSERT" And
            &StatementType <> "UPDATE" And
            &StatementType <> "DELETE" And
            &StatementType <> "MERGE") Or
         ( Not &write And
            &StatementType <> "SELECT" And
            &StatementType <> "WITH") Then
      throw CreateException(0, 0, "Only SELECT/WITH queries or single DML statements in their respective endpoint");
   End-If;
   &hasWhere = False;
   For &i = 1 To &words.Len
      &word = &words [&i];
      If &forbidden.Find(&word) > 0 Or
            ( Not &write And
               (&word = "INSERT" Or
                  &word = "UPDATE" Or
                  &word = "DELETE" Or
                  &word = "MERGE")) Then
         throw CreateException(0, 0, "SQL contains a forbidden keyword");
      End-If;
      If &write And
            (&word = "PS_C_AI_SQLAUD" Or
               &word = "C_AI_SQLAUD" Or
               &word = "RETURNING") Then
         throw CreateException(0, 0, "Direct audit writes and DML RETURNING are not supported");
      End-If;
      If &word = "WHERE" And
            &depths [&i] = 0 Then
         &hasWhere = True;
      End-If;
   End-For;
   If &write And
         (&StatementType = "UPDATE" Or
            &StatementType = "DELETE") And
         Not &AllowAllRows And
         Not &hasWhere Then
      throw CreateException(0, 0, "UPDATE/DELETE require an outer WHERE or allowAllRows=true");
   End-If;
   For &i = 1 To 64
      If (&i <= &Binds.Len And
            &positions [&i] <> 1) Or
            (&i > &Binds.Len And
               &positions [&i] <> 0) Then
         throw CreateException(0, 0, "binds must match contiguous SQL positions :1..:n exactly");
      End-If;
   End-For;
   %This.Prepare();
end-method;
